// React host preserves existing Prudle functions, controls and CSS.
const LEGACY_MARKUP = "\n<!-- Published Questions Sidebar — visible immediately when page opens -->\n<aside aria-label=\"Questions shown to students\" id=\"publishedQuestionsSidebar\">\n<div class=\"published-sidebar-head\">\n<button class=\"published-sidebar-icon-btn\" id=\"publishedSidebarToggle\" onclick=\"togglePublishedQuestionsSidebar()\" title=\"Minimize / Open\" type=\"button\">\n<i class=\"fa-solid fa-list-check\"></i>\n</button>\n<div class=\"published-sidebar-title\">\n<strong>Questions Shown to Students</strong>\n<small id=\"publishedSidebarRoleLabel\">Loading published questions...</small>\n</div>\n<button class=\"published-sidebar-refresh\" onclick=\"loadPublishedQuestionsSidebar(true)\" title=\"Refresh\" type=\"button\">\n<i class=\"fa-solid fa-rotate\"></i>\n</button>\n</div>\n<div class=\"published-sidebar-body\" id=\"publishedSidebarBody\">\n<div class=\"published-sidebar-loading\">⏳ Loading published questions...</div>\n</div>\n</aside>\n<div hidden=\"\" id=\"prudleDataStatus\" role=\"status\" style=\"max-width:1180px;margin:15px auto;padding:14px;border:1px solid #e9b2a9;border-radius:14px;background:#fff3f1;color:#9f3021;font:600 14px Tajawal,Arial,sans-serif\"></div>\n<div class=\"page\">\n<header class=\"prudle-modern-header\">\n<div class=\"prudle-brand\">\n<div class=\"prudle-brand-icon\"><i aria-hidden=\"true\" class=\"fa-solid fa-graduation-cap\"></i></div>\n<div><strong class=\"prudle-brand-title\">Exams and Quizzes — Prudle</strong>\n<span class=\"prudle-brand-sub\"><span class=\"prudle-online-dot\"></span><span id=\"prudleCurrentUserName\">Prudle Staff</span> · إدارة الاختبارات والكويزات</span>\n</div>\n</div>\n<div class=\"prudle-head-actions\">\n<button class=\"prudle-sidebar-trigger\" onclick=\"togglePublishedQuestionsSidebar()\" type=\"button\"><i class=\"fa-solid fa-bullhorn\"></i> Published Questions</button>\n</div>\n</header>\n<!-- □ Previews questions -->\n<div class=\"box\">\n<h3>□ Previews questions</h3>\n<!-- □ البحث + الفرز -->\n<div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:10px\">\n<input id=\"previewExamSearch\" oninput=\"filterExamDropdown(this.value)\" placeholder=\"□ Search exam...\" style=\"flex:1\"/>\n<select id=\"examFilterSort\" onchange=\"filterExamDropdown()\" style=\"width:180px\">\n<option value=\"new\">Newest</option>\n<option value=\"old\">Oldest</option>\n<option value=\"az\">A → Z</option>\n<option value=\"za\">Z → A</option>\n</select>\n</div> <!-- □ هذا كان ناقص -->\n<!-- □ قائمة الاختبارات -->\n<div id=\"examPreviewBox\" style=\"\n  margin-top:12px;\n  height:420px;\n  overflow:auto;\n  border:2px solid #dbeafe;\n  border-radius:22px;\n  padding:20px;\n  background:#fafcff;\n  resize:vertical;\n  min-height:250px;\n  max-height:900px;\n\">\n  جاري تحميل الاختبارات...\n</div>\n<!-- □ أزرار التحكم -->\n<div style=\"\n  display:flex;\n  gap:10px;\n  flex-wrap:wrap;\n  margin-top:10px;\n\">\n<!-- □ زر الخلط -->\n<button onclick=\"toggleShuffle()\" style=\"\n    flex:1;\n    background:#8b5cf6;\n    color:#fff;\n    padding:12px;\n    border:none;\n    border-radius:12px;\n    font-weight:900;\n    cursor:pointer;\n  \">\n    □ Shuffle Questions\n  </button>\n<!-- □ زر عرض كل الأسئلة -->\n<button onclick=\"toggleOnePageMode()\" style=\"\n    flex:1;\n    background:#0ea5e9;\n    color:#fff;\n    padding:12px;\n    border:none;\n    border-radius:12px;\n    font-weight:900;\n    cursor:pointer;\n  \">\n    □ One Page Questions\n  </button>\n<!-- ❌ حذف الاختبار -->\n<button id=\"deleteExamBtn\" onclick=\"deleteExam()\" style=\"\n    flex:1;\n    background:#e74c3c;\n    color:#fff;\n    padding:12px;\n    border:none;\n    border-radius:12px;\n    font-weight:900;\n    cursor:pointer;\n  \">\n  □ Delete the exam\n</button>\n</div>\n<!-- تعديل الوقت -->\n<div class=\"actions\">\n<div class=\"row\">\n<input id=\"editH\" min=\"0\" placeholder=\"Hour\" type=\"number\"/>\n<input id=\"editM\" min=\"0\" placeholder=\"Minutes\" type=\"number\"/>\n</div>\n<button onclick=\"editExamTime()\">⏱ Save the timer</button>\n<button onclick=\"loadQuestions()\">□ Update Page</button>\n</div>\n<!-- □ هذا أهم عنصر (عرض الأسئلة) -->\n<div id=\"courseTabs\" style=\"\n  display:flex;\n  gap:10px;\n  flex-wrap:wrap;\n  margin-top:15px;\n\"></div> <div id=\"questionsList\" style=\"margin-top:15px\"></div>\n</div>\n<div class=\"box import-generator\">\n<div class=\"import-head\">\n<div class=\"import-head-title\">\n<div class=\"import-head-icon\">\n<i class=\"fa-solid fa-file-import\"></i>\n</div>\n<div>\n<h3 style=\"margin:0\">Import Questions</h3>\n<div class=\"small\">\n          Import, review and edit questions before saving them to the selected exam.\n        </div>\n</div>\n</div>\n<div class=\"import-badge\">\n<i class=\"fa-solid fa-eye\"></i>\n      Preview before save\n    </div>\n</div>\n<div class=\"import-grid\">\n<div class=\"import-field\">\n<label for=\"wordFile\">\n<i class=\"fa-solid fa-file-word\"></i>\n        Word / TXT\n      </label>\n<input accept=\".docx,.txt\" id=\"wordFile\" type=\"file\"/>\n<button onclick=\"importWord()\" style=\"background:#17a673\" type=\"button\">\n<i class=\"fa-solid fa-wand-magic-sparkles\"></i>\n        Read Word Questions\n      </button>\n</div>\n<div class=\"import-field\">\n<label for=\"pdfFile\">\n<i class=\"fa-solid fa-file-pdf\"></i>\n        PDF\n      </label>\n<input accept=\".pdf\" id=\"pdfFile\" type=\"file\"/>\n<button onclick=\"importPDF()\" style=\"background:#e74c3c\" type=\"button\">\n<i class=\"fa-solid fa-wand-magic-sparkles\"></i>\n        Read PDF Questions\n      </button>\n</div>\n</div>\n<div class=\"import-note\">\n<i class=\"fa-solid fa-circle-info\"></i>\n    The file is analyzed first without saving anything. Review the imported questions,\n    edit any question or option, choose the correct answer, then press\n    <strong>Save Imported Questions</strong>.\n    Supported options: <strong>a) b) c) d)</strong> and automatic Word numbering\n    <strong>1. 2. 3. 4.</strong>. Mark one correct answer using <strong>*</strong>.\n  </div>\n<div class=\"import-status\" id=\"importStatus\"></div>\n<div id=\"importedQuestionsStage\">\n<div class=\"import-stage-toolbar\">\n<div>\n<strong style=\"color:#164478;font-size:18px\">\n          Imported Questions Preview\n        </strong>\n<div class=\"small\">\n          Changes here are temporary until you save.\n        </div>\n</div>\n<div class=\"import-stage-count\" id=\"importedQuestionsCount\">\n<i class=\"fa-solid fa-list-check\"></i>\n        0 Questions\n      </div>\n</div>\n<div class=\"imported-questions-grid\" id=\"importedQuestionsPreview\"></div>\n<div class=\"import-save-bar\">\n<button id=\"saveImportedQuestionsBtn\" onclick=\"saveImportedQuestions()\" style=\"background:#17a673\" type=\"button\">\n<i class=\"fa-solid fa-cloud-arrow-up\"></i>\n        Save Imported Questions\n      </button>\n<button onclick=\"clearImportedQuestionsStage()\" style=\"background:#6b7b8d\" type=\"button\">\n<i class=\"fa-solid fa-xmark\"></i>\n        Cancel Import\n      </button>\n</div>\n</div>\n</div>\n<!-- □ الفلاتر --> <select id=\"branchFilter\" onchange=\"loadCourses()\"></select>\n<select id=\"sectionFilter\" onchange=\"loadCourses()\"></select>\n<select id=\"typeFilter\" onchange=\"loadCourses()\">\n<option value=\"\">Type of course</option>\n<option value=\"online\"> online </option>\n<option value=\"offline\"> in person </option>\n</select>\n<!-- ✅ البحث + الفرز للدورات -->\n<div style=\"\n  display:flex;\n  gap:10px;\n  flex-wrap:wrap;\n  margin-top:10px;\n\">\n<input id=\"courseSearch\" oninput=\"loadCourses()\" placeholder=\"□ Search course...\" style=\"flex:1\"/>\n<select id=\"courseSort\" onchange=\"loadCourses()\" style=\"width:180px\">\n<option value=\"az\">\n      A → Z\n    </option>\n<option value=\"za\">\n      Z → A\n    </option>\n<option value=\"trainer\">\n      Trainer\n    </option>\n</select>\n</div>\n<!-- □ الدورات -->\n<div style=\"margin-top:12px;font-weight:900;color:#164478\">\n  □ Choose Courses\n</div>\n<div id=\"coursesBox\" style=\"\n  margin-top:6px;\n  max-height:180px;\n  overflow:auto;\n  border:1px solid #ddd;\n  padding:10px;\n  border-radius:12px;\n  background:#fafafa;\n\">\n  جاري تحميل الدورات...\n</div>\n<!-- □ البحث + الفرز (فوق) -->\n<div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:10px\">\n<input id=\"examSearchTop\" oninput=\"filterExamBank()\" placeholder=\"□ Search exam...\" style=\"flex:1\"/>\n<select id=\"examSortTop\" onchange=\"filterExamBank()\" style=\"width:180px\">\n<option value=\"new\">Newest</option>\n<option value=\"old\">Oldest</option>\n<option value=\"az\">A → Z</option>\n<option value=\"za\">Z → A</option>\n</select>\n<!-- □ بنك الاختبارات للنسخ -->\n<div id=\"examBank\" style=\"\n  margin-top:6px;\n  border:1px solid #ddd;\n  border-radius:12px;\n  padding:10px;\n  max-height:220px;\n  overflow:auto;\n  background:#fafafa;\n\">\n  Loading exams...\n</div>\n</div>\n<input id=\"examTitle\" placeholder=\"Quiz name\"/>\n<select id=\"examCategory\">\n<option value=\"\">Select Exam Type</option>\n<option value=\"midterm\">Midterm</option>\n<option value=\"finalExam\">Final Exam</option>\n<option value=\"listening\">Listening</option>\n<option value=\"speaking\">Speaking</option>\n<option value=\"quizEvaluation\">Quiz and Evaluation</option>\n</select>\n<div class=\"row\">\n<input id=\"h\" min=\"0\" placeholder=\"Hour\" type=\"number\"/>\n<input id=\"m\" min=\"0\" placeholder=\"Minutes\" type=\"number\"/>\n<input id=\"s\" min=\"0\" placeholder=\"Seconds\" type=\"number\"/>\n</div>\n<!-- □ زر الإنشاء -->\n<button onclick=\"createExam()\">➕ Create a test</button>\n</div>\n<!--  Edit /Add -->\n<div class=\"box\">\n<h3> Add / Edit </h3>\n<select id=\"examSelect\"></select>\n<select id=\"qType\" onchange=\"toggleQuestionType()\">\n<option value=\"mcq\">Multible Choice</option>\n<option value=\"order\">Rearrange</option>\n<option value=\"text\">Text Answer</option>\n<option value=\"match\">Matching</option>\n<option value=\"fill\">Fill in the Blanks</option>\n<option value=\"voice\">Voice Recording</option>\n</select>\n<!-- □ هنا تحطه منفصل -->\n<select id=\"groupSelect\">\n<option value=\"General\">General</option>\n<option value=\"Group A\">Group A</option>\n<option value=\"Group B\">Group B</option>\n<option value=\"Group C\">Group C</option>\n</select>\n<textarea id=\"question\" placeholder=\"Write the question here\"></textarea>\n<div class=\"hidden\" id=\"textAnswerLinesBox\" style=\"margin-top:10px;\">\n<label for=\"textAnswerLines\" style=\"display:block;font-weight:900;color:#164478;margin-bottom:6px;\">\n    Number of Answer Lines\n  </label>\n<input id=\"textAnswerLines\" max=\"20\" min=\"1\" placeholder=\"Number of lines shown below the question\" type=\"number\" value=\"4\"/>\n<div class=\"small\" style=\"margin-top:6px;\">\n    This number is used in the question preview and printed PDF.\n  </div>\n</div>\n<div class=\"passage-toolbar\" style=\"\n  display:flex;\n  gap:10px;\n  align-items:center;\n  flex-wrap:wrap;\n  margin:8px 0 10px;\n\">\n<button onclick=\"openPassageEditor()\" style=\"background:#0ea5e9\" type=\"button\">\n    ✍️ Add / Edit Reading Passage\n  </button>\n<span id=\"passageSavedStatus\" style=\"\n      display:none;\n      padding:8px 12px;\n      border-radius:999px;\n      background:#ecfdf5;\n      color:#166534;\n      border:1px solid #86efac;\n      font-weight:900;\n    \">\n    ✓ Passage saved\n  </span>\n<!-- kept for backward compatibility with old saved questions -->\n<select id=\"passageAlign\" style=\"display:none\">\n<option value=\"left\">Left</option>\n<option value=\"center\">Center</option>\n<option value=\"right\">Right</option>\n</select>\n</div>\n<!-- =========================================\n     LARGE WORD-LIKE PASSAGE EDITOR\n========================================= -->\n<div aria-hidden=\"true\" class=\"passage-editor-modal\" id=\"passageEditorModal\">\n<div class=\"passage-editor-shell\">\n<div class=\"passage-editor-head\">\n<div>\n<div class=\"passage-editor-title\">Reading Passage Editor</div>\n<div class=\"passage-editor-subtitle\">\n          Press Enter for a new line. Select text or a paragraph, then use the formatting tools.\n        </div>\n</div>\n<button class=\"passage-editor-close\" onclick=\"closePassageEditor(false)\" title=\"Close\" type=\"button\">✕</button>\n</div>\n<div class=\"passage-editor-toolbar\" dir=\"ltr\">\n<button onclick=\"passageCommand('bold')\" title=\"Bold\" type=\"button\"><b>B</b></button>\n<button onclick=\"passageCommand('italic')\" title=\"Italic\" type=\"button\"><i>I</i></button>\n<button onclick=\"passageCommand('underline')\" title=\"Underline\" type=\"button\"><u>U</u></button>\n<span class=\"passage-toolbar-separator\"></span>\n<button onclick=\"passageCommand('justifyLeft')\" title=\"Align left\" type=\"button\">☰←</button>\n<button onclick=\"passageCommand('justifyCenter')\" title=\"Center\" type=\"button\">☰</button>\n<button onclick=\"passageCommand('justifyRight')\" title=\"Align right\" type=\"button\">→☰</button>\n<span class=\"passage-toolbar-separator\"></span>\n<button onclick=\"passageCommand('insertUnorderedList')\" title=\"Bullets\" type=\"button\">• List</button>\n<button onclick=\"passageCommand('insertOrderedList')\" title=\"Numbered list\" type=\"button\">1. List</button>\n<span class=\"passage-toolbar-separator\"></span>\n<select id=\"passageFontSize\" onchange=\"passageFontSizeChange(this.value)\" title=\"Font size\">\n<option value=\"\">Font Size</option>\n<option value=\"2\">Small</option>\n<option value=\"3\">Normal</option>\n<option value=\"4\">Medium</option>\n<option value=\"5\">Large</option>\n<option value=\"6\">Very Large</option>\n</select>\n<button onclick=\"passageCommand('undo')\" title=\"Undo\" type=\"button\">↶</button>\n<button onclick=\"passageCommand('redo')\" title=\"Redo\" type=\"button\">↷</button>\n<button onclick=\"passageCommand('removeFormat')\" title=\"Clear formatting\" type=\"button\">\n        Clear format\n      </button>\n</div>\n<div class=\"passage-rich-editor\" contenteditable=\"true\" data-placeholder=\"Write or paste the reading passage here...\" dir=\"ltr\" id=\"passageRichEditor\" spellcheck=\"true\"></div>\n<div class=\"passage-editor-foot\">\n<div class=\"passage-editor-tip\">\n        Formatting is saved with the passage and used in student view and PDF.\n      </div>\n<div class=\"passage-editor-actions\">\n<button class=\"passage-editor-cancel\" onclick=\"closePassageEditor(false)\" type=\"button\">Cancel</button>\n<button class=\"passage-editor-save\" onclick=\"savePassageEditor()\" type=\"button\">✓ Save Passage</button>\n</div>\n</div>\n</div>\n</div>\n<div id=\"optionsBox\">\n<input id=\"opt1\" placeholder=\"Option 1\"/>\n<input id=\"opt2\" placeholder=\"Option 2\"/>\n<input id=\"opt3\" placeholder=\"Option 3\"/>\n<input id=\"opt4\" placeholder=\"Option 4\"/>\n</div>\n<!-- =========================================\n     DYNAMIC REARRANGE BUILDER\n========================================= -->\n<div id=\"rearrangeSection\" style=\"display:none;margin-top:12px;\">\n<div class=\"rearrange-items-box\" id=\"rearrangeItemsBox\"></div>\n<div class=\"rearrange-add-toolbar\">\n<button id=\"addRearrangeItemBtn\" onclick=\"addRearrangeItem()\" type=\"button\">\n<i class=\"fa-solid fa-plus\"></i>\n      Add Rearrange Item\n    </button>\n<span class=\"rearrange-item-count\" id=\"rearrangeItemCount\">\n      4 items\n    </span>\n</div>\n</div>\n<div id=\"matchingSection\" style=\"display:none;margin-top:12px;\">\n<div id=\"matchingBox\"></div>\n<div class=\"matching-add-toolbar\">\n<button id=\"addMatchingPairBtn\" onclick=\"addMatchingPair()\" type=\"button\">\n<i class=\"fa-solid fa-plus\"></i>\n      Add Matching Pair\n    </button>\n<span class=\"matching-pair-count\" id=\"matchingPairCount\">\n      4 pairs\n    </span>\n</div>\n</div>\n<div id=\"fillBlanksBox\">\n<div class=\"fill-builder-toolbar\">\n<div>\n<label>Layout</label>\n<select id=\"fillLayout\" onchange=\"renderFillBuilderPreview()\">\n<option value=\"horizontal\">Horizontal</option>\n<option value=\"vertical\">Vertical</option>\n</select>\n</div>\n<div>\n<label>Columns (Horizontal)</label>\n<input id=\"fillColumns\" max=\"12\" min=\"1\" oninput=\"renderFillBuilderPreview()\" type=\"number\" value=\"10\"/>\n</div>\n<button onclick=\"addFillItem()\" type=\"button\"><i class=\"fa-solid fa-plus\"></i> Add Item</button>\n</div>\n<div class=\"fill-items-list\" id=\"fillItemsList\"></div>\n<div class=\"fill-degree-note\" id=\"fillDegreeNote\">0 blanks = 0 marks</div>\n<div class=\"fill-preview-grid\" id=\"fillBuilderPreview\"></div>\n</div>\n<div id=\"correctBox\">\n<input id=\"correct\" min=\"0\" placeholder=\"The Correct answer No. (0-3)\" type=\"number\"/>\n</div>\n<div class=\"note hidden\" id=\"orderNote\">\n      ✳️ In the ordering question: write the options in the correct order; they will be shuffled for the student later.\n    </div>\n<div class=\"note hidden\" id=\"orderPreview\"></div>\n<input id=\"degree\" min=\"0.01\" oninput=\"updateQuestionDegreeDistributionNote()\" placeholder=\"Total question marks\" step=\"0.01\" type=\"number\"/>\n<div class=\"fill-degree-note\" id=\"questionDegreeDistributionNote\" style=\"display:none\">\n</div>\n<select id=\"mediaType\">\n<option value=\"none\">No Media</option>\n<option value=\"image\">Image</option>\n<option value=\"video\">Video</option>\n<option value=\"audio\">Audio</option>\n</select>\n<input class=\"question-url-field\" id=\"mediaUrlInput\" placeholder=\"URL\" type=\"url\"/>\n<input accept=\"image/*,video/*,audio/*\" id=\"file\" type=\"file\"/>\n<div class=\"actions\">\n<button onclick=\"saveQuestion()\">\n    □ Save / Update\n  </button>\n<button onclick=\"clearForm()\">\n    □ Cancel\n  </button>\n</div> </div>\n\n<div class=\"modal\" id=\"questionsModal\">\n<div class=\"modal-box\">\n<div class=\"modal-header\">\n<span id=\"modalTitle\"></span>\n<div style=\"display:flex;align-items:center;gap:10px;\">\n<button class=\"print-questions-btn\" onclick=\"printQuestionsPDF('questions')\" type=\"button\">\n<i class=\"fa-solid fa-file-pdf\"></i>\n              Questions PDF\n            </button>\n<button class=\"print-questions-btn print-answers-btn\" onclick=\"printQuestionsPDF('answers')\" type=\"button\">\n<i class=\"fa-solid fa-circle-check\"></i>\n              Questions &amp; Answers PDF\n            </button>\n<button class=\"print-questions-btn print-review-btn\" onclick=\"printQuestionsPDF('review')\" title=\"Review questions without the cover and instructions page\" type=\"button\">\n<i class=\"fa-solid fa-eye\"></i>\n              Review\n            </button>\n<button onclick=\"closeQuestionsModal()\" style=\"width:auto;margin:0;background:#ef4444;padding:10px 18px;\" type=\"button\">\n              ✕\n            </button>\n</div>\n</div>\n<div id=\"modalQuestions\"></div>\n</div>\n</div>\n<!-- Question Copy Bank Modal -->\n<div class=\"copy-bank-modal\" id=\"questionCopyBankModal\" onclick=\"closeQuestionCopyBank(event)\">\n<div class=\"copy-bank-box\" onclick=\"event.stopPropagation()\">\n<div class=\"copy-bank-head\">\n<div class=\"copy-bank-title\">\n<h2>\n<i class=\"fa-solid fa-copy\"></i>\n          Copy Questions From Previous Exams\n        </h2>\n<p>\n          Review the full question, select one or more questions, then copy them to the currently opened exam.\n        </p>\n</div>\n<button class=\"copy-bank-close\" onclick=\"closeQuestionCopyBank()\" type=\"button\">\n<i class=\"fa-solid fa-xmark\"></i>\n        Close\n      </button>\n</div>\n<div class=\"copy-bank-controls\">\n<div class=\"copy-bank-filter-row\">\n<input id=\"copyBankSearch\" oninput=\"renderQuestionCopyBank()\" placeholder=\"Search question, exam or group...\"/>\n<select id=\"copyBankExamFilter\" onchange=\"renderQuestionCopyBank()\">\n<option value=\"\">All Exams</option>\n</select>\n</div>\n<div class=\"copy-bank-actions-row\">\n<div style=\"display:flex;gap:9px;flex-wrap:wrap\">\n<button onclick=\"toggleAllCopyBankQuestions(true)\" style=\"background:#16a34a\" type=\"button\"><i class=\"fa-solid fa-square-check\"></i> Select All Visible</button>\n<button onclick=\"toggleAllCopyBankQuestions(false)\" style=\"background:#64748b\" type=\"button\"><i class=\"fa-solid fa-trash-can\"></i> Clear Selection</button>\n</div>\n</div>\n<div class=\"copy-bank-summary\">\n<span id=\"questionCopyBankCount\">0 questions selected</span>\n<span id=\"questionCopyBankFound\">Total Found: 0 Questions</span>\n</div>\n</div>\n<div class=\"copy-bank-grid\" id=\"questionCopyBankList\"></div>\n<div class=\"copy-bank-footer\">\n<div class=\"copy-bank-insert-options\">\n<strong>Insert copied questions:</strong>\n<label><input checked=\"\" name=\"copyInsertPosition\" type=\"radio\" value=\"end\"/> At the end</label>\n<label><input name=\"copyInsertPosition\" type=\"radio\" value=\"after\"/> After current question</label>\n<label><input name=\"copyInsertPosition\" type=\"radio\" value=\"beginning\"/> At beginning</label>\n</div>\n<button onclick=\"closeQuestionCopyBank()\" style=\"background:#64748b\" type=\"button\">Cancel</button>\n<button onclick=\"copySelectedBankQuestions()\" style=\"background:#17a673\" type=\"button\"><i class=\"fa-solid fa-copy\"></i> Copy Selected To My Exam</button>\n</div>\n</div>\n</div>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<section class=\"box\" id=\"prudleAIQuiz\">\n<h3>✨ توليد أسئلة بالذكاء الاصطناعي — CEFR</h3>\n<p class=\"ai-help\">اختر الاختبار من القائمة الأصلية أولاً. اختر المهارة والمستوى والعدد، ثم راجع الأسئلة واحفظ المحدد منها. التوليد يستخدم Worker المكتبة الحالي.</p>\n<div class=\"ai-grid\">\n<div><label for=\"aiSkill\">المهارة / Skill</label><select id=\"aiSkill\"><option value=\"grammar\">Grammar — القواعد</option><option value=\"vocabulary\">Vocabulary — المفردات</option><option value=\"reading\">Reading — القراءة</option><option value=\"listening\">Listening — الاستماع</option><option value=\"speaking\">Speaking — التحدث</option><option value=\"writing\">Writing — الكتابة</option></select></div>\n<div><label for=\"aiLevel\">المستوى CEFR</label><select id=\"aiLevel\"><option>A1</option><option>A2</option><option selected=\"\">B1</option><option>B2</option><option>C1</option><option>C2</option></select></div>\n<div><label for=\"aiCount\">عدد الأسئلة</label><input id=\"aiCount\" max=\"40\" min=\"1\" type=\"number\" value=\"5\"/></div>\n<div><label for=\"aiType\">نوع السؤال</label><select id=\"aiType\"><option value=\"mixed\">مختلط</option><option value=\"mcq\">اختيار من متعدد</option><option value=\"tf\">صح أو خطأ</option><option value=\"missing\">إكمال الفراغ</option><option value=\"order\">ترتيب الكلمات</option><option value=\"match\">مطابقة</option><option value=\"voice\">تسجيل صوتي (Speaking)</option></select></div>\n</div>\n<div class=\"ai-wide\"><label for=\"aiTopic\">الموضوع / القاعدة (اختياري)</label><input id=\"aiTopic\" placeholder=\"مثال: Present Perfect / Travel / Food\"/></div>\n<div class=\"ai-wide\"><label for=\"aiSource\">نص مرجعي أو قطعة Reading / Listening (اختياري)</label><textarea id=\"aiSource\" placeholder=\"اكتب نصًا يُبنى عليه توليد الأسئلة؛ أو اتركه فارغًا ليتولى الذكاء الاصطناعي إنشاء المحتوى الملائم للمستوى.\"></textarea></div>\n<div class=\"ai-grid\"><div><label for=\"aiDegree\">درجة السؤال الواحد</label><input id=\"aiDegree\" min=\"0.5\" step=\"0.5\" type=\"number\" value=\"1\"/></div><div><label for=\"aiGroup\">مجموعة الأسئلة</label><select id=\"aiGroup\"><option>General</option><option>Group A</option><option>Group B</option><option>Group C</option></select></div></div>\n<div style=\"margin-top:13px\"><button id=\"aiGenerateBtn\" onclick=\"prudleGenerateQuizAI()\" type=\"button\">✨ توليد الأسئلة</button><button disabled=\"\" id=\"aiSaveBtn\" onclick=\"prudleSaveGeneratedQuiz()\" style=\"background:#168349\" type=\"button\">💾 حفظ الأسئلة المحددة</button></div>\n<div aria-live=\"polite\" id=\"prudleAIStatus\" role=\"status\"></div>\n<div class=\"ai-results\" id=\"prudleAIResults\"></div>\n</section>\n\n\n<!-- PRUDLE: isolated local questions/answers preview for testing without authentication.\n     This preview NEVER writes data and NEVER queries private collections. -->\n<section id=\"prudleLocalPreview\" style=\"max-width:1180px;margin:28px auto;padding:18px;border:1px solid #dce6ef;border-radius:20px;background:#fff;box-shadow:0 8px 24px rgba(22,68,120,.08);font-family:Tajawal,Arial,sans-serif;direction:rtl\">\n<h3 style=\"margin:0 0 10px;color:#164478\">🧪 معاينة الأسئلة والإجابات بدون تسجيل دخول</h3>\n<p style=\"margin:0 0 12px;line-height:1.8;color:#475569\">يمكنك تجربة طريقة عرض الأسئلة والإجابات ببيانات مثال، أو استيراد نسخة JSON خاصة بك من الأسئلة. بيانات Firestore الفعلية لا تصبح متاحة للعامة بمجرد إزالة صفحة الدخول.</p>\n<div style=\"display:flex;flex-wrap:wrap;gap:10px;align-items:center\">\n<button id=\"prudleTrySample\" style=\"width:auto;margin:0;padding:10px 16px\" type=\"button\">عرض أسئلة تجريبية مع الإجابات</button>\n<label style=\"display:inline-flex;align-items:center;gap:8px;cursor:pointer;font-weight:700;color:#164478\">استيراد أسئلة JSON <input accept=\".json,application/json\" id=\"prudleQuestionImport\" style=\"width:min(320px,75vw);margin:0;padding:7px;background:#f8fbff\" type=\"file\"/></label>\n</div>\n<p aria-live=\"polite\" id=\"prudleLocalStatus\" style=\"color:#64748b;margin:12px 0 0\"></p>\n<div id=\"prudleLocalQuestions\" style=\"display:grid;gap:12px;margin-top:12px;direction:ltr;text-align:left\"></div>\n</section>\n\n";
const LEGACY_SCRIPTS = [{"src": "https://www.gstatic.com/firebasejs/11.0.1/firebase-app-compat.js"}, {"src": "https://www.gstatic.com/firebasejs/11.0.1/firebase-firestore-compat.js"}, {"src": "https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js"}, {"text": "\n(function () {\n  \"use strict\";\n  document.documentElement.classList.add(\"prudle-session-verified\");\n  // Preserve compatibility with modules listening for the old ready event.\n  window.addEventListener(\"DOMContentLoaded\", function () {\n    window.dispatchEvent(new CustomEvent(\"prudle-session-ready\"));\n  }, { once: true });\n})();\n"}, {"text": "\nfirebase.initializeApp({\n   apiKey:\"AIzaSyCCFBvZosI8dwShZjxvZzI-SU5igEbcOKk\",\n  authDomain:\"prudle-system.firebaseapp.com\",\n  projectId:\"prudle-system\"\n});\n\nconst db = firebase.firestore();\nwindow.addEventListener(\"message\", function(e){\n\n  const d = e.data || {};\n\n  if([\"https://www.prudle-education.com\",\"https://prudle-education.com\",\"https://app.prudle.edu.sa\"].includes(e.origin) &&\n     e.source === window.parent &&\n     (d.type === \"PRUDLE_AUTH\" || d.type === \"PRUDLE_USER_INFO\")){\n\n    localStorage.setItem(\"username\", d.username || d.assignedBy || \"\");\n    localStorage.setItem(\"role\", d.role || \"\");\n    if(Array.isArray(d.roles)) localStorage.setItem(\"roles\",JSON.stringify(d.roles));\n    localStorage.setItem(\"loginDate\", d.loginDate || \"\");\n\n    if(typeof loadQuestions === \"function\"){\n      loadQuestions();\n    }\n\n    if(typeof loadCourses === \"function\"){\n      loadCourses();\n    }\n\n    if(\n      typeof loadQuestions === \"function\" &&\n      CURRENT_PREVIEW_EXAM\n    ){\n      loadQuestions();\n    }\n\n    // تحديث الشريط مباشرة بعد وصول بيانات دخول المدرب/الأدمن\n    if(typeof loadPublishedQuestionsSidebar === \"function\"){\n      loadPublishedQuestionsSidebar(false).catch(err=>\n        console.warn(\"Published sidebar auth refresh:\", err)\n      );\n    }\n  }\n\n});\nasync function allowStudentRetake(examId, courseId, studentId, iqama){\n\n  const docId = `${examId}__${courseId}__${studentId}`;\n\n  await db.collection(\"examRetakes\")\n    .doc(docId)\n    .set({\n      examId,\n      courseId,\n      studentId,\n      iqama: iqama || \"\",\n      allowRetake: true,\n      createdAt: firebase.firestore.FieldValue.serverTimestamp()\n    }, { merge:true });\n\n}\nlet SELECTED_QUESTION_COURSE = \"\";\n\nlet EDIT_QUESTION_ID = null;\n\nlet CURRENT_PREVIEW_EXAM = \"\";\nlet ACTIVE_QUESTION_ID = \"\";\nlet CURRENT_PRINT_EXAM_DATA = null;\nlet CURRENT_COURSE_ID = \"\";\n\n/*\n  عند فتح اختبار من الشريط الجانبي نحفظ الدورة التي ضغط عليها المدرب.\n  أثناء هذا الوضع لا نعرض روابط دورات المدربين الآخرين.\n*/\nlet SIDEBAR_FOCUS_COURSE_ID = \"\";\n\n/*\n  ✅ سياق مستقل للطباعة:\n  يحفظ الدورة التي فتح منها المدرب الاختبار.\n*/\nlet PRINT_CONTEXT_COURSE_ID = \"\";\n// ✅ عند فتح الاختبار من الشريط: اعرض جميع أسئلة النموذج مثل الشاشة الرئيسية\nlet SIDEBAR_SHOW_FULL_EXAM = false;\nlet CURRENT_COURSE_NAME = \"\";\nlet CURRENT_TRAINER = \"\";\nlet CURRENT_PERIOD = \"\";\nlet CURRENT_PASSAGE = \"\";\nlet CURRENT_PASSAGE_HTML = \"\";\n    const passageAlignReset = document.getElementById(\"passageAlign\");\n    if(passageAlignReset) passageAlignReset.value = \"left\"; // □ الحل هنا\n\nconst CURRENT_USER = (localStorage.getItem(\"username\") || \"\")\n.replace(/\\s/g,'')\n.trim()\n.toLowerCase();\n/* ================= أدوات ================= */\nfunction norm(v){\n  return String(v || \"\").trim().toLowerCase();\n}\n\nfunction getCurrentRole(){\n  return (function(){const r=prudleQuizRoles();return r.includes(\"admin\")?\"admin\":r.includes(\"trainer\")?\"trainer\":String(localStorage.getItem(\"role\")||\"\").trim().toLowerCase()})()\n}\n\nfunction getCurrentUsername(){\n  return String(\n    localStorage.getItem(\"username\") || \"\"\n  )\n  .replace(/\\s+/g,\"\")\n  .trim()\n  .toLowerCase();\n}\n\nfunction canViewAllOpenCourses(){ return true; }\n\n/* =========================================\n   صلاحيات مهارات الدورات حسب حساب المدرب\n========================================= */\nfunction normalizeTrainerUser(value){\n  return String(value || \"\")\n    .replace(/\\s+/g,\"\")\n    .trim()\n    .toLowerCase();\n}\n\nfunction isAdminUser(){ return true; }\n\nfunction canEditTrainerCourseSkill(trainerName){ return true; }\n\nasync function verifyCourseSkillPermission(courseId){ return {allowed:true,trainer:\"\"}; }\n\nfunction isCourseVisibleForCurrentUser(course){\n  if(canViewAllOpenCourses()){\n    return true;\n  }\n\n  const trainerName = String(\n    course?.Trainer ||\n    course?.trainer ||\n    course?.TrainerName ||\n    course?.trainerName ||\n    \"\"\n  )\n  .replace(/\\s+/g,\"\")\n  .trim()\n  .toLowerCase();\n\n  const currentUsername = getCurrentUsername();\n\n  if(!currentUsername){\n    return false;\n  }\n\n  return trainerName === currentUsername;\n}\n\nfunction isOpenCourse(course){\n  const status = norm(course?.status);\n  return [\"open\",\"مفتوح\"].includes(status);\n}\n\n/* =========================================\n   Linked-course access: current user only\n   Admin keeps access to all courses.\n========================================= */\nfunction getLinkedCoursesForCurrentUser(coursesUsed, currentCourseId = \"\"){\n  const currentId = String(currentCourseId || \"\").trim();\n\n  return dedupeCoursesUsed(\n    Array.isArray(coursesUsed) ? coursesUsed : []\n  ).filter(course => {\n    const courseId = String(course?.courseId || \"\").trim();\n\n    if(!courseId || courseId === currentId){\n      return false;\n    }\n\n    return isCourseVisibleForCurrentUser(course);\n  });\n}\n\nasync function verifyLinkedCourseAccess(courseId){\n  courseId = String(courseId || \"\").trim();\n\n  if(!courseId){\n    return { allowed:false, course:null };\n  }\n\n  if(canViewAllOpenCourses()){\n    const adminDoc = await db.collection(\"Courses\").doc(courseId).get();\n    return {\n      allowed: adminDoc.exists,\n      course: adminDoc.exists ? (adminDoc.data() || {}) : null\n    };\n  }\n\n  const courseDoc = await db.collection(\"Courses\")\n    .doc(courseId)\n    .get();\n\n  if(!courseDoc.exists){\n    return { allowed:false, course:null };\n  }\n\n  const course = courseDoc.data() || {};\n\n  return {\n    allowed: isCourseVisibleForCurrentUser(course),\n    course\n  };\n}\nfunction normalizeTextAnswer(val){\n  return String(val || \"\")\n    .replace(/[^\\w\\s\\u0600-\\u06FF]/g, \"\") // حذف الرموز\n    .replace(/\\s+/g, \" \")                 // توحيد المسافات\n    .trim()\n    .toLowerCase();\n}\nfunction sameType(courseType, filterType){\n  const c = norm(courseType);\n  const f = norm(filterType);\n\n  if(!f) return true;\n\n  const onlineAliases = [\"online\",\"اونلاين\",\"أونلاين\",\"online course\",\"remote\"];\n  const offlineAliases = [\"offline\",\"حضوري\",\"in person\",\"onsite\"];\n\n  if(f === \"online\" && onlineAliases.includes(c)) return true;\n  if(f === \"offline\" && offlineAliases.includes(c)) return true;\n\n  return false;\n}\n\nfunction esc(str){\n\n  return String(str || \"\")\n\n    // تنظيف الرموز الغريبة فقط\n    .replace(/□/g, \"\")\n    \n\n    // حماية HTML\n    .replaceAll(\"&\",\"&amp;\")\n    .replaceAll(\"<\",\"&lt;\")\n    .replaceAll(\">\",\"&gt;\")\n    .replaceAll('\"',\"&quot;\")\n    .replaceAll(\"'\",\"&#39;\");\n\n}\nfunction getDuration(){\n  const hh = Math.max(Number(h.value || 0), 0);\n  const mm = Math.max(Number(m.value || 0), 0);\n  const ss = Math.max(Number(s.value || 0), 0);\n  return (hh * 3600) + (mm * 60) + ss;\n}\n\nfunction secondsToHMS(total){\n  total = Number(total || 0);\n  const hh = Math.floor(total / 3600);\n  const mm = Math.floor((total % 3600) / 60);\n  const ss = total % 60;\n  return `${hh}س ${mm}د ${ss}ث`;\n}\n\nfunction getOptions(){\n\n  /*\n    Rearrange has its own dynamic rows.\n    MCQ keeps the original four fixed option fields.\n  */\n  if(\n    document.getElementById(\"qType\")?.value === \"order\"\n  ){\n    return getRearrangeRows()\n      .map(row =>\n        String(\n          row.querySelector(\".rearrange-admin-input\")?.value || \"\"\n        ).trim()\n      )\n      .filter(Boolean);\n  }\n\n  return [\n    opt1.value,\n    opt2.value,\n    opt3.value,\n    opt4.value\n  ]\n    .map(v => String(v || \"\").trim())\n    .filter(v => v);\n}\n\nfunction renderMedia(mediaType, mediaUrl){\n  if(!mediaUrl || mediaType === \"none\") return \"\";\n\n  if(mediaType === \"image\"){\n    return `<div class=\"media-box\"><img src=\"${mediaUrl}\" alt=\"image\"></div>`;\n  }\n\n  if(mediaType === \"video\"){\n    return `<div class=\"media-box\"><video controls src=\"${mediaUrl}\"></video></div>`;\n  }\n\n  if(mediaType === \"audio\"){\n    return `<div class=\"media-box\"><audio controls src=\"${mediaUrl}\"></audio></div>`;\n  }\n\n  return \"\";\n}\n\nfunction clearForm(){\n  EDIT_QUESTION_ID = null;\n  question.value = \"\";\n  opt1.value = \"\";\n  opt2.value = \"\";\n  opt3.value = \"\";\n  opt4.value = \"\";\n  correct.value = \"\";\n  degree.value = \"\";\n  mediaType.value = \"none\";\n  file.value = \"\";\n\n  const mediaUrlField =\n    document.getElementById(\"mediaUrlInput\");\n\n  if(mediaUrlField){\n    mediaUrlField.value = \"\";\n  }\n\n  clearMatchingRows();\n  resetRearrangeItems([]);\n  resetFillItems();\n\n  const textAnswerLinesField =\n    document.getElementById(\"textAnswerLines\");\n\n  if(textAnswerLinesField){\n    textAnswerLinesField.value = 4;\n  }\n\n  qType.value = \"mcq\";\n  toggleQuestionType();\n}\nfunction toggleCourseBtn(btn){\n\n  const selected =\n    btn.dataset.selected === \"true\";\n\n  if(selected){\n\n    btn.dataset.selected = \"false\";\n    btn.classList.remove(\"on\");\n    btn.classList.add(\"off\");\n    btn.innerHTML = \"Not selected\";\n\n  }else{\n\n    btn.dataset.selected = \"true\";\n    btn.classList.remove(\"off\");\n    btn.classList.add(\"on\");\n    btn.innerHTML = \"Selected\";\n\n  }\n\n}\nfunction dedupeCoursesUsed(list){\n  const seen = new Set();\n  const out = [];\n\n  (list || []).forEach(item=>{\n    const key = `${item.courseId || \"\"}__${item.TrainingCourse || \"\"}__${item.Trainer || \"\"}`;\n    if(!seen.has(key)){\n      seen.add(key);\n      out.push(item);\n    }\n  });\n\n  return out;\n}\nasync function toggleShuffle(){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n    alert(\"اختر الاختبار أولاً\");\n    return;\n  }\n\n  const ref = db.collection(\"exams\").doc(examId);\n  const docSnap = await ref.get();\n\n  const current = docSnap.data().shuffleQuestions === true;\n\n  await ref.update({\n    shuffleQuestions: !current\n  });\n\n  alert(current ? \"تم إيقاف الخلط\" : \"تم تفعيل الخلط\");\n\n  // □ التحديث الفوري (هذا المهم)\n  await loadQuestions();\n}\nasync function toggleOnePageMode(){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n    alert(\"اختر الاختبار أولاً\");\n    return;\n  }\n\n  const ref = db.collection(\"exams\").doc(examId);\n  const docSnap = await ref.get();\n\n  if(!docSnap.exists){\n    alert(\"الاختبار غير موجود\");\n    return;\n  }\n\n  const current = docSnap.data().onePageQuestions === true;\n\n  await ref.update({\n    onePageQuestions: !current\n  });\n\n  alert(current ? \"تم إيقاف عرض كل الأسئلة في صفحة واحدة\" : \"تم تفعيل عرض كل الأسئلة في صفحة واحدة\");\n\n  await loadQuestions();\n}\n/* ================= الفلاتر ================= */\nasync function loadFilters(){\n  const snap = await db.collection(\"Courses\").get();\n\n  const branches = new Set();\n  const sections = new Set();\n\n  snap.forEach(doc=>{\n    const c = doc.data();\n    if(c.Branch) branches.add(c.Branch);\n    if(c.Section) sections.add(c.Section);\n  });\n\n  branchFilter.innerHTML = `<option value=\"\">All Branch</option>`;\n  [...branches].sort().forEach(v=>{\n    branchFilter.innerHTML += `<option value=\"${esc(v)}\">${esc(v)}</option>`;\n  });\n\n  sectionFilter.innerHTML = `<option value=\"\">All Section</option>`;\n  [...sections].sort().forEach(v=>{\n    sectionFilter.innerHTML += `<option value=\"${esc(v)}\">${esc(v)}</option>`;\n  });\n}\n\nasync function loadCourses(){\n\n  const box = document.getElementById(\"coursesBox\");\n\n  const search = (\n    document.getElementById(\"courseSearch\")?.value || \"\"\n  ).toLowerCase().trim();\n\n  const sort =\n    document.getElementById(\"courseSort\")?.value || \"az\";\n\n  const snap = await db.collection(\"Courses\").get();\n\n  if(snap.empty){\n    box.innerHTML = \"لا توجد دورات\";\n    return;\n  }\n\n  let courses = [];\n\n  snap.forEach(doc=>{\n\n    const c = doc.data();\n\n    const status = norm(c.status);\n\n    const openStatuses = [\"open\", \"مفتوح\"];\n\n    // ✅ فقط الدورات المفتوحة\n    if(!openStatuses.includes(status)) return;\n\n    // ✅ الفلاتر\n    if(branchFilter.value && c.Branch !== branchFilter.value) return;\n\n    if(sectionFilter.value && c.Section !== sectionFilter.value) return;\n\n    const typeValue =\n      document.getElementById(\"typeFilter\")?.value || \"\";\n\n    if(!sameType(c.CourseType, typeValue)) return;\n\n    const courseName = String(c.TrainingCourse || \"\");\n    const trainerName = String(c.Trainer || \"\");\n\n    // ✅ البحث\n    if(search){\n\n      const txt = `\n        ${courseName}\n        ${trainerName}\n        ${c.Branch || \"\"}\n        ${c.Section || \"\"}\n      `.toLowerCase();\n\n      if(!txt.includes(search)) return;\n    }\n\n    // الأدمن يرى جميع الدورات المفتوحة.\n    // المدرب يرى الدورات المفتوحة المرتبطة بحسابه فقط.\n    if(!isCourseVisibleForCurrentUser(c)){\n      return;\n    }\n\ncourses.push({\n  id: doc.id,\n  TrainingCourse: courseName,\n  Trainer: trainerName,\n  Period: c.Period || \"\"\n});\n  });\n\n  // ================= الفرز =================\n\n  if(sort === \"az\"){\n    courses.sort((a,b)=>\n      a.TrainingCourse.localeCompare(b.TrainingCourse)\n    );\n  }\n\n  if(sort === \"za\"){\n    courses.sort((a,b)=>\n      b.TrainingCourse.localeCompare(a.TrainingCourse)\n    );\n  }\n\n  if(sort === \"trainer\"){\n    courses.sort((a,b)=>\n      a.Trainer.localeCompare(b.Trainer)\n    );\n  }\n\n  // ================= العرض =================\n\n  let html = \"\";\n\n  courses.forEach(c=>{\n\n    html += `\n      <label style=\"\n        display:block;\n        padding:8px;\n        border-radius:10px;\n        margin-bottom:6px;\n        background:#fff;\n        border:1px solid #eee;\n        cursor:pointer;\n      \">\n\n  <button\n  type=\"button\"\n  class=\"course-select-btn off\"\n  data-id=\"${c.id}\"\n  data-selected=\"false\"\n  onclick=\"toggleCourseBtn(this)\"\n>\n  Not selected\n</button>\n\n${esc(c.TrainingCourse || \"-\")}\n|\n${esc(c.Trainer || \"-\")}\n${c.Period ? ` | ${esc(c.Period)}` : \"\"}\n      </label>\n    `;\n  });\n\n  box.innerHTML = html || \"لا توجد دورات مطابقة\";\n}\n/* ================= الاختبارات ================= */\nasync function createExam(){\n\n  const title = String(examTitle.value || \"\").trim();\n  const duration = getDuration();\nconst examCategory =\n  document.getElementById(\"examCategory\").value;\n\nif(!examCategory){\n  return alert(\"اختر نوع الاختبار\");\n}\n  // □ جمع الدورات المختارة\n  const selectedCourses = [];\n document.querySelectorAll(\".course-select-btn\").forEach(btn=>{\n\n  if(btn.dataset.selected === \"true\"){\n    selectedCourses.push(btn.dataset.id);\n  }\n\n});\n\n  if(selectedCourses.length === 0){\n    return alert(\"اختر دورة واحدة على الأقل\");\n  }\n\n  if(!title) return alert(\"name of the quiz\");\n  if(duration <= 0) return alert(\"time for the exam\");\n\n  // □ جلب بيانات الدورات\n  const coursesData = [];\n\n  for(const id of selectedCourses){\n    const doc = await db.collection(\"Courses\").doc(id).get();\n\n    if(doc.exists){\n      const c = doc.data();\n\ncoursesData.push({\n  courseId: id,\n  TrainingCourse: c.TrainingCourse || \"\",\n  Trainer: c.Trainer || \"\",\n  Period: c.Period || \"\"\n});}\n  }\n// ✅ جمع الاختبارات المختارة للنسخ منها\nconst selectedExamIds = [];\n\ndocument.querySelectorAll(\".examCheck:checked\").forEach(cb => {\n  selectedExamIds.push(cb.value);\n});\n\nconst newExamRef = await db.collection(\"exams\").add({\n\n  isHomework: false,\n\n  title: title,\nexamCategory: examCategory,\n  duration: duration,\n\n  courseIds: selectedCourses,\n\n  coursesData: coursesData,\n\n  // ✅ الاختبارات التي سيتم النسخ منها\n  linkedExams: selectedExamIds,\n\n  createdAt: new Date()\n\n});  const newExamId = newExamRef.id;\n// ✅ نسخ الأسئلة من الاختبارات المختارة\nfor(const oldExamId of selectedExamIds){\n\n  const qSnap = await db.collection(\"questions\")\n    .where(\"examId\",\"==\",oldExamId)\n    .get();\n\n  for(const doc of qSnap.docs){\n\n    const q = doc.data();\n\nawait db.collection(\"questions\").add({\n\n  examId: newExamId,\n\n  question: q.question || \"\",\n\n  passage: q.passage || \"\",\n  passageHtml: q.passageHtml || \"\",\n  passageAlign: [\"left\",\"center\",\"right\"].includes(q.passageAlign) ? q.passageAlign : \"left\",\n\n  /*\n    السؤال المنسوخ يعتبر نموذجًا جديدًا ومستقلًا:\n    لا يرث القفل من السؤال الأصلي.\n  */\n  locked:false,\n  lockedAt:null,\n  lockedBy:\"\",\n  lockReason:\"\",\n\n  options: q.options || [],\n\n  correct: q.correct ?? \"\",\n\n  degree: q.degree || 1,\n\n  type: q.type || \"mcq\",\n\n  mediaType: q.mediaType || \"none\",\n\n  mediaUrl: q.mediaUrl || \"\",\n\n  group: q.group || \"General\",\n\n  showMedia: q.showMedia !== false,\n\n  order: q.order || 0,\n\n  isMain: q.isMain || false,\n\n  coursesUsed: (coursesData || []).map(c => ({\n\n    courseId: c.courseId,\n\n    TrainingCourse: c.TrainingCourse,\n\n    Trainer: c.Trainer,\n\n    Period: c.Period || \"\"\n\n  })),\n\n  linkedExams: selectedExamIds,\n\n  createdAt: new Date()\n\n});\n  }\n\n}\n  // □ نسخ الأسئلة من الاختبارات المختارة\n\n  // □ عرض الاختبار الجديد مباشرة بدون تحديث الصفحة\nselectPreviewExam(newExamId);\n  // □ عرض الأسئلة فورًا\n  await loadQuestions();\n\n  alert(\"✅ تم إنشاء الاختبار ونسخ الأسئلة بنجاح\");\n\n  // □ تفريغ الحقول\nexamTitle.value = \"\";\nh.value = \"\";\nm.value = \"\";\ns.value = \"\";\n\ndocument.getElementById(\"examCategory\").value = \"\";\n\n document.querySelectorAll(\".course-select-btn\").forEach(btn=>{\n\n  btn.dataset.selected = \"false\";\n  btn.classList.remove(\"on\");\n  btn.classList.add(\"off\");\n  btn.innerHTML = \"Not selected\";\n\n});\n  document.querySelectorAll(\".examCheck\").forEach(cb=> cb.checked = false);\n\n  // □ تحديث قائمة الاختبارات فقط\n  await loadExams();\n} let EXAMS_DROPDOWN = [];\n\nasync function loadExams(){\n\n  const examSelect = document.getElementById(\"examSelect\");\n\n  try{\n\n    const snap = await db.collection(\"exams\")\n      .orderBy(\"createdAt\",\"desc\")\n      .get();\n\n    // □ إعادة تعيين القائمة\n    examSelect.innerHTML = `<option value=\"\">choose the exam</option>`;\n\n    EXAMS_DROPDOWN = [];\n\n    // ❌ لا توجد اختبارات\n    if(snap.empty){\n      examSelect.innerHTML = `<option value=\"\">No exams</option>`;\n\n      const previewBox = document.getElementById(\"examPreviewBox\");\n      if(previewBox){\n        previewBox.innerHTML = \"لا توجد اختبارات\";\n      }\n\n      return;\n    }\n\n    // □ تعبئة البيانات\n    snap.forEach(d=>{\n      const e = d.data();\n\nconst coursesText = Array.isArray(e.coursesData)\n  ? e.coursesData.map(c => c.TrainingCourse || \"\").filter(Boolean).join(\" / \")\n  : (e.TrainingCourse || \"\");\n\nconst trainersText = Array.isArray(e.coursesData)\n  ? e.coursesData.map(c => c.Trainer || \"\").filter(Boolean).join(\" / \")\n  : (e.Trainer || \"\");\n\nconst periodsText = Array.isArray(e.coursesData)\n  ? e.coursesData.map(c => c.Period || \"\").filter(Boolean).join(\" / \")\n  : \"\";\n\nconst item = {\n  id: d.id,\n  title: String(e.title || \"\"),\n  examCategory: e.examCategory || \"\",\n  course: String(coursesText || \"\"),\n  trainer: String(trainersText || \"\"),\n  period: String(periodsText || \"\"),\n  hasLockedQuestions: e.hasLockedQuestions === true,\n  createdAt: e.createdAt?.seconds || 0\n};\n      // □ تخزين للكاش (للبحث)\n      EXAMS_DROPDOWN.push(item);\n// ✅ بنك الاختبارات للنسخ\nconst bank =\n  document.getElementById(\"examBank\");\n\n// ✅ تنظيف البنك قبل إعادة التحميل\nif(bank){\n  bank.innerHTML = \"\";\n}\nif(bank){\n\n  bank.innerHTML += `\n\n    <label style=\"\n      display:block;\n      padding:10px;\n      margin-bottom:8px;\n      border-radius:12px;\n      background:#fff;\n      border:1px solid #eee;\n      cursor:pointer;\n    \">\n\n      <input\n        type=\"checkbox\"\n        class=\"examCheck\"\n        value=\"${d.id}\"\n        style=\"margin-left:8px\"\n      >\n\n      ${esc(item.title)}\n      |\n      ${esc(item.course)}\n      |\n      ${esc(item.trainer)}\n\n    </label>\n\n  `;\n}\n\n      // □ قائمة الإنشاء / التعديل\n      examSelect.innerHTML += `\n        <option value=\"${item.id}\">\n          ${esc(item.title)} | ${esc(item.course)} | ${esc(item.trainer)}\n        </option>\n      `;\n    });\n\n    // □ عرض مباشر في Preview\n    filterExamDropdown(\n      document.getElementById(\"previewExamSearch\")?.value || \"\"\n    );\nfilterExamBank();\n\n  }catch(err){\n    console.error(err);\n\n    examSelect.innerHTML = `<option value=\"\">Error loading exams</option>`;\n\n    const previewBox = document.getElementById(\"examPreviewBox\");\n    if(previewBox){\n      previewBox.innerHTML = \"❌ Error loading exams\";\n    }\n  }\n}\nfunction filterExamBank(){\n\n  const search =\n    (\n      document.getElementById(\"examSearchTop\")?.value || \"\"\n    ).toLowerCase().trim();\n\n  const sort =\n    document.getElementById(\"examSortTop\")?.value || \"new\";\n\n  let list = [...EXAMS_DROPDOWN];\n\n  // ✅ البحث\n  if(search){\n\n    list = list.filter(e => {\n\n      return (\n        (e.title || \"\").toLowerCase().includes(search) ||\n        (e.course || \"\").toLowerCase().includes(search) ||\n        (e.trainer || \"\").toLowerCase().includes(search)\n      );\n\n    });\n\n  }\n\n  // ✅ الفرز\n  if(sort === \"new\"){\n    list.sort((a,b)=> b.createdAt - a.createdAt);\n  }\n\n  if(sort === \"old\"){\n    list.sort((a,b)=> a.createdAt - b.createdAt);\n  }\n\n  if(sort === \"az\"){\n    list.sort((a,b)=>\n      a.title.localeCompare(b.title)\n    );\n  }\n\n  if(sort === \"za\"){\n    list.sort((a,b)=>\n      b.title.localeCompare(a.title)\n    );\n  }\n\n  const bank =\n    document.getElementById(\"examBank\");\n\n  if(!bank) return;\n\n  let html = \"\";\n\n  list.forEach(e => {\n\n    html += `\n\n      <label style=\"\n        display:block;\n        padding:10px;\n        margin-bottom:8px;\n        border-radius:12px;\n        background:#fff;\n        border:1px solid #eee;\n        cursor:pointer;\n      \">\n\n        <input\n          type=\"checkbox\"\n          class=\"examCheck\"\n          value=\"${e.id}\"\n          style=\"margin-left:8px\"\n        >\n\n        ${esc(e.title)}\n        |\n        ${esc(e.course)}\n        |\n        ${esc(e.trainer)}\n\n      </label>\n\n    `;\n\n  });\n\n  bank.innerHTML =\n    html || \"No exams\";\n\n}\n\nfunction getExamCategoryLabel(category){\n  const labels = {\n    midterm: \"Midterm\",\n    finalExam: \"Final Exam\",\n    listening: \"Listening\",\n    speaking: \"Speaking\",\n    quizEvaluation: \"Quiz and Evaluation\"\n  };\n  return labels[category] || \"Select Exam Type\";\n}\n\nfunction getExamCategoryColor(category){\n  const colors = {\n    midterm: \"#f59e0b\",\n    finalExam: \"#dc2626\",\n    listening: \"#0ea5e9\",\n    speaking: \"#16a34a\",\n    quizEvaluation: \"#8b5cf6\"\n  };\n  return colors[category] || \"#164478\";\n}\n\nasync function changeExamCategory(examId, newCategory, selectElement){\n  const category = String(newCategory || \"\").trim();\n\n  if(!category){\n    alert(\"اختر نوع الاختبار\");\n    return;\n  }\n\n  if(selectElement){\n    selectElement.disabled = true;\n  }\n\n  try{\n    await db.collection(\"exams\").doc(examId).update({\n      examCategory: category,\n      updatedAt: new Date()\n    });\n\n    const item = EXAMS_DROPDOWN.find(exam => exam.id === examId);\n    if(item){\n      item.examCategory = category;\n    }\n\n    // تحديث لون البطاقة مباشرة\n    const card = document.querySelector(`.exam-card[data-id=\"${examId}\"]`);\n    const color = getExamCategoryColor(category);\n\n    if(card){\n      const sideBar = card.querySelector(\".exam-category-side\");\n      const titleBox = card.querySelector(\".exam-category-title\");\n      const titleInput = card.querySelector(\".exam-title-input\");\n\n      if(sideBar) sideBar.style.background = color;\n      if(titleBox) titleBox.style.color = color;\n      if(titleInput){\n        titleInput.style.borderColor = color;\n        titleInput.style.color = color;\n      }\n    }\n\n    alert(\"✅ تم تغيير نوع الاختبار بنجاح\");\n\n  }catch(err){\n    console.error(err);\n    alert(\"❌ تعذر تغيير نوع الاختبار\");\n    await loadExams();\n  }finally{\n    if(selectElement){\n      selectElement.disabled = false;\n    }\n  }\n}\n\nfunction filterExamDropdown(inputValue){\n\n  let search = \"\";\n\n  if(typeof inputValue === \"string\"){\n    search = inputValue.toLowerCase().trim();\n  }else{\n    search = document.getElementById(\"previewExamSearch\")?.value.toLowerCase().trim() || \"\";\n  }\n\n  const sort = document.getElementById(\"examFilterSort\")?.value || \"new\";\n\n  let list = [...EXAMS_DROPDOWN];\n\n  // البحث\n  if(search){\n    list = list.filter(e =>\n      (e.title || \"\").toLowerCase().includes(search) ||\n      (e.course || \"\").toLowerCase().includes(search) ||\n      (e.trainer || \"\").toLowerCase().includes(search)\n    );\n  }\n\n  // الفرز\n  if(sort === \"new\") list.sort((a,b)=> b.createdAt - a.createdAt);\n  if(sort === \"old\") list.sort((a,b)=> a.createdAt - b.createdAt);\n  if(sort === \"az\") list.sort((a,b)=> a.title.localeCompare(b.title));\n  if(sort === \"za\") list.sort((a,b)=> b.title.localeCompare(a.title));\n\n  const box = document.getElementById(\"examPreviewBox\");\n\n  let html = `\n    <div style=\"\n      display:grid;\n      grid-template-columns:repeat(auto-fill,minmax(340px,1fr));\n      gap:14px;\n    \">\n  `;\n\n  list.forEach(e=>{\nlet cardColor = getExamCategoryColor(e.examCategory);\nhtml += `\n\n<div class=\"exam-card\"\n  data-id=\"${e.id}\"\n  onclick=\"SIDEBAR_FOCUS_COURSE_ID=''; openExamTab('${e.id}', true)\"\n  style=\"\n    background:#fff;\n    border:2px solid #dbeafe;\n    border-radius:22px;\n    padding:18px;\n    cursor:pointer;\n    transition:.25s;\n    box-shadow:0 6px 18px rgba(0,0,0,.06);\n    position:relative;\n    overflow:hidden;\n  \">\n\n  <div class=\"exam-category-side\" style=\"\n    position:absolute;\n    top:0;\n    right:0;\n    width:8px;\n    height:100%;\n    background:${cardColor};\n  \"></div>\n\n<div class=\"exam-category-title\" style=\"\n  font-size:20px;\n  font-weight:900;\n  color:${cardColor};\n  margin-bottom:14px;\n  text-align:center;\n  line-height:1.6;\n\">\n\n  ${esc(e.title || \"-\")}\n<input\n  class=\"exam-title-input\"\n  value=\"${esc(e.title || \"\")}\"\n\n  onclick=\"event.stopPropagation()\"\n\n  onchange=\"renameExam('${e.id}', this.value)\"\n\n  ${\n    (\n      false\n    )\n      ? \"disabled\"\n      : \"\"\n  }\n\n  style=\"\n    margin-top:10px;\n    text-align:center;\n\n    border:2px solid ${\n      (\n        false\n      )\n        ? '#991b1b'\n        : cardColor\n    };\n\n    color:${\n      (\n        false\n      )\n        ? '#991b1b'\n        : cardColor\n    };\n\n    background:${\n      (\n        false\n      )\n        ? '#fee2e2'\n        : '#fff'\n    };\n\n    font-weight:900;\n\n    cursor:${\n      (\n        false\n      )\n        ? 'not-allowed'\n        : 'text'\n    };\n  \"\n>\n\n<select\n  aria-label=\"Change Exam Type\"\n  onclick=\"event.stopPropagation()\"\n  onchange=\"event.stopPropagation(); changeExamCategory('${e.id}', this.value, this)\"\n  style=\"\n    margin-top:10px;\n    border:2px solid ${cardColor};\n    color:${cardColor};\n    background:#fff;\n    font-weight:900;\n    text-align:center;\n    direction:ltr;\n    cursor:pointer;\n  \"\n>\n  <option value=\"\" ${!e.examCategory ? \"selected\" : \"\"}>Select Exam Type</option>\n  <option value=\"midterm\" ${e.examCategory === \"midterm\" ? \"selected\" : \"\"}>Midterm</option>\n  <option value=\"finalExam\" ${e.examCategory === \"finalExam\" ? \"selected\" : \"\"}>Final Exam</option>\n  <option value=\"listening\" ${e.examCategory === \"listening\" ? \"selected\" : \"\"}>Listening</option>\n  <option value=\"speaking\" ${e.examCategory === \"speaking\" ? \"selected\" : \"\"}>Speaking</option>\n  <option value=\"quizEvaluation\" ${e.examCategory === \"quizEvaluation\" ? \"selected\" : \"\"}>Quiz and Evaluation</option>\n</select>\n\n<div style=\"\n  margin-top:8px;\n  font-size:15px;\n  color:#6b7280;\n  font-weight:700;\n\">\n  ${esc(e.course || \"-\")}\n</div>\n\n</div>\n\n<div style=\"\n  background:#f8fbff;\n  border:1px solid #dbeafe;\n  border-radius:16px;\n  padding:14px;\n  text-align:center;\n  line-height:2;\n  font-weight:900;\n  color:#374151;\n  font-size:16px;\n\">\n\n  ${esc(e.trainer || \"-\")}\n\n  <br>\n\n  ⏰ ${esc(e.period || \"-\")}\n<br>\n\n\n</div>\n<div class=\"exam-actions\" onclick=\"event.stopPropagation()\">\n\n  <button\n    class=\"preview-btn\"\n    onclick=\"\n      event.stopPropagation();\n      SIDEBAR_FOCUS_COURSE_ID = \"\";\n      openExamTab('${e.id}', true);\n    \"\n  >\n    □ Show Below\n  </button>\n\n  <button\n    class=\"preview-btn\"\n    onclick=\"\n      event.stopPropagation();\n      openFullQuestions('${e.id}');\n    \"\n  >\n    □ View All\n  </button>\n\n</div>\n</div>\n`;  \n});\n  html += `</div>`;\n\n  box.innerHTML = html || \"لا توجد نتائج\";\n}\nfunction changeCourseTab(courseId){\n\n  // الانتقال اليدوي بين الدورات يعيد العرض العادي\n  SIDEBAR_FOCUS_COURSE_ID = \"\";\n  SIDEBAR_SHOW_FULL_EXAM = false;\n  CURRENT_COURSE_ID = courseId;\n\n  // ✅ أي دورة يختارها المدرب تصبح سياق الطباعة الحالي\n  PRINT_CONTEXT_COURSE_ID =\n    String(courseId || \"\").trim();\n\n  try{\n    sessionStorage.setItem(\n      \"prudlePrintCourseId\",\n      PRINT_CONTEXT_COURSE_ID\n    );\n  }catch(_){}\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n    alert(\"اختر الاختبار أولاً\");\n    return;\n  }\n\n  openExamTab(examId, false);\n}async function openExamTab(\n  examId,\n  resetCourse = true\n){\n\n  CURRENT_PREVIEW_EXAM = examId;\n// ✅ ربط الأسئلة بهذه الدورة\n\n\n  // ✅ تلوين الكروت\n  document.querySelectorAll(\".exam-card\")\n    .forEach(card=>{\n      card.style.borderColor = \"#dbeafe\";\n      card.style.background = \"#fff\";\n      card.classList.remove(\"exam-card-selected\");\n      card.removeAttribute(\"aria-current\");\n    });\n\n  const activeCard = document.querySelector(\n    `.exam-card[data-id=\"${examId}\"]`\n  );\n\n  if(activeCard){\n    activeCard.style.borderColor = \"#164478\";\n    activeCard.style.background = \"#eef5ff\";\n    activeCard.classList.add(\"exam-card-selected\");\n    activeCard.setAttribute(\"aria-current\",\"true\");\n  }\n\n  // ✅ تغيير الاختبار الحالي\n  document.getElementById(\"examSelect\").value = examId;\n\n  // =========================================\n  // ✅ تحميل بيانات الاختبار\n  // =========================================\n\n  const examDoc = await db.collection(\"exams\")\n    .doc(examId)\n    .get();\n\n  if(!examDoc.exists) return;\n\n  const examData = examDoc.data();\n\n  // =========================================\n  // ✅ reset أول مرة فقط\n  // =========================================\n\n  if(resetCourse){\n\n    // الفتح العادي من قائمة الاختبارات يلغي وضع التركيز القادم من الشريط\n    SIDEBAR_FOCUS_COURSE_ID = \"\";\n    SIDEBAR_SHOW_FULL_EXAM = false;\n\n    CURRENT_COURSE_ID = \"\";\n    CURRENT_COURSE_NAME = \"\";\n    CURRENT_TRAINER = \"\";\n    CURRENT_PERIOD = \"\";\n\n  }\n\n  // =========================================\n  // ✅ تبويبات الدورات\n  // =========================================\n\n  const tabsBox =\n    document.getElementById(\"courseTabs\");\n\n  tabsBox.innerHTML = \"\";\n\n  const rawCourses =\n    examData.coursesData || [];\n\n  /*\n    إذا فُتح الاختبار من الشريط:\n    اعرض تبويب الدورة التي ضغط عليها فقط.\n    قد تكون الدورة مرتبطة بالأسئلة وليست ضمن coursesData الأساسية،\n    لذلك نضيف بيانات CURRENT_* كخيار احتياطي.\n  */\n  let courses = rawCourses;\n\n  if(SIDEBAR_FOCUS_COURSE_ID){\n\n    const focusedFromExam =\n      rawCourses.filter(c =>\n        String(c.courseId || \"\").trim() ===\n        String(SIDEBAR_FOCUS_COURSE_ID || \"\").trim()\n      );\n\n    courses = focusedFromExam.length\n      ? focusedFromExam\n      : [{\n          courseId: SIDEBAR_FOCUS_COURSE_ID,\n          TrainingCourse: CURRENT_COURSE_NAME || \"\",\n          Trainer: CURRENT_TRAINER || \"\",\n          Period: CURRENT_PERIOD || \"\"\n        }];\n  }\n\n  // ✅ أول دورة افتراضية\n  if(!CURRENT_COURSE_ID && courses.length){\n\n    CURRENT_COURSE_ID =\n      courses[0].courseId || \"\";\n\n    CURRENT_COURSE_NAME =\n      courses[0].TrainingCourse || \"\";\n\n    CURRENT_TRAINER =\n      courses[0].Trainer || \"\";\n\n    CURRENT_PERIOD =\n      courses[0].Period || \"\";\n  }\n\n  courses.forEach(c=>{\n\n    const active =\n      CURRENT_COURSE_ID === c.courseId;\n\n    tabsBox.innerHTML += `\n\n      <div\n        onclick=\"changeCourseTab('${c.courseId}')\"\n\n        style=\"\n          padding:12px 18px;\n          border-radius:14px;\n          cursor:pointer;\n          font-weight:900;\n          border:2px solid ${active ? '#164478' : '#dbeafe'};\n          background:${active ? '#eef5ff' : '#fff'};\n          color:#164478;\n          min-width:180px;\n          text-align:center;\n          transition:.25s;\n        \"\n      >\n\n        ${esc(c.TrainingCourse || \"-\")}\n\n        <br>\n\n        <span style=\"font-size:13px\">\n          ${esc(c.Trainer || \"-\")}\n        </span>\n\n        <br>\n\n        <span style=\"font-size:13px\">\n          ⏰ ${esc(c.Period || \"-\")}\n        </span>\n\n      </div>\n      \n    `;\n  });\n\n  // ✅ تحميل الأسئلة\n  await loadQuestions();\n}\nfunction selectPreviewExam(examId){\n\n  \n\n  // إزالة التحديد القديم\n  document.querySelectorAll(\".exam-card\")\n    .forEach(card=>{\n      card.style.borderColor = \"#dbeafe\";\n      card.style.background = \"#fff\";\n    });\n\n  // تمييز الكرت المختار\n  const activeCard = document.querySelector(\n    `.exam-card[data-id=\"${examId}\"]`\n  );\n\n  if(activeCard){\n\n    activeCard.style.borderColor = \"#164478\";\n    activeCard.style.background = \"#eef5ff\";\n  }\n\n  // فتح الأسئلة\nopenExamTab(examId);}\n\nfunction passageEscapeHtml(value){\n  return String(value ?? \"\")\n    .replace(/&/g,\"&amp;\")\n    .replace(/</g,\"&lt;\")\n    .replace(/>/g,\"&gt;\")\n    .replace(/\"/g,\"&quot;\")\n    .replace(/'/g,\"&#039;\");\n}\n\nfunction passagePlainToHtml(value){\n  return passageEscapeHtml(value)\n    .replace(/\\r\\n/g,\"\\n\")\n    .replace(/\\r/g,\"\\n\")\n    .split(\"\\n\")\n    .map(line=>`<div>${line || \"<br>\"}</div>`)\n    .join(\"\");\n}\n\n/*\n  نسمح فقط بتنسيقات آمنة ومناسبة للـ Reading Passage.\n  هذا يمنع script / iframe / event handlers من الحفظ.\n*/\nfunction sanitizePassageHtml(html){\n  const source = String(html || \"\");\n\n  if(!source.trim()) return \"\";\n\n  const parser = new DOMParser();\n  const parsed = parser.parseFromString(\n    `<div id=\"passageSanitizeRoot\">${source}</div>`,\n    \"text/html\"\n  );\n\n  const root =\n    parsed.getElementById(\"passageSanitizeRoot\");\n\n  if(!root) return \"\";\n\n  const allowedTags = new Set([\n    \"DIV\",\"P\",\"BR\",\"B\",\"STRONG\",\"I\",\"EM\",\"U\",\n    \"UL\",\"OL\",\"LI\",\"SPAN\",\"FONT\"\n  ]);\n\n  const allowedTextAlign = new Set([\n    \"left\",\"center\",\"right\",\"justify\"\n  ]);\n\n  function cleanNode(node){\n    [...node.childNodes].forEach(child=>{\n\n      if(child.nodeType === Node.COMMENT_NODE){\n        child.remove();\n        return;\n      }\n\n      if(child.nodeType !== Node.ELEMENT_NODE){\n        return;\n      }\n\n      if(!allowedTags.has(child.tagName)){\n        const fragment =\n          parsed.createDocumentFragment();\n\n        while(child.firstChild){\n          fragment.appendChild(child.firstChild);\n        }\n\n        child.replaceWith(fragment);\n        return;\n      }\n\n      const textAlign =\n        String(child.style?.textAlign || \"\")\n          .toLowerCase();\n\n      const fontWeight =\n        String(child.style?.fontWeight || \"\");\n\n      const fontStyle =\n        String(child.style?.fontStyle || \"\");\n\n      const textDecoration =\n        String(child.style?.textDecoration || \"\");\n\n      const fontSize =\n        String(child.style?.fontSize || \"\");\n\n      [...child.attributes].forEach(attr=>{\n        child.removeAttribute(attr.name);\n      });\n\n      if(allowedTextAlign.has(textAlign)){\n        child.style.textAlign = textAlign;\n      }\n\n      if(\n        fontWeight === \"bold\" ||\n        Number(fontWeight) >= 600\n      ){\n        child.style.fontWeight = \"bold\";\n      }\n\n      if(fontStyle === \"italic\"){\n        child.style.fontStyle = \"italic\";\n      }\n\n      if(textDecoration.includes(\"underline\")){\n        child.style.textDecoration = \"underline\";\n      }\n\n      if(\n        /^\\d+(\\.\\d+)?(px|pt|em|rem|%)$/.test(fontSize)\n      ){\n        child.style.fontSize = fontSize;\n      }\n\n      cleanNode(child);\n    });\n  }\n\n  cleanNode(root);\n\n  return root.innerHTML.trim();\n}\n\nfunction getPassageDisplayHtml(q){\n  const html =\n    sanitizePassageHtml(q?.passageHtml || \"\");\n\n  if(html){\n    return html;\n  }\n\n  return passagePlainToHtml(\n    String(q?.passage || \"\")\n  );\n}\n\nfunction openPassageEditor(){\n  const modal =\n    document.getElementById(\"passageEditorModal\");\n\n  const editor =\n    document.getElementById(\"passageRichEditor\");\n\n  if(!modal || !editor) return;\n\n  editor.innerHTML =\n    CURRENT_PASSAGE_HTML\n      ? sanitizePassageHtml(CURRENT_PASSAGE_HTML)\n      : passagePlainToHtml(CURRENT_PASSAGE);\n\n  modal.classList.add(\"show\");\n  modal.setAttribute(\"aria-hidden\",\"false\");\n\n  setTimeout(()=>{\n    editor.focus();\n  },50);\n}\n\nfunction closePassageEditor(saveChanges=false){\n  const modal =\n    document.getElementById(\"passageEditorModal\");\n\n  if(!modal) return;\n\n  if(saveChanges){\n    savePassageEditor();\n    return;\n  }\n\n  modal.classList.remove(\"show\");\n  modal.setAttribute(\"aria-hidden\",\"true\");\n}\n\nfunction passageCommand(command,value=null){\n  const editor =\n    document.getElementById(\"passageRichEditor\");\n\n  if(!editor) return;\n\n  editor.focus();\n\n  try{\n    document.execCommand(\n      command,\n      false,\n      value\n    );\n  }catch(error){\n    console.warn(\n      \"Passage formatting command failed:\",\n      command,\n      error\n    );\n  }\n}\n\nfunction passageFontSizeChange(value){\n  if(!value) return;\n\n  passageCommand(\n    \"fontSize\",\n    value\n  );\n\n  const field =\n    document.getElementById(\"passageFontSize\");\n\n  if(field){\n    field.value = \"\";\n  }\n}\n\nfunction savePassageEditor(){\n  const editor =\n    document.getElementById(\"passageRichEditor\");\n\n  const modal =\n    document.getElementById(\"passageEditorModal\");\n\n  if(!editor || !modal) return;\n\n  const cleanHtml =\n    sanitizePassageHtml(editor.innerHTML);\n\n  const plainText =\n    String(editor.innerText || \"\")\n      .replace(/\\u00a0/g,\" \")\n      .replace(/\\n{3,}/g,\"\\n\\n\")\n      .trim();\n\n  if(!plainText){\n    CURRENT_PASSAGE = \"\";\n    CURRENT_PASSAGE_HTML = \"\";\n\n    const status =\n      document.getElementById(\n        \"passageSavedStatus\"\n      );\n\n    if(status){\n      status.style.display = \"none\";\n    }\n\n    modal.classList.remove(\"show\");\n    modal.setAttribute(\"aria-hidden\",\"true\");\n    return;\n  }\n\n  CURRENT_PASSAGE =\n    plainText;\n\n  CURRENT_PASSAGE_HTML =\n    cleanHtml;\n\n  /*\n    passageAlign يبقى للتوافق مع الأسئلة القديمة.\n    المحاذاة الجديدة يمكن أن تختلف من سطر إلى سطر\n    وتحفظ داخل passageHtml.\n  */\n  const alignField =\n    document.getElementById(\"passageAlign\");\n\n  if(alignField){\n    const firstBlock =\n      editor.querySelector(\n        \"div,p,li\"\n      );\n\n    const firstAlign =\n      String(\n        firstBlock?.style?.textAlign ||\n        editor.style.textAlign ||\n        \"left\"\n      ).toLowerCase();\n\n    alignField.value =\n      [\"left\",\"center\",\"right\"].includes(firstAlign)\n        ? firstAlign\n        : \"left\";\n  }\n\n  const status =\n    document.getElementById(\n      \"passageSavedStatus\"\n    );\n\n  if(status){\n    status.style.display =\n      \"inline-flex\";\n\n    status.textContent =\n      \"✓ Passage saved — \" +\n      plainText.split(\"\\n\").length +\n      \" line(s)\";\n  }\n\n  modal.classList.remove(\"show\");\n  modal.setAttribute(\"aria-hidden\",\"true\");\n}\n\n/* backward compatibility */\nfunction addPassage(){\n  openPassageEditor();\n}\n\n// Close by clicking outside the editor window\ndocument.addEventListener(\"click\",event=>{\n  const modal =\n    document.getElementById(\"passageEditorModal\");\n\n  if(\n    modal &&\n    modal.classList.contains(\"show\") &&\n    event.target === modal\n  ){\n    closePassageEditor(false);\n  }\n});\n\n// Escape closes the editor without saving.\ndocument.addEventListener(\"keydown\",event=>{\n  if(event.key !== \"Escape\") return;\n\n  const modal =\n    document.getElementById(\"passageEditorModal\");\n\n  if(\n    modal &&\n    modal.classList.contains(\"show\")\n  ){\n    closePassageEditor(false);\n  }\n});\n\n/* ================= Fill in the Blanks ================= */\nfunction getFillRows(){\n  return [...document.querySelectorAll(\"#fillItemsList .fill-admin-row\")];\n}\n\nfunction addFillItem(item={}){\n  const list=document.getElementById(\"fillItemsList\");\n  if(!list) return;\n  const row=document.createElement(\"div\");\n  row.className=\"fill-admin-row\";\n  row.innerHTML=`\n    <div class=\"fill-admin-index\"></div>\n    <input class=\"fill-display\" placeholder=\"Visible text / label\" value=\"${esc(item.display || item.text || \"\")}\" oninput=\"updateFillDegreeAndPreview()\">\n    <input class=\"fill-answer\" placeholder=\"Correct answer\" value=\"${esc(item.answer || \"\")}\" oninput=\"updateFillDegreeAndPreview()\">\n    <select class=\"fill-mode\" onchange=\"updateFillDegreeAndPreview()\">\n      <option value=\"blank\" ${(item.mode || (item.answer ? \"blank\":\"fixed\")) === \"blank\" ? \"selected\":\"\"}>Blank</option>\n      <option value=\"fixed\" ${(item.mode || (item.answer ? \"blank\":\"fixed\")) === \"fixed\" ? \"selected\":\"\"}>Fixed</option>\n    </select>\n    <button type=\"button\" class=\"fill-admin-delete\" onclick=\"this.closest('.fill-admin-row').remove();updateFillDegreeAndPreview()\"><i class=\"fa-solid fa-trash\"></i></button>`;\n  list.appendChild(row);\n  updateFillDegreeAndPreview();\n}\n\nfunction resetFillItems(items=[]){\n  const list=document.getElementById(\"fillItemsList\");\n  if(!list) return;\n  list.innerHTML=\"\";\n  (items.length ? items : [\n    {display:\"1\",mode:\"fixed\"},\n    {display:\"\",answer:\"\",mode:\"blank\"}\n  ]).forEach(addFillItem);\n  updateFillDegreeAndPreview();\n}\n\nfunction collectFillItems(){\n  const items=getFillRows().map((row,index)=>{\n    const display=String(row.querySelector('.fill-display')?.value || '').trim();\n    const answer=String(row.querySelector('.fill-answer')?.value || '').trim();\n    const mode=row.querySelector('.fill-mode')?.value === 'fixed' ? 'fixed' : 'blank';\n    if(mode === 'blank' && !answer){\n      throw new Error(`Enter the correct answer for blank ${index+1}.`);\n    }\n    if(mode === 'fixed' && !display){\n      throw new Error(`Enter visible text for fixed item ${index+1}.`);\n    }\n    return {display,answer,mode};\n  });\n  if(!items.length) throw new Error('Add at least one item.');\n  if(!items.some(item=>item.mode === 'blank')) throw new Error('Add at least one blank.');\n  return items;\n}\n\nfunction updateFillDegreeAndPreview(){\n  const rows=getFillRows();\n  rows.forEach(row=>{\n    const el=row.querySelector('.fill-admin-index');\n    if(el) el.textContent=\"\";\n    const mode=row.querySelector('.fill-mode')?.value || 'blank';\n    const answer=row.querySelector('.fill-answer');\n    if(answer){\n      answer.disabled=mode === 'fixed';\n      if(mode === 'fixed') answer.value='';\n    }\n  });\n  const blankCount=rows.filter(r=>(r.querySelector('.fill-mode')?.value || 'blank') === 'blank').length;\n  const note=document.getElementById('fillDegreeNote');\n  if(note){\n    const totalDegree = Number(document.getElementById(\"degree\")?.value || 0);\n    const eachDegree = blankCount > 0 && totalDegree > 0\n      ? blankCount / totalDegree\n      : 0;\n\n    note.textContent =\n      `${blankCount} blank${blankCount===1?'':'s'} ÷ ` +\n      `${formatMarkNumber(totalDegree)} total marks = ` +\n      `${formatMarkNumber(eachDegree)} marks for each correct part`;\n  }\n\n  renderFillBuilderPreview();\n}\n\nfunction renderFillBuilderPreview(){\n  const preview=document.getElementById('fillBuilderPreview');\n  if(!preview) return;\n  const layout=document.getElementById('fillLayout')?.value || 'horizontal';\n  const columns=Math.max(1,Math.min(12,Number(document.getElementById('fillColumns')?.value || 10)));\n  preview.style.gridTemplateColumns=layout === 'vertical' ? '1fr' : `repeat(${columns},minmax(0,1fr))`;\n  preview.innerHTML=getFillRows().map(row=>{\n    const display=String(row.querySelector('.fill-display')?.value || '').trim();\n    const mode=row.querySelector('.fill-mode')?.value || 'blank';\n\n    if(layout === 'vertical'){\n      if(mode === 'fixed'){\n        return `\n          <div\n            class=\"fill-preview-cell\"\n            style=\"justify-content:flex-start\">\n            ${esc(display)}\n          </div>\n        `;\n      }\n\n      return `\n        <div\n          class=\"fill-preview-cell blank\"\n          style=\"justify-content:flex-start;gap:12px\">\n          ${display ? `<strong>${esc(display)}</strong>` : \"\"}\n          <span>........................</span>\n        </div>\n      `;\n    }\n\n    return `\n      <div class=\"fill-preview-cell ${mode === 'blank' ? 'blank' : ''}\">\n        ${mode === 'blank' ? '........' : esc(display)}\n      </div>\n    `;\n  }).join('');\n\n  const blankCount =\n    getFillRows()\n      .filter(row=>\n        row.querySelector(\".fill-mode\")?.value === \"blank\"\n      )\n      .length;\n\n  const totalDegree =\n    Number(\n      document.getElementById(\"degree\")?.value || 0\n    );\n\n  const fillNote =\n    document.getElementById(\"fillDegreeNote\");\n\n  if(fillNote){\n    const eachDegree =\n      blankCount > 0 && totalDegree > 0\n        ? blankCount / totalDegree\n        : 0;\n\n    fillNote.textContent =\n      `${blankCount} blanks ÷ ` +\n      `${formatMarkNumber(totalDegree)} total marks = ` +\n      `${formatMarkNumber(eachDegree)} marks for each correct part`;\n  }\n\n  updateQuestionDegreeDistributionNote();\n}\n\nfunction getFillBlankCount(items){\n  return (Array.isArray(items)?items:[]).filter(item=>item?.mode === 'blank').length;\n}\n\n\nfunction formatMarkNumber(value){\n  const number = Number(value || 0);\n  if(!Number.isFinite(number)) return \"0\";\n  return Number(number.toFixed(4)).toString();\n}\n\nfunction getQuestionGradingParts(questionData){\n  const q = questionData || {};\n\n  if(q.type === \"match\"){\n    return Math.max(\n      1,\n      Array.isArray(q.correct)\n        ? q.correct.length\n        : 0\n    );\n  }\n\n  if(q.type === \"fill\"){\n    return Math.max(\n      1,\n      Array.isArray(q.fillItems)\n        ? q.fillItems.filter(item=>item?.mode === \"blank\").length\n        : 0\n    );\n  }\n\n  return 1;\n}\n\nfunction getQuestionDegreeDistributionText(questionData){\n  const q = questionData || {};\n  const totalDegree = Number(q.degree || 0);\n  const parts = getQuestionGradingParts(q);\n\n  if(q.type !== \"match\" && q.type !== \"fill\"){\n    return `Total: ${formatMarkNumber(totalDegree)} marks`;\n  }\n\n  const unitName =\n    q.type === \"match\"\n      ? \"matching pairs\"\n      : \"blanks\";\n\n  const eachDegree =\n    totalDegree > 0\n      ? parts / totalDegree\n      : 0;\n\n  return `${parts} ${unitName} ÷ ${formatMarkNumber(totalDegree)} total marks = ${formatMarkNumber(eachDegree)} marks for each correct part`;\n}\n\nfunction updateQuestionDegreeDistributionNote(){\n  const note =\n    document.getElementById(\"questionDegreeDistributionNote\");\n\n  if(!note) return;\n\n  const type =\n    document.getElementById(\"qType\")?.value || \"mcq\";\n\n  const totalDegree =\n    Number(\n      document.getElementById(\"degree\")?.value || 0\n    );\n\n  let parts = 1;\n  let unitName = \"question\";\n\n  if(type === \"match\"){\n    parts = Math.max(\n      1,\n      getMatchingRows()\n        .filter(row=>{\n          const left =\n            String(\n              row.querySelector(\".match-left\")?.value || \"\"\n            ).trim();\n\n          const right =\n            String(\n              row.querySelector(\".match-right\")?.value || \"\"\n            ).trim();\n\n          const image =\n            String(\n              row.querySelector(\".match-image-url\")?.value ||\n              row.dataset.uploadedUrl ||\n              \"\"\n            ).trim();\n\n          return left && (right || image);\n        })\n        .length\n    );\n\n    unitName = \"matching pairs\";\n  }\n\n  else if(type === \"fill\"){\n    parts = Math.max(\n      1,\n      getFillRows()\n        .filter(row=>\n          row.querySelector(\".fill-mode\")?.value === \"blank\"\n        )\n        .length\n    );\n\n    unitName = \"blanks\";\n  }\n\n  if(type !== \"match\" && type !== \"fill\"){\n    note.style.display = totalDegree > 0 ? \"block\" : \"none\";\n    note.textContent =\n      totalDegree > 0\n        ? `Total question marks: ${formatMarkNumber(totalDegree)}`\n        : \"\";\n    return;\n  }\n\n  note.style.display = \"block\";\n\n  const eachDegree =\n    totalDegree > 0\n      ? parts / totalDegree\n      : 0;\n\n  note.textContent =\n    `${parts} ${unitName} ÷ ` +\n    `${formatMarkNumber(totalDegree)} total marks = ` +\n    `${formatMarkNumber(eachDegree)} marks for each correct part`;\n}\n\nfunction updateQuickDegreeDistributionNote(questionId, questionType){\n  const input =\n    document.getElementById(`edit_degree_${questionId}`);\n\n  const note =\n    document.getElementById(`edit_degree_note_${questionId}`);\n\n  if(!input || !note) return;\n\n  const totalDegree =\n    Number(input.value || 0);\n\n  if(questionType !== \"match\" && questionType !== \"fill\"){\n    note.textContent =\n      `Total question marks: ${formatMarkNumber(totalDegree)}`;\n    return;\n  }\n\n  const card =\n    input.closest(\".pro-question-card\");\n\n  let parts = 1;\n\n  if(card){\n    const storedParts =\n      Number(card.dataset.gradingParts || 0);\n\n    if(storedParts > 0){\n      parts = storedParts;\n    }\n  }\n\n  const eachDegree =\n    totalDegree > 0\n      ? parts / totalDegree\n      : 0;\n\n  note.textContent =\n    `${parts} parts ÷ ` +\n    `${formatMarkNumber(totalDegree)} total marks = ` +\n    `${formatMarkNumber(eachDegree)} marks for each correct part`;\n}\n\n/* ================= نوع السؤال ================= */\nfunction toggleQuestionType(){\n\n  const type = qType.value;\n\n  setTimeout(()=>{\n    updateQuestionDegreeDistributionNote();\n  },0);\n\n  const matchingBox =\n    document.getElementById(\"matchingBox\");\n\n  const matchingSection =\n    document.getElementById(\"matchingSection\");\n  const fillBlanksBox = document.getElementById(\"fillBlanksBox\");\n  const textAnswerLinesBox = document.getElementById(\"textAnswerLinesBox\");\n\n  const rearrangeSection =\n    document.getElementById(\"rearrangeSection\");\n  degree.readOnly = false;\n\n  correctBox.classList.add(\"hidden\");\n  orderNote.classList.add(\"hidden\");\n  orderPreview.classList.add(\"hidden\");\n  optionsBox.classList.remove(\"hidden\");\n\n  if(matchingBox){\n    matchingBox.classList.remove(\"show\");\n  }\n\n  if(matchingSection){\n    matchingSection.classList.remove(\"show\");\n    matchingSection.style.display = \"none\";\n  }\n  if(fillBlanksBox){\n    fillBlanksBox.classList.remove(\"show\");\n  }\n\n  if(rearrangeSection){\n    rearrangeSection.classList.remove(\"show\");\n    rearrangeSection.style.display = \"none\";\n  }\n\n  if(textAnswerLinesBox){\n    textAnswerLinesBox.classList.add(\"hidden\");\n  }\n\n  correct.value = \"\";\n\n  if(type === \"mcq\"){\n\n    optionsBox.classList.remove(\"hidden\");\n    correctBox.classList.remove(\"hidden\");\n\n    correct.type = \"number\";\n    correct.placeholder =\n      \"Correct answer number (0-3)\";\n  }\n\n  if(type === \"order\"){\n\n    /*\n      Rearrange no longer uses the fixed MCQ option inputs.\n      It has its own dynamic item builder.\n    */\n    optionsBox.classList.add(\"hidden\");\n\n    if(rearrangeSection){\n      rearrangeSection.classList.add(\"show\");\n      rearrangeSection.style.display = \"block\";\n    }\n\n    if(!getRearrangeRows().length){\n      resetRearrangeItems([]);\n    }\n\n    orderNote.classList.remove(\"hidden\");\n    orderPreview.classList.remove(\"hidden\");\n  }\n\n  if(type === \"text\"){\n\n    optionsBox.classList.add(\"hidden\");\n    correctBox.classList.remove(\"hidden\");\n\n    if(textAnswerLinesBox){\n      textAnswerLinesBox.classList.remove(\"hidden\");\n    }\n\n    correct.type = \"text\";\n    correct.placeholder =\n      \"Enter the correct answer. Separate alternatives with commas.\";\n  }\n\n  if(type === \"match\"){\n\n    optionsBox.classList.add(\"hidden\");\n    degree.readOnly = false;\n    correctBox.classList.add(\"hidden\");\n\n    if(matchingBox){\n      matchingBox.classList.add(\"show\");\n    }\n\n    if(matchingSection){\n      matchingSection.classList.add(\"show\");\n      matchingSection.style.display = \"block\";\n    }\n\n    if(!getMatchingRows().length){\n      resetMatchingRows([]);\n    }\n\n    orderNote.classList.remove(\"hidden\");\n\n    orderNote.innerHTML =\n      \"Enter the left word, then add either a matching word/text or an image using URL/upload. One mark is assigned to each pair.\";\n    collectMatchingPairsForDegree();\n  }\n\n  if(type === \"fill\"){\n    optionsBox.classList.add(\"hidden\");\n    correctBox.classList.add(\"hidden\");\n    degree.readOnly = false;\n    if(fillBlanksBox) fillBlanksBox.classList.add(\"show\");\n    orderNote.classList.remove(\"hidden\");\n    orderNote.innerHTML = \"Choose horizontal or vertical layout. Each blank is worth one mark. Capital and small English letters are treated as the same answer.\";\n    if(!getFillRows().length) resetFillItems();\n    updateFillDegreeAndPreview();\n  }\n\n  if(type === \"voice\"){\n\n    optionsBox.classList.add(\"hidden\");\n    correctBox.classList.add(\"hidden\");\n    orderNote.classList.remove(\"hidden\");\n\n    orderNote.innerHTML =\n      \"The student will record their voice.\";\n  }\n\n  updateOrderPreview();\n}\nconst MIN_REARRANGE_ITEMS = 4;\nconst MAX_REARRANGE_ITEMS = 20;\n\nfunction getRearrangeRows(){\n  return [\n    ...document.querySelectorAll(\n      \"#rearrangeItemsBox .rearrange-admin-row\"\n    )\n  ];\n}\n\nfunction createRearrangeItemRow(value = \"\", index = null){\n\n  const box =\n    document.getElementById(\"rearrangeItemsBox\");\n\n  if(!box) return null;\n\n  const currentRows =\n    getRearrangeRows();\n\n  const rowIndex =\n    index === null\n      ? currentRows.length\n      : Number(index);\n\n  const row =\n    document.createElement(\"div\");\n\n  row.className =\n    \"rearrange-admin-row\";\n\n  row.dataset.rearrangeIndex =\n    String(rowIndex);\n\n  row.innerHTML = `\n    <div class=\"rearrange-admin-index\">\n      ${rowIndex + 1}\n    </div>\n\n    <input\n      type=\"text\"\n      class=\"rearrange-admin-input\"\n      placeholder=\"Rearrange item ${rowIndex + 1}\"\n      value=\"${esc(value)}\"\n      oninput=\"updateOrderPreview()\"\n    >\n\n    <button\n      type=\"button\"\n      class=\"rearrange-remove-btn\"\n      onclick=\"removeRearrangeItem(this)\"\n      title=\"Remove this item\"\n    >\n      <i class=\"fa-solid fa-trash\"></i>\n    </button>\n  `;\n\n  box.appendChild(row);\n\n  renumberRearrangeRows();\n\n  return row;\n}\n\nfunction renumberRearrangeRows(){\n\n  const rows =\n    getRearrangeRows();\n\n  rows.forEach((row,index)=>{\n\n    row.dataset.rearrangeIndex =\n      String(index);\n\n    const number =\n      row.querySelector(\n        \".rearrange-admin-index\"\n      );\n\n    if(number){\n      number.textContent =\n        String(index + 1);\n    }\n\n    const input =\n      row.querySelector(\n        \".rearrange-admin-input\"\n      );\n\n    if(input){\n      input.placeholder =\n        `Rearrange item ${index + 1}`;\n    }\n\n    const removeBtn =\n      row.querySelector(\n        \".rearrange-remove-btn\"\n      );\n\n    if(removeBtn){\n      removeBtn.disabled =\n        rows.length <= MIN_REARRANGE_ITEMS;\n    }\n  });\n\n  const count =\n    document.getElementById(\n      \"rearrangeItemCount\"\n    );\n\n  if(count){\n    count.textContent =\n      `${rows.length} item${rows.length === 1 ? \"\" : \"s\"}`;\n  }\n\n  const addBtn =\n    document.getElementById(\n      \"addRearrangeItemBtn\"\n    );\n\n  if(addBtn){\n    addBtn.disabled =\n      rows.length >= MAX_REARRANGE_ITEMS;\n  }\n\n  updateOrderPreview();\n}\n\nfunction addRearrangeItem(value = \"\"){\n\n  const rows =\n    getRearrangeRows();\n\n  if(rows.length >= MAX_REARRANGE_ITEMS){\n    alert(\n      `Maximum ${MAX_REARRANGE_ITEMS} Rearrange items.`\n    );\n    return;\n  }\n\n  const row =\n    createRearrangeItemRow(\n      value,\n      rows.length\n    );\n\n  if(row){\n    setTimeout(()=>{\n      row.querySelector(\n        \".rearrange-admin-input\"\n      )?.focus();\n    },30);\n  }\n}\n\nfunction removeRearrangeItem(button){\n\n  const row =\n    button?.closest(\n      \".rearrange-admin-row\"\n    );\n\n  if(!row) return;\n\n  const rows =\n    getRearrangeRows();\n\n  if(rows.length <= MIN_REARRANGE_ITEMS){\n    return;\n  }\n\n  row.remove();\n\n  renumberRearrangeRows();\n}\n\nfunction resetRearrangeItems(items = []){\n\n  const box =\n    document.getElementById(\n      \"rearrangeItemsBox\"\n    );\n\n  if(!box) return;\n\n  box.innerHTML = \"\";\n\n  const saved =\n    Array.isArray(items)\n      ? items\n      : [];\n\n  const total =\n    Math.max(\n      MIN_REARRANGE_ITEMS,\n      saved.length\n    );\n\n  for(let i = 0; i < total; i++){\n    createRearrangeItemRow(\n      saved[i] || \"\",\n      i\n    );\n  }\n\n  renumberRearrangeRows();\n}\n\nfunction updateOrderPreview(){\n  if(qType.value !== \"order\"){\n    orderPreview.innerHTML = \"\";\n    return;\n  }\n\n  const options = getOptions();\n\n  if(options.length === 0){\n    orderPreview.innerHTML = `the correct order will appear here`;\n    return;\n  }\n\n  orderPreview.innerHTML = `<strong>الترتيب الصحيح الذي سيُحفظ:</strong>`;\n  options.forEach((op, i)=>{\n    orderPreview.innerHTML += `<div>${i+1}) ${esc(op)}</div>`;\n  });\n}\n\n\n/* ================= رفع الميديا ================= */\n\nconst MIN_MATCHING_PAIRS = 4;\nconst MAX_MATCHING_PAIRS = 20;\n\nfunction getMatchingRows(){\n  return [\n    ...document.querySelectorAll(\n      \"#matchingBox .match-admin-row\"\n    )\n  ];\n}\n\nfunction createMatchingPairRow(pair = {}, index = null){\n\n  const box =\n    document.getElementById(\"matchingBox\");\n\n  if(!box) return null;\n\n  const currentRows =\n    getMatchingRows();\n\n  const rowIndex =\n    index === null\n      ? currentRows.length\n      : Number(index);\n\n  const imageUrl =\n    String(\n      pair?.mediaUrl ||\n      pair?.imageUrl ||\n      pair?.image ||\n      \"\"\n    ).trim();\n\n  const row =\n    document.createElement(\"div\");\n\n  row.className =\n    \"match-admin-row\";\n\n  row.dataset.matchIndex =\n    String(rowIndex);\n\n  row.dataset.uploadedUrl =\n    imageUrl;\n\n  row.innerHTML = `\n    <div class=\"match-row-head\">\n      <h4>Matching Pair ${rowIndex + 1}</h4>\n\n      <button\n        type=\"button\"\n        class=\"match-remove-btn\"\n        onclick=\"removeMatchingPair(this)\"\n        title=\"Remove this matching pair\"\n      >\n        <i class=\"fa-solid fa-trash\"></i>\n      </button>\n    </div>\n\n    <label>Word / Left Item</label>\n    <input\n      class=\"match-left\"\n      placeholder=\"${rowIndex === 0 ? \"Example: cat\" : rowIndex === 1 ? \"Example: dog\" : \"Enter the left item\"}\"\n      value=\"${esc(pair?.left || \"\")}\"\n    >\n\n    <label>Matching Word / Text</label>\n    <input\n      class=\"match-right\"\n      placeholder=\"${rowIndex === 0 ? \"Example: قطة — leave blank when using an image\" : rowIndex === 1 ? \"Example: كلب — leave blank when using an image\" : \"Enter matching text or leave blank for an image\"}\"\n      value=\"${esc(pair?.right || \"\")}\"\n    >\n\n    <label>URL</label>\n    <input\n      class=\"match-image-url\"\n      placeholder=\"Paste image URL\"\n      value=\"${esc(imageUrl)}\"\n      oninput=\"updateMatchAdminPreview(this.closest('.match-admin-row'))\"\n    >\n\n    <label>Upload Image</label>\n    <input\n      type=\"file\"\n      class=\"match-image-file\"\n      accept=\"image/*\"\n      onchange=\"prepareMatchImageFile(this)\"\n    >\n\n    <div class=\"match-upload-status\">\n      ${\n        imageUrl\n          ? \"Saved image loaded. You may keep it or replace it.\"\n          : \"Use text, an image URL, or upload an image.\"\n      }\n    </div>\n\n    <div class=\"match-media-preview\"></div>\n  `;\n\n  box.appendChild(row);\n\n  updateMatchAdminPreview(row);\n  renumberMatchingRows();\n\n  return row;\n}\n\nfunction renumberMatchingRows(){\n\n  const rows =\n    getMatchingRows();\n\n  rows.forEach((row,index)=>{\n\n    row.dataset.matchIndex =\n      String(index);\n\n    const title =\n      row.querySelector(\"h4\");\n\n    if(title){\n      title.textContent =\n        `Matching Pair ${index + 1}`;\n    }\n\n    const removeBtn =\n      row.querySelector(\n        \".match-remove-btn\"\n      );\n\n    if(removeBtn){\n      /*\n        Keep at least 4 rows visible by default.\n        Extra rows can be removed freely.\n      */\n      removeBtn.disabled =\n        rows.length <= MIN_MATCHING_PAIRS;\n    }\n  });\n\n  const count =\n    document.getElementById(\n      \"matchingPairCount\"\n    );\n\n  if(count){\n    count.textContent =\n      `${rows.length} pair${rows.length === 1 ? \"\" : \"s\"}`;\n  }\n\n  const addBtn =\n    document.getElementById(\n      \"addMatchingPairBtn\"\n    );\n\n  if(addBtn){\n    addBtn.disabled =\n      rows.length >= MAX_MATCHING_PAIRS;\n  }\n\n  collectMatchingPairsForDegree();\n}\n\nfunction addMatchingPair(pair = {}){\n\n  const rows =\n    getMatchingRows();\n\n  if(rows.length >= MAX_MATCHING_PAIRS){\n    alert(\n      `Maximum ${MAX_MATCHING_PAIRS} matching pairs.`\n    );\n    return;\n  }\n\n  const row =\n    createMatchingPairRow(\n      pair,\n      rows.length\n    );\n\n  if(row){\n    setTimeout(()=>{\n      row.querySelector(\n        \".match-left\"\n      )?.focus();\n    },30);\n  }\n}\n\nfunction removeMatchingPair(button){\n\n  const row =\n    button?.closest(\n      \".match-admin-row\"\n    );\n\n  if(!row) return;\n\n  const rows =\n    getMatchingRows();\n\n  if(rows.length <= MIN_MATCHING_PAIRS){\n    return;\n  }\n\n  row.remove();\n  renumberMatchingRows();\n}\n\nfunction resetMatchingRows(pairs = []){\n\n  const box =\n    document.getElementById(\n      \"matchingBox\"\n    );\n\n  if(!box) return;\n\n  box.innerHTML = \"\";\n\n  const sourcePairs =\n    Array.isArray(pairs)\n      ? pairs\n      : [];\n\n  const total =\n    Math.max(\n      MIN_MATCHING_PAIRS,\n      sourcePairs.length\n    );\n\n  for(let i = 0; i < total; i++){\n    createMatchingPairRow(\n      sourcePairs[i] || {},\n      i\n    );\n  }\n\n  renumberMatchingRows();\n}\n\nfunction clearMatchingRows(){\n  resetMatchingRows([]);\n}\n\nfunction prepareMatchImageFile(fileInput){\n\n  const row =\n    fileInput?.closest(\n      \".match-admin-row\"\n    );\n\n  const fileObj =\n    fileInput?.files?.[0];\n\n  if(!row || !fileObj){\n    return;\n  }\n\n  if(\n    !String(fileObj.type || \"\")\n      .toLowerCase()\n      .startsWith(\"image/\")\n  ){\n\n    fileInput.value = \"\";\n\n    alert(\n      \"Matching media must be an image.\"\n    );\n\n    return;\n  }\n\n  const status =\n    row.querySelector(\n      \".match-upload-status\"\n    );\n\n  if(status){\n    status.textContent =\n      `Selected: ${fileObj.name}. The image will upload when the question is saved.`;\n  }\n}\n\nfunction updateMatchAdminPreview(row){\n\n  if(!row){\n    return;\n  }\n\n  const imageUrl =\n    row.querySelector(\n      \".match-image-url\"\n    )?.value\n      ?.trim() ||\n    \"\";\n\n  const preview =\n    row.querySelector(\n      \".match-media-preview\"\n    );\n\n  if(!preview){\n    return;\n  }\n\n  preview.innerHTML =\n    imageUrl\n      ? `\n        <img\n          src=\"${esc(imageUrl)}\"\n          alt=\"Matching image\">\n      `\n      : \"\";\n}\n\nasync function collectMatchingPairs(){\n\n  const pairs = [];\n\n  const rows =\n    getMatchingRows();\n\n  for(\n    let index = 0;\n    index < rows.length;\n    index++\n  ){\n\n    const row =\n      rows[index];\n\n    const left =\n      row.querySelector(\n        \".match-left\"\n      )?.value\n        ?.trim() ||\n      \"\";\n\n    const right =\n      row.querySelector(\n        \".match-right\"\n      )?.value\n        ?.trim() ||\n      \"\";\n\n    const imageUrlInput =\n      row.querySelector(\n        \".match-image-url\"\n      );\n\n    const fileInput =\n      row.querySelector(\n        \".match-image-file\"\n      );\n\n    const status =\n      row.querySelector(\n        \".match-upload-status\"\n      );\n\n    let imageUrl =\n      imageUrlInput?.value\n        ?.trim() ||\n      \"\";\n\n    const fileObj =\n      fileInput?.files?.[0];\n\n    const rowHasAnyValue =\n      Boolean(\n        left ||\n        right ||\n        imageUrl ||\n        fileObj\n      );\n\n    if(!rowHasAnyValue){\n      continue;\n    }\n\n    if(!left){\n\n      throw new Error(\n        `Matching Pair ${index + 1}: enter the left word.`\n      );\n    }\n\n    if(fileObj){\n\n      if(\n        !String(fileObj.type || \"\")\n          .toLowerCase()\n          .startsWith(\"image/\")\n      ){\n\n        throw new Error(\n          `Matching Pair ${index + 1}: only image files are supported.`\n        );\n      }\n\n      if(status){\n        status.innerHTML =\n          `<i class=\"fa-solid fa-spinner fa-spin\"></i> Uploading image...`;\n      }\n\n      imageUrl =\n        await uploadFileToCloudinary(\n          fileObj\n        );\n\n      if(imageUrlInput){\n        imageUrlInput.value =\n          imageUrl;\n      }\n\n      if(fileInput){\n        fileInput.value = \"\";\n      }\n\n      if(status){\n        status.innerHTML =\n          `<i class=\"fa-solid fa-circle-check\"></i> Image uploaded successfully.`;\n      }\n\n      updateMatchAdminPreview(\n        row\n      );\n    }\n\n    if(!right && !imageUrl){\n\n      throw new Error(\n        `Matching Pair ${index + 1}: enter matching text or add an image URL/file.`\n      );\n    }\n\n    pairs.push({\n      left:left,\n      right:right,\n      mediaType:\n        imageUrl\n          ? \"image\"\n          : \"none\",\n      mediaUrl:imageUrl,\n      imageUrl:imageUrl\n    });\n  }\n\n  if(pairs.length < 2){\n\n    throw new Error(\n      \"Add at least two valid matching pairs.\"\n    );\n  }\n\n  return pairs;\n}\n\nfunction renderMatchingPairAdmin(pair){\n\n  const imageUrl =\n    String(\n      pair?.mediaUrl ||\n      pair?.imageUrl ||\n      pair?.image ||\n      \"\"\n    ).trim();\n\n  const rightText =\n    String(\n      pair?.right ||\n      \"\"\n    ).trim();\n\n  return `\n    <li style=\"\n      direction:ltr;\n      text-align:left;\n      margin-bottom:10px;\n    \">\n      <strong>${esc(pair?.left || \"\")}</strong>\n      =\n      ${\n        imageUrl\n          ? `\n            <div style=\"margin-top:7px\">\n              <img\n                src=\"${esc(imageUrl)}\"\n                alt=\"Matching image\"\n                style=\"\n                  max-width:170px;\n                  max-height:130px;\n                  object-fit:contain;\n                  border-radius:10px;\n                  border:1px solid #dce6ef;\n                  background:#fff;\n                \">\n            </div>\n          `\n          : esc(rightText)\n      }\n    </li>\n  `;\n}\n\nasync function uploadFileToCloudinary(fileObj){\n  if(!fileObj) throw new Error(\"لا يوجد ملف\");\n\n  const form = new FormData();\n  form.append(\"file\", fileObj);\n  form.append(\"upload_preset\", \"kcgfhigd\");\n\n  const url = \"https://api.cloudinary.com/v1_1/dgs6mo4hl/auto/upload\";\n\n  const res = await fetch(url, {\n    method: \"POST\",\n    body: form\n  });\n\n  const text = await res.text();\n  console.log(\"RAW RESPONSE:\", text);\n\n  let data;\n  try{\n    data = JSON.parse(text);\n  }catch(e){\n    throw new Error(\"استجابة غير مفهومة من السيرفر\");\n  }\n\n  console.log(\"Cloudinary:\", data);\n\n  if(!data.secure_url){\n    throw new Error(data.error?.message || \"Cloudinary رفض الملف\");\n  }\n\n  return data.secure_url;\n}\n\nfunction collectMatchingPairsForDegree(){\n  if(qType?.value !== \"match\") return;\n  const count=getMatchingRows().filter(row=>{\n    const left=String(row.querySelector('.match-left')?.value || '').trim();\n    const right=String(row.querySelector('.match-right')?.value || '').trim();\n    const image=String(row.querySelector('.match-image-url')?.value || '').trim() || row.dataset.uploadedUrl || '';\n    return left && (right || image);\n  }).length;\n  updateQuestionDegreeDistributionNote();\n}\n\ndocument.addEventListener('input',function(event){\n  if(event.target?.closest('#matchingBox')) collectMatchingPairsForDegree();\n});\ndocument.addEventListener('change',function(event){\n  if(event.target?.closest('#matchingBox')) collectMatchingPairsForDegree();\n});\n\n/* ================= حفظ / تعديل السؤال ================= */\nasync function saveQuestion(){\n\n  const examId = examSelect.value;\n\n  if(!examId){\n    return alert(\"Choose the exam first\");\n  }\n\n  // □ جلب آخر ترتيب\n  const lastSnap = await db.collection(\"questions\")\n    .where(\"examId\",\"==\",examId)\n    .get();\n\n  let newOrder = 1;\n\n  if(!lastSnap.empty){\n\n    const orders = lastSnap.docs.map(d =>\n      Number(d.data().order || 0)\n    );\n\n    newOrder = Math.max(...orders, 0) + 1;\n  }\n\n  const qText = String(question.value || \"\").trim();\n  const options = getOptions();\n\n  let deg   = Number(degree.value || 0);\n  const type  = qType.value;\n  let fillItems = [];\n  let fillLayoutValue = \"horizontal\";\n  let fillColumnsValue = 10;\n  let answerLinesValue = 4;\n  const media = mediaType.value;\n\n  const fileObj = file.files[0];\n\n  const showMedia = true;\n\n  const group =\n    document.getElementById(\"groupSelect\")?.value || \"General\";\n\n  if(!qText){\n    return alert(\"اكتب السؤال\");\n  }\n\n  if(\n    (\n      type === \"mcq\" ||\n      type === \"order\"\n    )\n    &&\n    options.length < 2\n  ){\n    return alert(\"Enter at least two options.\");\n  }\n\n  if(deg <= 0){\n    return alert(\"Insert the total marks for this question.\");\n  }\n\n  let correctAnswer;\n\n  // ================= VOICE =================\n  if(type === \"voice\"){\n\n    correctAnswer = \"voice\";\n  }\n\n  // ================= ORDER =================\n  else if(type === \"order\"){\n\n    correctAnswer = [...options];\n  }\n\n  // ================= TEXT =================\n  else if(type === \"text\"){\n\n    correctAnswer = String(correct.value || \"\")\n      .split(\",\")\n      .map(v => normalizeTextAnswer(v))\n      .filter(v => v);\n\n    answerLinesValue = Math.max(\n      1,\n      Math.min(\n        20,\n        Number(\n          document.getElementById(\"textAnswerLines\")?.value || 4\n        )\n      )\n    );\n  }\n\n  // ================= FILL IN THE BLANKS =================\n  else if(type === \"fill\"){\n    try{\n      fillItems = collectFillItems();\n    }catch(error){\n      return alert(error?.message || \"Invalid fill-in-the-blanks items.\");\n    }\n    fillLayoutValue = document.getElementById(\"fillLayout\")?.value === \"vertical\" ? \"vertical\" : \"horizontal\";\n    fillColumnsValue = Math.max(1,Math.min(12,Number(document.getElementById(\"fillColumns\")?.value || 10)));\n    correctAnswer = fillItems\n      .filter(item=>item.mode === \"blank\")\n      .map(item=>normalizeTextAnswer(item.answer));\n\n    if(deg <= 0){\n      return alert(\"Insert the total marks for this question.\");\n    }\n  }\n\n  // ================= MATCH =================\n  else if(type === \"match\"){\n\n    try{\n\n      correctAnswer =\n        await collectMatchingPairs();\n\n      if(deg <= 0){\n        return alert(\"Insert the total marks for this question.\");\n      }\n\n    }catch(error){\n\n      return alert(\n        error?.message ||\n        \"Invalid matching pairs.\"\n      );\n    }\n  }\n\n  // ================= MCQ =================\n  else{\n\n    const i = Number(correct.value);\n\n    if(\n      isNaN(i) ||\n      i < 0 ||\n      i >= options.length\n    ){\n      return alert(\"No. of the correct answer\");\n    }\n\n    correctAnswer = i;\n  }\n\n  // ================= EXAM =================\n  const examDoc = await db.collection(\"exams\")\n    .doc(examId)\n    .get();\n\n  if(!examDoc.exists){\n    return alert(\"الاختبار غير موجود\");\n  }\n\n  const exam = examDoc.data();\n\n\n\n\n  // ================= MEDIA =================\n  let mediaUrl =\n    String(\n      document.getElementById(\"mediaUrlInput\")?.value ||\n      \"\"\n    ).trim();\n\n  let finalMediaType =\n    mediaUrl\n      ? media\n      : \"none\";\n\n  if(fileObj){\n\n    try{\n\n      const mime = fileObj.type || \"\";\n\n      if(mime.startsWith(\"image/\")){\n        finalMediaType = \"image\";\n      }\n\n      else if(mime.startsWith(\"video/\")){\n        finalMediaType = \"video\";\n      }\n\n      else if(mime.startsWith(\"audio/\")){\n        finalMediaType = \"audio\";\n      }\n\n      else{\n        return alert(\"نوع الملف غير مدعوم\");\n      }\n\n      mediaUrl = await uploadFileToCloudinary(fileObj);\n\n    }catch(err){\n\n      console.error(err);\n\n      return alert(\"فشل رفع الملف: \" + err.message);\n    }\n  }\n\n  if(\n    mediaUrl &&\n    (\n      !finalMediaType ||\n      finalMediaType === \"none\"\n    )\n  ){\n    return alert(\n      \"Choose the media type for the URL.\"\n    );\n  }\n\n  // =========================================================\n  // ======================== UPDATE =========================\n  // =========================================================\n\n  if(EDIT_QUESTION_ID){\n\n    const oldDoc = await db.collection(\"questions\")\n      .doc(EDIT_QUESTION_ID)\n      .get();\n\n    const oldData = oldDoc.exists\n      ? oldDoc.data()\n      : {};\n\n    const data = {\nlocked:\n  oldData.locked === true,\n\n      examId: examId,\n\n      question: qText,\n\n      passage:\n        CURRENT_PASSAGE ||\n        oldData.passage ||\n        \"\",\n      passageHtml:\n        CURRENT_PASSAGE_HTML ||\n        oldData.passageHtml ||\n        \"\",\n      passageAlign:\n        document.getElementById(\"passageAlign\")?.value ||\n        oldData.passageAlign ||\n        \"left\",\n\n      options:\n        type === \"match\"\n          ? correctAnswer.map(pair =>\n              pair.mediaUrl\n                ? `${pair.left}=[Image]`\n                : `${pair.left}=${pair.right}`\n            )\n          : type === \"fill\"\n            ? fillItems.map(item=>item.mode === \"fixed\" ? item.display : \"[Blank]\")\n            : options,\n\n      correct: correctAnswer,\n      fillItems: type === \"fill\" ? fillItems : [],\n      fillLayout: type === \"fill\" ? fillLayoutValue : \"\",\n      fillColumns: type === \"fill\" ? fillColumnsValue : 0,\n      answerLines: type === \"text\" ? answerLinesValue : 0,\n\n      degree: deg,\n\n      type: type,\n\n      mediaType:\n        mediaUrl\n          ? finalMediaType\n          : \"none\",\n\n      mediaUrl:\n        mediaUrl || \"\",\n\n      group: group,\n\n      showMedia: true,\n\n      // □ المحافظة على الترتيب القديم\n      order: oldData.order ?? 0,\n\n      coursesUsed: dedupeCoursesUsed([\n\n        ...(oldData.coursesUsed || []),\n\n        ...(exam.coursesData || []).map(c => ({\n          courseId: c.courseId,\n          TrainingCourse: c.TrainingCourse,\n          Trainer: c.Trainer\n        }))\n\n      ])\n    };\n\nawait db.collection(\"questions\")\n  .doc(EDIT_QUESTION_ID)\n  .update(data);\n\n// =====================================\n// ✅ تحديث النتائج القديمة تلقائياً\n// =====================================\n\nconst resultsSnap = await db.collection(\"results\")\n  .where(\"examId\",\"==\",examId)\n  .get();\n\nfor(const resultDoc of resultsSnap.docs){\n\n  const result = resultDoc.data();\n\n  if(\n    !result.answers ||\n    result.answers[EDIT_QUESTION_ID] === undefined\n  ){\n    continue;\n  }\n\n  const studentAnswer =\n    result.answers[EDIT_QUESTION_ID];\n\n  let earned = 0;\n\n  if(type === \"mcq\"){\n\n    if(Number(studentAnswer) === Number(correctAnswer)){\n      earned = Number(deg || 0);\n    }\n\n  }\n\n  else if(type === \"text\"){\n\n    const normalizedStudent =\n      normalizeTextAnswer(studentAnswer);\n\n    const validAnswers =\n      Array.isArray(correctAnswer)\n        ? correctAnswer\n        : [];\n\n    if(validAnswers.includes(normalizedStudent)){\n      earned = Number(deg || 0);\n    }\n\n  }\n\n  else if(type === \"order\"){\n\n    if(\n      JSON.stringify(studentAnswer) ===\n      JSON.stringify(correctAnswer)\n    ){\n      earned = Number(deg || 0);\n    }\n\n  }\n\n  else if(type === \"match\"){\n    const answersObject = studentAnswer && typeof studentAnswer === \"object\" ? studentAnswer : {};\n    correctAnswer.forEach((pair,index)=>{\n      const expected = String(pair.mediaUrl || pair.imageUrl || pair.image || pair.right || \"\").trim();\n      const received = Array.isArray(studentAnswer)\n        ? String(studentAnswer[index]?.mediaUrl || studentAnswer[index]?.right || studentAnswer[index]?.value || \"\").trim()\n        : String(answersObject[index] ?? answersObject[String(index)] ?? \"\").trim();\n      if(received === expected) earned += 1;\n    });\n  }\n\n  else if(type === \"fill\"){\n    const answerObject = studentAnswer && typeof studentAnswer === \"object\" ? studentAnswer : {};\n    const blanks = fillItems.filter(item=>item.mode === \"blank\");\n    blanks.forEach((item,index)=>{\n      const received = normalizeTextAnswer(answerObject[index] ?? answerObject[String(index)] ?? \"\");\n      if(received === normalizeTextAnswer(item.answer)) earned += 1;\n    });\n  }\n\n  let details =\n    Array.isArray(result.details)\n      ? result.details\n      : [];\n\n  details = details.map(d=>{\n\n    if(d.questionId !== EDIT_QUESTION_ID){\n      return d;\n    }\n\n    return {\n      ...d,\n      correctAnswer: correctAnswer,\n      earned: earned,\n      degree: Number(deg || 0)\n    };\n\n  });\n\n  const totalScore = details.reduce((sum,d)=>\n    sum + Number(d.earned || 0)\n  ,0);\n\n  const totalDegree = details.reduce((sum,d)=>\n    sum + Number(d.degree || 0)\n  ,0);\n\n  const percent =\n    totalDegree > 0\n      ? Math.round((totalScore / totalDegree) * 100)\n      : 0;\n\n  await db.collection(\"results\")\n    .doc(resultDoc.id)\n    .update({\n\n      details: details,\n      score: totalScore,\n      totalDegree: totalDegree,\n      percent: percent\n\n    });\n\n}\n    await updateVisibleQuestions(examId);\n\n    CURRENT_PASSAGE = \"\";\n    CURRENT_PASSAGE_HTML = \"\";\n\n    alert(\"✅ update has done\");\n\n    clearForm();\n\n    await loadQuestions();\n\n    return;\n  }\n\n// ================= ADD =================\n  await db.collection(\"questions\").add({\n    examId: examId,\norder: newOrder,\n    question: qText,\n\n    // □ أهم إضافة\n    passage: CURRENT_PASSAGE || \"\",\n    passageHtml: CURRENT_PASSAGE_HTML || \"\",\n    passageAlign:\n      document.getElementById(\"passageAlign\")?.value ||\n      \"left\",\n\n    options:\n      type === \"match\"\n        ? correctAnswer.map(pair =>\n            pair.mediaUrl\n              ? `${pair.left}=[Image]`\n              : `${pair.left}=${pair.right}`\n          )\n        : type === \"fill\"\n          ? fillItems.map(item=>item.mode === \"fixed\" ? item.display : \"[Blank]\")\n          : options,\n\n    correct: correctAnswer,\n    fillItems: type === \"fill\" ? fillItems : [],\n    fillLayout: type === \"fill\" ? fillLayoutValue : \"\",\n    fillColumns: type === \"fill\" ? fillColumnsValue : 0,\n    answerLines: type === \"text\" ? answerLinesValue : 0,\n    degree: deg,\n\n    gradingParts:\n      type === \"match\"\n        ? correctAnswer.length\n        : type === \"fill\"\n          ? correctAnswer.length\n          : 1,\n\n    partDegree:\n      type === \"match\" || type === \"fill\"\n        ? Number((deg / Math.max(correctAnswer.length,1)).toFixed(6))\n        : deg,\n\n    type: type,\n    mediaType:\n      mediaUrl\n        ? finalMediaType\n        : \"none\",\n\n    mediaUrl:\n      mediaUrl || \"\",\n\n    group: group,\n    showMedia: true,\nlocked:false,\n\n    coursesUsed: dedupeCoursesUsed(\n      (exam.coursesData || []).map(c => ({\n        courseId: c.courseId,\n        TrainingCourse: c.TrainingCourse,\n        Trainer: c.Trainer\n      }))\n    ),\n\n    createdAt: new Date()\n  });\n\n// □ مهم جدًا: تحديث الأسئلة الظاهرة للطالب\nawait updateVisibleQuestions(examId);\n\nCURRENT_PASSAGE = \"\";\nCURRENT_PASSAGE_HTML = \"\";\n\nalert(\"✅ save successfully\");\nclearForm();\nawait loadQuestions();\n}\nasync function updateVisibleQuestions(examId){\n\n  if(!examId) return;\n\nconst snap = await db.collection(\"questions\")\n  .where(\"examId\",\"==\",examId)\n  .get();\n  const ids = snap.docs\n    .sort((a,b)=>{\n      const A = Number(a.data().order || 0);\n      const B = Number(b.data().order || 0);\n      return A - B;\n    })\n    .map(d => d.id);\n\nconst examRef =\n  db.collection(\"exams\").doc(examId);\n\nconst examDoc =\n  await examRef.get();\n\nconst oldMap =\n  examDoc.data()?.visibleQuestionsByCourse || {};\nif(!CURRENT_COURSE_ID){\n  return;\n}\noldMap[CURRENT_COURSE_ID] = ids;\n\nawait examRef.update({\n  visibleQuestionsByCourse: oldMap\n});\n  console.log(\"✅ كل الأسئلة أصبحت ظاهرة للطالب:\", ids.length);\n}\n/* ================= تعديل السؤال ================= */\nasync function editQuestion(id){\n\n  try{\n\n    const doc = await db.collection(\"questions\").doc(id).get();\n\n    if(!doc.exists){\n      alert(\"السؤال غير موجود\");\n      return;\n    }\n\n    const q = doc.data() || {};\n\n    EDIT_QUESTION_ID = id;\n\n    /* اختيار الاختبار المحفوظ */\n    if(q.examId){\n      examSelect.value = q.examId;\n    }\n\n    /* تحديد النوع أولاً؛ لأن toggleQuestionType يمسح خانة الإجابة */\n    qType.value = q.type || \"mcq\";\n    toggleQuestionType();\n\n    /* البيانات العامة لجميع أنواع الأسئلة */\n    question.value = q.question || \"\";\n    degree.value = q.degree ?? \"\";\n\n    const groupField = document.getElementById(\"groupSelect\");\n    if(groupField){\n      groupField.value = q.group || \"General\";\n    }\n\n    CURRENT_PASSAGE = String(q.passage || \"\");\n    CURRENT_PASSAGE_HTML =\n      sanitizePassageHtml(\n        q.passageHtml ||\n        passagePlainToHtml(q.passage || \"\")\n      );\n\n    const passageStatus =\n      document.getElementById(\"passageSavedStatus\");\n\n    if(passageStatus){\n      passageStatus.style.display =\n        CURRENT_PASSAGE ? \"inline-flex\" : \"none\";\n\n      if(CURRENT_PASSAGE){\n        passageStatus.textContent =\n          \"✓ Passage loaded — click Add / Edit Reading Passage\";\n      }\n    }\n\n    const passageAlignField = document.getElementById(\"passageAlign\");\n    if(passageAlignField){\n      passageAlignField.value = [\"left\",\"center\",\"right\"].includes(q.passageAlign)\n        ? q.passageAlign\n        : \"left\";\n    }\n\n    mediaType.value = q.mediaType || (q.mediaUrl ? \"image\" : \"none\");\n\n    const mediaUrlField = document.getElementById(\"mediaUrlInput\");\n    if(mediaUrlField){\n      mediaUrlField.value = q.mediaUrl || \"\";\n    }\n\n    if(file){\n      file.value = \"\";\n    }\n\n    /* تنظيف الحقول قبل تعبئة النوع المحفوظ */\n    opt1.value = \"\";\n    opt2.value = \"\";\n    opt3.value = \"\";\n    opt4.value = \"\";\n    correct.value = \"\";\n    clearMatchingRows();\n\n    const savedOptions = Array.isArray(q.options) ? q.options : [];\n\n    /* Multiple Choice */\n    if(qType.value === \"mcq\"){\n\n      opt1.value = savedOptions[0] || \"\";\n      opt2.value = savedOptions[1] || \"\";\n      opt3.value = savedOptions[2] || \"\";\n      opt4.value = savedOptions[3] || \"\";\n\n      correct.value =\n        q.correct !== undefined && q.correct !== null\n          ? String(q.correct)\n          : \"\";\n    }\n\n    /* Rearrange: load every saved item dynamically */\n    else if(qType.value === \"order\"){\n\n      const orderedItems =\n        Array.isArray(q.correct) && q.correct.length\n          ? q.correct\n          : savedOptions;\n\n      resetRearrangeItems(\n        orderedItems\n      );\n\n      updateOrderPreview();\n    }\n\n    /* Text Answer */\n    else if(qType.value === \"text\"){\n\n      const savedAnswers = Array.isArray(q.correct)\n        ? q.correct\n        : (\n            q.correct !== undefined && q.correct !== null\n              ? [q.correct]\n              : []\n          );\n\n      correct.value = savedAnswers\n        .map(value => String(value || \"\").trim())\n        .filter(Boolean)\n        .join(\", \");\n\n      const textAnswerLinesField =\n        document.getElementById(\"textAnswerLines\");\n\n      if(textAnswerLinesField){\n        textAnswerLinesField.value = Math.max(\n          1,\n          Math.min(20,Number(q.answerLines || 4))\n        );\n      }\n    }\n\n    /* Matching: نص مع نص أو نص مع صورة */\n    else if(qType.value === \"match\"){\n\n      let pairs = Array.isArray(q.correct) ? q.correct : [];\n\n      /* دعم الأسئلة القديمة المحفوظة داخل options بصيغة left=right */\n      if(!pairs.length && savedOptions.length){\n        pairs = savedOptions.map(item => {\n          const value = String(item || \"\");\n          const separatorIndex = value.indexOf(\"=\");\n\n          if(separatorIndex < 0){\n            return {left:value,right:\"\",mediaUrl:\"\"};\n          }\n\n          return {\n            left:value.slice(0,separatorIndex).trim(),\n            right:value.slice(separatorIndex + 1).trim() === \"[Image]\"\n              ? \"\"\n              : value.slice(separatorIndex + 1).trim(),\n            mediaUrl:\"\"\n          };\n        });\n      }\n\n      /*\n        Create enough rows for every saved pair.\n        Old questions with 2–4 pairs still show at least 4 rows,\n        while questions with 5+ pairs load all of them.\n      */\n      resetMatchingRows(pairs);\n\n      collectMatchingPairsForDegree();\n    }\n\n    /* Fill in the Blanks */\n    else if(qType.value === \"fill\"){\n\n      const layout = document.getElementById(\"fillLayout\");\n      const columns = document.getElementById(\"fillColumns\");\n\n      if(layout){\n        layout.value = q.fillLayout === \"vertical\"\n          ? \"vertical\"\n          : \"horizontal\";\n      }\n\n      if(columns){\n        columns.value = Math.max(\n          1,\n          Math.min(12,Number(q.fillColumns || 10))\n        );\n      }\n\n      resetFillItems(\n        Array.isArray(q.fillItems)\n          ? q.fillItems\n          : []\n      );\n\n      updateFillDegreeAndPreview();\n    }\n\n    /* Voice Recording لا يحتوي إجابة نصية */\n    else if(qType.value === \"voice\"){\n      correct.value = \"\";\n    }\n\n    updateQuestionDegreeDistributionNote();\n\n    /* نقل المستخدم إلى قسم التعديل بعد تحميل كل القيم */\n    const editBox = qType.closest(\".box\");\n    if(editBox){\n      editBox.scrollIntoView({\n        behavior:\"smooth\",\n        block:\"start\"\n      });\n    }\n\n  }catch(error){\n\n    console.error(\"editQuestion error:\",error);\n    alert(\"تعذر تحميل بيانات السؤال للتعديل\");\n  }\n}\n\nasync function quickUpdateQuestion(id, options = {}){\n  const silent = options.silent === true;\n  const reload = options.reload !== false;\n\n  const qDoc = await db.collection(\"questions\").doc(id).get();\n  if(!qDoc.exists){\n    if(!silent) alert(\"Question not found\");\n    return false;\n  }\n\n  const old = qDoc.data();\n// ✅ السؤال مقفل\nif(old.locked === true){\n\n  if(!silent) alert(\"🔒 Locked Question\");\n\n  return false;\n}\n\n  const newQuestion = document.getElementById(\"edit_q_\" + id).value.trim();\n  const newPassage  = document.getElementById(\"edit_passage_\" + id).value.trim();\n\n  const oldPassageText =\n    String(old.passage || \"\").trim();\n\n  const newPassageHtml =\n    newPassage === oldPassageText\n      ? String(old.passageHtml || \"\")\n      : passagePlainToHtml(newPassage);\n\n  const newDegree   = Number(document.getElementById(\"edit_degree_\" + id).value || 0);\n  const newCorrect  = document.getElementById(\"edit_correct_\" + id).value.trim();\nconst updatedOptions = [];\n\n(old.options || []).forEach((_,i)=>{\n\n  updatedOptions.push(\n    document.getElementById(`edit_option_${id}_${i}`)?.value.trim() || \"\"\n  );\n\n});\n\n  if(!newQuestion){\n    if(!silent) alert(\"Write the question\");\n    return false;\n  }\n\n  if(newDegree <= 0){\n    if(!silent) alert(\"Insert degree\");\n    return false;\n  }\n\n  let correctAnswer = old.correct;\n\n  if(old.type === \"mcq\"){\n    const i = Number(newCorrect);\n    if(isNaN(i) || i < 0 || i >= (old.options || []).length){\n      if(!silent) alert(\"Correct answer must be option number مثل 0 أو 1 أو 2 أو 3\");\n      return false;\n    }\n    correctAnswer = i;\n  }\n\n  else if(old.type === \"text\"){\n    correctAnswer = newCorrect\n      .split(\",\")\n      .map(v => normalizeTextAnswer(v))\n      .filter(v => v);\n  }\n\nif(old.type === \"order\"){\n  correctAnswer = [...updatedOptions];\n}\n  else if(old.type === \"match\"){\n\n    /*\n      Matching questions that contain images are edited\n      through the main Add / Edit form so their URLs are preserved.\n    */\n    const oldPairs =\n      Array.isArray(old.correct)\n        ? old.correct\n        : [];\n\n    const hasImagePairs =\n      oldPairs.some(pair =>\n        Boolean(\n          pair?.mediaUrl ||\n          pair?.imageUrl ||\n          pair?.image\n        )\n      );\n\n    if(hasImagePairs){\n\n      correctAnswer =\n        oldPairs;\n\n    }else{\n\n      correctAnswer =\n        (updatedOptions || [])\n          .map(op=>{\n\n            const [left,right] =\n              String(op)\n                .split(\"=\");\n\n            if(!left || !right){\n              return null;\n            }\n\n            return {\n              left:left.trim(),\n              right:right.trim(),\n              mediaType:\"none\",\n              mediaUrl:\"\",\n              imageUrl:\"\"\n            };\n          })\n          .filter(Boolean);\n    }\n  }\n\n  const gradingParts =\n    old.type === \"match\"\n      ? Math.max(\n          1,\n          Array.isArray(correctAnswer)\n            ? correctAnswer.length\n            : 0\n        )\n      : old.type === \"fill\"\n        ? Math.max(\n            1,\n            Array.isArray(old.fillItems)\n              ? old.fillItems.filter(item=>item?.mode === \"blank\").length\n              : 0\n          )\n        : 1;\n\n  const partDegree =\n    old.type === \"match\" || old.type === \"fill\"\n      ? Number((newDegree / gradingParts).toFixed(6))\n      : newDegree;\n\n  await db.collection(\"questions\").doc(id).update({\n    question: newQuestion,\n    options: updatedOptions,\n    passage: newPassage,\n    passageHtml: sanitizePassageHtml(newPassageHtml),\n    degree: newDegree,\n    gradingParts: gradingParts,\n    partDegree: partDegree,\n    correct: correctAnswer,\n    updatedAt: new Date()\n  });\n\n  if(!silent){\n    alert(\"✅ Updated successfully\");\n  }\n\n  if(reload){\n    await loadQuestions();\n  }\n\n  return true;\n}\nasync function editExamTime(){\n\nconst examId = CURRENT_PREVIEW_EXAM;\n  if(!examId){\n    alert(\"اختر الاختبار أولاً\");\n    return;\n  }\n\n  const examDoc = await db.collection(\"exams\").doc(examId).get();\n\n  if(!examDoc.exists){\n    alert(\"الاختبار غير موجود\");\n    return;\n  }\n\n  // قراءة القيم من الحقول\n  let hours = Math.max(Number(document.getElementById(\"editH\").value) || 0, 0);\n  let minutes = Math.max(Number(document.getElementById(\"editM\").value) || 0, 0);\n\n  // ❌ إذا الاثنين فاضي\n  if(hours === 0 && minutes === 0){\n    alert(\"Insert the timer\");\n    return;\n  }\n\n  // □ تحويل الدقائق الزائدة\n  if(minutes >= 60){\n    hours += Math.floor(minutes / 60);\n    minutes = minutes % 60;\n  }\n\n  const newDuration = (hours * 3600) + (minutes * 60);\n\n  await db.collection(\"exams\").doc(examId).update({\n    duration: newDuration\n  });\n\n  alert(`✅ تم التحديث: ${hours} ساعة و ${minutes} دقيقة`);\n\n  await loadExams();\n\n  // تفريغ الحقول\n  document.getElementById(\"editH\").value = \"\";\n  document.getElementById(\"editM\").value = \"\";\n}/* ================= مزامنة مهارة المجموعة مع الدورة المرتبطة ================= */\nasync function syncLinkedCourseSkillWithTop(examId, groupName, linkedCourseId){\n\n  examId = String(examId || \"\").trim();\n  groupName = String(groupName || \"General\").trim();\n  linkedCourseId = String(linkedCourseId || \"\").trim();\n\n  if(!examId || !linkedCourseId) return;\n\n  const examRef = db.collection(\"exams\").doc(examId);\n  const examDoc = await examRef.get();\n\n  if(!examDoc.exists) return;\n\n  const examData = examDoc.data() || {};\n  const map = examData.groupSkillsByCourse || {};\n\n  // المهارة المعتمدة هي المهارة المختارة في الأعلى للدورة الحالية\n  const topSkill =\n    map?.[CURRENT_COURSE_ID]?.[groupName]\n    || examData.groupSkills?.[groupName]\n    || \"\";\n\n  if(!map[linkedCourseId]){\n    map[linkedCourseId] = {};\n  }\n\n  map[linkedCourseId][groupName] = topSkill;\n\n  await examRef.update({\n    groupSkillsByCourse: map,\n    updatedAt: firebase.firestore.FieldValue.serverTimestamp()\n  });\n}\n\n\n/* =========================================\n   SYNC WHOLE EXAM / MODEL TO A COURSE\n   ✅ أي ربط لسؤال من النموذج = ربط النموذج كاملًا\n   ✅ يمنع ظهور السؤال الأول فقط\n========================================= */\nasync function syncAllVisibleLinkedQuestions(\n  examId,\n  courseId\n){\n  examId = String(examId || \"\").trim();\n  courseId = String(courseId || \"\").trim();\n\n  if(!examId || !courseId){\n    return [];\n  }\n\n  const examRef =\n    db.collection(\"exams\").doc(examId);\n\n  const [examDoc, courseDoc, qSnap] =\n    await Promise.all([\n      examRef.get(),\n      db.collection(\"Courses\").doc(courseId).get(),\n      db.collection(\"questions\")\n        .where(\"examId\",\"==\",examId)\n        .get()\n    ]);\n\n  if(!examDoc.exists){\n    return [];\n  }\n\n  const examData =\n    examDoc.data() || {};\n\n  const courseData =\n    courseDoc.exists\n      ? (courseDoc.data() || {})\n      : {};\n\n  /*\n    ✅ احصل على بيانات الدورة.\n    لو لم نجدها في Courses نحاول أخذها من أي سؤال مرتبط سابقًا.\n  */\n  let courseInfo = {\n    courseId: courseId,\n    TrainingCourse:\n      courseData.TrainingCourse || \"\",\n    Trainer:\n      courseData.Trainer || \"\",\n    Period:\n      courseData.Period || \"\"\n  };\n\n  qSnap.forEach(doc=>{\n    const q = doc.data() || {};\n    const used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    const oldLink =\n      used.find(item =>\n        String(item?.courseId || \"\").trim() ===\n        courseId\n      );\n\n    if(oldLink){\n      courseInfo = {\n        courseId: courseId,\n        TrainingCourse:\n          courseInfo.TrainingCourse ||\n          oldLink.TrainingCourse || \"\",\n        Trainer:\n          courseInfo.Trainer ||\n          oldLink.Trainer || \"\",\n        Period:\n          courseInfo.Period ||\n          oldLink.Period || \"\"\n      };\n    }\n  });\n\n  const visibleQuestionIds = [];\n  const orderMap = {};\n  const batch = db.batch();\n\n  qSnap.forEach(doc=>{\n    const q = doc.data() || {};\n\n    orderMap[doc.id] =\n      Number(q.order || 0);\n\n    /*\n      ✅ إصلاح أصل المشكلة:\n      أضف الدورة إلى coursesUsed في كل أسئلة النموذج،\n      وليس في السؤال الذي تم الضغط عليه فقط.\n    */\n    const updatedCoursesUsed =\n      dedupeCoursesUsed([\n        ...(\n          Array.isArray(q.coursesUsed)\n            ? q.coursesUsed\n            : []\n        ),\n        courseInfo\n      ]);\n\n    batch.update(\n      db.collection(\"questions\").doc(doc.id),\n      {\n        coursesUsed: updatedCoursesUsed,\n\n        // للتوافق مع الحقول القديمة\n        linkedCourseId: courseId,\n        linkedCourseName:\n          courseInfo.TrainingCourse || \"\",\n        linkedTrainer:\n          courseInfo.Trainer || \"\",\n        linkedPeriod:\n          courseInfo.Period || \"\"\n      }\n    );\n\n    /*\n      لا نرسل للطالب إلا الأسئلة الظاهرة فعليًا.\n      Reading Passage الرئيسي لا يُحسب كسؤال مستقل.\n    */\n    const questionVisible =\n      q.showQuestion !== false &&\n      q.visible !== false &&\n      q.hidden !== true &&\n      q.isMain !== true;\n\n    if(questionVisible){\n      visibleQuestionIds.push(doc.id);\n    }\n  });\n\n  await batch.commit();\n\n  visibleQuestionIds.sort(\n    (a,b)=>\n      (orderMap[a] || 0) -\n      (orderMap[b] || 0)\n  );\n\n  /*\n    ✅ الخريطة التي يستخدمها الطالب والشريط الجانبي\n    تحتوي الآن على كل الأسئلة الفعلية للنموذج.\n  */\n  const visibleMap = {\n    ...(examData.visibleQuestionsByCourse || {})\n  };\n\n  visibleMap[courseId] =\n    visibleQuestionIds;\n\n  const updateData = {\n    visibleQuestionsByCourse:\n      visibleMap,\n\n    updatedAt:\n      firebase.firestore.FieldValue.serverTimestamp()\n  };\n\n  /*\n    توافق مع النظام القديم فقط إذا كانت الدورة الحالية هي نفسها.\n  */\n  if(\n    String(CURRENT_COURSE_ID || \"\").trim() ===\n    courseId\n  ){\n    updateData.visibleQuestions =\n      visibleQuestionIds;\n  }\n\n  await examRef.set(\n    updateData,\n    { merge:true }\n  );\n\n  console.log(\n    \"✅ Whole exam linked:\",\n    examId,\n    courseId,\n    visibleQuestionIds.length\n  );\n\n  return visibleQuestionIds;\n}\n\n/* ================= إرسال السؤال لدورة أخرى ================= */\nasync function sendToCourse(questionId){\n  const qDoc = await db.collection(\"questions\").doc(questionId).get();\n  if(!qDoc.exists) return alert(\"No questions\");\n\n  const q = qDoc.data();\n\n  const coursesSnap = await db.collection(\"Courses\").get();\n\n  let courses = [];\n\n  coursesSnap.forEach(doc=>{\n    const c = doc.data();\n\n    if(!isOpenCourse(c)) return;\n    if(!isCourseVisibleForCurrentUser(c)) return;\n\n    courses.push({\n      id: doc.id,\n      TrainingCourse: c.TrainingCourse || \"\",\n      Trainer: c.Trainer || \"\",\n      Period: c.Period || \"\"\n    });\n  });\n\n  if(!courses.length){\n    return alert(\n      canViewAllOpenCourses()\n        ? \"No open courses are available\"\n        : \"No open courses are linked to your trainer account\"\n    );\n  }\n\n  let text = \"Choose new course No.:\\\\n\\\\n\";\n  courses.forEach((c, i)=>{\n   text += `${i+1}) ${c.TrainingCourse} | ${c.Trainer} | ${c.Period || \"-\"}\\n`;\n  });\n\n  const choice = prompt(text);\n  if(choice === null) return;\n\n  const selected = courses[Number(choice) - 1];\n  if(!selected){\n    alert(\"not correct\");\n    return;\n  }\n\n  const updatedCourses = dedupeCoursesUsed([\n    ...(q.coursesUsed || []),\n    {\n      courseId: selected.id,\n      TrainingCourse: selected.TrainingCourse,\n      Trainer: selected.Trainer\n    }\n  ]);\n\nawait db.collection(\"questions\")\n  .doc(questionId)\n  .update({\n\n    linkedCourseId: selected.id,\n\n    linkedCourseName:\n      selected.TrainingCourse || \"\",\n\n    linkedTrainer:\n      selected.Trainer || \"\",\n\n    linkedPeriod:\n      selected.Period || \"\",\n\n    // ✅ حفظ كل الدورات بشكل صحيح\n    coursesUsed: dedupeCoursesUsed([\n\n      ...(q.coursesUsed || []),\n\n      {\n        courseId: selected.id,\n\n        TrainingCourse:\n          selected.TrainingCourse || \"\",\n\n        Trainer:\n          selected.Trainer || \"\",\n\n        Period:\n          selected.Period || \"\"\n      }\n\n    ])\n\n});\n\n  // ✅ اجعل مهارة الدورة المرتبطة مطابقة للمهارة المختارة في الأعلى\n  await syncLinkedCourseSkillWithTop(\n    q.examId,\n    q.group || \"General\",\n    selected.id\n  );\n\n  /*\n    تحديث قائمة الطالب بكل الأسئلة المرتبطة بالدورة،\n    وليس السؤال الحالي فقط.\n  */\n  const linkedIds = await syncAllVisibleLinkedQuestions(\n    q.examId,\n    selected.id\n  );\n\n  alert(\n    \"✅ The full exam/model has been linked successfully.\\n\" +\n    \"Questions shown to students: \" + linkedIds.length\n  );\n  await loadQuestions();\n}\nfunction liveExamPreview(searchText){\n\n  // □ فلترة القائمة أولًا\n  filterExamDropdown(searchText);\n\n  const examFilter = document.getElementById(\"examFilter\");\n\n  // □ إذا فيه نتائج → اختر أول واحد تلقائي\n  if(examFilter && examFilter.options.length > 1){\n\n    examFilter.selectedIndex = 1;\n\n    // □ عرض الأسئلة مباشرة\n    loadQuestions();\n  }\n}\nasync function removeSelectedLinkedCourse(questionId){\n\n  const select =\n    document.getElementById(\n      \"linkedSelect_\" + questionId\n    );\n\n  if(!select || !select.value){\n    alert(\"Choose course first\");\n    return;\n  }\n\n  const courseId =\n    String(select.value || \"\").trim();\n\n  if(!courseId){\n    alert(\"Choose course first\");\n    return;\n  }\n\n  const access = await verifyLinkedCourseAccess(courseId);\n\n  if(!access.allowed){\n    alert(\"⛔ You can manage linked courses for your user only\");\n    return;\n  }\n\n  const qDoc =\n    await db.collection(\"questions\")\n      .doc(questionId)\n      .get();\n\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const clickedQuestion =\n    qDoc.data() || {};\n\n  const examId =\n    String(clickedQuestion.examId || \"\").trim();\n\n  if(!examId){\n    alert(\"Exam not found\");\n    return;\n  }\n\n  try{\n\n    /*\n      ✅ REMOVE LINK = إلغاء ربط النموذج كاملًا من الدورة المحددة.\n\n      مهم:\n      لا نستدعي syncAllVisibleLinkedQuestions() بعد الحذف،\n      لأن هذه الدالة مخصصة للربط وستعيد إضافة الدورة إلى كل الأسئلة.\n    */\n\n    const [examDoc, qSnap] =\n      await Promise.all([\n        db.collection(\"exams\")\n          .doc(examId)\n          .get(),\n\n        db.collection(\"questions\")\n          .where(\"examId\",\"==\",examId)\n          .get()\n      ]);\n\n    if(!examDoc.exists){\n      alert(\"Exam not found\");\n      return;\n    }\n\n    const examData =\n      examDoc.data() || {};\n\n    const baseCourses =\n      Array.isArray(examData.coursesData)\n        ? examData.coursesData\n        : [];\n\n    const batch =\n      db.batch();\n\n    /*\n      ✅ احذف الدورة المرتبطة من coursesUsed\n      في جميع أسئلة النموذج، وليس السؤال الذي ضغطنا عليه فقط.\n    */\n    qSnap.forEach(doc=>{\n\n      const q =\n        doc.data() || {};\n\n      const oldUsed =\n        Array.isArray(q.coursesUsed)\n          ? q.coursesUsed\n          : [];\n\n      let filtered =\n        oldUsed.filter(c =>\n          String(c?.courseId || \"\").trim() !==\n          courseId\n        );\n\n      /*\n        إذا أصبح السؤال بدون أي دورة، رجعه للدورة/الدورات الأساسية\n        فقط، مع التأكد من عدم إعادة الدورة التي نحذف ربطها.\n      */\n      if(filtered.length === 0){\n\n        filtered =\n          baseCourses\n            .filter(c =>\n              String(c?.courseId || \"\").trim() !==\n              courseId\n            )\n            .map(c => ({\n              courseId:\n                c.courseId || \"\",\n\n              TrainingCourse:\n                c.TrainingCourse || \"\",\n\n              Trainer:\n                c.Trainer || \"\",\n\n              Period:\n                c.Period || \"\"\n            }));\n\n      }\n\n      const updateData = {\n        coursesUsed:\n          dedupeCoursesUsed(filtered)\n      };\n\n      /*\n        تنظيف حقول الربط القديمة إذا كانت تشير إلى\n        نفس الدورة التي تم حذفها.\n      */\n      if(\n        String(q.linkedCourseId || \"\").trim() ===\n        courseId\n      ){\n        updateData.linkedCourseId =\n          firebase.firestore.FieldValue.delete();\n\n        updateData.linkedCourseName =\n          firebase.firestore.FieldValue.delete();\n\n        updateData.linkedTrainer =\n          firebase.firestore.FieldValue.delete();\n\n        updateData.linkedPeriod =\n          firebase.firestore.FieldValue.delete();\n      }\n\n      batch.update(\n        db.collection(\"questions\").doc(doc.id),\n        updateData\n      );\n\n    });\n\n    await batch.commit();\n\n    /*\n      ✅ الأهم:\n      احذف الدورة فورًا من قائمة الأسئلة الظاهرة للطلاب.\n      بهذا الطالب لا يستطيع رؤية أي سؤال من هذا النموذج\n      بعد الضغط على Remove Link.\n    */\n    const visibleMap = {\n      ...(examData.visibleQuestionsByCourse || {})\n    };\n\n    delete visibleMap[courseId];\n\n    /*\n      ✅ حذف مهارات الدورة المرتبطة أيضًا حتى لا تبقى\n      كأنها مرتبطة في الواجهة.\n    */\n    const groupSkillsByCourse = {\n      ...(examData.groupSkillsByCourse || {})\n    };\n\n    delete groupSkillsByCourse[courseId];\n\n    const examUpdate = {\n      visibleQuestionsByCourse:\n        visibleMap,\n\n      groupSkillsByCourse:\n        groupSkillsByCourse,\n\n      updatedAt:\n        firebase.firestore.FieldValue.serverTimestamp()\n    };\n\n    /*\n      إذا كانت الدورة المفتوحة حاليًا هي نفس الدورة التي ألغينا ربطها،\n      امسح حقل النظام القديم أيضًا.\n    */\n    if(\n      String(CURRENT_COURSE_ID || \"\").trim() ===\n      courseId\n    ){\n      examUpdate.visibleQuestions = [];\n    }\n\n    await db.collection(\"exams\")\n      .doc(examId)\n      .set(\n        examUpdate,\n        { merge:true }\n      );\n\n    /*\n      إذا كان الشريط/الواجهة مركّزًا على الدورة التي أزيلت،\n      ألغِ هذا التركيز حتى لا تعود للظهور من الكاش المحلي.\n    */\n    if(\n      typeof SIDEBAR_FOCUS_COURSE_ID !== \"undefined\" &&\n      String(SIDEBAR_FOCUS_COURSE_ID || \"\").trim() ===\n      courseId\n    ){\n      SIDEBAR_FOCUS_COURSE_ID = \"\";\n    }\n\n    /*\n      ✅ تحديث زر Shown فورًا في الشريط الجانبي.\n      لا ننتظر onSnapshot أو إعادة تحميل الشريط حتى يرى المستخدم النتيجة.\n    */\n    const sidebarCheckboxId =\n      \"publishedVisible_\" +\n      String(examId).replace(/[^a-zA-Z0-9_-]/g,\"_\") +\n      \"_\" +\n      String(courseId).replace(/[^a-zA-Z0-9_-]/g,\"_\");\n\n    const sidebarCheckbox =\n      document.getElementById(sidebarCheckboxId);\n\n    if(sidebarCheckbox){\n      sidebarCheckbox.checked = false;\n      sidebarCheckbox.disabled = true;\n\n      const toggleLabel =\n        sidebarCheckbox.closest(\".published-visibility-toggle\");\n\n      if(toggleLabel){\n        toggleLabel.classList.add(\"is-hidden\");\n\n        const toggleText =\n          toggleLabel.querySelector(\".published-toggle-text\");\n\n        if(toggleText){\n          toggleText.textContent = \"Hidden\";\n        }\n      }\n    }\n\n    /*\n      ✅ أعد بناء الشريط مباشرة من Firebase بعد حذف الربط.\n      بما أن visibleQuestionsByCourse[courseId] حُذف أعلاه،\n      سيختفي النموذج من قائمة Shown بدل أن يبقى أخضر من الكاش.\n    */\n    if(typeof loadPublishedQuestionsSidebar === \"function\"){\n      await loadPublishedQuestionsSidebar(true);\n    }else if(typeof schedulePublishedSidebarRefresh === \"function\"){\n      schedulePublishedSidebarRefresh(0);\n    }\n\n    alert(\n      \"✅ Link removed completely. Shown has been turned off and students can no longer see this model in the selected course.\"\n    );\n\n    await loadQuestions();\n\n  }catch(err){\n\n    console.error(\n      \"REMOVE LINK ERROR:\",\n      err\n    );\n\n    alert(\n      \"❌ Failed to remove link: \" +\n      (err?.message || String(err))\n    );\n\n  }\n\n}\nasync function relinkQuestion(questionId){\n\n  const qDoc =\n    await db.collection(\"questions\")\n      .doc(questionId)\n      .get();\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = qDoc.data();\n\n  const coursesSnap =\n    await db.collection(\"Courses\").get();\n\n  let courses = [];\n\n  coursesSnap.forEach(doc=>{\n    const c = doc.data();\n\n    if(!isOpenCourse(c)) return;\n    if(!isCourseVisibleForCurrentUser(c)) return;\n\n    courses.push({\n      id: doc.id,\n      TrainingCourse: c.TrainingCourse || \"\",\n      Trainer: c.Trainer || \"\",\n      Period: c.Period || \"\"\n    });\n  });\n\n  if(!courses.length){\n    alert(\n      canViewAllOpenCourses()\n        ? \"No open courses are available\"\n        : \"No open courses are linked to your trainer account\"\n    );\n    return;\n  }\n\nconst old =\n  document.getElementById(\n    \"relinkBox_\" + questionId\n  );\n\nif(old){\n  old.remove();\n}\n\nconst html = `\n\n  <div\n    id=\"relinkBox_${questionId}\"\n    style=\"\n      margin-top:12px;\n      background:#fff;\n      border:2px solid #16a34a;\n      border-radius:14px;\n      padding:12px;\n    \"\n  >\n\n    <select\n      id=\"relinkSelect_${questionId}\"\n      style=\"\n        width:100%;\n        padding:12px;\n        border-radius:12px;\n        border:2px solid #16a34a;\n        font-weight:900;\n      \"\n    >\n\n      <option value=\"\">\n        ${\n          canViewAllOpenCourses()\n            ? \"Choose course — All open courses\"\n            : \"Choose course — My open courses only\"\n        }\n      </option>\n\n      ${courses.map(c => `\n\n        <option value=\"${c.id}\">\n\n          ${c.TrainingCourse}\n          |\n          ${c.Trainer}\n          ${c.Period ? ` | ${c.Period}` : \"\"}\n\n        </option>\n\n      `).join(\"\")}\n\n    </select>\n\n    <button\n      onclick=\"confirmRelinkQuestion('${questionId}')\"\n      style=\"\n        margin-top:10px;\n        width:100%;\n        padding:12px;\n        border:none;\n        border-radius:12px;\n        background:#16a34a;\n        color:#fff;\n        font-weight:900;\n        cursor:pointer;\n      \"\n    >\n      ✅ Confirm Link\n    </button>\n\n  </div>\n`;\n\nconst container =\n  document.getElementById(\n    \"linkedBox_\" + questionId\n  );\n\nif(container){\n\n  container.insertAdjacentHTML(\n    \"beforeend\",\n    html\n  );\n\n}\nreturn;\n  await db.collection(\"questions\")\n    .doc(questionId)\n    .update({\n\n      coursesUsed: dedupeCoursesUsed([\n\n        ...(q.coursesUsed || []),\n\n        {\n          courseId: selected.id,\n\n          TrainingCourse:\n            selected.TrainingCourse || \"\",\n\n          Trainer:\n            selected.Trainer || \"\",\n\n          Period:\n            selected.Period || \"\"\n        }\n\n      ])\n\n    });\n\n  alert(\"✅ Course linked again\");\n\n  await loadQuestions();\n\n}\nasync function confirmRelinkQuestion(questionId){\n\n  const select =\n    document.getElementById(\n      \"relinkSelect_\" + questionId\n    );\n\n  if(!select || !select.value){\n    alert(\"Choose course first\");\n    return;\n  }\n\n  const courseId =\n    String(select.value).trim();\n\n  const qRef =\n    db.collection(\"questions\").doc(questionId);\n\n  const qDoc =\n    await qRef.get();\n\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = qDoc.data();\n\n  const cDoc =\n    await db.collection(\"Courses\")\n      .doc(courseId)\n      .get();\n\n  if(!cDoc.exists){\n    alert(\"Course not found\");\n    return;\n  }\n\n  const selected = {\n    id: cDoc.id,\n    ...cDoc.data()\n  };\n\n  await qRef.update({\n\n    coursesUsed: dedupeCoursesUsed([\n\n      ...(q.coursesUsed || []),\n\n      {\n        courseId: selected.id,\n\n        TrainingCourse:\n          selected.TrainingCourse || \"\",\n\n        Trainer:\n          selected.Trainer || \"\",\n\n        Period:\n          selected.Period || \"\"\n      }\n\n    ])\n\n  });\n\n  // ✅ اجعل مهارة الدورة المرتبطة مطابقة للمهارة المختارة في الأعلى\n  await syncLinkedCourseSkillWithTop(\n    q.examId,\n    q.group || \"General\",\n    selected.id\n  );\n\n  const linkedIds = await syncAllVisibleLinkedQuestions(\n    q.examId,\n    selected.id\n  );\n\n  alert(\n    \"✅ The full exam/model has been linked successfully.\\n\" +\n    \"Questions shown to students: \" + linkedIds.length\n  );\n\n  await loadQuestions();\n\n}\n/* ================= حذف السؤال ================= */\nasync function deleteExam(){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n    alert(\"Choose the exam first\");\n    return;\n  }\n\n  const confirmDelete = confirm(\n    \"⚠️ سيتم حذف الاختبار وأسئلته فقط، وستبقى نتائج الطلاب محفوظة. هل تريد المتابعة؟\"\n  );\n\n  if(!confirmDelete) return;\n\n  try{\n\n    /* ==================================\n       حذف أسئلة الاختبار فقط\n    ================================== */\n\n    const qSnap = await db.collection(\"questions\")\n      .where(\"examId\",\"==\",examId)\n      .get();\n\n    for(const doc of qSnap.docs){\n\n      await db.collection(\"questions\")\n        .doc(doc.id)\n        .delete();\n\n    }\n\n    /* ==================================\n       مهم: لا نحذف النتائج القديمة\n    ================================== */\n\n    // لا تضع أي delete لمجموعة results هنا\n\n    /* ==================================\n       حذف مستند الاختبار فقط\n    ================================== */\n\n    await db.collection(\"exams\")\n      .doc(examId)\n      .delete();\n\n    alert(\n      \"✅ تم حذف الاختبار وأسئلته، وتم الاحتفاظ بنتائج الطلاب السابقة\"\n    );\n\n    CURRENT_PREVIEW_EXAM = \"\";\n    CURRENT_COURSE_ID = \"\";\n    CURRENT_COURSE_NAME = \"\";\n    CURRENT_TRAINER = \"\";\n    CURRENT_PERIOD = \"\";\n\n    const questionsList =\n      document.getElementById(\"questionsList\");\n\n    const courseTabs =\n      document.getElementById(\"courseTabs\");\n\n    if(questionsList){\n      questionsList.innerHTML = \"\";\n    }\n\n    if(courseTabs){\n      courseTabs.innerHTML = \"\";\n    }\n\n    await loadExams();\n\n  }catch(err){\n\n    console.error(\n      \"Delete exam error:\",\n      err\n    );\n\n    alert(\"❌ Failed to delete exam\");\n\n  }\n\n}\nasync function saveLinkedCourseSkill(\n  questionId,\n  courseId,\n  skill,\n  groupName,\n  selectElement = null\n){\n\n  const examId =\n    CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n\n    alert(\"Choose the exam first\");\n\n    if(selectElement){\n      selectElement.value =\n        selectElement.dataset.oldValue || \"\";\n    }\n\n    return;\n  }\n\n  try{\n\n    // ======================================\n    // 🔒 فحص أسئلة الدورة المرتبطة\n    // ======================================\n\n    const qSnap =\n      await db.collection(\"questions\")\n        .where(\"examId\", \"==\", examId)\n        .get();\n\n    const hasLockedQuestion =\n      qSnap.docs.some(doc => {\n\n        const q =\n          doc.data() || {};\n\n        const questionGroup =\n          String(q.group || \"General\").trim();\n\n        if(\n          questionGroup !==\n          String(groupName || \"General\").trim()\n        ){\n          return false;\n        }\n\n        if(q.locked !== true){\n          return false;\n        }\n\n        const used =\n          Array.isArray(q.coursesUsed)\n            ? q.coursesUsed\n            : [];\n\n        return used.some(c =>\n\n          String(c.courseId || \"\").trim() ===\n          String(courseId || \"\").trim()\n\n        );\n\n      });\n\n    if(hasLockedQuestion){\n\n      alert(\n        \"🔒 لا يمكن تعديل المهارة لأن الدورة تحتوي على سؤال مقفل داخل هذه المجموعة\"\n      );\n\n      if(selectElement){\n\n        selectElement.value =\n          selectElement.dataset.oldValue || \"\";\n\n      }\n\n      await loadQuestions();\n\n      return;\n    }\n\n    // ======================================\n    // ✅ حفظ المهارة\n    // ======================================\n\n    const examRef =\n      db.collection(\"exams\").doc(examId);\n\n    const examDoc =\n      await examRef.get();\n\n    if(!examDoc.exists){\n\n      alert(\"Exam not found\");\n\n      if(selectElement){\n        selectElement.value =\n          selectElement.dataset.oldValue || \"\";\n      }\n\n      return;\n    }\n\n    const examData =\n      examDoc.data() || {};\n\nconst map =\n  examData.groupSkillsByCourse || {};\n\nconst targetCourseId =\n  courseId || CURRENT_COURSE_ID;\n\nif(!targetCourseId){\n\n  alert(\"Choose the course first\");\n\n  if(selectElement){\n    selectElement.value =\n      selectElement.dataset.oldValue || \"\";\n  }\n\n  return;\n}\n\n/*\n  كل مدرب يستطيع تعديل مهارة دورته فقط.\n  لا يستطيع المدرب المرتبط بالأسئلة تعديل مهارة الدورة الأساسية\n  إذا لم تكن الدورة الأساسية تابعة لحسابه.\n*/\nconst permission =\n  await verifyCourseSkillPermission(\n    targetCourseId\n  );\n\nif(!permission.allowed){\n\n  alert(\n    \"⛔ يمكنك تغيير مهارة دورتك فقط، ولا يمكنك تغيير مهارة دورة مدرب آخر\"\n  );\n\n  if(selectElement){\n    selectElement.value =\n      selectElement.dataset.oldValue || \"\";\n  }\n\n  await loadQuestions();\n  return;\n}\n\nif(!map[targetCourseId]){\n  map[targetCourseId] = {};\n}\n\n// ✅ حفظ مهارة مستقلة خاصة بالدورة التي يملكها المدرب\nmap[targetCourseId][groupName] =\n  skill || \"\";\n\n    await examRef.update({\n\n      groupSkillsByCourse: map,\n\n      updatedAt:\n        firebase.firestore.FieldValue.serverTimestamp()\n\n    });\n\n    if(selectElement){\n\n      selectElement.dataset.oldValue =\n        skill || \"\";\n\n    }\n\n    await loadQuestions();\n\n    showSkillSavedToast(skill);\n\n  }catch(err){\n\n    console.error(\n      \"SAVE LINKED SKILL ERROR:\",\n      err\n    );\n\n    alert(\n      \"❌ فشل حفظ المهارة: \" +\n      (\n        err?.message ||\n        String(err)\n      )\n    );\n\n    if(selectElement){\n\n      selectElement.value =\n        selectElement.dataset.oldValue || \"\";\n\n    }\n\n  }\n\n}\nasync function toggleLinkedCourseQuestions(courseId, show){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId || !courseId){\n    alert(\"Choose exam and course first\");\n    return;\n  }\n\n  const access = await verifyLinkedCourseAccess(courseId);\n\n  if(!access.allowed){\n    alert(\"⛔ You can show/hide linked courses for your user only\");\n    return;\n  }\n\n  const examRef =\n    db.collection(\"exams\").doc(examId);\n\n  const examDoc =\n    await examRef.get();\n\n  if(!examDoc.exists){\n    alert(\"Exam not found\");\n    return;\n  }\n\n  const examData =\n    examDoc.data() || {};\n\n  const visibleMap =\n    examData.visibleQuestionsByCourse || {};\n\n  const qSnap =\n    await db.collection(\"questions\")\n      .where(\"examId\",\"==\",examId)\n      .get();\n\n  const ids = [];\n\n  qSnap.forEach(doc=>{\n\n    const q =\n      doc.data() || {};\n\n    const used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    const belongs =\n      used.some(c =>\n        String(c.courseId || \"\").trim() ===\n        String(courseId || \"\").trim()\n      );\n\n    if(belongs){\n      ids.push(doc.id);\n    }\n\n  });\n\n  if(show){\n    /*\n      إعادة جمع جميع الأسئلة المرتبطة بهذه الدورة.\n      هذا يمنع حفظ سؤال واحد فقط داخل الخريطة.\n    */\n    await syncAllVisibleLinkedQuestions(\n      examId,\n      courseId\n    );\n  }else{\n    visibleMap[courseId] = [];\n\n    await examRef.set(\n      {\n        visibleQuestionsByCourse:\n          visibleMap,\n\n        updatedAt:\n          firebase.firestore.FieldValue.serverTimestamp()\n      },\n      {\n        merge:true\n      }\n    );\n  }\n\n  alert(\n    show\n      ? \"✅ Questions shown to students\"\n      : \"✅ Questions hidden from students\"\n  );\n\n  await loadQuestions();\n}\n\n\n/* =========================================\n   ONE GLOBAL QUESTION TOOLBAR\n========================================= */\ndocument.addEventListener(\"click\",function(event){\n  const card = event.target.closest(\n    \".pro-question-card[data-question-id]\"\n  );\n\n  if(!card) return;\n\n  setActiveQuestion(\n    card.dataset.questionId || \"\"\n  );\n});\n\nfunction setActiveQuestion(questionId){\n  ACTIVE_QUESTION_ID = String(questionId || \"\").trim();\n\n  document.querySelectorAll(\".pro-question-card\")\n    .forEach(card=>{\n      card.classList.toggle(\n        \"active-question\",\n        card.dataset.questionId === ACTIVE_QUESTION_ID\n      );\n    });\n\n  const label = document.getElementById(\"activeQuestionLabel\");\n  if(label){\n    if(ACTIVE_QUESTION_ID){\n      const card = document.querySelector(\n        `.pro-question-card[data-question-id=\"${ACTIVE_QUESTION_ID}\"]`\n      );\n      const number = card?.dataset.questionNumber || \"\";\n      label.textContent =\n        number\n          ? `Selected Question: ${number}`\n          : \"A question is selected\";\n    }else{\n      label.textContent =\n        \"Click any question card to select it for Edit, Linked Courses, Reset, or Delete.\";\n    }\n  }\n\n  updateSelectedQuestionDeleteButton();\n}\n\nfunction updateSelectedQuestionDeleteButton(){\n  const btn = document.getElementById(\"deleteSelectedQuestionBtn\");\n  if(!btn) return;\n\n  const id = String(ACTIVE_QUESTION_ID || \"\").trim();\n\n  if(!id){\n    btn.disabled = true;\n    btn.style.background = \"#94a3b8\";\n    btn.style.cursor = \"not-allowed\";\n    btn.innerHTML = \"🗑️ Delete Selected Question\";\n    btn.title = \"Select a question first\";\n    return;\n  }\n\n  const card = document.querySelector(\n    `.pro-question-card[data-question-id=\"${id}\"]`\n  );\n\n  const locked =\n    String(card?.dataset.questionLocked || \"false\") === \"true\";\n\n  if(locked){\n    btn.disabled = true;\n    btn.style.background = \"#94a3b8\";\n    btn.style.cursor = \"not-allowed\";\n    btn.innerHTML = \"🔒 Locked — Cannot Delete\";\n    btn.title = \"This question is locked. Unlock it before deleting.\";\n  }else{\n    btn.disabled = false;\n    btn.style.background = \"#dc2626\";\n    btn.style.cursor = \"pointer\";\n    btn.innerHTML = \"🗑️ Delete Selected Question\";\n    btn.title = \"Delete only the selected question\";\n  }\n}\n\nfunction getActiveQuestionId(){\n  if(\n    ACTIVE_QUESTION_ID &&\n    document.querySelector(\n      `.pro-question-card[data-question-id=\"${ACTIVE_QUESTION_ID}\"]`\n    )\n  ){\n    return ACTIVE_QUESTION_ID;\n  }\n\n  const firstCard =\n    document.querySelector(\".pro-question-card\");\n\n  if(firstCard){\n    setActiveQuestion(firstCard.dataset.questionId || \"\");\n    return firstCard.dataset.questionId || \"\";\n  }\n\n  alert(\"No question is available\");\n  return \"\";\n}\n\nfunction editActiveQuestion(){\n  const id = getActiveQuestionId();\n  if(id) editQuestion(id);\n}\n\nfunction toggleActiveLinkedCourses(){\n  const id = getActiveQuestionId();\n  if(!id) return;\n\n  const box = document.getElementById(`linkedBox_${id}`);\n  if(!box) return;\n\n  box.style.display =\n    box.style.display === \"none\" || !box.style.display\n      ? \"block\"\n      : \"none\";\n\n  if(box.style.display === \"block\"){\n    box.scrollIntoView({\n      behavior:\"smooth\",\n      block:\"center\"\n    });\n  }\n}\n\nfunction resetAllActiveQuestion(){\n  const id = getActiveQuestionId();\n  if(id) resetAllByQuestion(id);\n}\n\nfunction resetStudentActiveQuestion(){\n  const id = getActiveQuestionId();\n  if(id) resetOneByQuestion(id);\n}\n\nfunction deleteActiveQuestion(){\n  const id = getActiveQuestionId();\n  if(id) deleteQuestion(id);\n}\n\nasync function saveAllQuestionEdits(){\n  const cards = [\n    ...document.querySelectorAll(\n      \".pro-question-card[data-question-id]\"\n    )\n  ];\n\n  if(!cards.length){\n    alert(\"No questions to save\");\n    return;\n  }\n\n  const button =\n    document.getElementById(\"saveAllQuestionEditsBtn\");\n\n  if(button){\n    button.disabled = true;\n    button.textContent = \"⏳ Saving All Changes...\";\n  }\n\n  let saved = 0;\n  let skipped = 0;\n  const failed = [];\n\n  try{\n    for(const card of cards){\n      const id =\n        String(card.dataset.questionId || \"\").trim();\n\n      if(!id) continue;\n\n      try{\n        const result = await quickUpdateQuestion(id,{\n          silent:true,\n          reload:false\n        });\n\n        if(result === true){\n          saved++;\n        }else{\n          skipped++;\n        }\n      }catch(error){\n        console.error(\n          \"SAVE ALL QUESTION ERROR:\",\n          id,\n          error\n        );\n        failed.push(id);\n      }\n    }\n\n    await autoSaveVisibleQuestions();\n    await loadQuestions();\n\n    const message = [\n      `✅ Saved: ${saved}`,\n      skipped ? `Skipped: ${skipped}` : \"\",\n      failed.length ? `Failed: ${failed.length}` : \"\"\n    ].filter(Boolean).join(\" | \");\n\n    alert(message);\n\n  }finally{\n    if(button){\n      button.disabled = false;\n      button.textContent = \"✅ Save All Changes\";\n    }\n  }\n}\n\n/* ================= عرض الأسئلة ================= */\nasync function loadQuestions(){\n\n  const questionsList =\n    document.getElementById(\"questionsList\");\n\n  let selectedExamId =\n    CURRENT_PREVIEW_EXAM;\n\n  if(!selectedExamId){\n\n    questionsList.innerHTML = `\n      <div class=\"empty\">⚠️ choose the exam</div>\n    `;\n\n    return;\n  }\n\n  try{\n\n    const examDoc =\n      await db.collection(\"exams\")\n        .doc(selectedExamId)\n        .get();\n\n    const examData =\n      examDoc.exists ? examDoc.data() : {};\n\n    const onePageQuestions =\n      examData.onePageQuestions === true;\n\n    const visibleMap =\n      examData.visibleQuestionsByCourse || {};\n\n    const courseVisible =\n      (visibleMap[CURRENT_COURSE_ID] || []).length > 0;\n\n    let visibleQuestions =\n      visibleMap[CURRENT_COURSE_ID] || [];\n\n    if(visibleQuestions.length === 0){\n\n      const firstCourseId =\n        Object.keys(visibleMap)[0];\n\n      if(\n        firstCourseId &&\n        firstCourseId !== CURRENT_COURSE_ID\n      ){\n        visibleQuestions =\n          visibleMap[firstCourseId] || [];\n      }\n\n    }\n\n    const groupSkillsByCourse =\n      examData.groupSkillsByCourse || {};\n\n    const groupSkills =\n      groupSkillsByCourse[CURRENT_COURSE_ID] || {};\n\n    questionsList.innerHTML = \"\";\n\n    questionsList.innerHTML += `\n\n      <div style=\"margin-top:10px;margin-bottom:15px\">\n\n        <button\n          onclick=\"toggleLinkedCourseQuestions(\n            '${CURRENT_COURSE_ID}',\n            ${!courseVisible}\n          )\"\n          style=\"\n            width:100%;\n            padding:14px;\n            border:none;\n            border-radius:14px;\n            font-weight:900;\n            font-size:16px;\n            cursor:pointer;\n            background:${courseVisible ? '#16a34a' : '#dc2626'};\n            color:#fff;\n          \"\n        >\n          ${\n            courseVisible\n              ? '□ Hide Questions'\n              : '✅ Show Questions'\n          }\n        </button>\n\n      </div>\n\n    `;\n\n    const USER_ROLE =\n      (\n        localStorage.getItem(\"role\") || \"\"\n      ).toLowerCase();\n\n    questionsList.innerHTML += `\n      <div class=\"exam-global-actions\" id=\"examGlobalActions\">\n\n        <div class=\"exam-global-note\" id=\"activeQuestionLabel\">\n          Click any question card to select it for Edit, Linked Courses, Reset, or Delete.\n          Save All Changes saves every edited question at once.\n        </div>\n\n        <button\n          id=\"saveAllQuestionEditsBtn\"\n          type=\"button\"\n          onclick=\"saveAllQuestionEdits()\"\n          style=\"background:#16a34a\">\n          ✅ Save All Changes\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"editActiveQuestion()\"\n          style=\"background:#0ea5e9\">\n          ✏️ Edit Selected Question\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"toggleActiveLinkedCourses()\"\n          style=\"background:#2563eb\">\n          🔗 Linked Courses\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"resetAllActiveQuestion()\"\n          style=\"background:#7c3aed\">\n          ♻️ Reset All\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"resetStudentActiveQuestion()\"\n          style=\"background:#f59e0b\">\n          👤 Reset Student\n        </button>\n\n        <button\n          id=\"deleteSelectedQuestionBtn\"\n          type=\"button\"\n          onclick=\"deleteActiveQuestion()\"\n          style=\"background:#94a3b8\"\n          disabled\n          title=\"Select a question first\">\n          🗑️ Delete Selected Question\n        </button>\n\n      </div>\n    `;\n\n    if(true){\n\n      questionsList.innerHTML += `\n\n        <div style=\"\n          display:flex;\n          gap:10px;\n          flex-wrap:wrap;\n          margin-top:14px;\n          margin-bottom:14px;\n        \">\n\n          <button\n            onclick=\"bulkLockQuestions(true)\"\n            style=\"\n              flex:1;\n              background:#dc2626;\n              color:#fff;\n              border:none;\n              border-radius:14px;\n              padding:14px;\n              font-weight:900;\n              cursor:pointer;\n            \"\n          >\n            □ Lock Selected\n          </button>\n\n          <button\n            onclick=\"bulkLockQuestions(false)\"\n            style=\"\n              flex:1;\n              background:#16a34a;\n              color:#fff;\n              border:none;\n              border-radius:14px;\n              padding:14px;\n              font-weight:900;\n              cursor:pointer;\n            \"\n          >\n            □ Unlock Selected\n          </button>\n<button\n  onclick=\"updateAllQuestionsDegree()\"\n  style=\"\n    flex:1;\n    background:#7c3aed;\n    color:#fff;\n    border:none;\n    border-radius:14px;\n    padding:14px;\n    font-weight:900;\n    cursor:pointer;\n  \"\n>\n  ⭐ Change All Degrees\n</button>\n        </div>\n\n      `;\n\n    }\nquestionsList.innerHTML += `\n  <div class=\"question-management-toolbar\">\n    <button type=\"button\" onclick=\"openQuestionCopyBank()\" style=\"background:#8b5cf6\">\n      <i class=\"fa-solid fa-copy\"></i> Copy From Previous Exams\n    </button>\n    <button type=\"button\" onclick=\"normalizeCurrentQuestionOrder()\" style=\"background:#0ea5e9\">\n      <i class=\"fa-solid fa-arrow-down-1-9\"></i> Renumber Questions\n    </button>\n  </div>\n`;\n\nconst snap =\n  await db.collection(\"questions\")\n    .where(\"examId\",\"==\",selectedExamId)\n    .get();\n\nconst examQuestions =\n  snap.docs.map(doc=>({\n    id: doc.id,\n    ...doc.data()\n  }));\nconst hasLockedQuestions =\n  examQuestions.some(q => q.locked === true);\n\nconst deleteExamBtn =\n  document.getElementById(\"deleteExamBtn\");\n\nif(deleteExamBtn){\n  if(false){\n    deleteExamBtn.style.display = \"none\";\n  }else{\n    deleteExamBtn.style.display = \"block\";\n  }\n}\n/*\n  ✅ FIX — الفرق بين فتح النموذج من مربع الاختبارات وفتحه من الشريط\n\n  1) عند الضغط على بطاقة الاختبار من \"Previews questions\":\n     نعرض جميع الأسئلة الفعلية التابعة لنفس examId بدون فلترة coursesUsed.\n\n  2) عند الضغط على الاختبار من \"Questions Shown to Students\":\n     نحافظ على SIDEBAR_FOCUS_COURSE_ID لمعرفة دورة المدرب والتحكم بها،\n     لكن SIDEBAR_SHOW_FULL_EXAM يجعلنا نعرض جميع أسئلة النموذج كاملة\n     تماماً مثل الضغط على الاختبار من الشاشة الرئيسية.\n\n  المشكلة السابقة:\n  openExamTab() عند الفتح العادي يختار أول دورة داخل coursesData،\n  وبعدها هذا الفلتر كان يحذف أي سؤال لا يحتوي تلك الدورة داخل coursesUsed،\n  لذلك كانت تظهر مجموعة ناقصة وقد يظهر سؤال واحد فقط.\n*/\nlet questions = [...examQuestions];\n\nif(SIDEBAR_FOCUS_COURSE_ID && SIDEBAR_SHOW_FULL_EXAM !== true){\n\n  const focusCourseId =\n    String(SIDEBAR_FOCUS_COURSE_ID || \"\").trim();\n\n  questions = questions.filter(q => {\n\n    const used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    /*\n      السؤال بدون coursesUsed يعتبر من أسئلة النموذج الأساسية،\n      لذلك يبقى ظاهرًا أيضًا.\n    */\n    if(used.length === 0){\n      return true;\n    }\n\n    return used.some(c =>\n      String(c.courseId || \"\").trim() ===\n      focusCourseId\n    );\n\n  });\n\n}\n\nlet totalDegree = 0;\n\nquestions.forEach(q => {\n  totalDegree += Number(q.degree || 0);\n});\n\nquestionsList.innerHTML += `\n  <div style=\"\n    background:#ecfdf5;\n    border:2px solid #bbf7d0;\n    color:#166534;\n    padding:14px;\n    border-radius:16px;\n    font-size:22px;\n    font-weight:900;\n    text-align:center;\n    margin-bottom:15px;\n  \">\n    ⭐ Total Quiz Marks: ${totalDegree}\n  </div>\n`;\n\nquestionsList.innerHTML += `\n\n  <div class=\"badge ${onePageQuestions ? 'ok' : 'warn'}\"\n       style=\"margin-bottom:10px\">\n    □ One Page:\n    ${onePageQuestions ? 'ON' : 'OFF'}\n  </div>\n\n`;\n\nquestions.sort((a,b)=>{\n  const ao = Number(a.order || 0);\n  const bo = Number(b.order || 0);\n  if(ao !== bo) return ao - bo;\n  const at = a.createdAt?.seconds || 0;\n  const bt = b.createdAt?.seconds || 0;\n  return at - bt;\n});\n\nconst questionNumberMap = new Map(\n  questions.map((item, idx) => [item.id, idx + 1])\n);\n\nconst homeworkCount =\n  questions.filter(q =>\n    String(q.group || \"\").toLowerCase()\n      .includes(\"homework\")\n  ).length;\n\nif(examData.isHomework === true){\n\n  questionsList.innerHTML += `\n\n    <div style=\"\n      margin-top:10px;\n      background:#fff7ed;\n      border:2px solid #fdba74;\n      color:#9a3412;\n      padding:14px;\n      border-radius:14px;\n      font-weight:900;\n      line-height:1.9;\n    \">\n\n      □ Homework Quiz\n      <br>\n      ✅ Total Homework Quizzes in this course:\n      ${homeworkCount}\n      <br>\n      □ Maximum counted:\n      5 Homework only = 10 marks\n\n    </div>\n\n  `;\n}\n\nif(!questions.length){\n\n  questionsList.innerHTML += `\n    <div class=\"empty\">لا توجد أسئلة</div>\n  `;\n\n  return;\n}\n    const allQuestionsSnap =\n      await db.collection(\"questions\").get();\n\n    const allQuestions =\n      allQuestionsSnap.docs.map(doc => ({\n        id: doc.id,\n        ...doc.data()\n      }));\n\n    const grouped = {};\n\n    questions.forEach(q=>{\n\n      const groupName =\n        String(q.group || \"General\");\n\n      if(!grouped[groupName]){\n        grouped[groupName] = [];\n      }\n\n      grouped[groupName].push(q);\n\n    });\n    // ✅ جلب كل الاختبارات لحساب المهارات والدورات المرتبطة\nconst examsSnapForSkills =\n  await db.collection(\"exams\").get();\n// ======================================\n// ✅ Linked Courses Stats\n// ======================================\n\nconst linkedCoursesStats = {};\n\n// ✅ المرور على الأسئلة\n// ✅ المرور على جميع الأسئلة\nallQuestions.forEach(q=>{\n\n  // ❌ تجاهل Reading Passage\n  if(q.isMain === true){\n    return;\n  }\n\n  const used =\n    Array.isArray(q.coursesUsed)\n      ? q.coursesUsed\n      : [];\n\n// ❌ تجاهل الأسئلة التي ليست مرتبطة\n// بنفس الدورة الحالية أو المرتبطة\n\nconst hasCurrentCourse =\n  used.some(c =>\n\n    String(c.courseId || \"\").trim() ===\n    String(CURRENT_COURSE_ID).trim()\n\n  );\n\nif(!hasCurrentCourse){\n  return;\n}\n  const realGroupName =\n    String(q.group || \"General\").trim();\n\n  used.forEach(c=>{\n\n    const cid =\n      String(c.courseId || \"\").trim();\n\n    // ❌ تجاهل الدورة الأساسية\n    if(\n      cid ===\n      String(CURRENT_COURSE_ID).trim()\n    ){\n      return;\n    }\n\n    // ✅ إنشاء الدورة\n    if(!linkedCoursesStats[cid]){\n\n      linkedCoursesStats[cid] = {\n\n        courseId: cid,\n\n        TrainingCourse:\n          c.TrainingCourse || \"\",\n\n        Trainer:\n          c.Trainer || \"\",\n\n        Period:\n          c.Period || \"\",\n\n        skills: {},\n\n        savedSkills:\n          groupSkillsByCourse?.[cid] || {}\n\n      };\n\n    }\n\n    // ✅ المهارة الخاصة بالدورة\n// ✅ جلب المهارة المحفوظة تلقائياً\nlet skillName =\n\n  linkedCoursesStats[cid]\n    ?.savedSkills?.[realGroupName]\n\n  ||\n\n  groupSkillsByCourse?.[cid]?.[realGroupName]\n\n  ||\n\n  groupSkills?.[realGroupName]\n\n  ||\n\n  \"\";\n\n// ✅ إذا لا توجد مهارة\n// حاول أخذها من أي اختبار آخر\nif(!skillName){\n\n  examsSnapForSkills.forEach(examDoc=>{\n\n    const ex = examDoc.data() || {};\n\n    const map =\n      ex.groupSkillsByCourse || {};\n\n    const saved =\n      map?.[cid]?.[realGroupName];\n\n    if(saved && !skillName){\n\n      skillName = saved;\n\n    }\n\n  });\n\n}\n    // ❌ تجاهل إذا لا توجد مهارة\n    if(!skillName || skillName === \"No Skill\"){\n      return;\n    }\n\n    // ✅ إنشاء المهارة\n    if(\n      linkedCoursesStats[cid]\n        .skills[skillName] === undefined\n    ){\n      linkedCoursesStats[cid]\n        .skills[skillName] = 0;\n    }\n\n    // ✅ كل سؤال يزيد العدد\n// ======================================\n// ✅ حساب المهارة حسب عدد الدورات\n// وليس حسب عدد الأسئلة\n// ======================================\n\n// إنشاء مخزن داخلي\nif(\n  !linkedCoursesStats[cid]\n    .countedSkills\n){\n  linkedCoursesStats[cid]\n    .countedSkills = {};\n}\n\n// إنشاء Set للمهارة\nif(\n  !linkedCoursesStats[cid]\n    .countedSkills[skillName]\n){\n  linkedCoursesStats[cid]\n    .countedSkills[skillName] = new Set();\n}\n\n// ✅ إنشاء Set للامتحانات\nif(\n  !linkedCoursesStats[cid]\n    .countedSkills[skillName]\n){\n  linkedCoursesStats[cid]\n    .countedSkills[skillName] = new Set();\n}\n\n// ✅ كل اختبار ينحسب مرة واحدة\nlinkedCoursesStats[cid]\n  .countedSkills[skillName]\n  .add(String(q.examId || \"\"));\n\n// ✅ العدد النهائي\nlinkedCoursesStats[cid]\n  .skills[skillName] =\n\n  linkedCoursesStats[cid]\n    .countedSkills[skillName]\n    .size;  });\n\n});\n\n/*\n  ============================================================\n  SIDEBAR COURSE FOCUS\n  عند فتح الاختبار من الشريط الجانبي:\n  Linked Courses يجب أن يعرض دورة المدرب المختارة فقط،\n  حتى لو كانت نفس الأسئلة مرتبطة بدورات مدربين آخرين.\n  ============================================================\n*/\nif(\n  SIDEBAR_FOCUS_COURSE_ID &&\n  String(SIDEBAR_FOCUS_COURSE_ID).trim() ===\n  String(CURRENT_COURSE_ID || \"\").trim()\n){\n  const focusId =\n    String(SIDEBAR_FOCUS_COURSE_ID).trim();\n\n  const focusStats = {\n    courseId: focusId,\n    TrainingCourse: CURRENT_COURSE_NAME || \"\",\n    Trainer: CURRENT_TRAINER || \"\",\n    Period: CURRENT_PERIOD || \"\",\n    skills: {},\n    savedSkills:\n      groupSkillsByCourse?.[focusId] || {},\n    countedSkills: {}\n  };\n\n  /*\n    نحسب الإحصاءات للدورة المختارة نفسها،\n    بدل إحصاءات الدورات الأخرى المرتبطة بنفس الأسئلة.\n  */\n  allQuestions.forEach(q=>{\n    if(q.isMain === true) return;\n\n    const used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    const belongsToFocus =\n      used.some(item =>\n        String(item?.courseId || \"\").trim() ===\n        focusId\n      );\n\n    if(!belongsToFocus) return;\n\n    const realGroupName =\n      String(q.group || \"General\").trim();\n\n    let skillName =\n      groupSkillsByCourse?.[focusId]?.[realGroupName]\n      || groupSkills?.[realGroupName]\n      || \"\";\n\n    if(!skillName){\n      examsSnapForSkills.forEach(examDoc=>{\n        const ex = examDoc.data() || {};\n        const saved =\n          ex.groupSkillsByCourse?.[focusId]?.[realGroupName];\n\n        if(saved && !skillName){\n          skillName = saved;\n        }\n      });\n    }\n\n    if(!skillName || skillName === \"No Skill\"){\n      return;\n    }\n\n    if(!focusStats.countedSkills[skillName]){\n      focusStats.countedSkills[skillName] = new Set();\n    }\n\n    focusStats.countedSkills[skillName]\n      .add(String(q.examId || \"\"));\n  });\n\n  Object.keys(focusStats.countedSkills)\n    .forEach(skillName=>{\n      focusStats.skills[skillName] =\n        focusStats.countedSkills[skillName].size;\n    });\n\n  // امسح جميع دورات الآخرين ثم أضف دورة المدرب المختارة فقط.\n  Object.keys(linkedCoursesStats)\n    .forEach(key => delete linkedCoursesStats[key]);\n\n  linkedCoursesStats[focusId] = focusStats;\n}\n\n    Object.keys(grouped).forEach(groupName=>{\n\n      const groupQuestions = grouped[groupName];\n      const encodedGroup = encodeURIComponent(groupName);\n\n      const allChecked = groupQuestions.every(q =>\n        visibleQuestions.includes(q.id)\n      );\n// ======================================\n// 🔒 هل يوجد سؤال مقفل داخل هذه المجموعة؟\n// إذا كان سؤال واحد مقفلاً، تمنع المهارة كلها\n// ======================================\n\nconst groupHasLockedQuestion =\n  groupQuestions.some(q =>\n    q.locked === true\n  );\n      const currentSkill = groupSkills[groupName] || \"\";\nconst baseSkill =\n  groupSkillsByCourse?.[CURRENT_COURSE_ID]?.[groupName] || \"\";\n\nconst canEditBaseSkill =\n  canEditTrainerCourseSkill(\n    CURRENT_TRAINER\n  );\n// ======================================\n// ✅ حساب مهارات الجروب الحالية\n// ======================================\n\n// ======================================\n// ======================================\n// ✅ حساب جميع اختبارات الدورة بدون await هنا\n// ======================================\n\nlet homeworkCount = 0;\nlet listeningCount = 0;\nlet readingCount = 0;\nlet grammarCount = 0;\nlet generalCount = 0;\n\nconst countedExams = new Set();\n\nexamsSnapForSkills.forEach(doc=>{\n\n  const ex = doc.data() || {};\n  const examId = doc.id;\n\n  if(countedExams.has(examId)) return;\n\n  const belongsToCourse =\n    Array.isArray(ex.courseIds) &&\n    ex.courseIds.some(id =>\n      String(id).trim() ===\n      String(CURRENT_COURSE_ID).trim()\n    );\n\n  if(!belongsToCourse) return;\n\n  const map = ex.groupSkillsByCourse || {};\n  const courseSkills = map[CURRENT_COURSE_ID] || {};\n\n  const hasThisGroup =\n    courseSkills[groupName];\n\n  if(!hasThisGroup) return;\n\n  countedExams.add(examId);\n\n  const skill = courseSkills[groupName] || \"General\";\n\n  if(skill === \"Homework\") homeworkCount++;\n  else if(skill === \"Listening\") listeningCount++;\n  else if(skill === \"Reading\") readingCount++;\n  else if(skill === \"Grammar\") grammarCount++;\n  else generalCount++;\n\n});// ======================================\n// ✅ GROUP BOX\n// ======================================\n\nquestionsList.innerHTML += `\n\n<div style=\"\n  border:2px solid #cfe0ff;\n  background:#f3f8ff;\n  border-radius:18px;\n  padding:16px;\n  margin-top:18px;\n\">\n\n  <div style=\"\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    flex-wrap:wrap;\n    gap:10px;\n  \">\n\n    <div style=\"\n      font-weight:900;\n      color:#164478;\n      font-size:20px;\n    \">\n      □ ${esc(groupName)}\n    </div>\n\n    <label style=\"\n      display:flex;\n      gap:8px;\n      align-items:center;\n      font-weight:900;\n      color:#164478;\n    \">\n\n      <input\n        type=\"checkbox\"\n        class=\"groupMasterCheck\"\n        data-group=\"${esc(groupName)}\"\n        ${allChecked ? \"checked\" : \"\"}\n        onchange='toggleWholeGroup(${JSON.stringify(groupName)}, this.checked)'\n      >\n\n      All Questions\n\n    </label>\n\n  </div>\n\n  <div style=\"\n    display:flex;\n    gap:10px;\n    flex-wrap:wrap;\n    margin-top:14px;\n  \">\n<div style=\"width:100%;margin-bottom:12px\">\n\n  <select\n\n  id=\"groupSkill_${encodedGroup}\"\n\n  data-old-value=\"${esc(baseSkill)}\"\n\n  ${\n    (\n      groupHasLockedQuestion ||\n      !canEditBaseSkill\n    )\n      ? \"disabled\"\n      : \"\"\n  }\n\n  title=\"${\n    !canEditBaseSkill\n      ? 'هذه المهارة تخص مدرب الدورة الأساسية فقط'\n      : (\n          groupHasLockedQuestion\n            ? 'المجموعة تحتوي على سؤال مقفل'\n            : 'تغيير مهارة دورتك'\n        )\n  }\"\n\n  onchange=\"\n    saveGroupSkill(\n      '${encodedGroup}',\n      this.value,\n      '${CURRENT_COURSE_ID}',\n      this\n    )\n  \"\n\n  style=\"\n    width:100%;\n    padding:12px;\n    border-radius:12px;\n\n    border:2px solid ${\n      (\n          groupHasLockedQuestion ||\n          !canEditBaseSkill\n        )\n        ? '#991b1b'\n        : '#164478'\n    };\n\n    background:${\n      (\n          groupHasLockedQuestion ||\n          !canEditBaseSkill\n        )\n        ? '#fee2e2'\n        : '#ffffff'\n    };\n\n    color:${\n      (\n          groupHasLockedQuestion ||\n          !canEditBaseSkill\n        )\n        ? '#991b1b'\n        : '#164478'\n    };\n\n    cursor:${\n      (\n          groupHasLockedQuestion ||\n          !canEditBaseSkill\n        )\n        ? 'not-allowed'\n        : 'pointer'\n    };\n\n    opacity:${\n      (\n          groupHasLockedQuestion ||\n          !canEditBaseSkill\n        )\n        ? '.80'\n        : '1'\n    };\n\n    font-weight:900;\n  \"\n>\n    <option value=\"\" ${baseSkill===\"\" ? \"selected\" : \"\"}>No Skill</option>\n    <option value=\"Listening\" ${baseSkill===\"Listening\" ? \"selected\" : \"\"}>Listening</option>\n    <option value=\"Speaking\" ${baseSkill===\"Speaking\" ? \"selected\" : \"\"}>Speaking</option>\n    <option value=\"Reading\" ${baseSkill===\"Reading\" ? \"selected\" : \"\"}>Reading</option>\n    <option value=\"Writing\" ${baseSkill===\"Writing\" ? \"selected\" : \"\"}>Writing</option>\n    <option value=\"Grammar\" ${baseSkill===\"Grammar\" ? \"selected\" : \"\"}>Grammar</option>\n    <option value=\"Vocabulary\" ${baseSkill===\"Vocabulary\" ? \"selected\" : \"\"}>Vocabulary</option>\n    <option value=\"Homework\" ${baseSkill===\"Homework\" ? \"selected\" : \"\"}>Homework</option>\n  </select>\n\n</div>\n    <div class=\"skill-box\">□ Homework<br>${homeworkCount}</div>\n    <div class=\"skill-box\">□ Listening<br>${listeningCount}</div>\n    <div class=\"skill-box\">□ Reading<br>${readingCount}</div>\n    <div class=\"skill-box\">✍️ Grammar<br>${grammarCount}</div>\n    <div class=\"skill-box\">□ General<br>${generalCount}</div>\n\n    ${Object.keys(linkedCoursesStats).length ? `\n\n<div style=\"\n  width:100%;\n  margin-top:18px;\n  background:#ffffff;\n  border:1px solid #dbeafe;\n  border-radius:18px;\n  padding:16px;\n\">\n\n  <div style=\"\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:10px;\n    flex-wrap:wrap;\n    margin-bottom:14px;\n  \">\n\n    <div style=\"\n      font-size:20px;\n      font-weight:900;\n      color:#164478;\n    \">\n      □ Linked Courses\n    </div>\n\n    <div style=\"\n      background:#eef5ff;\n      color:#164478;\n      padding:6px 14px;\n      border-radius:999px;\n      font-weight:900;\n      font-size:13px;\n    \">\n      ${Object.keys(linkedCoursesStats).length} Courses\n    </div>\n\n  </div>\n\n  <div style=\"\n    display:grid;\n    grid-template-columns:repeat(auto-fill,minmax(260px,1fr));\n    gap:14px;\n  \">\n\n    ${Object.values(linkedCoursesStats).map(c=>{\n\n      const linkedVisible =\n        Array.isArray(visibleMap[c.courseId]) &&\n        visibleMap[c.courseId].length > 0;\n\n      return `\n\n        <div style=\"\n          background:${linkedVisible ? '#f0fdf4' : '#fef2f2'};\n          border:2px solid ${linkedVisible ? '#22c55e' : '#ef4444'};\n          border-radius:18px;\n          padding:14px;\n        \">\n\n          <div style=\"\n            display:flex;\n            justify-content:space-between;\n            align-items:center;\n            gap:8px;\n            margin-bottom:10px;\n          \">\n\n            <div style=\"\n              font-size:18px;\n              font-weight:900;\n              color:#164478;\n              line-height:1.5;\n            \">\n              ${esc(c.TrainingCourse || \"-\")}\n            </div>\n\n            <span style=\"\n              background:${linkedVisible ? '#16a34a' : '#dc2626'};\n              color:#fff;\n              padding:5px 10px;\n              border-radius:999px;\n              font-size:12px;\n              font-weight:900;\n              white-space:nowrap;\n            \">\n              ${linkedVisible ? 'Visible' : 'Hidden'}\n            </span>\n\n          </div>\n\n          <div style=\"\n            color:#374151;\n            font-weight:800;\n            font-size:14px;\n            line-height:1.9;\n            margin-bottom:12px;\n          \">\n            □‍□ ${esc(c.Trainer || \"-\")}\n            <br>\n            ⏰ ${esc(c.Period || \"-\")}\n          </div>\n${(()=>{\n\n  const realGroupName =\n    String(groupName || \"General\").trim();\n\n  // ✅ لكل دورة مرتبطة مهارة مستقلة خاصة بها\n  const linkedSkill =\n    groupSkillsByCourse?.[c.courseId]?.[realGroupName]\n    || baseSkill\n    || \"\";\n\n  const canEditLinkedSkill =\n    canEditTrainerCourseSkill(\n      c.Trainer || \"\"\n    );\n// ======================================\n// 🔒 فحص الأسئلة المقفلة التابعة لهذه\n// الدورة المرتبطة وهذه المجموعة\n// ======================================\n\nconst linkedGroupHasLockedQuestion =\n  groupQuestions.some(q => {\n\n    if(q.locked !== true){\n      return false;\n    }\n\n    const used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    return used.some(item =>\n\n      String(item.courseId || \"\").trim() ===\n      String(c.courseId || \"\").trim()\n\n    );\n\n  });\n  return `\n\n   <select\n\n  data-old-value=\"${esc(linkedSkill)}\"\n\n  ${\n    (\n      linkedGroupHasLockedQuestion ||\n      !canEditLinkedSkill\n    )\n      ? \"disabled\"\n      : \"\"\n  }\n\n  onchange=\"\n    saveLinkedCourseSkill(\n      '',\n      '${c.courseId}',\n      this.value,\n      ${JSON.stringify(realGroupName)},\n      this\n    )\n  \"\n\n  title=\"${\n    !canEditLinkedSkill\n      ? 'هذه المهارة تخص مدرب هذه الدورة فقط'\n      : (\n          linkedGroupHasLockedQuestion\n            ? 'الدورة تحتوي على سؤال مقفل في هذه المجموعة'\n            : 'يمكنك تغيير مهارة دورتك المرتبطة فقط'\n        )\n  }\"\n\n  style=\"\n    width:100%;\n    padding:12px;\n    border-radius:12px;\n\n    border:2px solid ${\n      (\n          linkedGroupHasLockedQuestion ||\n          !canEditLinkedSkill\n        )\n        ? '#991b1b'\n        : '#164478'\n    };\n\n    background:${\n      (\n          linkedGroupHasLockedQuestion ||\n          !canEditLinkedSkill\n        )\n        ? '#fee2e2'\n        : '#ffffff'\n    };\n\n    color:${\n      (\n          linkedGroupHasLockedQuestion ||\n          !canEditLinkedSkill\n        )\n        ? '#991b1b'\n        : '#164478'\n    };\n\n    cursor:${\n      (\n        linkedGroupHasLockedQuestion ||\n        !canEditLinkedSkill\n      )\n        ? 'not-allowed'\n        : 'pointer'\n    };\n\n    opacity:.88;\n\n    font-weight:900;\n    margin-top:10px;\n    margin-bottom:12px;\n  \"\n>\n\n  <option value=\"\" ${linkedSkill === \"\" ? \"selected\" : \"\"}>\n    No Skill\n  </option>\n\n  <option value=\"Listening\" ${linkedSkill === \"Listening\" ? \"selected\" : \"\"}>\n    Listening\n  </option>\n\n  <option value=\"Speaking\" ${linkedSkill === \"Speaking\" ? \"selected\" : \"\"}>\n    Speaking\n  </option>\n\n  <option value=\"Reading\" ${linkedSkill === \"Reading\" ? \"selected\" : \"\"}>\n    Reading\n  </option>\n\n  <option value=\"Writing\" ${linkedSkill === \"Writing\" ? \"selected\" : \"\"}>\n    Writing\n  </option>\n\n  <option value=\"Grammar\" ${linkedSkill === \"Grammar\" ? \"selected\" : \"\"}>\n    Grammar\n  </option>\n\n  <option value=\"Vocabulary\" ${linkedSkill === \"Vocabulary\" ? \"selected\" : \"\"}>\n    Vocabulary\n  </option>\n\n  <option value=\"Homework\" ${linkedSkill === \"Homework\" ? \"selected\" : \"\"}>\n    Homework\n  </option>\n\n</select>\n\n<div style=\"\n  margin-top:-5px;\n  margin-bottom:12px;\n  padding:8px 10px;\n  border-radius:10px;\n  background:#eef5ff;\n  border:1px solid #dbeafe;\n  color:#164478;\n  text-align:center;\n  font-weight:900;\n  font-size:13px;\n\">\n  🔄 This skill automatically matches the skill selected above\n</div>\n\n${\n  linkedGroupHasLockedQuestion\n    ? `\n      <div style=\"\n        margin-top:-5px;\n        margin-bottom:12px;\n        padding:8px 10px;\n        border-radius:10px;\n        background:#fee2e2;\n        border:1px solid #fecaca;\n        color:#991b1b;\n        text-align:center;\n        font-weight:900;\n        font-size:13px;\n      \">\n        🔒 Skill cannot be changed because this group contains a locked question\n      </div>\n    `\n    : \"\"\n}\n\n`;\n\n})()}\n\n<button\n  onclick=\"toggleLinkedCourseQuestions('${c.courseId}', ${!linkedVisible})\"\n  style=\"\n    background:${linkedVisible ? '#dc2626' : '#16a34a'};\n    color:#fff;\n    border:none;\n    border-radius:12px;\n    padding:11px;\n    font-weight:900;\n    cursor:pointer;\n    width:100%;\n    margin-bottom:12px;\n  \"\n>\n  ${linkedVisible ? '□ Hide From Students' : '□️ Show To Students'}\n</button>\n\n<div style=\"\n  display:grid;\n  grid-template-columns:repeat(2,1fr);\n  gap:8px;\n\">\n\n  <div class=\"skill-box\">\n    Listening<br>\n    <span style=\"font-size:22px\">\n      ${Number(c.skills?.Listening || 0)}\n    </span>\n  </div>\n\n  <div class=\"skill-box\">\n    Homework<br>\n    <span style=\"font-size:22px\">\n      ${Number(c.skills?.Homework || 0)}\n    </span>\n  </div>\n\n  <div class=\"skill-box\">\n    Grammar ✍️<br>\n    <span style=\"font-size:22px\">\n      ${Number(c.skills?.Grammar || 0)}\n    </span>\n  </div>\n\n  <div class=\"skill-box\">\n    Reading<br>\n    <span style=\"font-size:22px\">\n      ${Number(c.skills?.Reading || 0)}\n    </span>\n  </div>\n\n</div>\n\n        </div>\n\n      `;\n\n    }).join(\"\")}\n\n  </div>\n\n</div>\n\n` : \"\"}\n\n</div>\n`;groupQuestions.forEach((q,index)=>{\n\n  const mediaVisible = q.showMedia !== false;\n  const media = mediaVisible\n    ? renderMedia(q.mediaType, q.mediaUrl)\n    : (q.mediaUrl ? `<div class=\"note\" style=\"background:#fff7ed;color:#9a3412;border-color:#fed7aa\">Media is hidden from students</div>` : \"\");\n\n  const checked =\n  Array.isArray(visibleQuestions) &&\n  visibleQuestions.includes(q.id)\n    ? \"checked\"\n    : \"\";\n  let optionsHtml = \"\";\n\n  if(q.type === \"mcq\" || q.type === \"order\"){\n    optionsHtml = Array.isArray(q.options)\n      ? q.options.map(op=>`\n        <li style=\"direction:ltr;text-align:left\">\n          ${esc(op)}\n        </li>\n      `).join(\"\")\n      : \"\";\n  }\n\n  else if(q.type === \"match\"){\n    optionsHtml = Array.isArray(q.correct)\n      ? q.correct\n          .map(\n            pair =>\n              renderMatchingPairAdmin(\n                pair\n              )\n          )\n          .join(\"\")\n      : \"\";\n  }\n\n  else if(q.type === \"fill\"){\n    const items=Array.isArray(q.fillItems)?q.fillItems:[];\n    optionsHtml=items.map((item,i)=>`<li style=\"direction:ltr;text-align:left\">${i+1}. ${item.mode === \"blank\" ? `<strong>Blank:</strong> ${esc(item.answer || \"\")}` : `<strong>Fixed:</strong> ${esc(item.display || \"\")}`}</li>`).join(\"\");\n  }\n\n  else if(q.type === \"text\"){\n    optionsHtml = `\n      <li>Text Answer</li>\n      <li>Answer Lines: ${Math.max(1,Math.min(20,Number(q.answerLines || 4)))}</li>\n    `;\n  }\n\n  let coursesHTML = \"\";\n\n  if(q.coursesUsed && q.coursesUsed.length){\n    q.coursesUsed.forEach((c, i)=>{\n      coursesHTML += `\n        <div class=\"used-item\">\n          <span class=\"badge used\">Use ${i+1}</span>\n          <br>\n          <b>Course:</b> ${esc(c.TrainingCourse || \"-\")}\n          <br>\n          <b>Trainer:</b> ${esc(c.Trainer || \"-\")}\n        </div>\n      `;\n    });\n  }else{\n    coursesHTML = `\n      <div class=\"used-item\">No courses</div>\n    `;\n  }\n\nquestionsList.innerHTML += `\n\n<div class=\"pro-question-card\"\n  draggable=\"true\"\n  data-question-id=\"${q.id}\"\n  data-question-order=\"${Number(q.order || 0)}\"\n  data-question-number=\"${questionNumberMap.get(q.id) || \"\"}\"\n  data-question-locked=\"${q.locked === true ? \"true\" : \"false\"}\"\n  onclick=\"setActiveQuestion('${q.id}')\"\n>\n\n  <div class=\"pro-question-head\">\n\n    <div style=\"font-weight:900;display:flex;align-items:center;gap:9px\">\n      <span class=\"question-drag-handle\" title=\"Drag to move\">☰</span>\n      Question ${questionNumberMap.get(q.id) || (index + 1)}\n    </div>\n\n    <div class=\"question-order-actions\">\n      <button type=\"button\" onclick=\"event.stopPropagation();moveQuestionByStep('${q.id}',-1)\" title=\"Move up\">⬆ Up</button>\n      <button type=\"button\" onclick=\"event.stopPropagation();moveQuestionByStep('${q.id}',1)\" title=\"Move down\">⬇ Down</button>\n      <button type=\"button\" onclick=\"event.stopPropagation();duplicateQuestion('${q.id}')\" title=\"Copy this question\">📄 Copy</button>\n    </div>\n\n  </div>\n\n  <div style=\"\n  display:flex;\n  justify-content:center;\n  margin:12px 0;\n\">\n  <div style=\"\n    background:#ecfdf5;\n    border:2px solid #22c55e;\n    color:#166534;\n    padding:10px 20px;\n    border-radius:999px;\n    font-size:20px;\n    font-weight:900;\n  \">\n    ⭐ ${formatMarkNumber(q.degree || 0)} Marks\n    ${\n      q.type === \"match\" || q.type === \"fill\"\n        ? `<div style=\"font-size:12px;margin-top:4px\">\n            ${esc(getQuestionDegreeDistributionText(q))}\n          </div>`\n        : \"\"\n    }\n  </div>\n</div>\n\n    ${\n      q.locked\n      ? `<div style=\"\n          background:#fee2e2;\n          color:#991b1b;\n          border:1px solid #fecaca;\n          padding:10px;\n          border-radius:12px;\n          font-weight:900;\n          margin-bottom:10px;\n          line-height:1.8;\n          text-align:center;\n        \">\n          🔒 Locked Question\n          <br>\n          <span style=\"\n            font-size:13px;\n            color:#7f1d1d;\n          \">\n            Locked by Admin:\n            ${esc(q.lockedBy || q.lockedByUsername || \"Legacy Lock\")}\n          </span>\n        </div>`\n      : \"\"\n    }\n\n    <label style=\"\n      display:flex;\n      align-items:center;\n      gap:8px;\n      font-weight:900;\n      color:#164478;\n      margin-bottom:10px;\n    \">\n      <input\n        type=\"checkbox\"\n        class=\"questionCheck\"\n        value=\"${q.id}\"\n        data-group=\"${esc(groupName)}\"\n        ${checked}\n        onchange=\"saveVisibleQuestions()\"\n      >\n      Show to students\n    </label>\n\n${\n      q.passage\n      ? `\n        <textarea\n          id=\"edit_passage_${q.id}\"\n          class=\"pro-edit-input\"\n          style=\"min-height:70px;background:#fff7ed;border-color:#fed7aa;color:#9a3412;font-weight:800;\"\n          placeholder=\"Passage / Paragraph\"\n        >${esc(q.passage || \"\")}</textarea>\n      `\n      : `\n        <textarea\n          id=\"edit_passage_${q.id}\"\n          class=\"pro-edit-input\"\n          style=\"min-height:55px;background:#fff7ed;border-color:#fed7aa;\"\n          placeholder=\"Passage / Paragraph\"\n        ></textarea>\n      `\n    }\n\n<textarea\n  id=\"edit_q_${q.id}\"\n  class=\"pro-edit-input\"\n  style=\"\n    min-height:100px;\n    font-size:22px;\n    font-weight:900;\n    line-height:1.9;\n  \"\n>\n    ${esc(q.question || \"\")}</textarea>\n\n    ${media}\n\n    ${q.mediaUrl && q.mediaType !== \"none\" ? `\n      <button\n        type=\"button\"\n        onclick=\"toggleMediaVisibility('${q.id}', ${mediaVisible})\"\n        style=\"background:${mediaVisible ? '#dc2626' : '#16a34a'};margin-top:10px\"\n      >\n        ${mediaVisible ? '🙈 Hide Media From Students' : '👁️ Show Media To Students'}\n      </button>\n    ` : \"\"}\n\n  <div style=\"\n  margin-top:12px;\n  background:#f8fbff;\n  border:1px solid #dbeafe;\n  border-radius:14px;\n  padding:12px;\n\">\n\n  <b style=\"\n    color:#164478;\n    font-size:18px;\n  \">\n    Options / Answer\n  </b>\n\n  ${(q.options || []).map((op,i)=>{\n\n    const isCorrect =\n      Number(q.correct) === i;\n\n    return `\n\n      <input\n        id=\"edit_option_${q.id}_${i}\"\n        value=\"${esc(op)}\"\n\n        style=\"\n          width:100%;\n          margin-top:10px;\n          padding:14px;\n          font-size:18px;\n          font-weight:900;\n          direction:ltr;\n          text-align:left;\n          border-radius:12px;\n\n          background:\n            ${isCorrect ? '#ecfdf5' : '#fff'};\n\n          border:\n            2px solid\n            ${isCorrect ? '#22c55e' : '#dbeafe'};\n\n          color:\n            ${isCorrect ? '#166534' : '#111827'};\n        \"\n      >\n\n      ${\n        isCorrect\n        ? `\n          <div style=\"\n            color:#16a34a;\n            font-weight:900;\n            margin-top:4px;\n            font-size:15px;\n          \">\n            ✅ Correct Answer\n          </div>\n        `\n        : \"\"\n      }\n\n    `;\n\n  }).join(\"\")}\n\n</div>\n\n    <input\n      id=\"edit_degree_${q.id}\"\n      class=\"pro-edit-input\"\n      type=\"number\"\n      min=\"0.01\"\n      step=\"0.01\"\n      value=\"${Number(q.degree || 0)}\"\n      placeholder=\"Total question marks\"\n      oninput=\"updateQuickDegreeDistributionNote('${q.id}', '${q.type}')\"\n    >\n\n    <div\n      id=\"edit_degree_note_${q.id}\"\n      class=\"fill-degree-note\"\n      style=\"margin-top:8px\">\n      ${getQuestionDegreeDistributionText(q)}\n    </div>\n\n    <input\n      id=\"edit_correct_${q.id}\"\n      class=\"pro-edit-input\"\n      value=\"${\n        Array.isArray(q.correct)\n          ? esc(q.correct.join(\", \"))\n          : esc(q.correct)\n      }\"\n      placeholder=\"Correct Answer\"\n    >\n\n    <div style=\"margin-top:12px\">\n      <span class=\"pro-chip\">Group: ${esc(q.group || \"General\")}</span>\n      <span class=\"pro-chip\">Order: ${Number(q.order || 0)}</span>\n    </div>\n<div\n  id=\"linkedBox_${q.id}\"\n  style=\"\n    display:none;\n    margin-top:15px;\n    background:#eef5ff;\n    border:2px solid #dbeafe;\n    border-radius:18px;\n    padding:15px;\n  \"\n>\n\n  <div style=\"\n    font-size:18px;\n    font-weight:900;\n    color:#164478;\n    margin-bottom:12px;\n  \">\n    □ Linked Courses Only\n  </div>\n<button\n  onclick=\"relinkQuestion('${q.id}')\"\n  style=\"\n    width:100%;\n    background:#16a34a;\n    color:#fff;\n    border:none;\n    border-radius:12px;\n    padding:12px;\n    font-weight:900;\n    cursor:pointer;\n    margin-bottom:12px;\n  \"\n>\n\n  ➕ Add Linked Course\n</button>\n  ${(()=>{\n    const linkedCoursesForUser =\n      getLinkedCoursesForCurrentUser(\n        q.coursesUsed,\n        CURRENT_COURSE_ID\n      );\n\n    return linkedCoursesForUser.length\n      ? `\n\n      <select\n        id=\"linkedSelect_${q.id}\"\n        style=\"\n          width:100%;\n          padding:12px;\n          border-radius:12px;\n          border:2px solid #164478;\n          font-weight:900;\n        \"\n      >\n\n        ${linkedCoursesForUser.map(c=>`\n          <option value=\"${c.courseId}\">\n            ${esc(c.TrainingCourse || \"-\")}\n            |\n            ${esc(c.Trainer || \"-\")}\n            ${c.Period ? ` | ${esc(c.Period)}` : \"\"}\n          </option>\n        `).join(\"\")}\n\n      </select>\n\n      <div style=\"\n        display:grid;\n        grid-template-columns:repeat(auto-fit,minmax(160px,1fr));\n        gap:10px;\n        margin-top:12px;\n      \">\n\n        <button\n          onclick=\"\n            resetLinkedCourseOne(\n              '${q.id}',\n              document.getElementById('linkedSelect_${q.id}').value\n            )\n          \"\n          style=\"background:#f59e0b\"\n        >\n          □ Reset Student\n        </button>\n\n        <button\n          onclick=\"\n            resetLinkedCourseAll(\n              '${q.id}',\n              document.getElementById('linkedSelect_${q.id}').value\n            )\n          \"\n          style=\"background:#dc2626\"\n        >\n          ♻️ Reset Course\n        </button>\n\n        <button\n          onclick=\"removeSelectedLinkedCourse('${q.id}')\"\n          style=\"background:#ef4444\"\n        >\n          ❌ Remove Link\n        </button>\n\n      </div>\n\n    `\n      : `\n      <div style=\"\n        background:#fff;\n        border:1px dashed #cbd5e1;\n        border-radius:12px;\n        padding:12px;\n        color:#64748b;\n        font-weight:900;\n        text-align:center;\n      \">\n        No other linked courses for this user\n      </div>\n    `;\n  })()}\n\n</div>\n  </div>\n\n</div>\n\n`;\n\n});\n    });\n\n    initializeQuestionDragDrop();\n\n    const preferredCard =\n      ACTIVE_QUESTION_ID\n        ? document.querySelector(\n            `.pro-question-card[data-question-id=\"${ACTIVE_QUESTION_ID}\"]`\n          )\n        : document.querySelector(\".pro-question-card\");\n\n    if(preferredCard){\n      setActiveQuestion(\n        preferredCard.dataset.questionId || \"\"\n      );\n    }else{\n      ACTIVE_QUESTION_ID = \"\";\n    }\n\n  }catch(err){\n    console.error(err);\n    questionsList.innerHTML = `<div class=\"empty\">حدث خطأ أثناء تحميل الأسئلة</div>`;\n  }\n}\nasync function autoSaveVisibleQuestions(){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId) return;\n\n  if(!CURRENT_COURSE_ID) return;\n\n  // الأسئلة المحددة فقط\n  const selected = [];\n\n  document\n    .querySelectorAll(\".questionCheck:checked\")\n    .forEach(cb=>{\n\n      selected.push(cb.value);\n\n    });\n\n  const ref =\n    db.collection(\"exams\").doc(examId);\n\n  const docSnap =\n    await ref.get();\n\n  const oldMap =\n    docSnap.data()?.visibleQuestionsByCourse || {};\n\n  // حفظ خاص بهذه الدورة\n  oldMap[CURRENT_COURSE_ID] = selected;\n\n  // ✅ النظام الجديد\n  await ref.update({\n\n    visibleQuestionsByCourse: oldMap,\n\n    // ✅ توافق مع النظام القديم\n    visibleQuestions: selected\n\n  });\n\n  console.log(\n    \"✅ Saved:\",\n    CURRENT_COURSE_ID,\n    selected.length\n  );\n\n  // تحديث الشريط مباشرة بعد تغيير Show to students\n  schedulePublishedSidebarRefresh(50);\n}\nfunction toggleWholeGroup(groupName, checked){\n\n  document.querySelectorAll(`.questionCheck[data-group=\"${esc(groupName)}\"]`)\n    .forEach(cb=>{\n      cb.checked = checked;\n    });\n\n  syncGroupCheck(groupName);\n}\nasync function saveGroupSkill(\n  encodedGroup,\n  skill,\n  courseId,\n  selectElement = null\n){\n\n  const examId =\n    CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n\n    alert(\"Choose the exam first\");\n\n    if(selectElement){\n      selectElement.value =\n        selectElement.dataset.oldValue || \"\";\n    }\n\n    return;\n  }\n\n  const groupName =\n    decodeURIComponent(encodedGroup || \"\");\n\n  if(!groupName){\n\n    alert(\"Group not found\");\n\n    if(selectElement){\n      selectElement.value =\n        selectElement.dataset.oldValue || \"\";\n    }\n\n    return;\n  }\n\n  try{\n\n    // ======================================\n    // 🔒 جلب جميع أسئلة المجموعة\n    // ======================================\n\n    const qSnap =\n      await db.collection(\"questions\")\n        .where(\"examId\", \"==\", examId)\n        .get();\n\n    const groupHasLockedQuestion =\n      qSnap.docs.some(doc => {\n\n        const q =\n          doc.data() || {};\n\n        const questionGroup =\n          String(q.group || \"General\").trim();\n\n        return (\n          questionGroup ===\n            String(groupName).trim()\n          &&\n          q.locked === true\n        );\n\n      });\n\n    // ======================================\n    // ❌ منع تغيير المهارة\n    // ======================================\n\n    if(groupHasLockedQuestion){\n\n      alert(\n        \"🔒 لا يمكن تعديل المهارة لأن المجموعة تحتوي على سؤال مقفل\"\n      );\n\n      if(selectElement){\n\n        selectElement.value =\n          selectElement.dataset.oldValue || \"\";\n\n      }\n\n      await loadQuestions();\n\n      return;\n    }\n\n    // ======================================\n    // ✅ جلب الاختبار\n    // ======================================\n\n    const examRef =\n      db.collection(\"exams\").doc(examId);\n\n    const examDoc =\n      await examRef.get();\n\n    if(!examDoc.exists){\n\n      alert(\"Exam not found\");\n\n      if(selectElement){\n        selectElement.value =\n          selectElement.dataset.oldValue || \"\";\n      }\n\n      return;\n    }\n\n    const examData =\n      examDoc.data() || {};\n\n    const map =\n      examData.groupSkillsByCourse || {};\n\nconst targetCourseId =\n  courseId || CURRENT_COURSE_ID;\n\nif(!targetCourseId){\n\n  alert(\"Choose the course first\");\n\n  if(selectElement){\n    selectElement.value =\n      selectElement.dataset.oldValue || \"\";\n  }\n\n  return;\n}\n\nconst permission =\n  await verifyCourseSkillPermission(\n    targetCourseId\n  );\n\nif(!permission.allowed){\n\n  alert(\n    \"⛔ لا يمكنك تغيير المهارة الأساسية لأنها ليست تابعة لدورتك\"\n  );\n\n  if(selectElement){\n    selectElement.value =\n      selectElement.dataset.oldValue || \"\";\n  }\n\n  await loadQuestions();\n  return;\n}\n\nif(!map[targetCourseId]){\n  map[targetCourseId] = {};\n}\n\n// ✅ تغيير مهارة الدورة الحالية فقط دون تعديل مهارات الدورات المرتبطة\nmap[targetCourseId][groupName] =\n  skill || \"\";\n\n    await examRef.update({\n      groupSkillsByCourse: map,\n      updatedAt:\n        firebase.firestore.FieldValue.serverTimestamp()\n    });\n\n    // حفظ القيمة الجديدة كقيمة أصلية\n    if(selectElement){\n\n      selectElement.dataset.oldValue =\n        skill || \"\";\n\n    }\n\n    await loadQuestions();\n\n    showSkillSavedToast(skill);\n\n  }catch(err){\n\n    console.error(\n      \"SAVE GROUP SKILL ERROR:\",\n      err\n    );\n\n    alert(\n      \"❌ فشل حفظ المهارة: \" +\n      (\n        err?.message ||\n        String(err)\n      )\n    );\n\n    if(selectElement){\n\n      selectElement.value =\n        selectElement.dataset.oldValue || \"\";\n\n    }\n\n  }\n\n}\nfunction showSkillSavedToast(skill){\n\n  const oldToast =\n    document.getElementById(\n      \"skillSavedToast\"\n    );\n\n  if(oldToast){\n    oldToast.remove();\n  }\n\n  const toast =\n    document.createElement(\"div\");\n\n  toast.id =\n    \"skillSavedToast\";\n\n  toast.innerHTML = `\n    ✅ Skill Saved:\n    <b>${esc(skill || \"No Skill\")}</b>\n  `;\n\n  toast.style.cssText = `\n    position:fixed;\n    top:20px;\n    left:50%;\n    transform:translateX(-50%);\n    background:#16a34a;\n    color:#fff;\n    padding:14px 22px;\n    border-radius:16px;\n    font-weight:900;\n    z-index:999999;\n    box-shadow:0 10px 25px rgba(0,0,0,.18);\n    font-size:15px;\n  `;\n\n  document.body.appendChild(toast);\n\n  setTimeout(()=>{\n\n    toast.remove();\n\n  },2000);\n\n}\nfunction syncSortBottom(val){\n  const topSort = document.getElementById(\"examSortTop\");\n  if(topSort) topSort.value = val;\n\n  filterExams(document.getElementById(\"examSearchBottom\")?.value || \"\");\n}\nfunction syncGroupCheck(groupName){\n\n  const items = [\ndocument.querySelectorAll(\n  `.questionCheck[data-group=\"${CSS.escape(groupName)}\"]`\n)\n  ];\n\n  const master = document.querySelector(\n    `.groupMasterCheck[data-group=\"${CSS.escape(groupName)}\"]`\n  );\n\n  if(!master || !items.length) return;\n\n  master.checked = items.every(cb => cb.checked);\n}\nasync function resetOneByQuestion(questionId){\n\n  const qDoc = await db.collection(\"questions\").doc(questionId).get();\n\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = qDoc.data();\n  const examId = q.examId;\n\n  const iqama = prompt(\"insert his Id:\");\n\n  if(!iqama) return;\n\n  const studentSnap = await db.collection(\"students\")\n    .where(\"iqama\",\"==\",iqama)\n    .get();\n\n  if(studentSnap.empty){\n    alert(\"WRONG\");\n    return;\n  }\n\n  const studentId = studentSnap.docs[0].id;\n\n  const resultSnap = await db.collection(\"results\")\n    .where(\"studentId\",\"==\",studentId)\n    .where(\"examId\",\"==\",examId)\n    .where(\"courseId\",\"==\",CURRENT_COURSE_ID)\n    .get();\n\n  for(const doc of resultSnap.docs){\n    await db.collection(\"results\").doc(doc.id).delete();\n  }\n\n  await allowStudentRetake(\n    examId,\n    CURRENT_COURSE_ID,\n    studentId,\n    iqama\n  );\n\n  alert(\"✅ Student can do the exam again\");\n\n}\nasync function resetAllByQuestion(questionId){\n\nconst qDoc = await db.collection(\"questions\").doc(questionId).get();\nconst q = qDoc.data();\nconst examId = q.examId;\n\nif(!confirm(\"⚠️ All results for this test will be deleted. \")) return;\n\nconst snap = await db.collection(\"results\")\n.where(\"examId\",\"==\",examId)\n.where(\"courseId\",\"==\",CURRENT_COURSE_ID)\n.get();\nfor(const doc of snap.docs){\n  await db.collection(\"results\").doc(doc.id).delete();\n}\n\nalert(\"✅ The test is open to everyone \");\n\n}\nasync function importPDF(){\n\n  const examId =\n    document.getElementById(\"examSelect\")?.value || \"\";\n\n  if(!examId){\n    alert(\"⚠️ اختر الاختبار أولاً\");\n    return;\n  }\n\n  const file =\n    document.getElementById(\"pdfFile\")?.files?.[0];\n\n  if(!file){\n    alert(\"⚠️ اختر ملف PDF أولاً\");\n    return;\n  }\n\n  setImportStatus(\n    \"info\",\n    '<i class=\"fa-solid fa-spinner fa-spin\"></i> Reading PDF file...'\n  );\n\n  try{\n\n    const typedArray =\n      new Uint8Array(\n        await file.arrayBuffer()\n      );\n\n    const pdf =\n      await pdfjsLib\n        .getDocument(typedArray)\n        .promise;\n\n    let fullText = \"\";\n\n    for(\n      let pageNumber = 1;\n      pageNumber <= pdf.numPages;\n      pageNumber++\n    ){\n\n      const page =\n        await pdf.getPage(pageNumber);\n\n      const content =\n        await page.getTextContent();\n\n      const rows = new Map();\n\n      content.items.forEach(item => {\n\n        const y =\n          Math.round(\n            Number(item.transform?.[5] || 0)\n          );\n\n        if(!rows.has(y)){\n          rows.set(y, []);\n        }\n\n        rows.get(y).push({\n          x:\n            Number(item.transform?.[4] || 0),\n          text:\n            String(item.str || \"\")\n        });\n\n      });\n\n      const pageLines =\n        [...rows.entries()]\n          .sort((a,b) => b[0] - a[0])\n          .map(([,items]) =>\n            items\n              .sort((a,b) => a.x - b.x)\n              .map(item => item.text)\n              .join(\" \")\n              .replace(/\\s+/g, \" \")\n              .trim()\n          )\n          .filter(Boolean);\n\n      fullText +=\n        pageLines.join(\"\\n\") +\n        \"\\n\\n\";\n\n    }\n\n    console.log(\n      \"PDF IMPORT TEXT:\",\n      fullText\n    );\n\n    processTextToQuestions(\n      fullText,\n      file.name || \"PDF\"\n    );\n\n  }catch(error){\n\n    console.error(\n      \"PDF IMPORT ERROR:\",\n      error\n    );\n\n    setImportStatus(\n      \"error\",\n      \"❌ فشل قراءة ملف PDF: \" +\n      (\n        error?.message ||\n        String(error)\n      )\n    );\n\n  }\n\n}\n\nfunction convertWordHtmlToImportText(html){\n\n  return String(html || \"\")\n\n    // ✅ نحفظ البولد كعلامة خاصة\n    .replace(/<strong[^>]*>/gi, \"[[BOLD]]\")\n    .replace(/<\\/strong>/gi, \"[[/BOLD]]\")\n    .replace(/<b[^>]*>/gi, \"[[BOLD]]\")\n    .replace(/<\\/b>/gi, \"[[/BOLD]]\")\n\n    // ✅ تحويل فقرات Word إلى أسطر\n    .replace(/<br\\s*\\/?>/gi, \"\\n\")\n    .replace(/<\\/p>/gi, \"\\n\")\n    .replace(/<p[^>]*>/gi, \"\")\n\n    // ✅ تنظيف باقي HTML\n    .replace(/<[^>]+>/g, \"\")\n\n    // ✅ رموز HTML\n    .replace(/&nbsp;/gi, \" \")\n    .replace(/&amp;/gi, \"&\")\n    .replace(/&lt;/gi, \"<\")\n    .replace(/&gt;/gi, \">\")\n    .replace(/&quot;/gi, '\"')\n    .replace(/&#39;/gi, \"'\")\n\n    .replace(/\\n{3,}/g, \"\\n\\n\")\n    .trim();\n}\n/* =====================================================\n   تحويل HTML الخاص بـ Word إلى نص\n   مع المحافظة على الترقيم التلقائي\n===================================================== */\nfunction wordHtmlToNumberedText(html){\n\n  const parser = new DOMParser();\n\n  const doc = parser.parseFromString(\n    String(html || \"\"),\n    \"text/html\"\n  );\n\n  const output = [];\n\n  function cleanText(value){\n\n    return String(value || \"\")\n\n      .replace(/\\u00A0/g, \" \")\n\n      .replace(\n        /[\\u200B-\\u200F\\u202A-\\u202E\\u2060\\uFEFF]/g,\n        \"\"\n      )\n\n      .replace(/[ \\t]+/g, \" \")\n\n      .trim();\n  }\n\n  function readNode(node){\n\n    if(!node) return;\n\n    /* =========================================\n       قائمة Word مرقمة تلقائيًا\n    ========================================= */\n    if(node.nodeType === Node.ELEMENT_NODE){\n\n      const tag =\n        String(node.tagName || \"\").toLowerCase();\n\n      if(tag === \"ol\"){\n\n        const start =\n          Number(node.getAttribute(\"start\") || 1);\n\n        let number = start;\n\n        Array.from(node.children).forEach(li => {\n\n          if(\n            String(li.tagName || \"\").toLowerCase()\n            !== \"li\"\n          ){\n            return;\n          }\n\n          const parts = [];\n\n          Array.from(li.childNodes).forEach(child => {\n\n            const childTag =\n              child.nodeType === Node.ELEMENT_NODE\n                ? String(child.tagName || \"\").toLowerCase()\n                : \"\";\n\n            // عدم إدخال قائمة داخلية مرتين\n            if(childTag === \"ol\" || childTag === \"ul\"){\n              return;\n            }\n\n            const value =\n              cleanText(child.textContent);\n\n            if(value){\n              parts.push(value);\n            }\n\n          });\n\n          const line =\n            cleanText(parts.join(\" \"));\n\n          if(line){\n\n            output.push(\n              `${number}. ${line}`\n            );\n\n          }\n\n          number++;\n\n          // قراءة أي قوائم داخلية\n          Array.from(li.children).forEach(child => {\n\n            const childTag =\n              String(child.tagName || \"\").toLowerCase();\n\n            if(childTag === \"ol\" || childTag === \"ul\"){\n              readNode(child);\n            }\n\n          });\n\n        });\n\n        return;\n      }\n\n      /* =========================================\n         قائمة نقطية\n      ========================================= */\n      if(tag === \"ul\"){\n\n        Array.from(node.children).forEach(li => {\n\n          if(\n            String(li.tagName || \"\").toLowerCase()\n            !== \"li\"\n          ){\n            return;\n          }\n\n          const value =\n            cleanText(li.textContent);\n\n          if(value){\n            output.push(value);\n          }\n\n        });\n\n        return;\n      }\n\n      /* =========================================\n         الفقرات والعناوين\n      ========================================= */\n      if(\n        tag === \"p\" ||\n        tag === \"div\" ||\n        tag === \"h1\" ||\n        tag === \"h2\" ||\n        tag === \"h3\" ||\n        tag === \"h4\"\n      ){\n\n        const value =\n          cleanText(node.textContent);\n\n        if(value){\n          output.push(value);\n        }\n\n        return;\n      }\n    }\n\n    Array.from(node.childNodes || [])\n      .forEach(readNode);\n  }\n\n  Array.from(doc.body.childNodes)\n    .forEach(readNode);\n\n  return output\n    .join(\"\\n\")\n    .replace(/\\n{3,}/g, \"\\n\\n\")\n    .trim();\n}\nasync function importWord(){\n\n  const examId =\n    document.getElementById(\"examSelect\")?.value || \"\";\n\n  if(!examId){\n    alert(\"⚠️ اختر الاختبار أولاً\");\n    return;\n  }\n\n  const file =\n    document.getElementById(\"wordFile\")?.files?.[0];\n\n  if(!file){\n    alert(\"⚠️ اختر ملف Word أو TXT أولاً\");\n    return;\n  }\n\n  const fileName =\n    String(file.name || \"\").toLowerCase();\n\n  const isTxt =\n    fileName.endsWith(\".txt\");\n\n  const isWord =\n    fileName.endsWith(\".docx\");\n\n  if(!isTxt && !isWord){\n    alert(\"⚠️ الملف يجب أن يكون DOCX أو TXT\");\n    return;\n  }\n\n  setImportStatus(\n    \"info\",\n    '<i class=\"fa-solid fa-spinner fa-spin\"></i> Reading file...'\n  );\n\n  try{\n\n    let importedText = \"\";\n\n    window.WORD_HTML = \"\";\n\n    if(isTxt){\n\n      importedText =\n        await file.text();\n\n    }else{\n\n      const arrayBuffer =\n        await file.arrayBuffer();\n\n      const htmlResult =\n        await mammoth.convertToHtml({\n          arrayBuffer:\n            arrayBuffer\n        });\n\n      window.WORD_HTML =\n        htmlResult.value || \"\";\n\n      importedText =\n        wordHtmlToNumberedText(\n          window.WORD_HTML\n        );\n\n      if(!String(importedText || \"\").trim()){\n\n        const rawResult =\n          await mammoth.extractRawText({\n            arrayBuffer:\n              arrayBuffer\n          });\n\n        importedText =\n          rawResult.value || \"\";\n\n      }\n\n    }\n\n    console.log(\n      \"WORD IMPORT TEXT:\",\n      importedText\n    );\n\n    if(!String(importedText || \"\").trim()){\n\n      setImportStatus(\n        \"error\",\n        \"⚠️ لم يتم العثور على نص داخل الملف\"\n      );\n\n      return;\n\n    }\n\n    processTextToQuestions(\n      importedText,\n      file.name || \"Word\"\n    );\n\n  }catch(error){\n\n    console.error(\n      \"IMPORT WORD ERROR:\",\n      error\n    );\n\n    setImportStatus(\n      \"error\",\n      \"❌ فشل قراءة الملف: \" +\n      (\n        error?.message ||\n        String(error)\n      )\n    );\n\n  }\n\n}\nlet IMPORTED_QUESTIONS_STAGE = [];\nlet IMPORTED_SOURCE_NAME = \"\";\n\nfunction setImportStatus(type, message){\n\n  const status =\n    document.getElementById(\"importStatus\");\n\n  if(!status){\n    return;\n  }\n\n  status.className =\n    \"import-status show \" +\n    String(type || \"info\");\n\n  status.innerHTML =\n    String(message || \"\");\n\n}\n\nfunction clearImportedQuestionsStage(){\n\n  IMPORTED_QUESTIONS_STAGE = [];\n  IMPORTED_SOURCE_NAME = \"\";\n\n  const stage =\n    document.getElementById(\n      \"importedQuestionsStage\"\n    );\n\n  const preview =\n    document.getElementById(\n      \"importedQuestionsPreview\"\n    );\n\n  const count =\n    document.getElementById(\n      \"importedQuestionsCount\"\n    );\n\n  const status =\n    document.getElementById(\n      \"importStatus\"\n    );\n\n  if(stage){\n    stage.classList.remove(\"show\");\n  }\n\n  if(preview){\n    preview.innerHTML = \"\";\n  }\n\n  if(count){\n    count.innerHTML =\n      '<i class=\"fa-solid fa-list-check\"></i> 0 Questions';\n  }\n\n  if(status){\n    status.className =\n      \"import-status\";\n    status.innerHTML = \"\";\n  }\n\n  const wordInput =\n    document.getElementById(\"wordFile\");\n\n  const pdfInput =\n    document.getElementById(\"pdfFile\");\n\n  if(wordInput){\n    wordInput.value = \"\";\n  }\n\n  if(pdfInput){\n    pdfInput.value = \"\";\n  }\n\n}\n\nfunction processTextToQuestions(\n  text,\n  sourceName = \"Imported File\"\n){\n\n  const examId =\n    document.getElementById(\"examSelect\")?.value || \"\";\n\n  if(!examId){\n    alert(\"⚠️ اختر الاختبار أولاً\");\n    return;\n  }\n\n  try{\n\n    function cleanLine(value){\n\n      return String(value || \"\")\n        .replace(/\\u0000/g, \"\")\n        .replace(/\\u00A0/g, \" \")\n        .replace(\n          /[\\u200B-\\u200F\\u202A-\\u202E\\u2060\\uFEFF]/g,\n          \"\"\n        )\n        .replace(/\\s+/g, \" \")\n        .trim();\n\n    }\n\n    function countWords(value){\n\n      return cleanLine(value)\n        .split(/\\s+/)\n        .filter(Boolean)\n        .length;\n\n    }\n\n    function hasCorrectMarker(value){\n\n      const source =\n        String(value || \"\");\n\n      return (\n        source.includes(\"*\") ||\n        /\\(correct\\)|\\[correct\\]|\\{correct\\}/i.test(source)\n      );\n\n    }\n\n    function removeCorrectMarker(value){\n\n      return cleanLine(\n        String(value || \"\")\n          .replace(/\\*/g, \"\")\n          .replace(\n            /\\(correct\\)|\\[correct\\]|\\{correct\\}/gi,\n            \"\"\n          )\n      );\n\n    }\n\n    function looksLikeQuestion(value){\n\n      const valueText =\n        cleanLine(value);\n\n      if(!valueText){\n        return false;\n      }\n\n      if(\n        /^(\\*)?\\s*[a-hA-H]\\s*(\\*)?\\s*[\\)\\.\\-:]/.test(\n          valueText\n        )\n      ){\n        return false;\n      }\n\n      const plain =\n        valueText\n          .replace(/\\*/g, \"\")\n          .trim();\n\n      return (\n        valueText.includes(\"?\") ||\n        valueText.includes(\"؟\") ||\n        /_{2,}/.test(valueText) ||\n        /\\bchoose\\b/i.test(valueText) ||\n        /\\bcomplete\\b/i.test(valueText) ||\n        /\\bwhich\\b/i.test(valueText) ||\n        /\\bwhat\\b/i.test(valueText) ||\n        /\\bwhere\\b/i.test(valueText) ||\n        /\\bwho\\b/i.test(valueText) ||\n        /\\bwhen\\b/i.test(valueText) ||\n        /\\bwhy\\b/i.test(valueText) ||\n        /\\bhow\\b/i.test(valueText) ||\n        /\\bselect\\b/i.test(valueText) ||\n        /\\bfill\\b/i.test(valueText) ||\n        /\\bcorrect\\b/i.test(valueText) ||\n        countWords(plain) >= 4\n      );\n\n    }\n\n    function isTimeOrDecimal(value){\n\n      const valueText =\n        cleanLine(value);\n\n      return (\n        /^\\d{1,2}\\s*:\\s*\\d{1,2}\\s*(?:am|pm)?$/i.test(valueText) ||\n        /^\\d{1,2}\\s*\\.\\s*\\d{1,2}\\s*(?:am|pm)?$/i.test(valueText) ||\n        /^\\d{1,2}\\s*(?:am|pm)$/i.test(valueText)\n      );\n\n    }\n\n    function parseNumberedLine(value){\n\n      const valueText =\n        cleanLine(value);\n\n      if(\n        !valueText ||\n        isTimeOrDecimal(valueText)\n      ){\n        return null;\n      }\n\n      const match =\n        valueText.match(\n          /^(\\d{1,4})\\s*[\\.\\)\\-:]\\s*(.*)$/\n        );\n\n      if(!match){\n        return null;\n      }\n\n      return {\n        number:\n          Number(match[1]),\n        text:\n          cleanLine(match[2])\n      };\n\n    }\n\n    function parseLetterOption(value){\n\n      const valueText =\n        cleanLine(value);\n\n      const match =\n        valueText.match(\n          /^(\\*)?\\s*([a-hA-H])\\s*(\\*)?\\s*[\\)\\.\\-:]\\s*(.*)$/\n        );\n\n      if(!match){\n        return null;\n      }\n\n      return {\n        letter:\n          String(match[2] || \"\")\n            .toLowerCase(),\n        text:\n          cleanLine(match[4]),\n        correct:\n          Boolean(match[1] || match[3]) ||\n          hasCorrectMarker(match[4])\n      };\n\n    }\n\n    let cleanedText =\n      String(text || \"\")\n        .replace(/\\r\\n?/g, \"\\n\")\n        .replace(/\\u00A0/g, \" \")\n        .replace(\n          /[\\u200B-\\u200F\\u202A-\\u202E\\u2060\\uFEFF]/g,\n          \"\"\n        )\n        .replace(/\\t/g, \" \")\n        .replace(/[（]/g, \"(\")\n        .replace(/[）]/g, \")\")\n        .replace(/[“”]/g, '\"')\n        .replace(/[‘’]/g, \"'\")\n        .replace(\n          /([^\\n])\\s+([a-hA-H])\\s*[\\)\\.\\-:]\\s*/g,\n          \"$1\\n$2) \"\n        )\n        .replace(/[ \\t]+$/gm, \"\")\n        .replace(/^[ \\t]+/gm, \"\")\n        .replace(/\\n{4,}/g, \"\\n\\n\\n\")\n        .trim();\n\n    if(!cleanedText){\n\n      setImportStatus(\n        \"error\",\n        \"⚠️ لم يتم العثور على نص داخل الملف\"\n      );\n\n      return;\n    }\n\n    const lines =\n      cleanedText\n        .split(\"\\n\")\n        .map(cleanLine)\n        .filter(Boolean);\n\n    const parsedQuestions = [];\n\n    let currentQuestion = null;\n    let lastQuestionNumber = null;\n\n    function startQuestion(\n      number,\n      questionText\n    ){\n\n      currentQuestion = {\n        number:\n          Number(number),\n        question:\n          cleanLine(questionText),\n        options: [],\n        optionMode:\n          null,\n        nextNumericOption:\n          1\n      };\n\n      lastQuestionNumber =\n        Number(number);\n\n    }\n\n    function addOption(\n      optionText,\n      isCorrect = false\n    ){\n\n      if(!currentQuestion){\n        return;\n      }\n\n      const cleanedOption =\n        cleanLine(optionText);\n\n      if(!cleanedOption){\n        return;\n      }\n\n      currentQuestion.options.push({\n        text:\n          removeCorrectMarker(cleanedOption),\n        correct:\n          isCorrect === true ||\n          hasCorrectMarker(cleanedOption)\n      });\n\n    }\n\n    function finalizeQuestion(){\n\n      if(!currentQuestion){\n        return;\n      }\n\n      const options =\n        currentQuestion.options\n          .map(option => ({\n            text:\n              removeCorrectMarker(option.text),\n            correct:\n              option.correct === true\n          }))\n          .filter(option =>\n            option.text\n          );\n\n      const correctIndexes =\n        options\n          .map((option,index) =>\n            option.correct ? index : -1\n          )\n          .filter(index =>\n            index >= 0\n          );\n\n      if(\n        currentQuestion.question &&\n        options.length >= 2\n      ){\n\n        parsedQuestions.push({\n          number:\n            currentQuestion.number,\n          question:\n            cleanLine(currentQuestion.question),\n          options:\n            options.map(option =>\n              option.text\n            ),\n          correct:\n            correctIndexes.length === 1\n              ? correctIndexes[0]\n              : -1,\n          degree:\n            1,\n          valid:\n            correctIndexes.length === 1\n        });\n\n      }else{\n\n        console.warn(\n          \"IMPORT QUESTION SKIPPED:\",\n          currentQuestion\n        );\n\n      }\n\n      currentQuestion = null;\n\n    }\n\n    for(\n      let lineIndex = 0;\n      lineIndex < lines.length;\n      lineIndex++\n    ){\n\n      const line =\n        lines[lineIndex];\n\n      const letterOption =\n        parseLetterOption(line);\n\n      if(\n        currentQuestion &&\n        letterOption\n      ){\n\n        currentQuestion.optionMode =\n          \"letter\";\n\n        addOption(\n          letterOption.text,\n          letterOption.correct\n        );\n\n        continue;\n      }\n\n      const numberedLine =\n        parseNumberedLine(line);\n\n      if(numberedLine){\n\n        const number =\n          numberedLine.number;\n\n        const numberedText =\n          numberedLine.text;\n\n        const expectedQuestionNumber =\n          lastQuestionNumber === null\n            ? number\n            : lastQuestionNumber + 1;\n\n        /*\n          سؤال جديد بعد وجود خيارين أو أكثر.\n          هذا يمنع اعتبار الخيار الرقمي رقم 2 سؤالًا جديدًا\n          بعد وجود الخيار الأول فقط.\n        */\n        const canBeNextQuestion =\n          (\n            lastQuestionNumber === null ||\n            number === expectedQuestionNumber\n          ) &&\n          looksLikeQuestion(numberedText) &&\n          (\n            !currentQuestion ||\n            currentQuestion.options.length >= 2 ||\n            currentQuestion.optionMode === \"letter\"\n          );\n\n        if(canBeNextQuestion){\n\n          finalizeQuestion();\n\n          startQuestion(\n            number,\n            numberedText\n          );\n\n          continue;\n        }\n\n        /*\n          بداية أول سؤال في الملف.\n        */\n        if(\n          !currentQuestion &&\n          looksLikeQuestion(numberedText)\n        ){\n\n          startQuestion(\n            number,\n            numberedText\n          );\n\n          continue;\n        }\n\n        /*\n          خيارات Word الرقمية:\n          1. option\n          2. option\n          3. option\n        */\n        if(\n          currentQuestion &&\n          currentQuestion.optionMode === null &&\n          number === 1\n        ){\n\n          currentQuestion.optionMode =\n            \"numeric\";\n\n          currentQuestion.nextNumericOption =\n            2;\n\n          addOption(\n            numberedText,\n            hasCorrectMarker(numberedText)\n          );\n\n          continue;\n        }\n\n        if(\n          currentQuestion &&\n          currentQuestion.optionMode === \"numeric\" &&\n          number === currentQuestion.nextNumericOption\n        ){\n\n          addOption(\n            numberedText,\n            hasCorrectMarker(numberedText)\n          );\n\n          currentQuestion.nextNumericOption++;\n\n          continue;\n        }\n\n        /*\n          احتياط للسؤال التالي عندما انتهت الخيارات الرقمية.\n        */\n        if(\n          currentQuestion &&\n          number === expectedQuestionNumber &&\n          looksLikeQuestion(numberedText)\n        ){\n\n          finalizeQuestion();\n\n          startQuestion(\n            number,\n            numberedText\n          );\n\n          continue;\n        }\n\n      }\n\n      if(!currentQuestion){\n        continue;\n      }\n\n      /*\n        إذا فقد Word بادئة الخيار، نضيف السطر كخيار.\n      */\n      addOption(\n        line,\n        hasCorrectMarker(line)\n      );\n\n    }\n\n    finalizeQuestion();\n\n    IMPORTED_QUESTIONS_STAGE =\n      parsedQuestions;\n\n    IMPORTED_SOURCE_NAME =\n      String(sourceName || \"Imported File\");\n\n    renderImportedQuestionsStage();\n\n    const validCount =\n      parsedQuestions.filter(item =>\n        Number(item.correct) >= 0\n      ).length;\n\n    const needsReview =\n      parsedQuestions.length - validCount;\n\n    setImportStatus(\n      parsedQuestions.length\n        ? \"success\"\n        : \"error\",\n      parsedQuestions.length\n        ? (\n            `✅ تم استخراج ${parsedQuestions.length} سؤال من ${esc(IMPORTED_SOURCE_NAME)}.` +\n            (\n              needsReview > 0\n                ? ` يوجد ${needsReview} سؤال يحتاج تحديد إجابة صحيحة قبل الحفظ.`\n                : \" راجع الأسئلة ثم اضغط زر الحفظ.\"\n            )\n          )\n        : \"⚠️ لم يتم التعرف على أسئلة صالحة داخل الملف.\"\n    );\n\n  }catch(error){\n\n    console.error(\n      \"QUESTION PARSE ERROR:\",\n      error\n    );\n\n    setImportStatus(\n      \"error\",\n      \"❌ حدث خطأ أثناء تحليل الأسئلة: \" +\n      (\n        error?.message ||\n        String(error)\n      )\n    );\n\n  }\n\n}\n\nfunction renderImportedQuestionsStage(){\n\n  const stage =\n    document.getElementById(\n      \"importedQuestionsStage\"\n    );\n\n  const preview =\n    document.getElementById(\n      \"importedQuestionsPreview\"\n    );\n\n  const count =\n    document.getElementById(\n      \"importedQuestionsCount\"\n    );\n\n  if(!stage || !preview || !count){\n    return;\n  }\n\n  if(!IMPORTED_QUESTIONS_STAGE.length){\n\n    stage.classList.remove(\"show\");\n    preview.innerHTML = \"\";\n    return;\n\n  }\n\n  stage.classList.add(\"show\");\n\n  count.innerHTML =\n    '<i class=\"fa-solid fa-list-check\"></i> ' +\n    IMPORTED_QUESTIONS_STAGE.length +\n    \" Questions\";\n\n  let html = \"\";\n\n  IMPORTED_QUESTIONS_STAGE.forEach(\n    (item, questionIndex) => {\n\n      const hasCorrect =\n        Number(item.correct) >= 0 &&\n        Number(item.correct) < item.options.length;\n\n      html += `\n        <div class=\"imported-question-card\">\n          <div class=\"imported-question-head\">\n            <strong>\n              Question ${questionIndex + 1}\n            </strong>\n\n            <span>\n              ${item.options.length} Options\n            </span>\n          </div>\n\n          <div class=\"imported-question-body\">\n            <label style=\"font-weight:900;color:#164478\">\n              Question\n            </label>\n\n            <textarea\n              id=\"importQuestion_${questionIndex}\"\n              oninput=\"updateImportedQuestionText(${questionIndex},this.value)\"\n              style=\"min-height:90px\"\n            >${esc(item.question)}</textarea>\n\n            <div style=\"\n              margin-top:12px;\n              font-size:13px;\n              font-weight:900;\n              color:${hasCorrect ? '#17a673' : '#e74c3c'};\n            \">\n              ${\n                hasCorrect\n                  ? '<i class=\"fa-solid fa-circle-check\"></i> Correct answer selected'\n                  : '<i class=\"fa-solid fa-triangle-exclamation\"></i> Select one correct answer'\n              }\n            </div>\n\n            <div style=\"margin-top:9px\">\n      `;\n\n      item.options.forEach(\n        (option, optionIndex) => {\n\n          const checked =\n            Number(item.correct) === optionIndex;\n\n          html += `\n            <div class=\"\n              imported-option-row\n              ${checked ? \"correct-option\" : \"\"}\n            \">\n              <input\n                type=\"radio\"\n                name=\"importCorrect_${questionIndex}\"\n                ${checked ? \"checked\" : \"\"}\n                onchange=\"setImportedCorrectAnswer(\n                  ${questionIndex},\n                  ${optionIndex}\n                )\"\n                title=\"Correct answer\"\n              >\n\n              <input\n                type=\"text\"\n                value=\"${esc(option)}\"\n                oninput=\"updateImportedOption(\n                  ${questionIndex},\n                  ${optionIndex},\n                  this.value\n                )\"\n                placeholder=\"Option ${optionIndex + 1}\"\n              >\n            </div>\n          `;\n\n        }\n      );\n\n      html += `\n            </div>\n\n            <div class=\"row\" style=\"margin-top:10px\">\n              <div>\n                <label style=\"font-size:12px;font-weight:900\">\n                  Degree\n                </label>\n                <input\n                  type=\"number\"\n                  min=\"1\"\n                  value=\"${Number(item.degree || 1)}\"\n                  onchange=\"updateImportedDegree(\n                    ${questionIndex},\n                    this.value\n                  )\"\n                >\n              </div>\n            </div>\n\n            <div class=\"import-card-actions\">\n              <button\n                type=\"button\"\n                onclick=\"addImportedOption(${questionIndex})\"\n                style=\"background:#2467a5\"\n              >\n                <i class=\"fa-solid fa-plus\"></i>\n                Add Option\n              </button>\n\n              <button\n                type=\"button\"\n                onclick=\"deleteImportedQuestion(${questionIndex})\"\n                style=\"background:#e74c3c\"\n              >\n                <i class=\"fa-solid fa-trash\"></i>\n                Delete\n              </button>\n            </div>\n          </div>\n        </div>\n      `;\n\n    }\n  );\n\n  preview.innerHTML =\n    html;\n\n}\n\nfunction updateImportedQuestionText(\n  questionIndex,\n  value\n){\n\n  const item =\n    IMPORTED_QUESTIONS_STAGE[questionIndex];\n\n  if(!item){\n    return;\n  }\n\n  item.question =\n    String(value || \"\");\n\n}\n\nfunction updateImportedOption(\n  questionIndex,\n  optionIndex,\n  value\n){\n\n  const item =\n    IMPORTED_QUESTIONS_STAGE[questionIndex];\n\n  if(\n    !item ||\n    !Array.isArray(item.options)\n  ){\n    return;\n  }\n\n  item.options[optionIndex] =\n    String(value || \"\");\n\n}\n\nfunction updateImportedDegree(\n  questionIndex,\n  value\n){\n\n  const item =\n    IMPORTED_QUESTIONS_STAGE[questionIndex];\n\n  if(!item){\n    return;\n  }\n\n  item.degree =\n    Math.max(\n      Number(value || 1),\n      1\n    );\n\n}\n\nfunction setImportedCorrectAnswer(\n  questionIndex,\n  optionIndex\n){\n\n  const item =\n    IMPORTED_QUESTIONS_STAGE[questionIndex];\n\n  if(!item){\n    return;\n  }\n\n  item.correct =\n    Number(optionIndex);\n\n  item.valid =\n    true;\n\n  renderImportedQuestionsStage();\n\n}\n\nfunction addImportedOption(\n  questionIndex\n){\n\n  const item =\n    IMPORTED_QUESTIONS_STAGE[questionIndex];\n\n  if(!item){\n    return;\n  }\n\n  if(!Array.isArray(item.options)){\n    item.options = [];\n  }\n\n  item.options.push(\"\");\n\n  renderImportedQuestionsStage();\n\n}\n\nfunction deleteImportedQuestion(\n  questionIndex\n){\n\n  if(\n    !confirm(\n      \"هل تريد حذف هذا السؤال من قائمة الاستيراد؟\"\n    )\n  ){\n    return;\n  }\n\n  IMPORTED_QUESTIONS_STAGE.splice(\n    questionIndex,\n    1\n  );\n\n  renderImportedQuestionsStage();\n\n  if(!IMPORTED_QUESTIONS_STAGE.length){\n\n    setImportStatus(\n      \"info\",\n      \"تم حذف جميع الأسئلة المستوردة.\"\n    );\n\n  }\n\n}\n\nasync function saveImportedQuestions(){\n\n  const examId =\n    document.getElementById(\"examSelect\")?.value || \"\";\n\n  const group =\n    document.getElementById(\"groupSelect\")?.value || \"General\";\n\n  if(!examId){\n    alert(\"⚠️ اختر الاختبار أولاً\");\n    return;\n  }\n\n  if(!IMPORTED_QUESTIONS_STAGE.length){\n    alert(\"⚠️ لا توجد أسئلة مستوردة للحفظ\");\n    return;\n  }\n\n  const normalizedQuestions =\n    IMPORTED_QUESTIONS_STAGE.map(\n      (item,index) => {\n\n        const question =\n          String(item.question || \"\")\n            .replace(/\\s+/g, \" \")\n            .trim();\n\n        const options =\n          Array.isArray(item.options)\n            ? item.options.map(option =>\n                String(option || \"\")\n                  .replace(/\\s+/g, \" \")\n                  .trim()\n              )\n            : [];\n\n        return {\n          index:\n            index,\n          question:\n            question,\n          options:\n            options,\n          correct:\n            Number(item.correct),\n          degree:\n            Math.max(\n              Number(item.degree || 1),\n              1\n            )\n        };\n\n      }\n    );\n\n  const invalidQuestion =\n    normalizedQuestions.find(item =>\n      !item.question ||\n      item.options.length < 2 ||\n      item.options.some(option => !option) ||\n      !Number.isInteger(item.correct) ||\n      item.correct < 0 ||\n      item.correct >= item.options.length\n    );\n\n  if(invalidQuestion){\n\n    alert(\n      `⚠️ راجع السؤال رقم ${invalidQuestion.index + 1}.\\n` +\n      \"يجب كتابة السؤال وجميع الخيارات واختيار إجابة صحيحة واحدة.\"\n    );\n\n    return;\n  }\n\n  const saveButton =\n    document.getElementById(\n      \"saveImportedQuestionsBtn\"\n    );\n\n  if(saveButton){\n    saveButton.disabled = true;\n    saveButton.innerHTML =\n      '<i class=\"fa-solid fa-spinner fa-spin\"></i> Saving...';\n  }\n\n  setImportStatus(\n    \"info\",\n    '<i class=\"fa-solid fa-spinner fa-spin\"></i> Saving imported questions...'\n  );\n\n  try{\n\n    const examRef =\n      db.collection(\"exams\").doc(examId);\n\n    const examDoc =\n      await examRef.get();\n\n    if(!examDoc.exists){\n      throw new Error(\"الاختبار غير موجود\");\n    }\n\n    const examData =\n      examDoc.data() || {};\n\n    const coursesUsed =\n      Array.isArray(examData.coursesData)\n        ? examData.coursesData.map(c => ({\n            courseId:\n              c.courseId || \"\",\n            TrainingCourse:\n              c.TrainingCourse || \"\",\n            Trainer:\n              c.Trainer || \"\",\n            Period:\n              c.Period || \"\"\n          }))\n        : [];\n\n    const existingSnap =\n      await db.collection(\"questions\")\n        .where(\n          \"examId\",\n          \"==\",\n          examId\n        )\n        .get();\n\n    let orderCounter = 0;\n\n    if(!existingSnap.empty){\n\n      const orders =\n        existingSnap.docs.map(doc =>\n          Number(doc.data().order || 0)\n        );\n\n      orderCounter =\n        Math.max(...orders,0);\n\n    }\n\n    const batch =\n      db.batch();\n\n    const visibleIds = [];\n\n    normalizedQuestions.forEach(item => {\n\n      orderCounter++;\n\n      const questionRef =\n        db.collection(\"questions\").doc();\n\n      const questionData = {\n        examId:\n          examId,\n        question:\n          item.question,\n        passage:\n          \"\",\n        options:\n          item.options,\n        correct:\n          item.correct,\n        degree:\n          item.degree,\n        type:\n          \"mcq\",\n        group:\n          group,\n        skill:\n          group,\n        showMedia:\n          false,\n        mediaType:\n          \"none\",\n        mediaUrl:\n          \"\",\n        locked:\n          false,\n        coursesUsed:\n          coursesUsed,\n        order:\n          orderCounter,\n        importSource:\n          IMPORTED_SOURCE_NAME || \"\",\n        createdAt:\n          firebase.firestore\n            .FieldValue\n            .serverTimestamp()\n      };\n\n      if(CURRENT_COURSE_ID){\n        questionData.courseId =\n          CURRENT_COURSE_ID;\n      }\n\n      batch.set(\n        questionRef,\n        questionData\n      );\n\n      visibleIds.push(\n        questionRef.id\n      );\n\n    });\n\n    await batch.commit();\n\n    if(visibleIds.length){\n\n      await examRef.update({\n        visibleQuestions:\n          firebase.firestore\n            .FieldValue\n            .arrayUnion(\n              ...visibleIds\n            )\n      });\n\n    }\n\n    if(CURRENT_COURSE_ID){\n\n      const latestDoc =\n        await examRef.get();\n\n      const latestData =\n        latestDoc.data() || {};\n\n      const visibleQuestionsByCourse = {\n        ...(\n          latestData\n            .visibleQuestionsByCourse || {}\n        )\n      };\n\n      const oldIds =\n        Array.isArray(\n          visibleQuestionsByCourse[\n            CURRENT_COURSE_ID\n          ]\n        )\n          ? visibleQuestionsByCourse[\n              CURRENT_COURSE_ID\n            ]\n          : [];\n\n      visibleQuestionsByCourse[\n        CURRENT_COURSE_ID\n      ] = [\n        ...new Set([\n          ...oldIds,\n          ...visibleIds\n        ])\n      ];\n\n      await examRef.update({\n        visibleQuestionsByCourse:\n          visibleQuestionsByCourse\n      });\n\n    }\n\n    const savedCount =\n      normalizedQuestions.length;\n\n    clearImportedQuestionsStage();\n\n    setImportStatus(\n      \"success\",\n      `✅ تم حفظ ${savedCount} سؤال بنجاح`\n    );\n\n    await loadQuestions();\n\n  }catch(error){\n\n    console.error(\n      \"SAVE IMPORTED QUESTIONS ERROR:\",\n      error\n    );\n\n    setImportStatus(\n      \"error\",\n      \"❌ فشل حفظ الأسئلة: \" +\n      (\n        error?.message ||\n        String(error)\n      )\n    );\n\n  }finally{\n\n    if(saveButton){\n      saveButton.disabled = false;\n      saveButton.innerHTML =\n        '<i class=\"fa-solid fa-cloud-arrow-up\"></i> Save Imported Questions';\n    }\n\n  }\n\n}\nasync function showCourseSelector(questionId){\n\n  const selectHtml = `\n    <select id=\"courseDropdownSelect\"\n      style=\"\n        width:100%;\n        padding:14px;\n        border-radius:14px;\n        border:2px solid #dbeafe;\n        font-size:22px;\n        font-weight:700;\n      \">\n\n      <option value=\"\">Choose Course</option>\n\n    </select>\n  `;\n\n  const wrapper = document.createElement(\"div\");\n\n  wrapper.innerHTML = `\n\n    <div style=\"\n      position:fixed;\n      inset:0;\n      background:rgba(0,0,0,.45);\n      z-index:99999;\n      display:flex;\n      align-items:center;\n      justify-content:center;\n      padding:20px;\n    \"\n    id=\"courseModal\"\n    >\n\n      <div style=\"\n        width:100%;\n        max-width:520px;\n        background:#fff;\n        border-radius:24px;\n        padding:24px;\n        box-shadow:0 10px 40px rgba(0,0,0,.18);\n      \">\n\n        <div style=\"\n          font-size:24px;\n          font-weight:900;\n          color:#164478;\n          margin-bottom:18px;\n          text-align:center;\n        \">\n          □ Link Question To Course\n        </div>\n\n        ${selectHtml}\n\n        <div style=\"\n          display:flex;\n          gap:12px;\n          margin-top:22px;\n        \">\n\n          <button\n            id=\"saveCourseBtn\"\n            style=\"\n              flex:1;\n              background:#164478;\n              color:#fff;\n              border:none;\n              padding:14px;\n              border-radius:14px;\n              font-weight:900;\n              cursor:pointer;\n            \"\n          >\n            Save\n          </button>\n\n          <button\n            onclick=\"document.getElementById('courseModal').remove()\"\n            style=\"\n              flex:1;\n              background:#ef4444;\n              color:#fff;\n              border:none;\n              padding:14px;\n              border-radius:14px;\n              font-weight:900;\n              cursor:pointer;\n            \"\n          >\n            Cancel\n          </button>\n\n        </div>\n\n      </div>\n\n    </div>\n  `;\n\n  document.body.appendChild(wrapper);\n\n  const dropdown =\n    document.getElementById(\"courseDropdownSelect\");\n\n  // =========================================\n  // ✅ تحميل الدورات\n  // =========================================\n\n  const coursesSnap =\n    await db.collection(\"Courses\").get();\n\n  const CURRENT_USER =\n    String(localStorage.getItem(\"username\") || \"\")\n      .trim()\n      .toLowerCase();\n\n  coursesSnap.forEach(doc=>{\n\n    const c = doc.data();\n\n    const status =\n      String(c.status || \"\")\n        .trim()\n        .toLowerCase();\n\n    const trainer =\n      String(c.Trainer || \"\")\n        .trim()\n        .toLowerCase();\n\n    // ✅ فقط الدورات المفتوحة\n    if(\n      status !== \"open\" &&\n      status !== \"مفتوح\"\n    ){\n      return;\n    }\n\n    // ✅ فقط دورات المدرب\n    if(trainer !== CURRENT_USER){\n      return;\n    }\n\n    dropdown.innerHTML += `\n\n      <option\n        value=\"${doc.id}\"\n        data-course=\"${esc(c.TrainingCourse || \"\")}\"\n        data-trainer=\"${esc(c.Trainer || \"\")}\"\n        data-period=\"${esc(c.Period || \"\")}\"\n      >\n\n        ${esc(c.TrainingCourse || \"-\")}\n        | ${esc(c.Trainer || \"-\")}\n        | ${esc(c.Period || \"-\")}\n\n      </option>\n    `;\n  });\n\n  // =========================================\n  // ✅ الحفظ الحقيقي\n  // =========================================\n\n  document.getElementById(\"saveCourseBtn\")\n    .onclick = async function(){\n\n      const selected =\n        dropdown.options[\n          dropdown.selectedIndex\n        ];\n\n      const courseId =\n        selected.value;\n\n      if(!courseId){\n\n        alert(\"Choose Course\");\n\n        return;\n      }\n\n      // ✅ أهم تعديل\n      await db.collection(\"questions\")\n  .doc(questionId)\n  .update({\n\n    // ✅ الدورة المرتبط بها السؤال\n    linkedCourseId:\n      courseId,\n\n    // ✅ الاختبار الذي سيظهر داخله السؤال\n    linkedToExamId:\n      CURRENT_PREVIEW_EXAM,\n\n    // ✅ بيانات إضافية\n    linkedCourseName:\n      selected.dataset.course || \"\",\n\n    linkedTrainer:\n      selected.dataset.trainer || \"\",\n\n    linkedPeriod:\n      selected.dataset.period || \"\"\n\n  });\n      document\n        .getElementById(\"courseModal\")\n        .remove();\n\n      alert(\"✅ Course Linked\");\n\n      await loadQuestions();\n    };\n}\n/* ================= تشغيل ================= */\nasync function init(){\n  // Independent loading: failure of Courses must not prevent exams from loading.\n  const steps = [\n    [\"Course filters\", () => loadFilters()],\n    [\"Courses\", () => loadCourses()],\n    [\"Exams and Exam Bank\", () => loadExams()]\n  ];\n  const results = await Promise.allSettled(steps.map(async ([name, task]) => {\n    await task(); return name;\n  }));\n  const failed = results.map((result, i) => ({result, name:steps[i][0]}))\n    .filter(item => item.result.status === \"rejected\");\n  const status = document.getElementById(\"prudleDataStatus\");\n  if (failed.length){\n    console.warn(\"Prudle Worker initial data loading failed:\", failed);\n    if (status){\n      status.hidden = false;\n      status.setAttribute(\"role\", \"alert\");\n      const details = failed.map(({name,result})=>\n        name + \": \" + String(result.reason?.message || result.reason || \"Unknown error\")\n      );\n      status.textContent = \"تعذر تحميل بعض بيانات الاختبارات عبر Prudle Worker: \" +\n        details.join(\" | \") + \". تحقق من جلسة Firebase وصلاحيات /db، ثم أعد المحاولة.\";\n    }\n  }else if(status && !String(status.textContent || \"\").includes(\"وظائف الاختبارات\")){\n    status.hidden = true;\n    status.textContent = \"\";\n  }\n  try { toggleQuestionType(); } catch(error) { console.warn(\"Question type controls:\", error); }\n}\n\n/* =========================================\n   QUESTION ORDER / DRAG / COPY FUNCTIONS\n========================================= */\nlet QUESTION_DRAG_ID = \"\";\nlet QUESTION_COPY_BANK = [];\nlet QUESTION_COPY_SELECTED = new Set();\n\nfunction cleanQuestionForCopy(source, targetExamId, orderValue){\n  const q = source || {};\n  const copy = {\n    examId: targetExamId,\n    question: q.question || \"\",\n    passage: q.passage || \"\",\n    passageHtml: q.passageHtml || \"\",\n    passageAlign: [\"left\",\"center\",\"right\"].includes(q.passageAlign) ? q.passageAlign : \"left\",\n    options: Array.isArray(q.options) ? JSON.parse(JSON.stringify(q.options)) : [],\n    correct: Array.isArray(q.correct) ? [...q.correct] : (q.correct ?? \"\"),\n    degree: Number(q.degree || 1),\n    type: q.type || \"mcq\",\n    mediaType: q.mediaType || \"none\",\n    mediaUrl: q.mediaUrl || \"\",\n    group: q.group || \"General\",\n    showMedia: q.showMedia !== false,\n    order: Number(orderValue || 0),\n    isMain: q.isMain === true,\n\n    /*\n      النسخة سؤال جديد مستقل ومفتوح دائمًا،\n      حتى لو كان السؤال الأصلي مقفلًا.\n    */\n    locked:false,\n    lockedAt:null,\n    lockedBy:\"\",\n    lockReason:\"\",\n    lockSourceQuestionId:\"\",\n\n    createdBy: CURRENT_USER || \"\",\n    copiedFromQuestionId: q.id || \"\",\n    copiedFromExamId: q.examId || \"\",\n    copyIsIndependent:true,\n    inheritedLock:false,\n    createdAt: firebase.firestore.FieldValue.serverTimestamp()\n  };\n\n  if(Array.isArray(q.matchingPairs)) copy.matchingPairs = JSON.parse(JSON.stringify(q.matchingPairs));\n  if(Array.isArray(q.pairs)) copy.pairs = JSON.parse(JSON.stringify(q.pairs));\n  if(Array.isArray(q.answers)) copy.answers = JSON.parse(JSON.stringify(q.answers));\n  if(Array.isArray(q.fillItems)) copy.fillItems = JSON.parse(JSON.stringify(q.fillItems));\n  if(q.fillLayout) copy.fillLayout = q.fillLayout;\n  if(q.fillColumns) copy.fillColumns = Number(q.fillColumns);\n\n  // The copied question belongs to the currently selected course context.\n  if(CURRENT_COURSE_ID){\n    copy.coursesUsed = [{\n      courseId: CURRENT_COURSE_ID,\n      TrainingCourse: CURRENT_COURSE_NAME || \"\",\n      Trainer: CURRENT_TRAINER || \"\",\n      Period: CURRENT_PERIOD || \"\"\n    }];\n  }else{\n    /*\n      لا ننسخ روابط الدورات القديمة من السؤال الأصلي.\n      النسخة الجديدة تبدأ بدون روابط، ويمكن ربطها لاحقًا\n      بالدورات المطلوبة داخل الاختبار الجديد.\n    */\n    copy.coursesUsed = [];\n  }\n\n  return copy;\n}\n\nasync function getCurrentExamQuestionsOrdered(){\n  if(!CURRENT_PREVIEW_EXAM) return [];\n  const snap = await db.collection(\"questions\")\n    .where(\"examId\",\"==\",CURRENT_PREVIEW_EXAM)\n    .get();\n  return snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>{\n    const diff = Number(a.order || 0) - Number(b.order || 0);\n    if(diff) return diff;\n    return (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0);\n  });\n}\n\nasync function saveQuestionOrderByIds(ids){\n  if(!Array.isArray(ids) || !ids.length) return;\n  const chunks = [];\n  for(let i=0;i<ids.length;i+=450) chunks.push(ids.slice(i,i+450));\n  let offset = 0;\n  for(const part of chunks){\n    const batch = db.batch();\n    part.forEach((id,index)=>{\n      batch.update(db.collection(\"questions\").doc(id),{\n        order: offset + index + 1,\n        updatedAt: firebase.firestore.FieldValue.serverTimestamp()\n      });\n    });\n    await batch.commit();\n    offset += part.length;\n  }\n}\n\nasync function normalizeCurrentQuestionOrder(showMessage=true){\n  if(!CURRENT_PREVIEW_EXAM) return alert(\"اختر الاختبار أولاً\");\n  const items = await getCurrentExamQuestionsOrdered();\n  await saveQuestionOrderByIds(items.map(q=>q.id));\n  await loadQuestions();\n  if(showMessage) alert(\"✅ تم تحديث ترتيب وترقيم جميع الأسئلة تلقائياً\");\n}\n\nasync function moveQuestionByStep(questionId, direction){\n  const items = await getCurrentExamQuestionsOrdered();\n  const index = items.findIndex(q=>q.id===questionId);\n  if(index < 0) return;\n  const target = index + Number(direction || 0);\n  if(target < 0 || target >= items.length) return;\n  [items[index],items[target]] = [items[target],items[index]];\n  await saveQuestionOrderByIds(items.map(q=>q.id));\n  await loadQuestions();\n  requestAnimationFrame(()=>document.querySelector(`[data-question-id=\"${questionId}\"]`)?.scrollIntoView({behavior:\"smooth\",block:\"center\"}));\n}\n\nfunction initializeQuestionDragDrop(){\n  const cards = [...document.querySelectorAll(\"#questionsList .pro-question-card[data-question-id]\")];\n  cards.forEach(card=>{\n    card.addEventListener(\"dragstart\", e=>{\n      QUESTION_DRAG_ID = card.dataset.questionId || \"\";\n      card.classList.add(\"question-dragging\");\n      if(e.dataTransfer){\n        e.dataTransfer.effectAllowed = \"move\";\n        e.dataTransfer.setData(\"text/plain\",QUESTION_DRAG_ID);\n      }\n    });\n    card.addEventListener(\"dragend\",()=>{\n      QUESTION_DRAG_ID = \"\";\n      document.querySelectorAll(\".question-dragging,.question-drag-over\").forEach(el=>el.classList.remove(\"question-dragging\",\"question-drag-over\"));\n    });\n    card.addEventListener(\"dragover\",e=>{\n      e.preventDefault();\n      if(card.dataset.questionId !== QUESTION_DRAG_ID) card.classList.add(\"question-drag-over\");\n    });\n    card.addEventListener(\"dragleave\",()=>card.classList.remove(\"question-drag-over\"));\n    card.addEventListener(\"drop\",async e=>{\n      e.preventDefault();\n      card.classList.remove(\"question-drag-over\");\n      const targetId = card.dataset.questionId;\n      const sourceId = QUESTION_DRAG_ID || e.dataTransfer?.getData(\"text/plain\");\n      if(!sourceId || !targetId || sourceId===targetId) return;\n      const items = await getCurrentExamQuestionsOrdered();\n      const from = items.findIndex(q=>q.id===sourceId);\n      const to = items.findIndex(q=>q.id===targetId);\n      if(from<0 || to<0) return;\n      const [moved] = items.splice(from,1);\n      items.splice(to,0,moved);\n      await saveQuestionOrderByIds(items.map(q=>q.id));\n      await loadQuestions();\n      requestAnimationFrame(()=>document.querySelector(`[data-question-id=\"${sourceId}\"]`)?.scrollIntoView({behavior:\"smooth\",block:\"center\"}));\n    });\n  });\n}\n\nasync function duplicateQuestion(questionId){\n  if(!CURRENT_PREVIEW_EXAM) return alert(\"اختر الاختبار أولاً\");\n  const ref = db.collection(\"questions\").doc(questionId);\n  const doc = await ref.get();\n  if(!doc.exists) return alert(\"السؤال غير موجود\");\n  const items = await getCurrentExamQuestionsOrdered();\n  const sourceIndex = items.findIndex(q=>q.id===questionId);\n  const newRef = await db.collection(\"questions\").add(\n    cleanQuestionForCopy({id:doc.id,...doc.data()},CURRENT_PREVIEW_EXAM,sourceIndex+2)\n  );\n  const ids = items.map(q=>q.id);\n  ids.splice(sourceIndex+1,0,newRef.id);\n  await saveQuestionOrderByIds(ids);\n  await loadQuestions();\n  requestAnimationFrame(()=>document.querySelector(`[data-question-id=\"${newRef.id}\"]`)?.scrollIntoView({behavior:\"smooth\",block:\"center\"}));\n  alert(\"✅ تم نسخ السؤال ووضعه بعد السؤال الأصلي\");\n}\n\nasync function openQuestionCopyBank(){\n  if(!CURRENT_PREVIEW_EXAM) return alert(\"اختر الاختبار الذي تريد النسخ إليه أولاً\");\n\n  const modal = document.getElementById(\"questionCopyBankModal\");\n  const list = document.getElementById(\"questionCopyBankList\");\n  QUESTION_COPY_SELECTED = new Set();\n  list.innerHTML = `<div class=\"empty\">Loading questions...</div>`;\n  modal.classList.add(\"show\");\n  document.body.style.overflow = \"hidden\";\n\n  const [qSnap,eSnap] = await Promise.all([\n    db.collection(\"questions\").get(),\n    db.collection(\"exams\").get()\n  ]);\n\n  const exams = {};\n  eSnap.forEach(d=>exams[d.id]={id:d.id,...d.data()});\n\n  QUESTION_COPY_BANK = qSnap.docs\n    .map(d=>({\n      id:d.id,\n      ...d.data(),\n      examTitle:exams[d.data().examId]?.title || \"Untitled Exam\"\n    }))\n    .filter(q=>q.examId && q.examId !== CURRENT_PREVIEW_EXAM)\n    .sort((a,b)=>\n      String(a.examTitle).localeCompare(String(b.examTitle)) ||\n      Number(a.order||0)-Number(b.order||0)\n    );\n\n  const select = document.getElementById(\"copyBankExamFilter\");\n  const unique = [...new Map(\n    QUESTION_COPY_BANK.map(q=>[q.examId,{id:q.examId,title:q.examTitle}])\n  ).values()].sort((a,b)=>String(a.title).localeCompare(String(b.title)));\n\n  select.innerHTML = `<option value=\"\">All Exams</option>` +\n    unique.map(e=>`<option value=\"${esc(e.id)}\">${esc(e.title)}</option>`).join(\"\");\n\n  const search = document.getElementById(\"copyBankSearch\");\n  if(search) search.value = \"\";\n  renderQuestionCopyBank();\n}\n\nfunction closeQuestionCopyBank(event){\n  if(event && event.target?.id !== \"questionCopyBankModal\") return;\n  document.getElementById(\"questionCopyBankModal\")?.classList.remove(\"show\");\n  document.body.style.overflow = \"\";\n}\n\nfunction getCopyQuestionTypeLabel(type){\n  const map = {\n    mcq:\"Multiple Choice\",\n    match:\"Matching\",\n    order:\"Rearrange\",\n    text:\"Text Answer\",\n    fill:\"Fill in the Blanks\",\n    voice:\"Voice Recording\"\n  };\n  return map[type] || String(type || \"Question\");\n}\n\nfunction renderCopyQuestionDetails(q){\n  let html = \"\";\n\n  if(q.passage){\n    html += `<div class=\"copy-bank-passage\" style=\"text-align:${[\"left\",\"center\",\"right\"].includes(q.passageAlign) ? q.passageAlign : \"left\"}\"><strong>Reading Passage</strong><br>${getPassageDisplayHtml(q)}</div>`;\n  }\n\n  if(q.showMedia !== false && q.mediaUrl){\n    if(q.mediaType === \"image\"){\n      html += `<div class=\"copy-bank-media\"><img src=\"${esc(q.mediaUrl)}\" alt=\"Question image\"></div>`;\n    }else if(q.mediaType === \"video\"){\n      html += `<div class=\"copy-bank-media\"><video controls src=\"${esc(q.mediaUrl)}\"></video></div>`;\n    }else if(q.mediaType === \"audio\"){\n      html += `<div class=\"copy-bank-media\"><audio controls src=\"${esc(q.mediaUrl)}\"></audio></div>`;\n    }\n  }\n\n  if(q.type === \"mcq\"){\n    const correctIndex = Number(q.correct);\n    html += `<div class=\"copy-bank-options\">${(q.options || []).map((op,index)=>`\n      <div class=\"copy-bank-option ${index === correctIndex ? \"correct\" : \"\"}\">\n        ${String.fromCharCode(65 + index)}. ${esc(op)}\n        ${index === correctIndex ? `<i class=\"fa-solid fa-square-check\" style=\"margin-left:6px\"></i>` : \"\"}\n      </div>`).join(\"\")}</div>`;\n  }else if(q.type === \"order\"){\n    html += `<div class=\"copy-bank-options\">${(q.options || []).map((op,index)=>`\n      <div class=\"copy-bank-option\"><strong>${index+1}.</strong> ${esc(op)}</div>`).join(\"\")}</div>`;\n  }else if(q.type === \"match\"){\n    html += `<div style=\"margin-top:10px\">${(q.correct || []).map(pair=>{\n      const media = pair?.mediaUrl || pair?.imageUrl || pair?.image || \"\";\n      const right = media\n        ? `<img src=\"${esc(media)}\" alt=\"Matching image\">`\n        : `<span>${esc(pair?.right || \"\")}</span>`;\n      return `<div class=\"copy-bank-match-row\"><span>${esc(pair?.left || \"\")}</span><strong>↔</strong>${right}</div>`;\n    }).join(\"\")}</div>`;\n  }else if(q.type === \"fill\"){\n    const items=Array.isArray(q.fillItems)?q.fillItems:[];\n    html += `<div class=\"copy-bank-options\">${items.map((item,index)=>`<div class=\"copy-bank-option ${item.mode === \"blank\" ? \"correct\" : \"\"}\"><strong>${index+1}.</strong> ${item.mode === \"blank\" ? `Blank → ${esc(item.answer || \"\")}` : `Fixed → ${esc(item.display || \"\")}`}</div>`).join(\"\")}</div>`;\n  }else if(q.type === \"text\"){\n    html += `<div class=\"copy-bank-option correct\" style=\"margin-top:10px\"><strong>Correct answer:</strong> ${esc(Array.isArray(q.correct) ? q.correct.join(\" / \") : (q.correct || \"\"))}</div>`;\n    html += `<div class=\"copy-bank-option\" style=\"margin-top:7px\"><strong>Answer lines:</strong> ${Math.max(1,Math.min(20,Number(q.answerLines || 4)))}</div>`;\n  }else if(q.type === \"voice\"){\n    html += `<div class=\"copy-bank-option\" style=\"margin-top:10px\"><i class=\"fa-solid fa-microphone\"></i> Student records a voice answer.</div>`;\n  }\n\n  return html;\n}\n\nfunction toggleCopyBankQuestion(questionId,event){\n  if(event?.target?.closest(\"audio,video,button,a\")) return;\n\n  const checkbox = document.querySelector(`.copy-bank-check[value=\"${CSS.escape(questionId)}\"]`);\n  if(event?.target !== checkbox && checkbox){\n    checkbox.checked = !checkbox.checked;\n  }\n\n  if(checkbox?.checked) QUESTION_COPY_SELECTED.add(questionId);\n  else QUESTION_COPY_SELECTED.delete(questionId);\n\n  updateQuestionCopyBankCount();\n  checkbox?.closest(\".copy-bank-question\")?.classList.toggle(\"selected\",checkbox.checked);\n}\n\nfunction renderQuestionCopyBank(){\n  const examId = document.getElementById(\"copyBankExamFilter\")?.value || \"\";\n  const search = (document.getElementById(\"copyBankSearch\")?.value || \"\").trim().toLowerCase();\n\n  const visible = QUESTION_COPY_BANK.filter(q=>{\n    if(examId && q.examId !== examId) return false;\n    if(!search) return true;\n    return `${q.question||\"\"} ${q.examTitle||\"\"} ${q.group||\"\"} ${q.type||\"\"}`\n      .toLowerCase().includes(search);\n  });\n\n  const box = document.getElementById(\"questionCopyBankList\");\n  const found = document.getElementById(\"questionCopyBankFound\");\n  if(found) found.textContent = `Total Found: ${visible.length} Question${visible.length===1?\"\":\"s\"}`;\n\n  box.innerHTML = visible.length ? visible.map((q,index)=>{\n    const checked = QUESTION_COPY_SELECTED.has(q.id);\n    return `\n      <div class=\"copy-bank-question ${checked ? \"selected\" : \"\"}\" onclick='toggleCopyBankQuestion(${JSON.stringify(q.id)},event)'>\n        <div class=\"copy-bank-question-top\">\n          <input\n            type=\"checkbox\"\n            class=\"copy-bank-check copy-bank-question-check\"\n            value=\"${esc(q.id)}\"\n            ${checked ? \"checked\" : \"\"}\n            onchange='toggleCopyBankQuestion(${JSON.stringify(q.id)},event)'>\n\n          <div class=\"copy-bank-question-content\">\n            <div class=\"copy-bank-question-meta\">\n              <span class=\"copy-bank-q-number\">Q${index+1}</span>\n              <span class=\"badge type\">${esc(getCopyQuestionTypeLabel(q.type))}</span>\n              <span class=\"badge degree\">Marks: ${Number(q.degree||0)}</span>\n              <span class=\"badge used\">${esc(q.group||\"General\")}</span>\n            </div>\n\n            <div class=\"copy-bank-question-title\">${esc(q.question || \"(No question text)\")}</div>\n            <div class=\"copy-bank-source\">From: ${esc(q.examTitle || \"Untitled Exam\")}</div>\n            ${renderCopyQuestionDetails(q)}\n          </div>\n        </div>\n      </div>`;\n  }).join(\"\") : `<div class=\"empty\">No matching questions</div>`;\n\n  updateQuestionCopyBankCount();\n}\n\nfunction toggleAllCopyBankQuestions(checked){\n  document.querySelectorAll(\"#questionCopyBankList .copy-bank-check\").forEach(cb=>{\n    cb.checked = checked;\n    if(checked) QUESTION_COPY_SELECTED.add(cb.value);\n    else QUESTION_COPY_SELECTED.delete(cb.value);\n    cb.closest(\".copy-bank-question\")?.classList.toggle(\"selected\",checked);\n  });\n  updateQuestionCopyBankCount();\n}\n\nfunction updateQuestionCopyBankCount(){\n  const count = QUESTION_COPY_SELECTED.size;\n  const el = document.getElementById(\"questionCopyBankCount\");\n  if(el) el.textContent = `Selected Questions: ${count}`;\n}\n\nasync function copySelectedBankQuestions(){\n  if(!CURRENT_PREVIEW_EXAM) return alert(\"اختر الاختبار أولاً\");\n\n  const ids = [...QUESTION_COPY_SELECTED];\n  if(!ids.length) return alert(\"حدد سؤالاً واحداً على الأقل\");\n\n  const current = await getCurrentExamQuestionsOrdered();\n  const position = document.querySelector('input[name=\"copyInsertPosition\"]:checked')?.value || \"end\";\n\n  let insertIndex = current.length;\n  if(position === \"beginning\"){\n    insertIndex = 0;\n  }else if(position === \"after\" && EDIT_QUESTION_ID){\n    const editedIndex = current.findIndex(q=>q.id === EDIT_QUESTION_ID);\n    insertIndex = editedIndex >= 0 ? editedIndex + 1 : current.length;\n  }\n\n  const newIds = [];\n  for(const id of ids){\n    const source = QUESTION_COPY_BANK.find(q=>q.id===id);\n    if(!source) continue;\n    const ref = await db.collection(\"questions\").add(\n      cleanQuestionForCopy(source,CURRENT_PREVIEW_EXAM,1)\n    );\n    newIds.push(ref.id);\n  }\n\n  const finalIds = current.map(q=>q.id);\n  finalIds.splice(insertIndex,0,...newIds);\n  await saveQuestionOrderByIds(finalIds);\n\n  closeQuestionCopyBank();\n  await loadQuestions();\n  alert(`✅ تم نسخ ${newIds.length} سؤال وترتيبها تلقائياً`);\n}\n\nasync function deleteQuestion(id){\n\n  id = String(id || \"\").trim();\n\n  if(!id){\n    alert(\"معرّف السؤال غير موجود\");\n    return false;\n  }\n\n  try{\n    const ref =\n      db.collection(\"questions\").doc(id);\n\n    const qDoc =\n      await ref.get();\n\n    if(!qDoc.exists){\n      alert(\"Question not found\");\n      return false;\n    }\n\n    const q =\n      qDoc.data() || {};\n\n    /*\n      🔒 قاعدة الحذف:\n      السؤال المقفل لا يمكن حذفه.\n      يجب فك القفل أولاً، ثم يصبح زر الحذف متاحاً.\n    */\n    if(q.locked === true){\n      alert(\n        \"🔒 هذا السؤال مقفل ولا يمكن حذفه.\\n\" +\n        \"قم بفك قفل السؤال أولاً ثم حاول مرة أخرى.\"\n      );\n\n      const card = document.querySelector(\n        `.pro-question-card[data-question-id=\"${id}\"]`\n      );\n\n      if(card){\n        card.dataset.questionLocked = \"true\";\n      }\n\n      updateSelectedQuestionDeleteButton();\n      return false;\n    }\n\n    const questionNumber =\n      document.querySelector(\n        `.pro-question-card[data-question-id=\"${id}\"]`\n      )?.dataset.questionNumber || \"\";\n\n    const ok = confirm(\n      questionNumber\n        ? `⚠️ Delete Question ${questionNumber} only?\\n\\nThis will not delete the whole exam.`\n        : \"⚠️ Delete only this selected question?\"\n    );\n\n    if(!ok){\n      return false;\n    }\n\n    const examId =\n      String(q.examId || \"\").trim();\n\n    await ref.delete();\n\n    /*\n      إعادة ترتيب order مباشرة بعد حذف السؤال\n      حتى تصبح الأرقام 1,2,3... بدون فجوات.\n    */\n    if(examId){\n      try{\n        if(\n          typeof getCurrentExamQuestionsOrdered === \"function\" &&\n          typeof saveQuestionOrderByIds === \"function\" &&\n          String(CURRENT_PREVIEW_EXAM || \"\") === examId\n        ){\n          const remaining =\n            await getCurrentExamQuestionsOrdered();\n\n          await saveQuestionOrderByIds(\n            remaining.map(item => item.id)\n          );\n        }\n      }catch(orderErr){\n        console.warn(\n          \"Question deleted, but order normalization failed:\",\n          orderErr\n        );\n      }\n\n      await updateVisibleQuestions(examId);\n    }\n\n    if(EDIT_QUESTION_ID === id){\n      clearForm();\n    }\n\n    if(ACTIVE_QUESTION_ID === id){\n      ACTIVE_QUESTION_ID = \"\";\n    }\n\n    await loadQuestions();\n\n    /*\n      اختيار أقرب سؤال متبقٍ بعد إعادة التحميل.\n    */\n    const firstRemaining =\n      document.querySelector(\n        \".pro-question-card[data-question-id]\"\n      );\n\n    if(firstRemaining){\n      setActiveQuestion(\n        firstRemaining.dataset.questionId || \"\"\n      );\n    }else{\n      updateSelectedQuestionDeleteButton();\n    }\n\n    alert(\"✅ تم حذف السؤال المحدد فقط بنجاح\");\n    return true;\n\n  }catch(err){\n    console.error(\n      \"deleteQuestion error:\",\n      err\n    );\n\n    alert(\"❌ فشل حذف السؤال\");\n    return false;\n  }\n}\n\nasync function toggleMediaVisibility(questionId, currentState){\n  try{\n    await db.collection(\"questions\").doc(questionId).update({\n      showMedia: !currentState\n    });\n\n    alert(\"Updated successfully ✅\");\n\n    await loadQuestions();\n\n  }catch(err){\n    console.error(err);\n    alert(\"فشل التحديث ❌\");\n  }\n}\n// □ ربط اختيار الاختبار مع الأزرار\ndocument.addEventListener(\"change\", (e)=>{\n  if(e.target.classList.contains(\"examCheck\")){\n    \n  }\n});\nasync function unlinkQuestion(questionId){\n\n  try{\n\n    if(!confirm(\"Remove this link only?\")) return;\n\n    const ref =\n      db.collection(\"questions\").doc(questionId);\n\n    const docSnap = await ref.get();\n\n    if(!docSnap.exists){\n\n      alert(\"Question not found\");\n\n      return;\n    }\n\n    const q = docSnap.data() || {};\n\n    // جميع الدورات المرتبط بها السؤال\n    let used =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    // حذف الدورة الحالية فقط\n    used = used.filter(c => {\n\n      return String(c.courseId || \"\").trim() !==\n             String(CURRENT_COURSE_ID || \"\").trim();\n\n    });\n\n    // ====================================\n    // إذا بقيت دورات أخرى\n    // ====================================\n\n    if(used.length > 0){\n\n      const first = used[0];\n\n      await ref.update({\n\n        // جميع الدورات المتبقية\n        coursesUsed: used,\n\n        // أول دورة تصبح الرئيسية\n        linkedCourseId:\n          first.courseId || \"\",\n\n        linkedCourseName:\n          first.TrainingCourse || \"\",\n\n        linkedTrainer:\n          first.Trainer || \"\",\n\n        linkedPeriod:\n          first.Period || \"\"\n\n      });\n\n    }\n\n    // ====================================\n    // إذا لم يبق أي دورة\n    // ====================================\n\n    else{\n\n      await ref.update({\n\n        coursesUsed: [],\n\n        linkedCourseId:\n          firebase.firestore.FieldValue.delete(),\n\n        linkedCourseName:\n          firebase.firestore.FieldValue.delete(),\n\n        linkedTrainer:\n          firebase.firestore.FieldValue.delete(),\n\n        linkedPeriod:\n          firebase.firestore.FieldValue.delete()\n\n      });\n\n    }\n\n    alert(\"✅ Link removed only\");\n\n    // إعادة تحميل الأسئلة\n    await loadQuestions(CURRENT_PREVIEW_EXAM);\n\n  }catch(err){\n\n    console.error(err);\n\n    alert(\"❌ Failed to remove link\");\n\n  }\n}function toggleWholeGroup(groupName, checked){\n\n  document\n    .querySelectorAll(`.questionCheck[data-group=\"${groupName}\"]`)\n    .forEach(cb=>{\n\n      cb.checked = checked;\n\n    });\n\n  autoSaveVisibleQuestions();\n}\nasync function renameExam(examId, newTitle){\n\n  newTitle = String(newTitle || \"\").trim();\n\n  if(!newTitle){\n    alert(\"اكتب اسم الكويز\");\n    return;\n  }\n\n  const role = String(localStorage.getItem(\"role\") || \"\")\n    .trim()\n    .toLowerCase();\n\n  const qSnap = await db.collection(\"questions\")\n    .where(\"examId\",\"==\",examId)\n    .where(\"locked\",\"==\",true)\n    .limit(1)\n    .get();\n\n  if(false){\n    alert(\"□ Locked Quiz\");\n    await loadExams();\n    return;\n  }\n\n  await db.collection(\"exams\").doc(examId).update({\n    title: newTitle,\n    updatedAt: new Date()\n  });\n\n  await loadExams();\n}\nasync function updateAllQuestionsDegree(){\n\n  const examId = CURRENT_PREVIEW_EXAM;\n\n  if(!examId){\n    alert(\"اختر الاختبار أولاً\");\n    return;\n  }\n\n  const newDegree = Number(\n    prompt(\"اكتب الدرجة الجديدة لكل الأسئلة:\")\n  );\n\n  if(!newDegree || newDegree <= 0){\n    alert(\"اكتب درجة صحيحة\");\n    return;\n  }\n\n  if(!confirm(\"سيتم تعديل درجة جميع أسئلة هذا الاختبار، هل أنت متأكد؟\")){\n    return;\n  }\n\n  const qSnap = await db.collection(\"questions\")\n    .where(\"examId\",\"==\",examId)\n    .get();\n\n  for(const doc of qSnap.docs){\n\n    await db.collection(\"questions\")\n      .doc(doc.id)\n      .update({\n        degree: newDegree,\n        updatedAt: new Date()\n      });\n\n  }\n\n  alert(\"✅ تم تعديل درجة جميع أسئلة الاختبار\");\n\n  await loadQuestions();\n}\n\n/* =========================================\n   REPAIR ALL CURRENT EXAM LINKS\n   استخدمها مرة واحدة لإصلاح الروابط القديمة\n========================================= */\nasync function repairAllLinkedQuestionVisibility(){\n  const examId =\n    String(CURRENT_PREVIEW_EXAM || \"\").trim();\n\n  if(!examId){\n    alert(\"Choose the exam first\");\n    return;\n  }\n\n  const qSnap =\n    await db.collection(\"questions\")\n      .where(\"examId\",\"==\",examId)\n      .get();\n\n  const courseIds =\n    new Set();\n\n  qSnap.forEach(doc=>{\n    const q = doc.data() || {};\n\n    const coursesUsed =\n      Array.isArray(q.coursesUsed)\n        ? q.coursesUsed\n        : [];\n\n    coursesUsed.forEach(item=>{\n      const courseId =\n        String(item?.courseId || \"\").trim();\n\n      if(courseId){\n        courseIds.add(courseId);\n      }\n    });\n  });\n\n  for(const courseId of courseIds){\n    await syncAllVisibleLinkedQuestions(\n      examId,\n      courseId\n    );\n  }\n\n  alert(\n    `✅ Repaired ${courseIds.size} linked course(s). All linked questions will appear to students.`\n  );\n\n  await loadQuestions();\n}\n\n// □ تشغيل الصفحة\ninit();\n"}, {"src": "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/2.16.105/pdf.min.js"}, {"src": "https://unpkg.com/mammoth/mammoth.browser.min.js"}, {"text": "\nwindow.addEventListener(\"DOMContentLoaded\",()=>{\n  if(\n    document.getElementById(\"matchingBox\") &&\n    !getMatchingRows().length\n  ){\n    resetMatchingRows([]);\n  }\n});\n"}, {"text": "\nwindow.addEventListener(\"DOMContentLoaded\",()=>{\n  if(\n    document.getElementById(\"rearrangeItemsBox\") &&\n    !getRearrangeRows().length\n  ){\n    resetRearrangeItems([]);\n  }\n});\n"}, {"text": "\nconst PRUDLE_LIBRARY_AI_ENDPOINT=\"https://api-prudle.abbassaboali.workers.dev/public/library-ai\";\nlet prudleAIGenerated=[];\nfunction prudleQuizRoles(){\n  let r=[];try{const v=JSON.parse(localStorage.getItem(\"roles\")||\"[]\");if(Array.isArray(v))r=v.map(x=>String(x||\"\").toLowerCase().trim());}catch(e){}\n  for(const x of [localStorage.getItem(\"role\"),localStorage.getItem(\"userRole\")]){const a=String(x||\"\").toLowerCase().trim();if(a&&!r.includes(a))r.push(a)}return r;\n}\nfunction prudleAISafe(t){return String(t??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",\"\\\"\":\"&quot;\",\"'\":\"&#39;\"})[c])}\nfunction prudleAIStatus(s){document.getElementById(\"prudleAIStatus\").textContent=s}\nasync function prudleAIPost(body){const ac=new AbortController();const timer=setTimeout(()=>ac.abort(),120000);try{const resp=await fetch(PRUDLE_LIBRARY_AI_ENDPOINT,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body),signal:ac.signal});const txt=await resp.text();let d;try{d=JSON.parse(txt)}catch{throw Error(\"خدمة الذكاء الاصطناعي أرجعت استجابة غير صالحة\")};if(!resp.ok)throw Error(d.error||d.message||\"HTTP \"+resp.status);return d;}finally{clearTimeout(timer)}}\nfunction prudleAIParse(d){if(Array.isArray(d))return d;for(const x of [d.questions,d.data?.questions,d.result?.questions,d.result,d.data]){if(Array.isArray(x))return x};return []}\nfunction prudleAINormalize(x,kind){const text=String(x?.question||x?.q||x?.text||\"\").trim();if(!text)return null;let type=String(x.type||kind).toLowerCase();if(type===\"true_false\")type=\"tf\";if(type===\"fill\"||type===\"fill_in_blank\")type=\"missing\";\nlet options=Array.isArray(x.options)?x.options.map(v=>String(v??\"\").trim()).filter(Boolean):[];let answer=x.answer??x.correctAnswer??x.correct??\"\";\nif(type===\"tf\"){options=[\"True\",\"False\"];answer=/^(true|t|yes|1)$/i.test(String(answer))?\"True\":\"False\";type=\"mcq\"}\nif(type===\"missing\")type=\"text\";\nif(type===\"voice\")return {type:\"voice\",question:text,correct:\"voice\",options:[]};\nif(type===\"order\"){const p=Array.isArray(x.parts)?x.parts:Array.isArray(x.correctOrder)?x.correctOrder:[];return p.length>=2?{type:\"order\",question:text,options:p.map(String),correct:p.map(String)}:null}\nif(type===\"match\"){const pairs=(x.pairs||x.matches||[]).map(p=>Array.isArray(p)?p:[p.left,p.right]).filter(p=>p.length===2&&p.every(z=>String(z||\"\").trim())).map(([left,right])=>({left:String(left),right:String(right),mediaUrl:\"\"}));return pairs.length>=2?{type:\"match\",question:text,options:pairs.map(p=>p.left+\"=\"+p.right),correct:pairs}:null}\nif(type===\"text\")return {type:\"text\",question:text.replace(/___/g,\"________\"),options:[],correct:[String(answer).trim().toLowerCase()]};\nif(typeof answer===\"number\"&&options[answer]!==undefined)answer=options[answer];if(!options.length&&Array.isArray(x.answers))options=x.answers.map(a=>String(a.text||a));if(!options.length)return null;let idx=options.findIndex(o=>o.toLowerCase()===String(answer).trim().toLowerCase());if(idx<0&&/^\\d+$/.test(String(answer))&&Number(answer)<options.length)idx=Number(answer);if(idx<0)return null;return {type:\"mcq\",question:text,options,correct:idx};}\nasync function prudleGenerateQuizAI(){\n const btn=document.getElementById(\"aiGenerateBtn\"),save=document.getElementById(\"aiSaveBtn\"),level=document.getElementById(\"aiLevel\").value,skill=document.getElementById(\"aiSkill\").value,requestedCount=Math.min(40,Math.max(1,Number(document.getElementById(\"aiCount\").value)||5)),type=document.getElementById(\"aiType\").value,topic=document.getElementById(\"aiTopic\").value.trim(),source=document.getElementById(\"aiSource\").value.trim();\n if(!document.getElementById(\"examSelect\")?.value){prudleAIStatus(\"⚠️ حدد الاختبار أولًا من قائمة Add / Edit\");return;}\n // The current Worker model reliably generates at most 15 source-based questions per request.\n if((skill===\"reading\"||skill===\"listening\")&&requestedCount>15){prudleAIStatus(\"⚠️ الحد الحالي لأسئلة Reading/Listening في التوليد الواحد 15 سؤالًا. اختر 15 أو أقل.\");return;}\n const count=requestedCount;\n const kinds=type===\"mixed\"?(skill===\"speaking\"?[\"voice\",\"mcq\"]:[\"mcq\",\"tf\",\"missing\",\"order\"]):[type];\n btn.disabled=true;save.disabled=true;prudleAIGenerated=[];document.getElementById(\"prudleAIResults\").innerHTML=\"\";\n try{\n  prudleAIStatus(\"⏳ جاري إنشاء \"+(skill===\"listening\"?\"مقطع استماع MP3\":skill===\"reading\"?\"قطعة قراءة\":\"أسئلة\")+\" بمستوى \"+level+\" ...\");\n  let context=source||topic||(\"English assessment at CEFR \"+level);\n  let collected=[],sharedSource=\"\",sharedAudio=\"\",sharedTitle=\"\";\n  for(let k=0;k<kinds.length;k++){\n   const kind=kinds[k],n=Math.floor(count/kinds.length)+(k<count%kinds.length?1:0);if(!n)continue;\n   if(kind===\"voice\"&&skill===\"speaking\"){\n    const d=await prudleAIPost({task:\"generate_activity_questions\",generationScope:\"same\",generateNewPassage:false,text:context,sourceText:context,prompt:\"Create spoken English assessment questions suitable for \"+level,level,count:n,questionType:\"text\",skill});\n    collected.push(...prudleAIParse(d).slice(0,n).map(x=>prudleAINormalize({...x,type:\"voice\"},\"voice\")).filter(Boolean));continue;\n   }\n   // Reading and Listening: create source ONCE and use the same source for all question types.\n   const isComprehension=skill===\"reading\"||skill===\"listening\";\n   const useNewSource=isComprehension&&!sharedSource&&!source;\n   const effectiveSource=sharedSource||source||\"\";\n   const questionKind=kind===\"voice\"?\"mcq\":kind;\n   const d=await prudleAIPost({task:\"generate_activity_questions\",generationScope:useNewSource?\"new\":\"same\",generateNewPassage:useNewSource,\n    sourceText:isComprehension?effectiveSource:context, text:isComprehension?effectiveSource:context,\n    topic:topic||\"CEFR-appropriate English\",level,count:n,questionType:questionKind,requestedQuestionType:questionKind,\n    skill,voice:\"nova\",prompt:\"Generate accurate, level-appropriate assessment questions with unambiguous correct answers.\"});\n   if(isComprehension){\n    sharedSource=String(d.passage?.text||d.transcript||sharedSource||\"\").trim();\n    sharedTitle=String(d.passage?.title||sharedTitle||\"\").trim();\n    if(!sharedSource)throw Error(\"لم يرجع الـWorker نص القطعة أو الاستماع. تحقق من نسخة الـWorker المنشورة.\");\n    if(skill===\"listening\"){\n      sharedAudio=String(d.audioUrl||d.audio?.url||sharedAudio||\"\").trim();\n      if(!sharedAudio)throw Error(\"لم يرجع الـWorker ملف MP3 صالحًا، لا يمكن حفظ Listening بدون صوت.\");\n    }\n   }\n   const qs=prudleAIParse(d).slice(0,n);\n   for(const x of qs){const v=prudleAINormalize(x,questionKind);if(v){\n    v.passage=skill===\"reading\"?sharedSource:String(x.passage||x.sourceText||\"\").trim();\n    if(skill===\"listening\"){\n      v.passage=\"\"; // Do not display the transcript as reading text for students.\n      v.aiTranscript=sharedSource;\n      v.aiPassageTitle=sharedTitle;\n      v.mediaType=\"audio\";\n      v.mediaUrl=sharedAudio;\n    }\n    collected.push(v);\n   }}\n  }\n  prudleAIGenerated=collected.slice(0,count).map(q=>({...q,skill,cefrLevel:level,topic}));\n  if(prudleAIGenerated.length!==count)throw Error(\"تم توليد \"+prudleAIGenerated.length+\" سؤالًا بدل العدد المطلوب \"+count+\". جرّب عددًا أقل.\");\n  const audioPreview=sharedAudio?`<div style=\"margin:12px 0;padding:12px;background:#eef6ff;border-radius:12px\"><b>🎧 Listening MP3</b><audio controls preload=\"none\" src=\"${prudleAISafe(sharedAudio)}\" style=\"width:100%\"></audio></div>`:\"\";\n  const passagePreview=sharedSource?`<details style=\"margin:10px 0;padding:12px;background:#f4f8ff;border-radius:12px\"><summary>${skill===\"reading\"?\"📖 قطعة القراءة\":\"📝 نص الاستماع للمدرب فقط\"}</summary><pre style=\"white-space:pre-wrap\">${prudleAISafe(sharedSource)}</pre></details>`:\"\";\n  document.getElementById(\"prudleAIResults\").innerHTML=audioPreview+passagePreview+prudleAIGenerated.map((q,i)=>`<article class=\"ai-question\"><label><input type=\"checkbox\" class=\"ai-keep\" data-i=\"${i}\" checked><b>السؤال ${i+1} — ${prudleAISafe(q.type)} — ${prudleAISafe(level)}</b></label><pre>${prudleAISafe(q.question)}${q.options.length?\"\\n\"+prudleAISafe(q.options.join(\" | \")):\"\"}</pre></article>`).join(\"\");\n  save.disabled=false;prudleAIStatus(\"✅ تم توليد \"+prudleAIGenerated.length+\" سؤالًا\"+(sharedAudio?\" مع ملف صوتي MP3 حقيقي\":\"\")+\". راجعها ثم احفظ المحدد.\");\n }catch(e){console.error(\"Prudle AI Quiz\",e);prudleAIStatus(\"❌ \"+(e.name===\"AbortError\"?\"انتهت مهلة خدمة التوليد\":e.message))}finally{btn.disabled=false}\n}\nasync function prudleSaveGeneratedQuiz(){const examId=document.getElementById(\"examSelect\")?.value;const selected=[...document.querySelectorAll(\"#prudleAIResults .ai-keep:checked\")].map(e=>prudleAIGenerated[+e.dataset.i]).filter(Boolean);if(!examId||!selected.length){prudleAIStatus(\"⚠️ حدد اختبارًا وأسئلة للحفظ\");return}\n const degree=Number(document.getElementById(\"aiDegree\").value);if(!(degree>0)){prudleAIStatus(\"⚠️ درجة السؤال يجب أن تكون أكبر من صفر\");return}\n const save=document.getElementById(\"aiSaveBtn\");save.disabled=true;let saved=0;\n try{const ex=await db.collection(\"exams\").doc(examId).get();if(!ex.exists)throw Error(\"الاختبار غير موجود\");const exam=ex.data()||{};const existing=await db.collection(\"questions\").where(\"examId\",\"==\",examId).get();let order=Math.max(0,...existing.docs.map(d=>Number(d.data().order)||0));\n  for(const q of selected){let coursesUsed=(exam.coursesData||[]).map(c=>({courseId:c.courseId,TrainingCourse:c.TrainingCourse,Trainer:c.Trainer}));if(typeof dedupeCoursesUsed===\"function\")coursesUsed=dedupeCoursesUsed(coursesUsed);\n   const parts=q.type===\"match\"?q.correct.length:1;\n   await db.collection(\"questions\").add({examId,order:++order,question:q.question,passage:q.passage||\"\",passageHtml:\"\",passageAlign:\"left\",options:q.options,correct:q.correct,fillItems:[],fillLayout:\"\",fillColumns:0,answerLines:q.type===\"text\"?4:0,degree,gradingParts:parts,partDegree:degree/parts,type:q.type,mediaType:q.mediaType||\"none\",mediaUrl:q.mediaUrl||\"\",aiTranscript:q.aiTranscript||\"\",aiPassageTitle:q.aiPassageTitle||\"\",group:document.getElementById(\"aiGroup\").value,showMedia:true,locked:false,coursesUsed,skill:q.skill,cefrLevel:q.cefrLevel,aiGenerated:true,createdAt:new Date()});saved++;prudleAIStatus(\"⏳ تم حفظ \"+saved+\" من \"+selected.length)}\n  if(typeof updateVisibleQuestions===\"function\")await updateVisibleQuestions(examId);\n  if(typeof loadQuestions===\"function\")await loadQuestions();prudleAIStatus(\"✅ تم حفظ \"+saved+\" سؤالًا في الاختبار.\");\n  prudleAIGenerated=[];document.getElementById(\"prudleAIResults\").innerHTML=\"\";\n }catch(e){prudleAIStatus(\"❌ حُفظ \"+saved+\" سؤالًا. حدث خطأ: \"+e.message)}finally{save.disabled=true}\n}\n"}, {"text": "document.addEventListener(\"DOMContentLoaded\",()=>{const ai=document.getElementById(\"prudleAIQuiz\");const examSelect=document.getElementById(\"examSelect\");if(ai&&examSelect){const block=examSelect.closest(\".box\");if(block)block.parentNode.insertBefore(ai,block);}});"}, {"text": "\n(function(){\n \"use strict\";\n const $ = id => document.getElementById(id);\n const text = v => String(v ?? \"\");\n const esc = v => text(v).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n const sample = [\n  {type:'mcq',group:'Grammar',question:'Choose the correct sentence.',options:['She go to school.','She goes to school.','She going to school.'],correct:1,degree:2},\n  {type:'mcq',group:'Vocabulary',question:'What is the opposite of difficult?',options:['Easy','Heavy','Late'],correct:0,degree:1},\n  {type:'text',group:'Writing',question:'Write the past tense of “go”.',correct:'went',degree:1},\n  {type:'order',group:'Grammar',question:'Put these words in the correct order.',options:['every','English','day','I','study'],correct:'I study English every day',degree:2}\n ];\n function normalize(data){\n  if(Array.isArray(data)) return data;\n  if(!data || typeof data !== 'object') return [];\n  for(const key of ['questions','data','items','documents','records']){\n    if(Array.isArray(data[key])) return data[key];\n    if(data[key] && typeof data[key] === 'object'){\n      const nested=normalize(data[key]);if(nested.length) return nested;\n    }\n  }\n  return Object.values(data).filter(v => v && typeof v === 'object' && (v.question || v.text || v.type));\n }\n function unwrap(q){return q && q.fields && typeof q.fields === 'object' ? q.fields : q;}\n function getOptions(q){\n  let a=q.options || q.choices || q.answers || [];\n  if(!Array.isArray(a)) a=Object.values(a);\n  return a.map(v => typeof v === 'object' && v!==null ? (v.text??v.label??v.value??JSON.stringify(v)) : v);\n }\n function answer(q,options){\n  const raw=q.correct ?? q.correctAnswer ?? q.answer ?? q.answerKey ?? q.correctIndex;\n  if(raw===undefined || raw===null || raw==='') return 'Not specified in the imported data';\n  if(Array.isArray(raw)) return raw.map(v=>answer({...q,correct:v},options)).join(' · ');\n  if(typeof raw==='number' && raw>=0 && raw<options.length) return text(options[raw]);\n  if(typeof raw==='string' && /^\\d+$/.test(raw) && Number(raw)<options.length) return text(options[Number(raw)]);\n  return text(raw);\n }\n function render(data,label){\n  const questions=normalize(data).map(unwrap).filter(q=>q && typeof q==='object' && (q.question||q.text||q.title));\n  $('prudleLocalStatus').textContent= questions.length ? `${label}: ${questions.length} سؤال` : 'الملف لا يحتوي على أسئلة بالتنسيق المتوقع.';\n  $('prudleLocalQuestions').innerHTML=questions.map((q,i)=>{\n   const opts=getOptions(q);\n   const title=q.question??q.text??q.title;\n   const optsHtml=opts.length?`<ol style=\"margin:10px 0;padding-left:25px\">${opts.map(o=>`<li style=\"margin:4px 0\">${esc(o)}</li>`).join('')}</ol>`:'';\n   return `<article style=\"border:1px solid #dbeafe;border-radius:16px;padding:16px;background:#f8fbff;color:#1e293b\">\n     <div style=\"font-size:12px;color:#64748b;margin-bottom:8px\">Question ${i+1} · ${esc(q.group||q.skill||q.type||'General')} · ${esc(q.degree??1)} mark(s)</div>\n     <div style=\"font-weight:800;font-size:17px;white-space:pre-wrap\">${esc(title)}</div>\n     ${q.passage?`<blockquote style=\"white-space:pre-wrap;margin:8px 0;padding:10px;background:#fff;border-left:3px solid #164478\">${esc(q.passage)}</blockquote>`:''}\n     ${optsHtml}\n     <details style=\"margin-top:10px\"><summary style=\"cursor:pointer;color:#047857;font-weight:800\">Show correct answer</summary><div style=\"margin-top:8px;padding:10px;border-radius:10px;background:#e7f8ee;font-weight:700\">${esc(answer(q,opts))}</div></details>\n   </article>`;\n  }).join('');\n }\n $('prudleTrySample')?.addEventListener('click',()=>render(sample,'بيانات تجريبية فقط — ليست من قاعدة البيانات'));\n $('prudleQuestionImport')?.addEventListener('change',async e=>{\n  const file=e.target.files?.[0];if(!file)return;\n  try{const data=JSON.parse(await file.text());render(data,'أسئلة مستوردة محليًا');}\n  catch(error){$('prudleLocalStatus').textContent='تعذر قراءة JSON: '+error.message;}\n });\n})();\n"}, {"text": "\n\n\n// ✅ إعادة الاختبار لطالب واحد للدورة المرتبطة\nasync function resetLinkedCourseOneLegacy(\n  questionId,\n  courseId\n){\n\n  const enteredId =\n    String(prompt(\"Insert Student ID\") || \"\").trim();\n\n  if(!enteredId) return;\n\n  courseId =\n    String(courseId || \"\").trim();\n\n  if(!courseId){\n    alert(\"Choose linked course first\");\n    return;\n  }\n\n  const access =\n    await verifyLinkedCourseAccess(courseId);\n\n  if(!access.allowed){\n    alert(\"⛔ You can reset your linked course only\");\n    return;\n  }\n\n  const qDoc =\n    await db.collection(\"questions\")\n      .doc(questionId)\n      .get();\n\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = qDoc.data() || {};\n  const examId =\n    String(q.examId || \"\").trim();\n\n  if(!examId){\n    alert(\"Exam not found\");\n    return;\n  }\n\n  /*\n    ✅ مهم للدورات المرتبطة:\n    بعض النتائج القديمة قد تحفظ studentId كـ Firestore document ID،\n    وبعضها قد تحفظ رقم الهوية نفسه أو حقلاً مختلفاً.\n    لذلك لا نستخدم استعلام studentId واحد فقط.\n  */\n\n  // 1) ابحث عن سجل الطالب من رقم الهوية\n  let studentDoc = null;\n\n  const studentSnap =\n    await db.collection(\"students\")\n      .where(\"iqama\",\"==\",enteredId)\n      .get();\n\n  if(!studentSnap.empty){\n    studentDoc = studentSnap.docs[0];\n  }else{\n    /*\n      دعم إضافي إذا كان رقم الطالب محفوظاً في studentID بدلاً من iqama.\n    */\n    try{\n      const byStudentID =\n        await db.collection(\"students\")\n          .where(\"studentID\",\"==\",enteredId)\n          .get();\n\n      if(!byStudentID.empty){\n        studentDoc = byStudentID.docs[0];\n      }\n    }catch(e){\n      console.warn(\"studentID fallback:\", e);\n    }\n  }\n\n  if(!studentDoc){\n    alert(\"Student not found\");\n    return;\n  }\n\n  const studentData =\n    studentDoc.data() || {};\n\n  const firestoreStudentId =\n    String(studentDoc.id || \"\").trim();\n\n  /*\n    جميع القيم الممكن أن تكون قد استخدمت تاريخياً\n    كـ studentId داخل results.\n  */\n  const possibleStudentIds = new Set(\n    [\n      firestoreStudentId,\n      enteredId,\n      studentData.iqama,\n      studentData.studentId,\n      studentData.studentID,\n      studentData.id,\n      studentData.ID\n    ]\n    .map(v => String(v || \"\").trim())\n    .filter(Boolean)\n  );\n\n  /*\n    ✅ نبحث أولاً عن نتائج نفس الاختبار + نفس الدورة.\n    هذا نفس الأسلوب الذي يجعل Reset Course يعمل بشكل صحيح.\n    بعد ذلك نحدد نتيجة الطالب محلياً بدل فرض أن studentId\n    يساوي document ID فقط.\n  */\n  const courseResultsSnap =\n    await db.collection(\"results\")\n      .where(\"examId\",\"==\",examId)\n      .where(\"courseId\",\"==\",courseId)\n      .get();\n\n  if(courseResultsSnap.empty){\n    alert(\"No results for this linked course\");\n    return;\n  }\n\n  const matchedResultDocs =\n    courseResultsSnap.docs.filter(doc => {\n\n      const r = doc.data() || {};\n\n      const resultValues = [\n        r.studentId,\n        r.studentID,\n        r.iqama,\n        r.studentIqama,\n        r.id,\n        r.ID\n      ]\n      .map(v => String(v || \"\").trim())\n      .filter(Boolean);\n\n      return resultValues.some(v =>\n        possibleStudentIds.has(v)\n      );\n\n    });\n\n  if(!matchedResultDocs.length){\n\n    console.warn(\n      \"RESET LINKED STUDENT: no matching result\",\n      {\n        enteredId,\n        firestoreStudentId,\n        examId,\n        courseId,\n        possibleStudentIds:[...possibleStudentIds],\n        courseResults:\n          courseResultsSnap.docs.map(d => ({\n            id:d.id,\n            ...d.data()\n          }))\n      }\n    );\n\n    alert(\n      \"No result found for this student in the selected linked course\"\n    );\n    return;\n  }\n\n  // ✅ حذف نتيجة هذا الطالب فقط من هذه الدورة المرتبطة\n  const batch = db.batch();\n\n  matchedResultDocs.forEach(doc=>{\n    batch.delete(\n      db.collection(\"results\").doc(doc.id)\n    );\n  });\n\n  await batch.commit();\n\n  /*\n    ✅ السماح بإعادة الاختبار.\n    نستخدم document ID الحقيقي للطالب لأنه المستخدم\n    في آلية examRetakes الحالية.\n  */\n  await allowStudentRetake(\n    examId,\n    courseId,\n    firestoreStudentId,\n    enteredId\n  );\n\n  alert(\n    \"✅ Student can do the exam again for this linked course only\"\n  );\n\n}\n\n// ✅ إعادة الاختبار لطالب واحد في الدورة المرتبطة\n// نفس آلية الزر العاملة في الكود الثاني:\n// iqama -> student document ID -> result لنفس الاختبار والدورة فقط\nasync function resetLinkedCourseOne(\n  questionId,\n  courseId\n){\n\n  const iqama =\n    String(prompt(\"Insert Student ID\") || \"\").trim();\n\n  if(!iqama) return;\n\n  courseId = String(courseId || \"\").trim();\n\n  if(!courseId){\n    alert(\"Choose linked course first\");\n    return;\n  }\n\n  try{\n\n    const qDoc = await db.collection(\"questions\")\n      .doc(questionId)\n      .get();\n\n    if(!qDoc.exists){\n      alert(\"Question not found\");\n      return;\n    }\n\n    const q = qDoc.data() || {};\n    const examId = String(q.examId || \"\").trim();\n\n    if(!examId){\n      alert(\"Exam not found\");\n      return;\n    }\n\n    // البحث عن الطالب برقم الهوية، مثل الكود الثاني تماماً\n    const studentSnap = await db.collection(\"students\")\n      .where(\"iqama\",\"==\",iqama)\n      .get();\n\n    if(studentSnap.empty){\n      alert(\"Student not found\");\n      return;\n    }\n\n    const studentId = studentSnap.docs[0].id;\n\n    // حذف نتيجة الطالب لنفس الاختبار والدورة المرتبطة المحددة فقط\n    const resultSnap = await db.collection(\"results\")\n      .where(\"studentId\",\"==\",studentId)\n      .where(\"examId\",\"==\",examId)\n      .where(\"courseId\",\"==\",courseId)\n      .get();\n\n    if(resultSnap.empty){\n      alert(\"No result for this course\");\n      return;\n    }\n\n    const batch = db.batch();\n\n    resultSnap.docs.forEach(doc=>{\n      batch.delete(\n        db.collection(\"results\").doc(doc.id)\n      );\n    });\n\n    await batch.commit();\n\n    alert(\"✅ Student can do exam again\");\n\n  }catch(error){\n    console.error(\"RESET LINKED STUDENT ERROR:\", error);\n    alert(\"❌ Could not reset this student. Please try again.\");\n  }\n\n}\n\n// ✅ إعادة الاختبار لكل طلاب الدورة المرتبطة\nasync function resetLinkedCourseAll(\n  questionId,\n  courseId\n){\n\n  const ok = confirm(\n    \"Reset this linked course only?\"\n  );\n\n  if(!ok) return;\n\n  const access = await verifyLinkedCourseAccess(courseId);\n\n  if(!access.allowed){\n    alert(\"⛔ You can reset your linked course only\");\n    return;\n  }\n\n  const qDoc = await db.collection(\"questions\")\n    .doc(questionId)\n    .get();\n\n  if(!qDoc.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = qDoc.data();\n\n  const examId = q.examId;\n\n  // ✅ حذف نتائج نفس الدورة فقط\n  const resultSnap = await db.collection(\"results\")\n    .where(\"examId\",\"==\",examId)\n    .where(\"courseId\",\"==\",courseId)\n    .get();\n\n  if(resultSnap.empty){\n    alert(\"No students\");\n    return;\n  }\n\n  for(const doc of resultSnap.docs){\n\n    await db.collection(\"results\")\n      .doc(doc.id)\n      .delete();\n\n  }\n\n  alert(\"✅ Linked course reset completed\");\n\n}\n// ======================================\n// ✅ Lock / Unlock Question\n// ======================================\n\n// ======================================\n// 🔐 ADMIN LOCK / UNLOCK — SAME LOGIN ACCOUNT\n// ======================================\n\nfunction normalizeAdminLockUsername(value){\n  return String(value || \"\")\n    .trim()\n    .toLowerCase();\n}\n\n/*\n  يتحقق من أن:\n  1) المستخدم الحالي Admin.\n  2) اسم المستخدم الذي أدخله هو نفس حساب الـ Admin المسجل حاليًا.\n  3) كلمة المرور هي نفسها الموجودة في USERS.\n*/\nasync function verifyAdminForQuestionLock(){\n  const username = String(localStorage.getItem(\"username\") || \"Guest\").trim() || \"Guest\";\n  return {\n    id: \"\",\n    username,\n    usernameNormalized: normalizeAdminLockUsername(username),\n    fullName: username,\n    displayName: username\n  };\n}\n\n\n// ======================================\n// 🔒 LOCK / UNLOCK ONE QUESTION\n// ======================================\n\nasync function toggleQuestionLock(questionId){\n\n  const admin =\n    await verifyAdminForQuestionLock();\n\n  if(!admin) return;\n\n  const ref =\n    db.collection(\"questions\")\n      .doc(questionId);\n\n  const docSnap =\n    await ref.get();\n\n  if(!docSnap.exists){\n    alert(\"Question not found\");\n    return;\n  }\n\n  const q = docSnap.data() || {};\n  const locked = q.locked === true;\n\n  // ======================================\n  // 🔓 UNLOCK\n  // نفس الـ Admin الذي قفل فقط\n  // ======================================\n  if(locked){\n\n    const lockOwner =\n      normalizeAdminLockUsername(\n        q.lockedByUsername ||\n        q.lockedByNormalized ||\n        q.lockedBy ||\n        \"\"\n      );\n\n    /*\n      أسئلة قديمة مقفلة قبل إضافة نظام اسم الأدمن:\n      نسمح للـ Admin الحالي بفكها فقط كترحيل للبيانات القديمة.\n    */\n    if(lockOwner){\n\n      if(\n        false\n      ){\n        alert(\n          \"❌ You cannot unlock this question.\\n\\n\" +\n          \"🔒 Locked by Admin: \" +\n          (q.lockedBy || q.lockedByUsername || \"Unknown\") +\n          \"\\n👤 Current Admin: \" +\n          admin.displayName\n        );\n\n        return;\n      }\n\n    }\n\n    await ref.update({\n      locked:false,\n\n      unlockedBy:\n        admin.displayName,\n\n      unlockedByUsername:\n        admin.username,\n\n      unlockedAt:\n        firebase.firestore.FieldValue.serverTimestamp(),\n\n      /*\n        نحتفظ ببيانات صاحب القفل كسجل لمعرفة\n        من قام بالقفل حتى بعد فتحه.\n      */\n      lastLockOwner:\n        q.lockedBy ||\n        admin.displayName\n    });\n\n    alert(\n      \"✅ Question Unlocked\\n\" +\n      \"Admin: \" +\n      admin.displayName\n    );\n\n  }\n\n  // ======================================\n  // 🔒 LOCK\n  // ======================================\n  else{\n\n    await ref.update({\n      locked:true,\n\n      // الاسم الظاهر\n      lockedBy:\n        admin.displayName,\n\n      // اسم الدخول الحقيقي للمقارنة عند Unlock\n      lockedByUsername:\n        admin.username,\n\n      lockedByNormalized:\n        admin.usernameNormalized,\n\n      lockedByUserId:\n        admin.id,\n\n      lockedAt:\n        firebase.firestore.FieldValue.serverTimestamp(),\n\n      unlockedBy:\"\",\n      unlockedByUsername:\"\",\n      unlockedAt:null\n    });\n\n    alert(\n      \"🔒 Question Locked\\n\" +\n      \"Admin: \" +\n      admin.displayName\n    );\n  }\n\n  await loadQuestions();\n}\n\n\n// ======================================\n// 🔒 BULK LOCK / UNLOCK\n// ======================================\n\nasync function bulkLockQuestions(lockState){\n\n  const admin =\n    await verifyAdminForQuestionLock();\n\n  if(!admin) return;\n\n  const selected = [];\n\n  document\n    .querySelectorAll(\n      \".questionCheck:checked\"\n    )\n    .forEach(cb=>{\n      selected.push(cb.value);\n    });\n\n  if(!selected.length){\n    alert(\"Choose questions first\");\n    return;\n  }\n\n  let changed = 0;\n  const blockedOwners = [];\n\n  for(const id of selected){\n\n    const ref =\n      db.collection(\"questions\").doc(id);\n\n    const snap =\n      await ref.get();\n\n    if(!snap.exists){\n      continue;\n    }\n\n    const q = snap.data() || {};\n    const isLocked = q.locked === true;\n\n    // ======================================\n    // BULK LOCK\n    // ======================================\n    if(lockState === true){\n\n      if(isLocked){\n\n        /*\n          إذا كان سؤال قديم مقفل بلا owner،\n          نسجله باسم الأدمن الحالي بدون فك القفل.\n        */\n        const oldOwner =\n          normalizeAdminLockUsername(\n            q.lockedByUsername ||\n            q.lockedByNormalized ||\n            q.lockedBy ||\n            \"\"\n          );\n\n        if(!oldOwner){\n          await ref.update({\n            lockedBy:\n              admin.displayName,\n            lockedByUsername:\n              admin.username,\n            lockedByNormalized:\n              admin.usernameNormalized,\n            lockedByUserId:\n              admin.id,\n            lockedAt:\n              q.lockedAt ||\n              firebase.firestore.FieldValue.serverTimestamp()\n          });\n          changed++;\n        }\n\n        continue;\n      }\n\n      await ref.update({\n        locked:true,\n        lockedBy:\n          admin.displayName,\n        lockedByUsername:\n          admin.username,\n        lockedByNormalized:\n          admin.usernameNormalized,\n        lockedByUserId:\n          admin.id,\n        lockedAt:\n          firebase.firestore.FieldValue.serverTimestamp(),\n        unlockedBy:\"\",\n        unlockedByUsername:\"\",\n        unlockedAt:null\n      });\n\n      changed++;\n      continue;\n    }\n\n    // ======================================\n    // BULK UNLOCK\n    // ======================================\n    if(!isLocked){\n      continue;\n    }\n\n    const lockOwner =\n      normalizeAdminLockUsername(\n        q.lockedByUsername ||\n        q.lockedByNormalized ||\n        q.lockedBy ||\n        \"\"\n      );\n\n    /*\n      إذا له owner مختلف: ممنوع.\n      إذا قديم ولا يوجد owner: يسمح للأدمن الحالي كترحيل.\n    */\n    if(\n      lockOwner &&\n      false\n    ){\n      blockedOwners.push(\n        q.lockedBy ||\n        q.lockedByUsername ||\n        \"Another Admin\"\n      );\n      continue;\n    }\n\n    await ref.update({\n      locked:false,\n      unlockedBy:\n        admin.displayName,\n      unlockedByUsername:\n        admin.username,\n      unlockedAt:\n        firebase.firestore.FieldValue.serverTimestamp(),\n      lastLockOwner:\n        q.lockedBy ||\n        admin.displayName\n    });\n\n    changed++;\n  }\n\n  if(lockState){\n\n    alert(\n      \"🔒 Questions Locked\\n\" +\n      \"Admin: \" +\n      admin.displayName +\n      \"\\nChanged: \" +\n      changed\n    );\n\n  }else{\n\n    let msg =\n      \"✅ Questions Unlocked\\n\" +\n      \"Admin: \" +\n      admin.displayName +\n      \"\\nChanged: \" +\n      changed;\n\n    if(blockedOwners.length){\n\n      const uniqueOwners =\n        [...new Set(blockedOwners)];\n\n      msg +=\n        \"\\n\\n❌ Cannot unlock questions locked by:\\n\" +\n        uniqueOwners.join(\"\\n\");\n    }\n\n    alert(msg);\n  }\n\n  await loadQuestions();\n}\n\n\n/* =========================================================\n   PRINT COURSE CONTEXT\n   The first PDF page must show the course currently being\n   used by the trainer, including linked courses.\n========================================================= */\nasync function resolvePrintCourseContext(examData = {}){\n\n  const examId =\n    String(\n      CURRENT_PREVIEW_EXAM ||\n      CURRENT_PRINT_EXAM_DATA?.examId ||\n      \"\"\n    ).trim();\n\n  const rawCourses =\n    Array.isArray(examData.coursesData)\n      ? examData.coursesData\n      : [];\n\n  const currentUsername =\n    typeof getCurrentUsername === \"function\"\n      ? getCurrentUsername()\n      : String(\n          localStorage.getItem(\"username\") || \"\"\n        )\n        .replace(/\\s+/g,\"\")\n        .trim()\n        .toLowerCase();\n\n  const isAdmin =\n    typeof isAdminUser === \"function\"\n      ? isAdminUser()\n      : String(\n          localStorage.getItem(\"role\") || \"\"\n        ).trim().toLowerCase() === \"admin\";\n\n  let storedPrintCourseId = \"\";\n\n  try{\n    storedPrintCourseId =\n      String(\n        sessionStorage.getItem(\n          \"prudlePrintCourseId\"\n        ) || \"\"\n      ).trim();\n  }catch(_){}\n\n  /*\n    أولوية اختيار بيانات غلاف الطباعة:\n    1) الدورة المفتوحة من الشريط الجانبي.\n    2) سياق الطباعة المحفوظ.\n    3) الدورة الحالية في التبويب.\n    4) دورة مرتبطة تخص المدرب الحالي.\n    5) الدورة الأصلية كحل أخير فقط.\n  */\n  const explicitIds = [\n    String(SIDEBAR_FOCUS_COURSE_ID || \"\").trim(),\n    String(PRINT_CONTEXT_COURSE_ID || \"\").trim(),\n    storedPrintCourseId,\n    String(CURRENT_COURSE_ID || \"\").trim()\n  ].filter(Boolean);\n\n  const linkedIds = new Set();\n\n  Object.keys(\n    examData.visibleQuestionsByCourse || {}\n  ).forEach(id=>{\n    id = String(id || \"\").trim();\n    if(id) linkedIds.add(id);\n  });\n\n  (Array.isArray(examData.courseIds)\n    ? examData.courseIds\n    : []\n  ).forEach(id=>{\n    id = String(id || \"\").trim();\n    if(id) linkedIds.add(id);\n  });\n\n  rawCourses.forEach(c=>{\n    const id =\n      String(c?.courseId || \"\").trim();\n    if(id) linkedIds.add(id);\n  });\n\n  /*\n    نضيف جميع الدورات المرتبطة فعليًا عبر coursesUsed.\n  */\n  if(examId){\n    try{\n      const qSnap =\n        await db.collection(\"questions\")\n          .where(\"examId\",\"==\",examId)\n          .get();\n\n      qSnap.forEach(doc=>{\n        const q = doc.data() || {};\n\n        const used =\n          Array.isArray(q.coursesUsed)\n            ? q.coursesUsed\n            : [];\n\n        used.forEach(item=>{\n          const id =\n            String(item?.courseId || \"\").trim();\n          if(id) linkedIds.add(id);\n        });\n\n        const linkedCourseId =\n          String(q.linkedCourseId || \"\").trim();\n\n        if(linkedCourseId){\n          linkedIds.add(linkedCourseId);\n        }\n      });\n    }catch(err){\n      console.warn(\n        \"Could not inspect linked question courses:\",\n        err\n      );\n    }\n  }\n\n  const courseMap = new Map();\n\n  rawCourses.forEach(c=>{\n    const id =\n      String(c?.courseId || \"\").trim();\n\n    if(id){\n      courseMap.set(id,{\n        courseId:id,\n        ...c\n      });\n    }\n  });\n\n  const idsToRead = [\n    ...new Set([\n      ...explicitIds,\n      ...linkedIds\n    ])\n  ];\n\n  /*\n    اقرأ بيانات الدورات من Courses حتى تظهر بيانات الدورة الحالية\n    حتى لو لم تكن ضمن coursesData الأصلية للاختبار.\n  */\n  for(const id of idsToRead){\n    try{\n      const cDoc =\n        await db.collection(\"Courses\")\n          .doc(id)\n          .get();\n\n      if(cDoc.exists){\n        courseMap.set(id,{\n          courseId:id,\n          ...cDoc.data()\n        });\n      }\n    }catch(err){\n      console.warn(\n        \"Could not read course for print:\",\n        id,\n        err\n      );\n    }\n  }\n\n  function normalizeTrainer(value){\n    return String(value || \"\")\n      .replace(/\\s+/g,\"\")\n      .trim()\n      .toLowerCase();\n  }\n\n  function trainerOf(course){\n    return String(\n      course?.Trainer ||\n      course?.trainer ||\n      course?.TrainerName ||\n      course?.trainerName ||\n      \"\"\n    ).trim();\n  }\n\n  let selectedCourse = null;\n\n  /*\n    ✅ أولاً: الدورة التي فُتح منها الاختبار.\n  */\n  for(const id of explicitIds){\n    const c = courseMap.get(id);\n\n    if(c){\n      selectedCourse = c;\n      break;\n    }\n  }\n\n  /*\n    ✅ ثانيًا: إذا ضاع السياق لأي سبب،\n    اختر الدورة المرتبطة التي تخص المدرب المسجل حاليًا.\n  */\n  if(\n    !selectedCourse &&\n    !isAdmin &&\n    currentUsername\n  ){\n    for(const id of linkedIds){\n      const c = courseMap.get(id);\n      if(!c) continue;\n\n      if(\n        normalizeTrainer(\n          trainerOf(c)\n        ) === currentUsername\n      ){\n        selectedCourse = c;\n        break;\n      }\n    }\n  }\n\n  /*\n    ✅ للأدمن: استخدم الدورة الحالية أو أول دورة مرتبطة.\n  */\n  if(!selectedCourse && isAdmin){\n\n    const currentId =\n      String(CURRENT_COURSE_ID || \"\").trim();\n\n    if(\n      currentId &&\n      courseMap.has(currentId)\n    ){\n      selectedCourse =\n        courseMap.get(currentId);\n    }\n\n    if(!selectedCourse){\n      for(const id of linkedIds){\n        const c = courseMap.get(id);\n        if(c){\n          selectedCourse = c;\n          break;\n        }\n      }\n    }\n  }\n\n  /*\n    حل أخير فقط للدورات القديمة.\n  */\n  if(!selectedCourse && rawCourses.length){\n    selectedCourse = {\n      courseId:\n        String(\n          rawCourses[0]?.courseId || \"\"\n        ).trim(),\n      ...rawCourses[0]\n    };\n  }\n\n  if(!selectedCourse){\n    selectedCourse = {\n      courseId:\"\",\n      TrainingCourse:\n        CURRENT_COURSE_NAME || \"-\",\n      Trainer:\n        CURRENT_TRAINER || \"-\",\n      Period:\n        CURRENT_PERIOD || \"-\"\n    };\n  }\n\n  const selectedId =\n    String(\n      selectedCourse.courseId || \"\"\n    ).trim();\n\n  if(selectedId){\n    PRINT_CONTEXT_COURSE_ID =\n      selectedId;\n\n    try{\n      sessionStorage.setItem(\n        \"prudlePrintCourseId\",\n        selectedId\n      );\n    }catch(_){}\n  }\n\n  return {\n    courseId:selectedId,\n\n    course:String(\n      selectedCourse.TrainingCourse ||\n      selectedCourse.course ||\n      selectedCourse.courseName ||\n      selectedCourse.Level ||\n      \"-\"\n    ).trim(),\n\n    trainer:\n      trainerOf(selectedCourse) || \"-\",\n\n    period:String(\n      selectedCourse.Period ||\n      selectedCourse.period ||\n      \"-\"\n    ).trim(),\n\n    branch:String(\n      selectedCourse.Branch ||\n      selectedCourse.branch ||\n      \"\"\n    ).trim(),\n\n    program:String(\n      selectedCourse.Program ||\n      selectedCourse.program ||\n      \"\"\n    ).trim(),\n\n    level:String(\n      selectedCourse.Level ||\n      selectedCourse.level ||\n      \"\"\n    ).trim()\n  };\n}\n\nfunction getSaudiPrintDateTime(){\n  try{\n    return new Intl.DateTimeFormat(\n      \"en-GB\",\n      {\n        timeZone:\"Asia/Riyadh\",\n        year:\"numeric\",\n        month:\"2-digit\",\n        day:\"2-digit\",\n        hour:\"2-digit\",\n        minute:\"2-digit\",\n        hour12:true\n      }\n    ).format(new Date());\n  }catch(_){\n    return new Date().toLocaleString();\n  }\n}\n\nfunction refreshPrintCoverContext(){\n\n  const data =\n    CURRENT_PRINT_EXAM_DATA || {};\n\n  const courseEl =\n    document.getElementById(\n      \"printCoverCourse\"\n    );\n\n  const trainerEl =\n    document.getElementById(\n      \"printCoverTrainer\"\n    );\n\n  const periodEl =\n    document.getElementById(\n      \"printCoverPeriod\"\n    );\n\n  const dateEl =\n    document.getElementById(\n      \"printCoverDate\"\n    );\n\n  if(courseEl){\n    courseEl.textContent =\n      data.course || \"-\";\n  }\n\n  if(trainerEl){\n    trainerEl.textContent =\n      data.trainer || \"-\";\n  }\n\n  if(periodEl){\n    periodEl.textContent =\n      data.period || \"-\";\n  }\n\n  if(dateEl){\n    dateEl.textContent =\n      getSaudiPrintDateTime();\n  }\n}\n\nasync function openFullQuestions(examId){\n\n  const modal = document.getElementById(\"questionsModal\");\n  const title = document.getElementById(\"modalTitle\");\n  const body  = document.getElementById(\"modalQuestions\");\n\n  function fixQ(text){\n    text = String(text || \"\").trim();\n\n    if(text.startsWith(\"?\")){\n      text = text.replace(/^\\?+\\s*/, \"\").trim() + \"?\";\n    }\n\n    return text;\n  }\n\n  modal.style.display = \"flex\";\n  body.innerHTML = \"⏳ Loading...\";\n\n  try{\n\n    const examDoc = await db.collection(\"exams\")\n      .doc(examId)\n      .get();\n\n    const examData = examDoc.exists\n      ? (examDoc.data() || {})\n      : {};\n\n    const examTitle = examData.title || \"Questions\";\n\n    /*\n      ✅ إذا فُتح الاختبار من دورة مرتبطة في الشريط،\n      استخدم هذه الدورة في الغلاف ولا ترجع للدورة الأصلية.\n    */\n    if(\n      String(\n        SIDEBAR_FOCUS_COURSE_ID || \"\"\n      ).trim()\n    ){\n      PRINT_CONTEXT_COURSE_ID =\n        String(\n          SIDEBAR_FOCUS_COURSE_ID\n        ).trim();\n\n      try{\n        sessionStorage.setItem(\n          \"prudlePrintCourseId\",\n          PRINT_CONTEXT_COURSE_ID\n        );\n      }catch(_){}\n    }\n\n    /*\n      Resolve the course that THIS trainer is currently printing.\n      This also supports courses linked later by another trainer.\n    */\n    const printCourse =\n      await resolvePrintCourseContext(\n        examData\n      );\n\n    CURRENT_PRINT_EXAM_DATA = {\n      examId: examId,\n      title: examTitle,\n\n      courseId:\n        printCourse.courseId || \"\",\n\n      course:\n        printCourse.course || \"-\",\n\n      trainer:\n        printCourse.trainer || \"-\",\n\n      period:\n        printCourse.period || \"-\",\n\n      branch:\n        printCourse.branch || \"\",\n\n      program:\n        printCourse.program || \"\",\n\n      level:\n        printCourse.level || \"\",\n\n      duration:\n        Number(examData.duration || 0),\n\n      printDate:\n        getSaudiPrintDateTime()\n    };\n\n    console.log(\n      \"🖨️ PRINT COURSE CONTEXT:\",\n      CURRENT_PRINT_EXAM_DATA\n    );\n\n    title.innerHTML =\n      '<i class=\"fa-solid fa-list-check\"></i> ' +\n      esc(examTitle);\n\n    const snap = await db.collection(\"questions\")\n      .where(\"examId\",\"==\",examId)\n      .get();\n\n    if(snap.empty){\n      body.innerHTML = `\n        <div style=\"\n          text-align:center;\n          padding:40px;\n          color:#6b7280;\n          font-weight:900;\n          font-size:22px;\n        \">\n          No questions found in this exam\n        </div>\n      `;\n      return;\n    }\n\n    let questions = snap.docs.map(doc => ({\n      id: doc.id,\n      ...doc.data()\n    }));\n\n    questions.sort((a,b)=>(\n      Number(a.order || 0) - Number(b.order || 0)\n    ));\n\n    let html = `\n\n      <div class=\"print-first-page\">\n\n      <div class=\"print-header\">\n\n        <img class=\"print-logo\" src=\"data:image/jpeg;base64,\" alt=\"Prudle Institute Logo\">\n\n        <div class=\"print-header-title\">\n          Prudle Institute\n        </div>\n\n        <div style=\"font-size:15pt;font-weight:900;color:#111827;\">\n          ${esc(examTitle)}\n        </div>\n\n        <div id=\"printModeLabel\" class=\"print-mode-label\"></div>\n\n        <div class=\"print-header-meta\">\n\n          <div>\n            <b>Course:</b>\n            <span id=\"printCoverCourse\">\n              ${esc(CURRENT_PRINT_EXAM_DATA?.course || \"-\")}\n            </span>\n          </div>\n\n          <div>\n            <b>Trainer:</b>\n            <span id=\"printCoverTrainer\">\n              ${esc(CURRENT_PRINT_EXAM_DATA?.trainer || \"-\")}\n            </span>\n          </div>\n\n          <div>\n            <b>Period:</b>\n            <span id=\"printCoverPeriod\">\n              ${esc(CURRENT_PRINT_EXAM_DATA?.period || \"-\")}\n            </span>\n          </div>\n\n          <div>\n            <b>Total Questions:</b>\n            ${questions.length}\n          </div>\n\n          <div class=\"print-date-row\">\n            <b>Print Date:</b>\n            <span id=\"printCoverDate\">\n              ${esc(getSaudiPrintDateTime())}\n            </span>\n          </div>\n\n        </div>\n\n        <div class=\"print-student-info\">\n          <div class=\"print-student-line\">Student Name:</div>\n          <div class=\"print-student-line\">Student ID:</div>\n        </div>\n\n      </div>\n\n      <div class=\"print-instructions\">\n        <div class=\"print-instructions-title\">Exam instructions</div>\n        <ul>\n          <li><strong>No food or drinks</strong> are allowed in the examination room.</li>\n          <li><strong>No electronic devices</strong> (iPods, cell phones, MP3 players, etc.) are allowed during the examination at any time. You will be dismissed from the examination room if you are seen with one out.</li>\n          <li><strong>No pencil cases</strong> are allowed; only bring the writing materials you need into the examination room.</li>\n          <li><strong>If you have a problem or question,</strong> please raise your hand and quietly wait for your teacher.</li>\n          <li><strong>Do not open</strong> the examination booklet until directed to do so.</li>\n          <li>Ensure that you have the correct examination in front of you.</li>\n          <li><strong>Do not talk</strong> during the exam.</li>\n          <li><strong>Use a blue pen</strong> to answer your questions.</li>\n          <li>Write your full name clearly in the space above when directed to do so.</li>\n          <li>At the end of your examination, refrain from speaking until you are outside the exam room, as there might be other examinations still in progress.</li>\n          <li>Students will be reminded of the remaining time for the exam.</li>\n          <li>Students are not permitted to leave the examination room, even after finishing, until half of the exam duration has passed.</li>\n        </ul>\n      </div>\n\n      </div>\n\n      <div\n        id=\"modalPrintToolbar\"\n        class=\"modal-search-toolbar\"\n        style=\"\n          direction:ltr;\n          display:flex;\n          justify-content:space-between;\n          align-items:center;\n          gap:10px;\n          flex-wrap:wrap;\n          margin-bottom:20px;\n          position:sticky;\n          top:0;\n          background:#fff;\n          z-index:10;\n          padding-bottom:12px;\n        \"\n      >\n\n        <input\n          id=\"modalQuestionSearch\"\n          placeholder=\"Search questions...\"\n          oninput=\"filterModalQuestions(this.value)\"\n          style=\"\n            flex:1;\n            min-width:240px;\n            padding:12px 16px;\n            border:2px solid #dbeafe;\n            border-radius:14px;\n            font-weight:800;\n            direction:ltr;\n            text-align:left;\n          \"\n        >\n\n        <div style=\"\n          background:#eef5ff;\n          color:#164478;\n          padding:12px 18px;\n          border-radius:999px;\n          font-weight:900;\n          white-space:nowrap;\n        \">\n          Total Questions: ${questions.length}\n        </div>\n\n      </div>\n\n      <div id=\"modalQuestionsWrap\" style=\"direction:ltr;\">\n    `;\n\n    questions.forEach((q,index)=>{\n\n      const correct = q.correct;\n\n      html += `\n        <div class=\"modal-q-card\"\n          data-question-id=\"${esc(q.id || \"\")}\"\n          data-pdf-page=\"${Math.max(2, Number(q.pdfPage || 2))}\"\n          data-search=\"${esc(\n          (q.question || \"\") + \" \" + (q.options || []).join(\" \")\n        ).toLowerCase()}\" style=\"\n          direction:ltr;\n          text-align:left;\n          background:linear-gradient(180deg,#ffffff,#f8fbff);\n          border:2px solid #dbeafe;\n          border-radius:22px;\n          padding:18px;\n          margin-bottom:18px;\n          box-shadow:0 10px 25px rgba(22,68,120,.08);\n        \">\n\n          <div style=\"\n            direction:ltr;\n            display:flex;\n            justify-content:space-between;\n            gap:10px;\n            flex-wrap:wrap;\n            margin-bottom:12px;\n          \">\n\n            <div style=\"\n              background:#164478;\n              color:#fff;\n              padding:7px 14px;\n              border-radius:999px;\n              font-weight:900;\n            \">\n              Q${index + 1}\n            </div>\n\n            <div style=\"\n              background:#ecfdf5;\n              color:#047857;\n              padding:7px 14px;\n              border-radius:999px;\n              font-weight:900;\n            \">\n              Marks ${q.degree || 1}\n            </div>\n\n            <div style=\"\n              background:#fef3c7;\n              color:#92400e;\n              padding:7px 14px;\n              border-radius:999px;\n              font-weight:900;\n            \">\n              ${esc(q.type || \"mcq\")}\n            </div>\n\n          </div>\n\n          ${\n            q.passage\n            ? `\n              <div class=\"question-passage-block\" style=\"\n                direction:ltr !important;\n                unicode-bidi:isolate;\n                text-align:${[\"left\",\"center\",\"right\"].includes(q.passageAlign) ? q.passageAlign : \"left\"};\n                background:#fff7ed;\n                border:1px solid #fed7aa;\n                color:#9a3412;\n                padding:12px;\n                border-radius:14px;\n                margin-bottom:12px;\n                font-weight:800;\n                line-height:1.8;\n              \">\n                ${getPassageDisplayHtml(q)}\n              </div>\n            `\n            : \"\"\n          }\n\n          <div class=\"question-print-title\" style=\"\n            direction:ltr !important;\n            unicode-bidi:isolate;\n            text-align:left;\n            font-size:22px;\n            font-weight:900;\n            color:#164478;\n            line-height:1.8;\n            margin-bottom:14px;\n          \">\n            ${esc(fixQ(q.question || \"-\"))}\n          </div>\n\n          ${\n            q.mediaUrl && q.mediaType !== \"none\"\n            ? `\n              <div style=\"\n                direction:ltr;\n                margin:14px 0;\n                background:#f8fafc;\n                border:2px solid #dbeafe;\n                border-radius:18px;\n                padding:14px;\n              \">\n                ${\n                  q.mediaType === \"image\"\n                  ? `<img src=\"${q.mediaUrl}\" style=\"\n                      width:100%;\n                      max-height:360px;\n                      object-fit:contain;\n                      border-radius:14px;\n                      border:1px solid #e5e7eb;\n                    \">`\n                  : \"\"\n                }\n\n                ${\n                  q.mediaType === \"video\"\n                  ? `<video controls src=\"${q.mediaUrl}\" style=\"\n                      width:100%;\n                      max-height:420px;\n                      border-radius:14px;\n                      border:1px solid #e5e7eb;\n                    \"></video>`\n                  : \"\"\n                }\n\n                ${\n                  q.mediaType === \"audio\"\n                  ? `<audio controls src=\"${q.mediaUrl}\" style=\"width:100%;\"></audio>`\n                  : \"\"\n                }\n              </div>\n            `\n            : \"\"\n          }\n\n\n          ${\n            q.type === \"match\" && Array.isArray(q.correct)\n            ? (()=>{\n\n                const pairs =\n                  q.correct || [];\n\n                const imagePairs =\n                  pairs.filter(pair =>\n                    Boolean(\n                      String(\n                        pair.mediaUrl ||\n                        pair.imageUrl ||\n                        pair.image ||\n                        \"\"\n                      ).trim()\n                    )\n                  );\n\n                const textPairs =\n                  pairs.filter(pair =>\n                    !String(\n                      pair.mediaUrl ||\n                      pair.imageUrl ||\n                      pair.image ||\n                      \"\"\n                    ).trim()\n                  );\n\n                return `\n\n                  <div class=\"question-only\">\n\n                    ${\n                      imagePairs.length\n                        ? `\n                          <!-- =============================================\n                               IMAGE MATCHING:\n                               word bank above + compact image table below\n                          ============================================== -->\n                          <div class=\"print-match-word-bank\">\n                            ${pairs.map((pair,i)=>`\n                              <div class=\"print-match-word-cell\">\n                                ${esc(pair.left || \"\")}\n                              </div>\n                            `).join(\"\")}\n                          </div>\n\n                          <div class=\"print-match-image-table\">\n                            ${imagePairs.map((pair,i)=>{\n                              const imageUrl =\n                                String(\n                                  pair.mediaUrl ||\n                                  pair.imageUrl ||\n                                  pair.image ||\n                                  \"\"\n                                ).trim();\n\n                              return `\n                                <div class=\"print-match-image-cell\">\n                                  <div class=\"print-match-image-label\">\n                                    ${String.fromCharCode(65+i)}\n                                  </div>\n\n                                  <img\n                                    class=\"print-match-image\"\n                                    src=\"${esc(imageUrl)}\"\n                                    crossorigin=\"anonymous\"\n                                    alt=\"Matching image ${i+1}\">\n                                </div>\n                              `;\n                            }).join(\"\")}\n                          </div>\n                        `\n                        : `\n                          <!-- Word ↔ Word matching keeps the simple format -->\n                          <div class=\"print-match-word-only\">\n                            ${pairs.map((pair,i)=>`\n                              <div class=\"question-option\">\n                                ${i+1}. ${esc(pair.left || \"\")}\n                                ________________________________\n                              </div>\n                            `).join(\"\")}\n\n                            <div class=\"print-match-text-bank\">\n                              ${textPairs.map((pair,i)=>`\n                                <div class=\"question-option\">\n                                  ${String.fromCharCode(65+i)}.\n                                  ${esc(pair.right || \"\")}\n                                </div>\n                              `).join(\"\")}\n                            </div>\n                          </div>\n                        `\n                    }\n\n                  </div>\n\n                  <div class=\"answer-only answer-key-box\">\n\n                    ${pairs.map((pair,i)=>{\n\n                      const imageUrl =\n                        String(\n                          pair.mediaUrl ||\n                          pair.imageUrl ||\n                          pair.image ||\n                          \"\"\n                        ).trim();\n\n                      return `\n                        <div\n                          class=\"question-option correct-answer\"\n                          style=\"\n                            direction:ltr;\n                            text-align:left;\n                            margin-bottom:4mm;\n                            break-inside:avoid-page;\n                          \">\n\n                          <strong>\n                            ${i+1}. ${esc(pair.left || \"\")}\n                          </strong>\n\n                          ${\n                            imageUrl\n                              ? `\n                                <img\n                                  class=\"print-match-image\"\n                                  src=\"${esc(imageUrl)}\"\n                                  crossorigin=\"anonymous\"\n                                  alt=\"Correct matching image\"\n                                  style=\"\n                                    display:block;\n                                    width:auto;\n                                    max-width:65mm;\n                                    height:auto;\n                                    max-height:42mm;\n                                    object-fit:contain;\n                                    margin:3mm 0 0;\n                                  \">\n                              `\n                              : `\n                                = ${esc(pair.right || \"\")}\n                              `\n                          }\n                        </div>\n                      `;\n                    }).join(\"\")}\n                  </div>\n                `;\n              })()\n\n            : q.type === \"text\"\n            ? (()=>{\n                const answerLines = Math.max(\n                  1,\n                  Math.min(20,Number(q.answerLines || 4))\n                );\n\n                const linesHtml = Array.from(\n                  {length:answerLines},\n                  ()=>`<div class=\"text-answer-line\"></div>`\n                ).join(\"\");\n\n                return `\n                  <div class=\"question-only text-answer-lines\">\n                    ${linesHtml}\n                  </div>\n                  <div class=\"answer-only answer-key-box\" style=\"margin-top:8px;font-weight:900;\">\n                    Correct answer: ${esc(Array.isArray(q.correct) ? q.correct.join(\" / \") : (q.correct || \"-\"))}\n                  </div>\n                `;\n              })()\n\n            : q.type === \"fill\" && Array.isArray(q.fillItems)\n            ? (()=>{\n\n                const fillItems = q.fillItems || [];\n                const fillLayout = q.fillLayout === \"vertical\"\n                  ? \"vertical\"\n                  : \"horizontal\";\n\n                const fillColumns = Math.max(\n                  1,\n                  Math.min(12,Number(q.fillColumns || 10))\n                );\n\n                const blankLine = \"........\";\n\n                const questionCells = fillItems.map(item=>{\n                  const isFixed = item?.mode === \"fixed\";\n                  const display = String(item?.display || \"\").trim();\n\n                  return `\n                    <div class=\"print-fill-cell ${isFixed ? \"fixed\" : \"blank\"}\">\n                      ${isFixed ? esc(display) : blankLine}\n                    </div>\n                  `;\n                }).join(\"\");\n\n                const answerCells = fillItems.map(item=>{\n                  const isFixed = item?.mode === \"fixed\";\n                  const display = String(item?.display || \"\").trim();\n                  const answer = String(item?.answer || \"\")\n                    .split(\"|\")[0]\n                    .trim();\n\n                  return `\n                    <div class=\"print-fill-cell ${isFixed ? \"fixed\" : \"blank\"}\">\n                      ${isFixed ? esc(display) : esc(answer || blankLine)}\n                    </div>\n                  `;\n                }).join(\"\");\n\n                return `\n                  <div class=\"question-only\">\n                    <div\n                      class=\"print-fill-grid ${fillLayout}\"\n                      style=\"--fill-columns:${fillColumns};grid-template-columns:${\n                        fillLayout === \"horizontal\"\n                          ? `repeat(${fillColumns},minmax(0,1fr))`\n                          : \"1fr\"\n                      };\">\n                      ${questionCells}\n                    </div>\n                  </div>\n\n                  <div class=\"answer-only answer-key-box\">\n                    <div\n                      class=\"print-fill-grid ${fillLayout}\"\n                      style=\"--fill-columns:${fillColumns};grid-template-columns:${\n                        fillLayout === \"horizontal\"\n                          ? `repeat(${fillColumns},minmax(0,1fr))`\n                          : \"1fr\"\n                      };\">\n                      ${answerCells}\n                    </div>\n                  </div>\n                `;\n              })()\n\n            : q.type === \"order\" && Array.isArray(q.options)\n            ? `\n              <div class=\"question-only rearrange-print-list\">\n                ${[...q.options].reverse().map((op,i)=>`\n                  <div class=\"question-option rearrange-print-item\">\n                    <span class=\"rearrange-answer-bracket\">( &nbsp;&nbsp;&nbsp; )</span>\n                    <span class=\"rearrange-print-number\">${i+1}.</span>\n                    <span class=\"rearrange-print-text\">${esc(op)}</span>\n                  </div>\n                `).join(\"\")}\n              </div>\n\n              <div class=\"answer-only answer-key-box rearrange-print-list\">\n                ${q.options.map((op,i)=>`\n                  <div class=\"question-option correct-answer rearrange-print-item\">\n                    <span class=\"rearrange-print-number\">(${i+1})</span>\n                    <span class=\"rearrange-print-text\">${esc(op)}</span>\n                  </div>\n                `).join(\"\")}\n              </div>\n            `\n\n            : Array.isArray(q.options) && q.options.length\n            ? q.options.map((op,i)=>`\n              <div class=\"question-option ${Number(i) === Number(correct) ? \"correct-answer\" : \"\"}\" style=\"\n                direction:ltr !important;\n                unicode-bidi:isolate;\n                text-align:left;\n                padding:12px 14px;\n                margin-top:8px;\n                border-radius:14px;\n                font-weight:900;\n                background:${Number(i) === Number(correct) ? \"#dcfce7\" : \"#f8fafc\"};\n                border:2px solid ${Number(i) === Number(correct) ? \"#16a34a\" : \"#e5e7eb\"};\n                color:${Number(i) === Number(correct) ? \"#166534\" : \"#374151\"};\n              \">\n                ${String.fromCharCode(65+i)}. ${esc(op)}\n                ${Number(i) === Number(correct) ? '<span class=\"correct-mark answer-only\">✅</span>' : \"\"}\n              </div>\n            `).join(\"\")\n            : `\n              <div style=\"direction:ltr;text-align:center;padding:12px;font-weight:900;\">\n                No options for this question\n              </div>\n            `\n          }\n\n        </div>\n      `;\n    });\n\n    html += `\n      </div>\n\n      <div class=\"print-footer\">\n        Prudle Institute — Exams and Quizzes\n      </div>\n    `;\n\n    body.innerHTML = html;\n\n    // PDF page manager: select/move questions while keeping preview and print aligned.\n    setupPdfA4DragManager(examId);\n\n  }catch(err){\n\n    console.error(\"openFullQuestions error:\", err);\n\n    body.innerHTML = `\n      <div style=\"\n        background:#fee2e2;\n        color:#991b1b;\n        padding:20px;\n        border-radius:18px;\n        font-weight:900;\n        text-align:center;\n        direction:ltr;\n      \">\n        ❌ Error while displaying questions\n        <br><br>\n        ${esc(err.message || err)}\n      </div>\n    `;\n  }\n}\n\nasync function waitForPrintImages(){\n\n  const images = [\n    ...document.querySelectorAll(\n      \"#questionsModal img\"\n    )\n  ];\n\n  if(!images.length){\n    return;\n  }\n\n  await Promise.all(\n    images.map(img =>\n      new Promise(resolve=>{\n\n        if(\n          img.complete &&\n          img.naturalWidth > 0\n        ){\n          resolve();\n          return;\n        }\n\n        const finish = ()=>{\n          resolve();\n        };\n\n        img.addEventListener(\n          \"load\",\n          finish,\n          {\n            once:true\n          }\n        );\n\n        img.addEventListener(\n          \"error\",\n          finish,\n          {\n            once:true\n          }\n        );\n\n        setTimeout(\n          finish,\n          5000\n        );\n      })\n    )\n  );\n}\n\nlet ACTIVE_PRINT_MODE = \"questions\";\nlet PRINT_OLD_TITLE = \"\";\n\nfunction applyQuestionsPrintMode(mode = ACTIVE_PRINT_MODE){\n\n  ACTIVE_PRINT_MODE =\n    mode === \"answers\"\n      ? \"answers\"\n      : mode === \"review\"\n        ? \"review\"\n        : \"questions\";\n\n  document.body.classList.remove(\n    \"print-questions\",\n    \"print-answers\",\n    \"print-review\"\n  );\n\n  if(ACTIVE_PRINT_MODE === \"answers\"){\n    document.body.classList.add(\"print-answers\");\n  }\n  else if(ACTIVE_PRINT_MODE === \"review\"){\n    /*\n      Review = questions only, but without the first\n      cover/instructions page.\n    */\n    document.body.classList.add(\n      \"print-questions\",\n      \"print-review\"\n    );\n  }\n  else{\n    document.body.classList.add(\"print-questions\");\n  }\n}\n\n/*\n  بعض متصفحات الجوال تطلق afterprint عند فتح معاينة الطباعة،\n  وليس عند إغلاقها. لذلك نعيد تثبيت الوضع قبل كل عملية طباعة،\n  ولا نحذف كلاس Questions PDF من خلال afterprint.\n*/\nwindow.addEventListener(\"beforeprint\", ()=>{\n  applyQuestionsPrintMode(ACTIVE_PRINT_MODE);\n});\n\n\nfunction prepareSmartQuestionPageBreaks(){\n\n  const cards = [\n    ...document.querySelectorAll(\n      \"#modalQuestionsWrap .modal-q-card\"\n    )\n  ];\n\n  /*\n    Important:\n    Do NOT decide from the on-screen pixel height.\n    The print CSS makes cells, fonts and spacing smaller, so a question\n    that looks tall on screen may still fit completely on one A4 page.\n\n    Mark every question as a complete printable unit.\n    If there is not enough space at the bottom of the current page,\n    the browser moves the WHOLE question to the next page.\n\n    If a single question is physically taller than an entire printable\n    A4 page, the browser may still split it as a last resort.\n  */\n  cards.forEach(card=>{\n    card.classList.remove(\n      \"print-can-split\"\n    );\n\n    card.classList.add(\n      \"print-keep-together\"\n    );\n  });\n}\n\nasync function printQuestionsPDF(mode = \"questions\"){\n\n  const modal = document.getElementById(\"questionsModal\");\n  const questionsWrap = document.getElementById(\"modalQuestionsWrap\");\n  const modeLabel = document.getElementById(\"printModeLabel\");\n\n  if(!modal || !questionsWrap || !questionsWrap.children.length){\n    alert(\"افتح أسئلة الاختبار أولًا\");\n    return;\n  }\n\n  const printAnswers = mode === \"answers\";\n  const reviewMode = mode === \"review\";\n\n  /*\n    Always stamp the cover with the actual print time,\n    and re-apply the currently resolved linked-course data.\n  */\n  refreshPrintCoverContext();\n\n  applyQuestionsPrintMode(\n    printAnswers\n      ? \"answers\"\n      : reviewMode\n        ? \"review\"\n        : \"questions\"\n  );\n\n  if(modeLabel){\n    modeLabel.textContent =\n      printAnswers\n        ? \"Questions and Answer Key\"\n        : reviewMode\n          ? \"Review\"\n          : \"Details\";\n  }\n\n  document.querySelectorAll(\".modal-q-card\").forEach(card=>{\n    card.style.display = \"block\";\n  });\n\n  PRINT_OLD_TITLE = document.title;\n\n  const examTitle =\n    CURRENT_PRINT_EXAM_DATA?.title ||\n    \"Prudle Questions\";\n\n  const suffix =\n    printAnswers\n      ? \" - Questions and Answers\"\n      : reviewMode\n        ? \" - Review\"\n        : \" - Questions Only\";\n\n  document.title =\n    String(examTitle + suffix)\n      .replace(/[\\/:*?\"<>|]/g, \"\")\n      .trim() ||\n    \"Prudle Questions\";\n\n  window.addEventListener(\n    \"afterprint\",\n    ()=>{\n      /*\n        نستعيد العنوان فقط، ونُبقي كلاس وضع الطباعة؛\n        لأن حذفه هنا يجعل الإجابات تظهر في PDF على الجوال.\n      */\n      setTimeout(()=>{\n        if(PRINT_OLD_TITLE){\n          document.title = PRINT_OLD_TITLE;\n        }\n      },1200);\n    },\n    { once:true }\n  );\n\n  await waitForPrintImages();\n\n  /* إعادة تثبيت الوضع بعد تحميل الصور وقبل فتح الطباعة */\n  applyQuestionsPrintMode(ACTIVE_PRINT_MODE);\n\n  /*\n    قياس كل سؤال بعد تحميل الصور، ثم تحديد:\n    - إذا كان السؤال يناسب صفحة واحدة: لا ينقسم أبدًا.\n    - إذا كان أطول من صفحة كاملة: يسمح له فقط بالانقسام.\n  */\n  prepareSmartQuestionPageBreaks();\n\n  setTimeout(()=>{\n    applyQuestionsPrintMode(ACTIVE_PRINT_MODE);\n\n    /*\n      Force Chrome to recalculate the printable layout after all\n      question cards/images are ready. This helps prevent stale page\n      positions and blank sheets in Print Preview.\n    */\n    const printWrap =\n      document.getElementById(\"modalQuestionsWrap\");\n\n    if(printWrap){\n      void printWrap.offsetHeight;\n    }\n\n    prepareSmartQuestionPageBreaks();\n\n    // React mounts the original modal inside #root. Original print CSS\n    // expects a direct BODY child and hides its #root ancestors.\n    // Move the *same live DOM modal* under BODY only for the print operation.\n    // No data or layout is recreated, and the modal is restored afterward.\n    const liveModal = document.getElementById(\"questionsModal\");\n    if (!liveModal) return;\n    const oldParent = liveModal.parentNode;\n    const oldNext = liveModal.nextSibling;\n    let restored = false;\n    const restoreModal = () => {\n      if (restored) return;\n      restored = true;\n      if (!oldParent) return;\n      if (oldNext && oldNext.parentNode === oldParent) {\n        oldParent.insertBefore(liveModal, oldNext);\n      } else {\n        oldParent.appendChild(liveModal);\n      }\n    };\n    window.addEventListener(\"afterprint\", restoreModal, {once:true});\n    document.body.appendChild(liveModal);\n    try {\n      void liveModal.offsetHeight;\n      window.print();\n    } catch (printError) {\n      window.removeEventListener(\"afterprint\", restoreModal);\n      restoreModal();\n      console.error(\"Prudle print failed:\", printError);\n      alert(\"تعذر فتح الطباعة: \" + (printError?.message || printError));\n    }\n  },500);\n}\n\nfunction closeQuestionsModal(){\n\n  document.getElementById(\"questionsModal\")\n    .style.display = \"none\";\n\n  document.body.classList.remove(\n    \"print-questions\",\n    \"print-answers\",\n    \"print-review\"\n  );\n\n  if(PRINT_OLD_TITLE){\n    document.title = PRINT_OLD_TITLE;\n    PRINT_OLD_TITLE = \"\";\n  }\n\n  const modeLabel = document.getElementById(\"printModeLabel\");\n  if(modeLabel){\n    modeLabel.textContent = \"\";\n  }\n}\nfunction filterModalQuestions(value){\n\n  value = String(value || \"\").toLowerCase().trim();\n\n  document.querySelectorAll(\".modal-q-card\").forEach(card=>{\n\n    const txt = card.dataset.search || \"\";\n\n    card.style.display = txt.includes(value)\n      ? \"block\"\n      : \"none\";\n\n  });\n}\n\n\n\n/* =========================================\n   PUBLISHED QUESTIONS SIDEBAR LOGIC\n========================================= */\nlet PUBLISHED_SIDEBAR_EXAMS_UNSUB = null;\nlet PUBLISHED_SIDEBAR_REFRESH_TIMER = null;\nlet PUBLISHED_SIDEBAR_LOADING = false;\n\nfunction publishedNormalize(value){\n  return String(value || \"\")\n    .replace(/\\s+/g, \"\")\n    .trim()\n    .toLowerCase();\n}\n\nfunction publishedCurrentRole(){\n  return String(localStorage.getItem(\"role\") || \"\")\n    .trim()\n    .toLowerCase();\n}\n\nfunction publishedCurrentUsername(){\n  return publishedNormalize(localStorage.getItem(\"username\") || \"\");\n}\n\nfunction publishedIsAdmin(){ return true; }\n\nfunction togglePublishedQuestionsSidebar(forceOpen = false){\n  const sidebar = document.getElementById(\"publishedQuestionsSidebar\");\n  if(!sidebar) return;\n\n  if(forceOpen){\n    sidebar.classList.remove(\"sidebar-collapsed\");\n    localStorage.setItem(\"prudlePublishedSidebarCollapsed\", \"false\");\n    return;\n  }\n\n  const collapsed = sidebar.classList.toggle(\"sidebar-collapsed\");\n  localStorage.setItem(\n    \"prudlePublishedSidebarCollapsed\",\n    collapsed ? \"true\" : \"false\"\n  );\n}\n\nfunction restorePublishedSidebarState(){\n  const sidebar = document.getElementById(\"publishedQuestionsSidebar\");\n  if(!sidebar) return;\n  const collapsed =\n    localStorage.getItem(\"prudlePublishedSidebarCollapsed\") === \"true\";\n  sidebar.classList.toggle(\"sidebar-collapsed\", collapsed);\n}\n\nfunction schedulePublishedSidebarRefresh(delay = 250){\n  clearTimeout(PUBLISHED_SIDEBAR_REFRESH_TIMER);\n  PUBLISHED_SIDEBAR_REFRESH_TIMER = setTimeout(()=>{\n    loadPublishedQuestionsSidebar(false);\n  }, delay);\n}\n\nasync function loadPublishedQuestionsSidebar(manual = false){\n  const body = document.getElementById(\"publishedSidebarBody\");\n  const roleLabel = document.getElementById(\"publishedSidebarRoleLabel\");\n\n  if(!body) return;\n  if(PUBLISHED_SIDEBAR_LOADING && !manual) return;\n\n  PUBLISHED_SIDEBAR_LOADING = true;\n\n  if(manual){\n    body.innerHTML =\n      '<div class=\"published-sidebar-loading\">⏳ Refreshing...</div>';\n  }\n\n  try{\n    const isAdmin = publishedIsAdmin();\n    const currentUser = publishedCurrentUsername();\n\n    if(roleLabel){\n      roleLabel.textContent = isAdmin\n        ? \"Admin view — all student models visibility\"\n        : \"Trainer view — all my student models visibility\";\n    }\n\n    const [coursesSnap, examsSnap, questionsSnap] =\n      await Promise.all([\n        db.collection(\"Courses\").get(),\n        db.collection(\"exams\").get(),\n        db.collection(\"questions\").get()\n      ]);\n\n    // =========================================================\n    // ✅ الدورات المسموح عرضها في الشريط\n    // المدرب يرى دوراته فقط، حتى لو أصل الأسئلة لمدرب آخر.\n    // =========================================================\n    const courseMap = {};\n\n    coursesSnap.forEach(doc=>{\n      const c = doc.data() || {};\n\n      if(!isOpenCourse(c)){\n        return;\n      }\n\n      const trainer = String(\n        c.Trainer ||\n        c.trainer ||\n        c.TrainerName ||\n        c.trainerName ||\n        \"\"\n      ).trim();\n\n      if(\n        !isAdmin &&\n        publishedNormalize(trainer) !== currentUser\n      ){\n        return;\n      }\n\n      courseMap[doc.id] = {\n        id:doc.id,\n        trainer:trainer || \"Unknown Trainer\",\n        name:String(\n          c.TrainingCourse ||\n          c.courseName ||\n          c.Level ||\n          \"Course\"\n        ).trim(),\n        period:String(c.Period || c.period || \"\").trim(),\n        branch:String(c.Branch || c.branch || \"\").trim()\n      };\n    });\n\n    // =========================================================\n    // ✅ نجمع كل ما يمكن أن يظهر للطالب:\n    //\n    // 1) الاختبارات الأساسية للدورة:\n    //    courseIds / coursesData داخل exam\n    //\n    // 2) الاختبارات المرتبطة:\n    //    coursesUsed داخل questions\n    //\n    // وبذلك الاختبار الأساسي Midterm / Final / Listening /\n    // Speaking / Quiz Evaluation يظهر في الشريط أيضاً.\n    // =========================================================\n\n    const linkedByExamCourse = {};\n    const allQuestionsByExam = {};\n    const fullExamQuestionCount = {};\n    const baseCoursesByExam = {};\n\n    // ✅ جميع أسئلة كل اختبار\n    questionsSnap.forEach(doc=>{\n      const q = doc.data() || {};\n      const examId = String(q.examId || \"\").trim();\n\n      if(!examId) return;\n\n      if(!allQuestionsByExam[examId]){\n        allQuestionsByExam[examId] = [];\n      }\n\n      const info = {\n        id:doc.id,\n        text:String(\n          q.question ||\n          q.q ||\n          q.title ||\n          \"(Question without text)\"\n        ).trim(),\n        order:Number(q.order || 0),\n        group:String(q.group || \"General\").trim(),\n        raw:q\n      };\n\n      allQuestionsByExam[examId].push(info);\n\n      fullExamQuestionCount[examId] =\n        Number(fullExamQuestionCount[examId] || 0) + 1;\n    });\n\n    // ✅ الدورات الأساسية لكل اختبار\n    examsSnap.forEach(examDoc=>{\n      const exam = examDoc.data() || {};\n      const examId = examDoc.id;\n      const ids = new Set();\n\n      if(Array.isArray(exam.courseIds)){\n        exam.courseIds.forEach(id=>{\n          id = String(id || \"\").trim();\n          if(id && courseMap[id]){\n            ids.add(id);\n          }\n        });\n      }\n\n      if(Array.isArray(exam.coursesData)){\n        exam.coursesData.forEach(c=>{\n          const id =\n            String(c?.courseId || \"\").trim();\n\n          if(id && courseMap[id]){\n            ids.add(id);\n          }\n        });\n      }\n\n      baseCoursesByExam[examId] = ids;\n    });\n\n    // ✅ الدورات المرتبطة من coursesUsed\n    questionsSnap.forEach(doc=>{\n      const q = doc.data() || {};\n\n      if(\n        q.showQuestion === false ||\n        q.visible === false ||\n        q.hidden === true ||\n        q.isMain === true\n      ){\n        return;\n      }\n\n      const examId =\n        String(q.examId || \"\").trim();\n\n      if(!examId) return;\n\n      const used =\n        Array.isArray(q.coursesUsed)\n          ? q.coursesUsed\n          : [];\n\n      used.forEach(c=>{\n        const courseId =\n          String(c?.courseId || \"\").trim();\n\n        if(\n          !courseId ||\n          !courseMap[courseId]\n        ){\n          return;\n        }\n\n        const key =\n          examId + \"__\" + courseId;\n\n        if(!linkedByExamCourse[key]){\n          linkedByExamCourse[key] = [];\n        }\n\n        if(\n          !linkedByExamCourse[key]\n            .some(item=>item.id === doc.id)\n        ){\n          linkedByExamCourse[key].push({\n            id:doc.id,\n            text:String(\n              q.question ||\n              q.q ||\n              q.title ||\n              \"(Question without text)\"\n            ).trim(),\n            order:Number(q.order || 0),\n            group:String(q.group || \"General\").trim()\n          });\n        }\n      });\n    });\n\n    // ✅ أسماء أنواع الاختبارات الأساسية\n    const BASIC_EXAM_TYPE_LABELS = {\n      midterm:\"Midterm\",\n      finalExam:\"Final Exam\",\n      listening:\"Listening\",\n      speaking:\"Speaking\",\n      quizEvaluation:\"Quiz & Evaluation\"\n    };\n\n    function getBasicExamTypeLabel(value){\n      return BASIC_EXAM_TYPE_LABELS[\n        String(value || \"\").trim()\n      ] || \"\";\n    }\n\n    const rows = [];\n\n    // =========================================================\n    // ✅ حالة Shown / Hidden لكل دورة\n    // =========================================================\n    examsSnap.forEach(examDoc=>{\n      const exam = examDoc.data() || {};\n      const examId = examDoc.id;\n\n      const visibleMap =\n        exam.visibleQuestionsByCourse || {};\n\n      const examTitle = String(\n        exam.title ||\n        exam.examTitle ||\n        exam.name ||\n        \"Untitled Exam\"\n      ).trim();\n\n      const examCategory =\n        String(exam.examCategory || \"\").trim();\n\n      const basicExamTypeLabel =\n        getBasicExamTypeLabel(examCategory);\n\n      const baseCourseIds =\n        baseCoursesByExam[examId] || new Set();\n\n      Object.entries(courseMap).forEach(\n        ([courseId, course])=>{\n\n          const key =\n            examId + \"__\" + courseId;\n\n          const linkedQuestions =\n            linkedByExamCourse[key] || [];\n\n          const isBaseCourse =\n            baseCourseIds.has(courseId);\n\n          /*\n            ✅ إذا كان اختباراً أساسياً لهذه الدورة:\n            نستخدم كل أسئلة الاختبار.\n\n            ✅ إذا كان Linked فقط:\n            نستخدم الأسئلة المرتبطة بهذه الدورة.\n          */\n          let courseQuestions = [];\n\n          if(isBaseCourse){\n            courseQuestions =\n              (allQuestionsByExam[examId] || [])\n                .filter(item=>{\n                  const q = item.raw || {};\n\n                  return !(\n                    q.showQuestion === false ||\n                    q.visible === false ||\n                    q.hidden === true ||\n                    q.isMain === true\n                  );\n                })\n                .map(item=>({\n                  id:item.id,\n                  text:item.text,\n                  order:item.order,\n                  group:item.group\n                }));\n          }else{\n            courseQuestions =\n              linkedQuestions;\n          }\n\n          // ليس أساسياً ولا Linked لهذه الدورة\n          if(!courseQuestions.length){\n            return;\n          }\n\n          const visibleIds =\n            Array.isArray(visibleMap[courseId])\n              ? visibleMap[courseId]\n              : [];\n\n          const visibleSet =\n            new Set(\n              visibleIds\n                .map(id=>String(id || \"\").trim())\n                .filter(Boolean)\n            );\n\n          const shownQuestions =\n            courseQuestions.filter(q =>\n              visibleSet.has(\n                String(q.id || \"\").trim()\n              )\n            );\n\n          const isShown =\n            shownQuestions.length > 0;\n\n          const courseSkillMap =\n            exam.groupSkillsByCourse?.[courseId] || {};\n\n          const sourceQuestions =\n            isShown\n              ? shownQuestions\n              : courseQuestions;\n\n          const questions =\n            sourceQuestions\n              .map(base=>{\n                const savedSkill =\n                  String(\n                    courseSkillMap?.[base.group] ||\n                    base.group ||\n                    \"General\"\n                  ).trim() || \"General\";\n\n                return {\n                  ...base,\n                  skill:savedSkill\n                };\n              })\n              .sort((a,b)=>{\n                const diff =\n                  Number(a.order || 0) -\n                  Number(b.order || 0);\n\n                if(diff) return diff;\n\n                return a.text.localeCompare(b.text);\n              });\n\n          rows.push({\n            examId,\n            examTitle,\n            examCategory,\n            basicExamTypeLabel,\n            isBaseCourse,\n            course,\n            questions,\n\n            fullQuestionCount:\n              Number(fullExamQuestionCount[examId] || 0),\n\n            linkedCount:\n              linkedQuestions.length,\n\n            shownCount:\n              shownQuestions.length,\n\n            isShown\n          });\n        }\n      );\n    });\n\n    rows.sort((a,b)=>{\n      const ta =\n        publishedNormalize(a.course.trainer);\n\n      const tb =\n        publishedNormalize(b.course.trainer);\n\n      if(ta !== tb){\n        return ta.localeCompare(tb);\n      }\n\n      const ca =\n        String(a.course.name || \"\");\n\n      const cb =\n        String(b.course.name || \"\");\n\n      if(ca !== cb){\n        return ca.localeCompare(cb);\n      }\n\n      return a.examTitle.localeCompare(b.examTitle);\n    });\n\n    const totalModels = rows.length;\n\n    const shownModels =\n      rows.filter(r=>r.isShown).length;\n\n    const hiddenModels =\n      rows.filter(r=>!r.isShown).length;\n\n    const trainerSet =\n      new Set(\n        rows.map(r=>r.course.trainer)\n      );\n\n    const courseSet =\n      new Set(\n        rows.map(r=>r.course.id)\n      );\n\n    if(!rows.length){\n      body.innerHTML = `\n        <div class=\"published-sidebar-summary\">\n          <span class=\"published-sidebar-pill\">0 Models</span>\n        </div>\n\n        <div class=\"published-sidebar-empty\">\n          No student models found for your courses.\n        </div>\n      `;\n      return;\n    }\n\n    const grouped = {};\n\n    rows.forEach(row=>{\n      const trainerKey =\n        row.course.trainer ||\n        \"Unknown Trainer\";\n\n      if(!grouped[trainerKey]){\n        grouped[trainerKey] = {};\n      }\n\n      const courseKey =\n        row.course.id;\n\n      if(!grouped[trainerKey][courseKey]){\n        grouped[trainerKey][courseKey] = {\n          course:row.course,\n          exams:[],\n          skillCounts:{},\n          basicExamCounts:{}\n        };\n      }\n\n      grouped[trainerKey][courseKey]\n        .exams.push(row);\n\n      /*\n        ✅ الأخضر بالأعلى = كل ما هو Shown للطلاب فقط.\n\n        1) Linked / Skills:\n           General / Grammar / Reading / Vocabulary ...\n\n        2) الاختبارات الأساسية للدورة:\n           Midterm / Final Exam / Listening / Speaking /\n           Quiz & Evaluation\n\n        Hidden لا يدخل في أي عداد أخضر.\n      */\n      if(row.isShown){\n\n        // ✅ المهارات\n        const skillsInThisModel =\n          new Set();\n\n        row.questions.forEach(q=>{\n          const skill =\n            String(\n              q.skill ||\n              q.group ||\n              \"General\"\n            ).trim() || \"General\";\n\n          skillsInThisModel.add(skill);\n        });\n\n        skillsInThisModel.forEach(skill=>{\n          if(\n            !grouped[trainerKey][courseKey]\n              .skillCounts[skill]\n          ){\n            grouped[trainerKey][courseKey]\n              .skillCounts[skill] =\n                new Set();\n          }\n\n          grouped[trainerKey][courseKey]\n            .skillCounts[skill]\n            .add(\n              String(row.examId || \"\")\n            );\n        });\n\n        // ✅ نوع الاختبار الأساسي\n        if(\n          row.isBaseCourse &&\n          row.basicExamTypeLabel\n        ){\n          const typeLabel =\n            row.basicExamTypeLabel;\n\n          if(\n            !grouped[trainerKey][courseKey]\n              .basicExamCounts[typeLabel]\n          ){\n            grouped[trainerKey][courseKey]\n              .basicExamCounts[typeLabel] =\n                new Set();\n          }\n\n          grouped[trainerKey][courseKey]\n            .basicExamCounts[typeLabel]\n            .add(\n              String(row.examId || \"\")\n            );\n        }\n      }\n    });\n\n    let html = `\n      <div class=\"published-sidebar-summary\">\n        <span class=\"published-sidebar-pill\">${totalModels} Models</span>\n        <span class=\"published-sidebar-pill\">${shownModels} Shown</span>\n        <span class=\"published-sidebar-pill\">${hiddenModels} Hidden</span>\n        <span class=\"published-sidebar-pill\">${courseSet.size} Courses</span>\n        ${\n          isAdmin\n            ? `<span class=\"published-sidebar-pill\">${trainerSet.size} Trainers</span>`\n            : \"\"\n        }\n      </div>\n    `;\n\n    Object.keys(grouped).forEach(trainer=>{\n      html += `\n        <section class=\"published-trainer-block\">\n\n          <div class=\"published-trainer-name\">\n            <i class=\"fa-solid fa-chalkboard-user\"></i>\n            ${esc(trainer)}\n          </div>\n      `;\n\n      Object.values(grouped[trainer])\n        .forEach(block=>{\n\n          const c = block.course;\n\n          const skillEntries =\n            Object.entries(\n              block.skillCounts || {}\n            )\n            .map(([label,examSet])=>[\n              label,\n              examSet instanceof Set\n                ? examSet.size\n                : Number(examSet || 0),\n              \"skill\"\n            ]);\n\n          const basicExamEntries =\n            Object.entries(\n              block.basicExamCounts || {}\n            )\n            .map(([label,examSet])=>[\n              label,\n              examSet instanceof Set\n                ? examSet.size\n                : Number(examSet || 0),\n              \"basic\"\n            ]);\n\n          /*\n            ✅ نفس المنطقة الخضراء تعرض الآن:\n            المهارات + أنواع الاختبارات الأساسية المفعلة Shown.\n          */\n          const greenEntries =\n            [\n              ...skillEntries,\n              ...basicExamEntries\n            ]\n            .filter(([,count])=>\n              Number(count || 0) > 0\n            )\n            .sort((a,b)=>\n              String(a[0])\n                .localeCompare(\n                  String(b[0])\n                )\n            );\n\n          const skillSummaryHtml =\n            greenEntries.length\n              ? `\n                <div class=\"published-course-skills\">\n                  ${\n                    greenEntries\n                      .map(([label,count,kind])=>`\n                        <span\n                          class=\"published-skill-chip ${kind === \"basic\" ? \"published-basic-exam-chip\" : \"\"}\"\n                          title=\"${esc(label)}: ${Number(count || 0)} Shown model(s)\"\n                        >\n                          <span class=\"published-skill-name\">${esc(label)}</span>\n                          <strong class=\"published-skill-count\">${Number(count || 0)}</strong>\n                        </span>\n                      `)\n                      .join(\"\")\n                  }\n                </div>\n              `\n              : \"\";\n\n          html += `\n            <div class=\"published-course-block\">\n\n              <div class=\"published-course-meta\">\n                ${esc(c.name || \"Course\")}\n                ${c.period ? ` | ${esc(c.period)}` : \"\"}\n                ${c.branch ? ` | ${esc(c.branch)}` : \"\"}\n              </div>\n\n              ${skillSummaryHtml}\n          `;\n\n          block.exams.forEach(examRow=>{\n\n            const checkboxId =\n              \"publishedVisible_\" +\n              String(examRow.examId)\n                .replace(\n                  /[^a-zA-Z0-9_-]/g,\n                  \"_\"\n                ) +\n              \"_\" +\n              String(c.id)\n                .replace(\n                  /[^a-zA-Z0-9_-]/g,\n                  \"_\"\n                );\n\n            const checkedAttr =\n              examRow.isShown\n                ? \"checked\"\n                : \"\";\n\n            const statusText =\n              examRow.isShown\n                ? \"Shown\"\n                : \"Hidden\";\n\n            const statusTitle =\n              examRow.isShown\n                ? \"Click to hide this model from students in this linked course.\"\n                : \"Click to show this model to students in this linked course.\";\n\n            /*\n              ✅ الرقم بجانب اسم الاختبار مطابق للواجهة الرئيسية دائماً.\n              لا يتغير بسبب Shown / Hidden أو بسبب الدورة المرتبطة.\n            */\n            const count =\n              Number(examRow.fullQuestionCount || 0);\n\n            html += `\n              <div class=\"published-exam-row\">\n\n                <button\n                  type=\"button\"\n                  class=\"published-exam-name published-exam-open-btn\"\n                  onclick='openPublishedExamForEdit(${JSON.stringify(examRow.examId)}, ${JSON.stringify(c.id)})'\n                  title=\"Open this exam and edit its questions\"\n                >\n                  <i class=\"fa-regular fa-file-lines\"></i>\n\n                  <span>\n                    ${esc(examRow.examTitle)}\n                  </span>\n\n                  <span class=\"published-exam-count\">\n                    ${Number(count || 0)}\n                  </span>\n\n                  <i class=\"fa-solid fa-arrow-up-right-from-square published-exam-arrow\"></i>\n                </button>\n\n                <label\n                  class=\"published-visibility-toggle\"\n                  for=\"${checkboxId}\"\n                  title=\"${esc(statusTitle)}\"\n                >\n                  <input\n                    id=\"${checkboxId}\"\n                    type=\"checkbox\"\n                    ${checkedAttr}\n                    onchange='togglePublishedExamVisibility(${JSON.stringify(examRow.examId)}, ${JSON.stringify(c.id)}, this)'\n                    onclick=\"event.stopPropagation()\"\n                    aria-label=\"${esc(statusText)}\"\n                  >\n\n                  <span class=\"published-toggle-track\">\n                    <span class=\"published-toggle-thumb\"></span>\n                  </span>\n\n                  <span class=\"published-toggle-text\">\n                    ${statusText}\n                  </span>\n                </label>\n\n              </div>\n            `;\n          });\n\n          html += `</div>`;\n        });\n\n      html += `</section>`;\n    });\n\n    body.innerHTML = html;\n\n  }catch(error){\n\n    console.error(\n      \"PUBLISHED SIDEBAR ERROR:\",\n      error\n    );\n\n    body.innerHTML = `\n      <div class=\"published-sidebar-error\">\n        Unable to load student models status.<br>\n        ${esc(error?.message || String(error))}\n      </div>\n    `;\n\n  }finally{\n    PUBLISHED_SIDEBAR_LOADING = false;\n  }\n}\n\nasync function togglePublishedExamVisibility(examId, courseId, checkbox){\n  const desiredVisible =\n    checkbox?.checked === true;\n\n  examId =\n    String(examId || \"\").trim();\n\n  courseId =\n    String(courseId || \"\").trim();\n\n  if(!examId || !courseId){\n    if(checkbox){\n      checkbox.checked = !desiredVisible;\n    }\n    alert(\"Missing exam or course ID\");\n    return;\n  }\n\n  /*\n    ✅ التحكم من الشريط الجانبي:\n    ON  = إظهار كل الأسئلة المرتبطة بهذه الدورة للطالب.\n    OFF = إخفاء كل أسئلة هذا النموذج عن طلاب هذه الدورة فقط.\n\n    مهم:\n    هذا لا يعمل Remove Link.\n    coursesUsed يبقى كما هو، وبالتالي يبقى النموذج مرتبطاً بالدورة\n    ويمكن تشغيله مرة أخرى من نفس الزر.\n  */\n\n  try{\n    if(checkbox){\n      checkbox.disabled = true;\n    }\n\n    const examRef =\n      db.collection(\"exams\").doc(examId);\n\n    const examDoc =\n      await examRef.get();\n\n    if(!examDoc.exists){\n      throw new Error(\"Exam not found\");\n    }\n\n    const examData =\n      examDoc.data() || {};\n\n    const visibleMap = {\n      ...(examData.visibleQuestionsByCourse || {})\n    };\n\n    if(desiredVisible){\n\n      /*\n        ✅ اجلب الأسئلة المرتبطة فعلياً بهذه الدورة\n        حتى لو كان أصل النموذج أو الأسئلة لمدرب آخر.\n        معيار السماح هنا هو coursesUsed للدورة نفسها،\n        وليس مالك السؤال الأصلي.\n      */\n      const qSnap =\n        await db.collection(\"questions\")\n          .where(\"examId\",\"==\",examId)\n          .get();\n\n      const linkedIds = [];\n\n      qSnap.forEach(doc=>{\n        const q =\n          doc.data() || {};\n\n        if(\n          q.showQuestion === false ||\n          q.visible === false ||\n          q.hidden === true ||\n          q.isMain === true\n        ){\n          return;\n        }\n\n        const used =\n          Array.isArray(q.coursesUsed)\n            ? q.coursesUsed\n            : [];\n\n        const belongsToLinkedCourse =\n          used.some(c =>\n            String(c?.courseId || \"\").trim() ===\n            courseId\n          );\n\n        /*\n          ✅ الاختبار الأساسي:\n          إذا كانت الدورة موجودة في courseIds أو coursesData\n          في نفس exam، فكل أسئلة الاختبار الأساسية يمكن إظهارها.\n        */\n        const baseCourseIds =\n          new Set(\n            [\n              ...(Array.isArray(examData.courseIds)\n                ? examData.courseIds\n                : []),\n\n              ...(Array.isArray(examData.coursesData)\n                ? examData.coursesData.map(c=>c?.courseId)\n                : [])\n            ]\n            .map(id=>String(id || \"\").trim())\n            .filter(Boolean)\n          );\n\n        const belongsToBaseCourse =\n          baseCourseIds.has(courseId);\n\n        if(\n          belongsToLinkedCourse ||\n          belongsToBaseCourse\n        ){\n          linkedIds.push(doc.id);\n        }\n      });\n\n      if(!linkedIds.length){\n        throw new Error(\n          \"No linked questions were found for this course\"\n        );\n      }\n\n      visibleMap[courseId] =\n        [...new Set(linkedIds)];\n\n      const updateData = {\n        visibleQuestionsByCourse:\n          visibleMap,\n\n        updatedAt:\n          firebase.firestore.FieldValue.serverTimestamp()\n      };\n\n      /*\n        الحقل القديم visibleQuestions يُحدّث فقط إذا كانت\n        هذه هي الدورة المفتوحة حالياً في صفحة الإدارة.\n      */\n      if(\n        String(CURRENT_COURSE_ID || \"\").trim() ===\n        courseId &&\n        String(CURRENT_PREVIEW_EXAM || \"\").trim() ===\n        examId\n      ){\n        updateData.visibleQuestions =\n          [...new Set(linkedIds)];\n      }\n\n      await examRef.set(\n        updateData,\n        {merge:true}\n      );\n\n      console.log(\n        \"✅ SHOWN ON FROM SIDEBAR:\",\n        examId,\n        courseId,\n        linkedIds.length\n      );\n\n    }else{\n\n      /*\n        ✅ RED / HIDDEN:\n        لا نحذف الربط ولا coursesUsed.\n        فقط نمنع ظهور الأسئلة للطالب في هذه الدورة.\n      */\n      visibleMap[courseId] = [];\n\n      const updateData = {\n        visibleQuestionsByCourse:\n          visibleMap,\n\n        updatedAt:\n          firebase.firestore.FieldValue.serverTimestamp()\n      };\n\n      if(\n        String(CURRENT_COURSE_ID || \"\").trim() ===\n        courseId &&\n        String(CURRENT_PREVIEW_EXAM || \"\").trim() ===\n        examId\n      ){\n        updateData.visibleQuestions = [];\n      }\n\n      await examRef.set(\n        updateData,\n        {merge:true}\n      );\n\n      console.log(\n        \"✅ HIDDEN FROM SIDEBAR:\",\n        examId,\n        courseId\n      );\n    }\n\n    /*\n      تحديث نص/لون الزر فوراً قبل إعادة بناء الشريط.\n    */\n    if(checkbox){\n      const label =\n        checkbox.closest(\n          \".published-visibility-toggle\"\n        );\n\n      const statusTextEl =\n        label?.querySelector(\n          \".published-toggle-text\"\n        );\n\n      if(statusTextEl){\n        statusTextEl.textContent =\n          desiredVisible\n            ? \"Shown\"\n            : \"Hidden\";\n      }\n    }\n\n    /*\n      إذا كانت نفس الدورة/الاختبار مفتوحة في الصفحة،\n      أعد تحميل الأسئلة لتتزامن checkboxes الرئيسية أيضاً.\n    */\n    if(\n      String(CURRENT_PREVIEW_EXAM || \"\").trim() ===\n      examId &&\n      String(CURRENT_COURSE_ID || \"\").trim() ===\n      courseId &&\n      typeof loadQuestions === \"function\"\n    ){\n      await loadQuestions();\n    }\n\n    /*\n      أعد تحميل الشريط لتحديث العدادات والحالة.\n    */\n    if(\n      typeof loadPublishedQuestionsSidebar ===\n      \"function\"\n    ){\n      await loadPublishedQuestionsSidebar(true);\n    }else if(\n      typeof schedulePublishedSidebarRefresh ===\n      \"function\"\n    ){\n      schedulePublishedSidebarRefresh(0);\n    }\n\n  }catch(error){\n\n    console.error(\n      \"SIDEBAR VISIBILITY TOGGLE ERROR:\",\n      error\n    );\n\n    if(checkbox){\n      checkbox.checked =\n        !desiredVisible;\n\n      checkbox.disabled = false;\n    }\n\n    alert(\n      \"Unable to change student visibility: \" +\n      (error?.message || String(error))\n    );\n\n  }finally{\n\n    if(\n      checkbox &&\n      document.body.contains(checkbox)\n    ){\n      checkbox.disabled = false;\n    }\n  }\n}\n\nasync function openPublishedExamForEdit(examId, courseId){\n  try{\n    examId = String(examId || \"\").trim();\n    courseId = String(courseId || \"\").trim();\n\n    if(!examId) return;\n\n    /*\n      تأكد أن بطاقة نفس الكويز موجودة في قائمة الكويزات الرئيسية.\n      إذا كان البحث يخفيها، نمسح البحث ونعيد بناء القائمة كاملة\n      قبل فتح الاختبار حتى يتم تحديد البطاقة الصحيحة بصريًا.\n    */\n    const examExistsInMainList =\n      Array.isArray(EXAMS_DROPDOWN) &&\n      EXAMS_DROPDOWN.some(item =>\n        String(item?.id || \"\").trim() === examId\n      );\n\n    if(\n      !examExistsInMainList &&\n      typeof loadExams === \"function\"\n    ){\n      await loadExams();\n    }\n\n    const previewSearch =\n      document.getElementById(\"previewExamSearch\");\n\n    if(previewSearch){\n      previewSearch.value = \"\";\n    }\n\n    if(typeof filterExamDropdown === \"function\"){\n      filterExamDropdown(\"\");\n    }\n\n    // اختيار الدورة الصحيحة قبل فتح الاختبار\n    if(courseId){\n      // ✅ نحافظ على دورة المدرب المختارة للسياق والتحكم\n      SIDEBAR_FOCUS_COURSE_ID = courseId;\n      CURRENT_COURSE_ID = courseId;\n\n      // ✅ هذه الدورة هي التي يجب أن تظهر في غلاف PDF\n      PRINT_CONTEXT_COURSE_ID = courseId;\n\n      try{\n        sessionStorage.setItem(\n          \"prudlePrintCourseId\",\n          courseId\n        );\n      }catch(_){}\n\n      // ✅ لكن عرض الأسئلة نفسه يكون كاملاً مثل الشاشة الرئيسية\n      // لا نفلتر أسئلة النموذج حسب coursesUsed عند الفتح من الشريط.\n      SIDEBAR_SHOW_FULL_EXAM = true;\n\n      try{\n        const cDoc = await db.collection(\"Courses\").doc(courseId).get();\n        if(cDoc.exists){\n          const c = cDoc.data() || {};\n          CURRENT_COURSE_NAME =\n            c.TrainingCourse || c.course || \"\";\n          CURRENT_TRAINER =\n            c.Trainer || c.trainer || \"\";\n          CURRENT_PERIOD =\n            c.Period || c.period || \"\";\n        }\n      }catch(courseErr){\n        console.warn(\"Published sidebar course read:\", courseErr);\n      }\n    }\n\n    /*\n      false = لا تعيد CURRENT_COURSE_ID لأول دورة.\n      بهذا يفتح نفس الاختبار ونفس دورة المدرب التي ضغط عليها.\n    */\n    await openExamTab(examId, false);\n\n    /*\n      بعد فتح الاختبار، حدد بطاقته في القائمة الرئيسية\n      وانتقل إليها تلقائيًا مثل الاختيار اليدوي من الصورة الثانية.\n    */\n    setTimeout(()=>{\n      const selectedCard = document.querySelector(\n        `.exam-card[data-id=\"${examId}\"]`\n      );\n\n      if(selectedCard){\n        selectedCard.classList.add(\"exam-card-selected\");\n        selectedCard.setAttribute(\"aria-current\",\"true\");\n      }\n\n      const target =\n        selectedCard ||\n        document.getElementById(\"examPreviewBox\");\n\n      if(target){\n        target.scrollIntoView({\n          behavior:\"smooth\",\n          block:\"center\"\n        });\n      }\n    },160);\n\n  }catch(error){\n    console.error(\"OPEN PUBLISHED EXAM ERROR:\", error);\n    alert(\n      \"Unable to open this exam: \" +\n      (error?.message || String(error))\n    );\n  }\n}\n\nfunction startPublishedQuestionsSidebarWatcher(){\n  if(PUBLISHED_SIDEBAR_EXAMS_UNSUB){\n    try{ PUBLISHED_SIDEBAR_EXAMS_UNSUB(); }catch(e){}\n    PUBLISHED_SIDEBAR_EXAMS_UNSUB = null;\n  }\n\n  /*\n    visibleQuestionsByCourse is stored in exam documents.\n    Listening to exams makes the sidebar update whenever a checkbox,\n    Show/Hide button, link, or unlink changes student visibility.\n  */\n  PUBLISHED_SIDEBAR_EXAMS_UNSUB = db.collection(\"exams\")\n    .onSnapshot(\n      ()=>schedulePublishedSidebarRefresh(180),\n      err=>console.warn(\"Published sidebar watcher:\", err)\n    );\n}\n\nasync function initPublishedQuestionsSidebar(){\n  restorePublishedSidebarState();\n  await loadPublishedQuestionsSidebar(false);\n  startPublishedQuestionsSidebarWatcher();\n}\n\n/* The existing question checkbox calls saveVisibleQuestions().\n   Keep that API and refresh the sidebar immediately after saving. */\nasync function saveVisibleQuestions(){\n  await autoSaveVisibleQuestions();\n  schedulePublishedSidebarRefresh(50);\n}\n\nwindow.addEventListener(\"DOMContentLoaded\",function(){\n  if(document.getElementById(\"fillItemsList\") && !getFillRows().length){\n    resetFillItems();\n  }\n\n  /*\n    تشغيل الشريط بعد اكتمال تعريف جميع دوال الملف.\n    هذا يجعله يظهر تلقائيًا من أول فتح للصفحة\n    بدون الضغط على زر Refresh.\n  */\n  initPublishedQuestionsSidebar().catch(err=>{\n    console.warn(\"Published sidebar init:\", err);\n\n    const body =\n      document.getElementById(\"publishedSidebarBody\");\n\n    if(body){\n      body.innerHTML = `\n        <div class=\"published-sidebar-error\">\n          Unable to load published questions.<br>\n          ${esc(err?.message || String(err))}\n        </div>\n      `;\n    }\n  });\n});\n"}, {"text": "\nlet A4_DRAG_EXAM_ID = \"\";\nlet A4_DRAGGED_CARD = null;\nlet A4_DROP_INDICATOR = null;\n\nfunction a4GetCanvas(){\n  return document.getElementById(\"a4PagesCanvas\");\n}\nfunction a4GetPages(){\n  return [...document.querySelectorAll(\"#a4PagesCanvas .a4-question-page\")];\n}\nfunction a4GetCards(){\n  return [...document.querySelectorAll(\"#a4PagesCanvas .modal-q-card[data-question-id]\")];\n}\n\nfunction a4CreatePage(pageNumber){\n  const page=document.createElement(\"section\");\n  page.className=\"a4-question-page\";\n  page.dataset.pdfPage=String(pageNumber);\n  page.innerHTML=`\n    <div class=\"a4-page-label\">\n      <i class=\"fa-solid fa-file-pdf\"></i>\n      PDF Page ${pageNumber}\n      <small>${pageNumber===2?\"first questions page\":\"A4\"}</small>\n    </div>\n    <div class=\"a4-overflow-warning\">⚠ Content exceeds one A4 page</div>\n    <div class=\"a4-page-dropzone\"></div>\n    <div class=\"a4-page-bottom-line\">\n      <span>END OF PDF PAGE ${pageNumber}</span>\n    </div>\n  `;\n  a4BindPageDropEvents(page);\n  return page;\n}\n\nfunction a4CreateSeparator(fromPage,toPage){\n  const el=document.createElement(\"div\");\n  el.className=\"a4-screen-separator\";\n  el.innerHTML=`<span>A4 PAGE BREAK — Page ${fromPage} → Page ${toPage}</span>`;\n  return el;\n}\n\nfunction a4CreateAddPageZone(){\n  const el=document.createElement(\"div\");\n  el.className=\"a4-add-page-zone\";\n  el.innerHTML=`\n    <div>Add another physical A4 page</div>\n    <button type=\"button\" class=\"a4-add-page-btn\" style=\"background:#64748b\">\n      <i class=\"fa-solid fa-plus\"></i> Add A4 Page\n    </button>\n  `;\n  el.querySelector(\".a4-add-page-btn\")?.addEventListener(\"click\",a4AddNewPage);\n  return el;\n}\n\nfunction a4DecorateCard(card){\n  if(!card || card.querySelector(\".a4-question-drag-handle\")) return;\n\n  card.draggable=true;\n\n  const handle=document.createElement(\"div\");\n  handle.className=\"a4-question-drag-handle\";\n  handle.innerHTML=`\n    <span><i class=\"fa-solid fa-grip-lines\"></i> Drag question manually</span>\n    <span class=\"a4-current-page\"></span>\n  `;\n  card.insertBefore(handle,card.firstChild);\n\n  card.addEventListener(\"dragstart\",event=>{\n    A4_DRAGGED_CARD=card;\n    card.classList.add(\"a4-dragging\");\n    try{\n      event.dataTransfer.effectAllowed=\"move\";\n      event.dataTransfer.setData(\"text/plain\",String(card.dataset.questionId||\"\"));\n    }catch(_){}\n  });\n\n  card.addEventListener(\"dragend\",()=>{\n    card.classList.remove(\"a4-dragging\");\n    A4_DRAGGED_CARD=null;\n    a4RemoveDropIndicator();\n    a4GetPages().forEach(p=>p.classList.remove(\"a4-page-dragover\"));\n    a4RefreshPageBadges();\n    a4CheckAllPageOverflow();\n  });\n}\n\nfunction a4RemoveDropIndicator(){\n  if(A4_DROP_INDICATOR?.parentNode) A4_DROP_INDICATOR.remove();\n  A4_DROP_INDICATOR=null;\n}\nfunction a4EnsureDropIndicator(){\n  if(!A4_DROP_INDICATOR){\n    A4_DROP_INDICATOR=document.createElement(\"div\");\n    A4_DROP_INDICATOR.className=\"a4-drop-indicator\";\n  }\n  return A4_DROP_INDICATOR;\n}\n\nfunction a4GetInsertBefore(dropzone,mouseY){\n  const cards=[...dropzone.querySelectorAll(\":scope > .modal-q-card:not(.a4-dragging)\")];\n  let closest={offset:Number.NEGATIVE_INFINITY,element:null};\n\n  cards.forEach(card=>{\n    const box=card.getBoundingClientRect();\n    const offset=mouseY-box.top-box.height/2;\n    if(offset<0 && offset>closest.offset){\n      closest={offset,element:card};\n    }\n  });\n  return closest.element;\n}\n\nfunction a4BindPageDropEvents(page){\n  const dropzone=page.querySelector(\".a4-page-dropzone\");\n  if(!dropzone) return;\n\n  page.addEventListener(\"dragenter\",event=>{\n    if(!A4_DRAGGED_CARD) return;\n    event.preventDefault();\n    page.classList.add(\"a4-page-dragover\");\n  });\n\n  page.addEventListener(\"dragover\",event=>{\n    if(!A4_DRAGGED_CARD) return;\n    event.preventDefault();\n    try{event.dataTransfer.dropEffect=\"move\"}catch(_){}\n\n    const before=a4GetInsertBefore(dropzone,event.clientY);\n    const indicator=a4EnsureDropIndicator();\n\n    if(before) dropzone.insertBefore(indicator,before);\n    else dropzone.appendChild(indicator);\n  });\n\n  page.addEventListener(\"dragleave\",event=>{\n    if(!page.contains(event.relatedTarget)){\n      page.classList.remove(\"a4-page-dragover\");\n    }\n  });\n\n  page.addEventListener(\"drop\",async event=>{\n    if(!A4_DRAGGED_CARD) return;\n    event.preventDefault();\n    page.classList.remove(\"a4-page-dragover\");\n\n    const before=a4GetInsertBefore(dropzone,event.clientY);\n\n    if(before) dropzone.insertBefore(A4_DRAGGED_CARD,before);\n    else dropzone.appendChild(A4_DRAGGED_CARD);\n\n    a4RemoveDropIndicator();\n\n    // Renumber instantly after manual movement.\n    a4RenumberQuestions();\n    a4RefreshPageBadges();\n    a4CheckAllPageOverflow();\n\n    await a4SaveManualLayout(false);\n  });\n}\n\n\nfunction a4RenumberQuestions(){\n  const cards = a4GetCards();\n\n  cards.forEach((card,index)=>{\n    const number = index + 1;\n\n    card.dataset.questionNumber = String(number);\n\n    /*\n      Card structure after drag manager:\n      1) .a4-question-drag-handle\n      2) original question header containing:\n         - Q badge\n         - Marks badge\n         - Type badge\n    */\n    const header =\n      [...card.children].find(el =>\n        el !== card.querySelector(\".a4-question-drag-handle\") &&\n        el.querySelector &&\n        el.querySelector(\"div\")\n      );\n\n    if(header){\n      const directDivs =\n        [...header.children].filter(el =>\n          el.tagName === \"DIV\"\n        );\n\n      const qBadge = directDivs[0];\n\n      if(qBadge){\n        qBadge.textContent = `Q${number}`;\n      }\n    }\n\n    /*\n      Also update any explicit question-number marker if one is added later.\n    */\n    card.querySelectorAll(\n      \"[data-question-number-label], .question-number-label\"\n    ).forEach(el=>{\n      el.textContent = `Q${number}`;\n    });\n  });\n}\n\nfunction a4RefreshPageBadges(){\n  \n  a4RenumberQuestions();\na4GetPages().forEach(page=>{\n    const pageNo=Math.max(2,Number(page.dataset.pdfPage||2));\n\n    const label=page.querySelector(\".a4-page-label\");\n    if(label){\n      label.innerHTML=`\n        <i class=\"fa-solid fa-file-pdf\"></i>\n        PDF Page ${pageNo}\n        <small>${pageNo===2?\"first questions page\":\"A4\"}</small>\n      `;\n    }\n\n    const bottom=page.querySelector(\".a4-page-bottom-line span\");\n    if(bottom) bottom.textContent=`END OF PDF PAGE ${pageNo}`;\n\n    page.querySelectorAll(\".modal-q-card[data-question-id]\").forEach(card=>{\n      card.dataset.pdfPage=String(pageNo);\n      const badge=card.querySelector(\".a4-current-page\");\n      if(badge) badge.textContent=`PDF Page ${pageNo}`;\n    });\n\n    const dropzone=page.querySelector(\".a4-page-dropzone\");\n    const count=dropzone?.querySelectorAll(\":scope > .modal-q-card\").length||0;\n    let empty=dropzone?.querySelector(\".a4-page-empty\");\n\n    if(count===0 && dropzone && !empty){\n      empty=document.createElement(\"div\");\n      empty.className=\"a4-page-empty\";\n      empty.textContent=\"Drop a question here\";\n      dropzone.appendChild(empty);\n    }else if(count>0 && empty){\n      empty.remove();\n    }\n  });\n}\n\nfunction a4CheckPageOverflow(page){\n  const dropzone=page.querySelector(\".a4-page-dropzone\");\n  if(!dropzone) return;\n\n  const overflow=\n    window.innerWidth>760 &&\n    dropzone.scrollHeight>dropzone.clientHeight+12;\n\n  page.classList.toggle(\"a4-overflow\",overflow);\n}\nfunction a4CheckAllPageOverflow(){\n  requestAnimationFrame(()=>a4GetPages().forEach(a4CheckPageOverflow));\n}\n\nfunction a4RenderPageSeparators(){\n  const canvas=a4GetCanvas();\n  if(!canvas) return;\n\n  canvas.querySelectorAll(\":scope > .a4-screen-separator,:scope > .a4-add-page-zone\")\n    .forEach(el=>el.remove());\n\n  const pages=a4GetPages();\n\n  pages.forEach((page,index)=>{\n    const next=pages[index+1];\n    if(next){\n      canvas.insertBefore(\n        a4CreateSeparator(\n          Number(page.dataset.pdfPage||2),\n          Number(next.dataset.pdfPage||3)\n        ),\n        next\n      );\n    }\n  });\n\n  canvas.appendChild(a4CreateAddPageZone());\n}\n\nfunction a4NormalizePageNumbers(){\n  a4GetPages().forEach((page,index)=>{\n    page.dataset.pdfPage=String(index+2);\n  });\n  a4RefreshPageBadges();\n  a4RenderPageSeparators();\n}\n\nasync function a4AddNewPage(){\n  const canvas=a4GetCanvas();\n  if(!canvas) return;\n\n  canvas.querySelector(\":scope > .a4-add-page-zone\")?.remove();\n\n  const pageNo=a4GetPages().length+2;\n  const page=a4CreatePage(pageNo);\n  canvas.appendChild(page);\n\n  a4RenderPageSeparators();\n  a4RefreshPageBadges();\n  a4CheckAllPageOverflow();\n\n  page.scrollIntoView({behavior:\"smooth\",block:\"start\"});\n}\n\nfunction a4BuildToolbar(){\n  const toolbar=document.getElementById(\"modalPrintToolbar\");\n  if(!toolbar) return;\n\n  let manager=document.getElementById(\"a4DragToolbar\");\n  if(!manager){\n    manager=document.createElement(\"div\");\n    manager.id=\"a4DragToolbar\";\n    toolbar.appendChild(manager);\n  }\n\n  manager.innerHTML=`\n    <div class=\"a4-help\">\n      <i class=\"fa-solid fa-hand-pointer\"></i>\n      Drag any question up/down or between A4 sheets. The red dashed line shows the exact page separator.\n      PDF Page 1 is the cover; questions begin on PDF Page 2.\n    </div>\n    <button type=\"button\" id=\"a4SaveLayoutBtn\" style=\"background:#16a34a\">\n      <i class=\"fa-solid fa-floppy-disk\"></i> Save Layout\n    </button>\n    <button type=\"button\" id=\"a4CompactPagesBtn\" style=\"background:#7c3aed\">\n      <i class=\"fa-solid fa-layer-group\"></i> Remove Empty Pages\n    </button>\n  `;\n\n  manager.querySelector(\"#a4SaveLayoutBtn\")?.addEventListener(\"click\",()=>a4SaveManualLayout(true));\n\n  manager.querySelector(\"#a4CompactPagesBtn\")?.addEventListener(\"click\",async()=>{\n    a4GetPages().forEach(page=>{\n      if(!page.querySelector(\".modal-q-card\")) page.remove();\n    });\n\n    if(!a4GetPages().length){\n      a4GetCanvas()?.appendChild(a4CreatePage(2));\n    }\n\n    a4NormalizePageNumbers();\n    await a4SaveManualLayout(true);\n    a4CheckAllPageOverflow();\n  });\n}\n\nfunction a4BuildCanvasFromCurrentCards(){\n  const wrap=document.getElementById(\"modalQuestionsWrap\");\n  if(!wrap) return;\n\n  const cards=[...wrap.querySelectorAll(\".modal-q-card[data-question-id]\")];\n  if(!cards.length) return;\n\n  const canvas=document.createElement(\"div\");\n  canvas.id=\"a4PagesCanvas\";\n\n  wrap.innerHTML=\"\";\n  wrap.appendChild(canvas);\n\n  const pageMap=new Map();\n\n  cards.forEach(card=>{\n    a4DecorateCard(card);\n\n    const pageNo=Math.max(2,Number(card.dataset.pdfPage||2));\n\n    if(!pageMap.has(pageNo)){\n      pageMap.set(pageNo,a4CreatePage(pageNo));\n    }\n\n    pageMap.get(pageNo)\n      .querySelector(\".a4-page-dropzone\")\n      .appendChild(card);\n  });\n\n  const pageNumbers=[...pageMap.keys()];\n  const maxPage=Math.max(2,...pageNumbers);\n\n  for(let pageNo=2;pageNo<=maxPage;pageNo++){\n    canvas.appendChild(\n      pageMap.get(pageNo)||a4CreatePage(pageNo)\n    );\n  }\n\n  a4RenderPageSeparators();\n  a4RefreshPageBadges();\n}\n\nasync function a4SaveManualLayout(showMessage=false){\n  // Keep visible numbering synchronized with the order written to Firestore.\n  a4RenumberQuestions();\n\n  const examId=String(A4_DRAG_EXAM_ID||\"\").trim();\n  if(!examId) return;\n\n  const pages=a4GetPages();\n  const cards=a4GetCards();\n  if(!cards.length) return;\n\n  const batch=db.batch();\n  let order=1;\n\n  pages.forEach(page=>{\n    const pdfPage=Math.max(2,Number(page.dataset.pdfPage||2));\n\n    page.querySelectorAll(\".modal-q-card[data-question-id]\").forEach(card=>{\n      const id=String(card.dataset.questionId||\"\").trim();\n      if(!id) return;\n\n      batch.update(\n        db.collection(\"questions\").doc(id),\n        {\n          pdfPage,\n          order:order++,\n          pdfLayoutUpdatedAt:\n            firebase.firestore.FieldValue.serverTimestamp()\n        }\n      );\n    });\n  });\n\n  try{\n    await batch.commit();\n    if(showMessage) alert(\"✅ A4 question layout saved\");\n  }catch(err){\n    console.error(\"a4SaveManualLayout error:\",err);\n    alert(\"❌ Could not save A4 layout\\n\"+String(err.message||err));\n  }\n}\n\nfunction setupPdfA4DragManager(examId){\n  A4_DRAG_EXAM_ID=String(examId||\"\").trim();\n  a4BuildToolbar();\n  a4BuildCanvasFromCurrentCards();\n  a4CheckAllPageOverflow();\n\n  window.addEventListener(\n    \"resize\",\n    a4CheckAllPageOverflow,\n    {passive:true}\n  );\n}\n"}, {"text": "\n/*\n  openFullQuestions() can be opened after an Answers PDF operation while\n  body still carries print-answers. Screen CSS above already protects the\n  preview, but this also keeps the semantic screen state explicitly clean.\n*/\n(function(){\n  function enforceGeneralPreviewQuestionsOnly(){\n    const modal = document.getElementById(\"questionsModal\");\n    if(!modal) return;\n\n    /*\n      Do NOT remove print mode classes here because mobile printing relies\n      on them. Only mark the modal itself as a questions-only screen preview.\n    */\n    modal.classList.add(\"screen-questions-only\");\n\n    modal.querySelectorAll(\".answer-only\").forEach(el=>{\n      el.setAttribute(\"aria-hidden\",\"true\");\n    });\n\n    modal.querySelectorAll(\".question-only\").forEach(el=>{\n      el.removeAttribute(\"aria-hidden\");\n    });\n  }\n\n  const observer = new MutationObserver(()=>{\n    const modal = document.getElementById(\"questionsModal\");\n    if(\n      modal &&\n      modal.style.display !== \"none\"\n    ){\n      enforceGeneralPreviewQuestionsOnly();\n    }\n  });\n\n  window.addEventListener(\"DOMContentLoaded\",()=>{\n    observer.observe(document.body,{\n      childList:true,\n      subtree:true\n    });\n  });\n\n  window.enforceGeneralPreviewQuestionsOnly =\n    enforceGeneralPreviewQuestionsOnly;\n})();\n"}, {"text": "\n(function(){\n\n  let A4_MULTI_DRAG_IDS = [];\n  let A4_MULTI_DRAG_SOURCE = null;\n\n  function a4CardsInVisualOrder(){\n    const canvas = document.getElementById(\"a4PagesCanvas\");\n    if(!canvas) return [];\n\n    const cards = [];\n\n    canvas.querySelectorAll(\".a4-question-page\").forEach(page=>{\n      page.querySelectorAll(\n        \".a4-page-dropzone > .modal-q-card[data-question-id]\"\n      ).forEach(card=>cards.push(card));\n    });\n\n    return cards;\n  }\n\n  function a4SelectedCards(){\n    return a4CardsInVisualOrder().filter(card=>{\n      const cb = card.querySelector(\".a4-move-check\");\n      return Boolean(cb?.checked);\n    });\n  }\n\n  function a4UpdateSelectedVisual(){\n    a4CardsInVisualOrder().forEach(card=>{\n      const cb = card.querySelector(\".a4-move-check\");\n      card.classList.toggle(\n        \"a4-multi-selected\",\n        Boolean(cb?.checked)\n      );\n    });\n  }\n\n  function a4InstallMultiSelect(card){\n    if(\n      !card ||\n      card.querySelector(\".a4-move-select\")\n    ){\n      return;\n    }\n\n    const label = document.createElement(\"label\");\n    label.className = \"a4-move-select\";\n    label.title = \"Select this question to move it together with other selected questions\";\n    label.innerHTML = `\n      <input\n        type=\"checkbox\"\n        class=\"a4-move-check\"\n      >\n      <span>Move</span>\n    `;\n\n    card.appendChild(label);\n\n    const cb = label.querySelector(\".a4-move-check\");\n\n    cb.addEventListener(\"click\",event=>{\n      event.stopPropagation();\n    });\n\n    cb.addEventListener(\"change\",()=>{\n      a4UpdateSelectedVisual();\n    });\n  }\n\n  function a4ClearDropSlots(){\n    document.querySelectorAll(\n      \"#a4PagesCanvas .a4-drop-slot\"\n    ).forEach(el=>el.remove());\n  }\n\n  function a4CreateDropSlot(){\n    const slot = document.createElement(\"div\");\n    slot.className = \"a4-drop-slot\";\n\n    slot.addEventListener(\"dragenter\",event=>{\n      if(!A4_MULTI_DRAG_IDS.length) return;\n      event.preventDefault();\n      slot.classList.add(\"a4-drop-slot-active\");\n    });\n\n    slot.addEventListener(\"dragover\",event=>{\n      if(!A4_MULTI_DRAG_IDS.length) return;\n      event.preventDefault();\n      slot.classList.add(\"a4-drop-slot-active\");\n      try{\n        event.dataTransfer.dropEffect = \"move\";\n      }catch(_){}\n    });\n\n    slot.addEventListener(\"dragleave\",()=>{\n      slot.classList.remove(\"a4-drop-slot-active\");\n    });\n\n    slot.addEventListener(\"drop\",async event=>{\n      if(!A4_MULTI_DRAG_IDS.length) return;\n\n      event.preventDefault();\n      event.stopPropagation();\n\n      const parent = slot.parentElement;\n      if(!parent) return;\n\n      const movingCards = A4_MULTI_DRAG_IDS\n        .map(id =>\n          document.querySelector(\n            `#a4PagesCanvas .modal-q-card[data-question-id=\"${CSS.escape(id)}\"]`\n          )\n        )\n        .filter(Boolean);\n\n      /*\n        Insert before the slot. Nothing is replaced.\n        All selected questions keep their relative order.\n      */\n      movingCards.forEach(card=>{\n        parent.insertBefore(card,slot);\n      });\n\n      a4FinishMultiMove();\n      await a4SaveManualLayout(false);\n    });\n\n    return slot;\n  }\n\n  function a4BuildAllDropSlots(){\n    a4ClearDropSlots();\n\n    document.querySelectorAll(\n      \"#a4PagesCanvas .a4-page-dropzone\"\n    ).forEach(zone=>{\n\n      const cards = [\n        ...zone.querySelectorAll(\n          \":scope > .modal-q-card[data-question-id]\"\n        )\n      ];\n\n      if(!cards.length){\n        zone.appendChild(a4CreateDropSlot());\n        return;\n      }\n\n      cards.forEach(card=>{\n        zone.insertBefore(\n          a4CreateDropSlot(),\n          card\n        );\n      });\n\n      zone.appendChild(\n        a4CreateDropSlot()\n      );\n    });\n  }\n\n  function a4EnsureEnoughPagesForOverflow(){\n    const canvas = document.getElementById(\"a4PagesCanvas\");\n    if(!canvas) return;\n\n    let pages = [\n      ...canvas.querySelectorAll(\n        \":scope > .a4-question-page\"\n      )\n    ];\n\n    if(!pages.length && typeof a4CreatePage === \"function\"){\n      canvas.appendChild(a4CreatePage(2));\n      pages = [\n        ...canvas.querySelectorAll(\n          \":scope > .a4-question-page\"\n        )\n      ];\n    }\n\n    /*\n      We do NOT automatically redistribute the user's chosen questions.\n      We only make sure there is always another empty A4 sheet available,\n      making it easy to place one, two or several questions there.\n    */\n    const lastPage = pages[pages.length - 1];\n    const lastCount =\n      lastPage?.querySelectorAll(\n        \".a4-page-dropzone > .modal-q-card\"\n      ).length || 0;\n\n    if(lastCount > 0 && typeof a4CreatePage === \"function\"){\n      const nextPageNo = pages.length + 2;\n      canvas.appendChild(\n        a4CreatePage(nextPageNo)\n      );\n    }\n  }\n\n  function a4RemoveTrailingEmptyPages(){\n    const pages = [\n      ...document.querySelectorAll(\n        \"#a4PagesCanvas .a4-question-page\"\n      )\n    ];\n\n    /*\n      Keep one empty destination page after the last page with questions.\n    */\n    let seenLastNonEmpty = false;\n\n    for(let i=pages.length-1;i>=0;i--){\n      const page = pages[i];\n      const count =\n        page.querySelectorAll(\n          \".a4-page-dropzone > .modal-q-card\"\n        ).length;\n\n      if(count > 0){\n        seenLastNonEmpty = true;\n        break;\n      }\n\n      if(i < pages.length - 1){\n        page.remove();\n      }\n    }\n\n    if(!seenLastNonEmpty && pages.length > 1){\n      pages.slice(1).forEach(p=>p.remove());\n    }\n  }\n\n  function a4RenumberAllFinal(){\n    const cards = a4CardsInVisualOrder();\n\n    cards.forEach((card,index)=>{\n      const number = index + 1;\n      card.dataset.questionNumber = String(number);\n\n      const handle =\n        card.querySelector(\".a4-question-drag-handle\");\n\n      const header =\n        [...card.children].find(el =>\n          el !== handle &&\n          !el.classList.contains(\"a4-move-select\") &&\n          el.tagName === \"DIV\"\n        );\n\n      if(header){\n        const candidates = [...header.children].filter(\n          el => el.tagName === \"DIV\"\n        );\n\n        if(candidates[0]){\n          candidates[0].textContent = `Q${number}`;\n        }\n      }\n    });\n  }\n\n  function a4NormalizeAllPageNumbersFinal(){\n    const pages = [\n      ...document.querySelectorAll(\n        \"#a4PagesCanvas .a4-question-page\"\n      )\n    ];\n\n    pages.forEach((page,index)=>{\n      const pageNo = index + 2;\n      page.dataset.pdfPage = String(pageNo);\n\n      const label = page.querySelector(\".a4-page-label\");\n      if(label){\n        label.innerHTML = `\n          <i class=\"fa-solid fa-file-pdf\"></i>\n          PDF Page ${pageNo}\n          <small>${pageNo===2 ? \"first questions page\" : \"A4\"}</small>\n        `;\n      }\n\n      const bottom =\n        page.querySelector(\".a4-page-bottom-line span\");\n\n      if(bottom){\n        bottom.textContent =\n          `END OF PDF PAGE ${pageNo}`;\n      }\n\n      page.querySelectorAll(\n        \".modal-q-card[data-question-id]\"\n      ).forEach(card=>{\n        card.dataset.pdfPage = String(pageNo);\n\n        const badge =\n          card.querySelector(\".a4-current-page\");\n\n        if(badge){\n          badge.textContent = `PDF Page ${pageNo}`;\n        }\n      });\n    });\n  }\n\n  function a4RebuildSeparatorsFinal(){\n    const canvas = document.getElementById(\"a4PagesCanvas\");\n    if(!canvas) return;\n\n    canvas.querySelectorAll(\n      \":scope > .a4-screen-separator, :scope > .a4-add-page-zone\"\n    ).forEach(el=>el.remove());\n\n    const pages = [\n      ...canvas.querySelectorAll(\n        \":scope > .a4-question-page\"\n      )\n    ];\n\n    pages.forEach((page,index)=>{\n      const next = pages[index+1];\n      if(!next) return;\n\n      const separator = document.createElement(\"div\");\n      separator.className = \"a4-screen-separator\";\n      separator.innerHTML = `\n        <span>\n          END PDF PAGE ${index+2} &nbsp; | &nbsp;\n          START PDF PAGE ${index+3}\n        </span>\n      `;\n\n      canvas.insertBefore(separator,next);\n    });\n\n    if(typeof a4CreateAddPageZone === \"function\"){\n      canvas.appendChild(\n        a4CreateAddPageZone()\n      );\n    }\n  }\n\n  function a4RefreshFinalLayout(){\n    a4RemoveTrailingEmptyPages();\n    a4EnsureEnoughPagesForOverflow();\n    a4NormalizeAllPageNumbersFinal();\n    a4RenumberAllFinal();\n    a4RebuildSeparatorsFinal();\n\n    a4CardsInVisualOrder().forEach(card=>{\n      a4InstallMultiSelect(card);\n    });\n\n    a4UpdateSelectedVisual();\n\n    if(A4_MULTI_DRAG_IDS.length){\n      a4BuildAllDropSlots();\n    }\n  }\n\n  function a4StartMultiDrag(card,event){\n    const id = String(\n      card.dataset.questionId || \"\"\n    ).trim();\n\n    if(!id) return;\n\n    const checkedCards = a4SelectedCards();\n\n    /*\n      If the dragged card is selected, move ALL selected questions.\n      If it is not selected, move only this one question.\n    */\n    let movingCards = [];\n\n    if(\n      card.querySelector(\".a4-move-check\")?.checked &&\n      checkedCards.length\n    ){\n      movingCards = checkedCards;\n    }else{\n      movingCards = [card];\n    }\n\n    A4_MULTI_DRAG_IDS = movingCards\n      .map(c => String(c.dataset.questionId || \"\").trim())\n      .filter(Boolean);\n\n    A4_MULTI_DRAG_SOURCE = card;\n\n    movingCards.forEach(c=>{\n      c.classList.add(\"a4-dragging\");\n    });\n\n    a4BuildAllDropSlots();\n\n    try{\n      event.dataTransfer.effectAllowed = \"move\";\n      event.dataTransfer.setData(\n        \"text/plain\",\n        A4_MULTI_DRAG_IDS.join(\",\")\n      );\n    }catch(_){}\n  }\n\n  function a4FinishMultiMove(){\n    a4CardsInVisualOrder().forEach(card=>{\n      card.classList.remove(\"a4-dragging\");\n\n      const cb = card.querySelector(\".a4-move-check\");\n      if(cb){\n        cb.checked = false;\n      }\n    });\n\n    A4_MULTI_DRAG_IDS = [];\n    A4_MULTI_DRAG_SOURCE = null;\n\n    a4ClearDropSlots();\n    a4RefreshFinalLayout();\n  }\n\n  function a4PatchCardDragEvents(){\n    a4CardsInVisualOrder().forEach(card=>{\n      a4InstallMultiSelect(card);\n\n      if(card.dataset.multiDragPatched === \"1\"){\n        return;\n      }\n\n      card.dataset.multiDragPatched = \"1\";\n      card.draggable = true;\n\n      /*\n        Capture phase overrides the older one-card drag logic.\n      */\n      card.addEventListener(\n        \"dragstart\",\n        event=>{\n          event.stopImmediatePropagation();\n          a4StartMultiDrag(card,event);\n        },\n        true\n      );\n\n      card.addEventListener(\n        \"dragend\",\n        event=>{\n          event.stopImmediatePropagation();\n\n          /*\n            If the question was not actually dropped into a slot,\n            simply clean the drag state and leave the layout untouched.\n          */\n          if(A4_MULTI_DRAG_IDS.length){\n            a4CardsInVisualOrder().forEach(c=>\n              c.classList.remove(\"a4-dragging\")\n            );\n            A4_MULTI_DRAG_IDS = [];\n            A4_MULTI_DRAG_SOURCE = null;\n            a4ClearDropSlots();\n            a4RefreshFinalLayout();\n          }\n        },\n        true\n      );\n    });\n  }\n\n  function a4InitFinalMultiDrag(){\n    const canvas = document.getElementById(\"a4PagesCanvas\");\n    if(!canvas) return;\n\n    a4RefreshFinalLayout();\n    a4PatchCardDragEvents();\n\n    /*\n      Keep patching after modal rerenders or questions are moved.\n    */\n    const observer = new MutationObserver(()=>{\n      a4PatchCardDragEvents();\n    });\n\n    observer.observe(canvas,{\n      childList:true,\n      subtree:true\n    });\n  }\n\n  /*\n    Extend the existing setup function without replacing the rest of the code.\n  */\n  const originalSetup =\n    window.setupPdfA4DragManager;\n\n  window.setupPdfA4DragManager = function(examId){\n    if(typeof originalSetup === \"function\"){\n      originalSetup(examId);\n    }\n\n    setTimeout(()=>{\n      a4InitFinalMultiDrag();\n    },0);\n  };\n\n  /*\n    Override save so it always stores visual page/order exactly.\n    This keeps numbering and PDF order synchronized.\n  */\n  const originalSave =\n    window.a4SaveManualLayout;\n\n  window.a4SaveManualLayout = async function(showMessage=false){\n    a4NormalizeAllPageNumbersFinal();\n    a4RenumberAllFinal();\n\n    const examId =\n      String(window.A4_DRAG_EXAM_ID || \"\").trim();\n\n    const cards = a4CardsInVisualOrder();\n\n    if(!cards.length){\n      return;\n    }\n\n    /*\n      Fallback to original save if exam id is not visible in window scope.\n    */\n    if(!examId){\n      if(typeof originalSave === \"function\"){\n        return originalSave(showMessage);\n      }\n      return;\n    }\n\n    const batch = db.batch();\n    let order = 1;\n\n    document.querySelectorAll(\n      \"#a4PagesCanvas .a4-question-page\"\n    ).forEach(page=>{\n\n      const pdfPage =\n        Math.max(\n          2,\n          Number(page.dataset.pdfPage || 2)\n        );\n\n      page.querySelectorAll(\n        \".a4-page-dropzone > .modal-q-card[data-question-id]\"\n      ).forEach(card=>{\n\n        const id =\n          String(card.dataset.questionId || \"\").trim();\n\n        if(!id) return;\n\n        batch.update(\n          db.collection(\"questions\").doc(id),\n          {\n            pdfPage,\n            order:order++,\n            pdfLayoutUpdatedAt:\n              firebase.firestore.FieldValue.serverTimestamp()\n          }\n        );\n      });\n    });\n\n    try{\n      await batch.commit();\n\n      if(showMessage){\n        alert(\"✅ A4 question layout saved\");\n      }\n    }catch(err){\n      console.error(\n        \"Final A4 layout save error:\",\n        err\n      );\n\n      alert(\n        \"❌ Could not save A4 layout\\n\" +\n        String(err.message || err)\n      );\n    }\n  };\n\n})();\n"}, {"text": "\n(function(){\n  let running = false;\n\n  function pages(){\n    return [...document.querySelectorAll(\"#a4PagesCanvas .a4-question-page\")];\n  }\n\n  function zone(page){\n    return page?.querySelector(\".a4-page-dropzone\");\n  }\n\n  function cards(z){\n    return [...z.querySelectorAll(\":scope > .modal-q-card[data-question-id]\")];\n  }\n\n  function overflowing(z){\n    return z && z.scrollHeight > z.clientHeight + 3;\n  }\n\n  function ensureNext(page){\n    const all = pages();\n    const i = all.indexOf(page);\n    if(i < 0) return null;\n\n    let next = all[i+1];\n\n    if(!next && typeof a4CreatePage === \"function\"){\n      const canvas = document.getElementById(\"a4PagesCanvas\");\n      next = a4CreatePage(i + 3);\n      canvas?.appendChild(next);\n    }\n\n    return next;\n  }\n\n  async function pushOverflow(saveAfter=false){\n    if(running) return;\n    running = true;\n\n    try{\n      for(let pass=0; pass<50; pass++){\n        let changed = false;\n        const all = pages();\n\n        for(const page of all){\n          const z = zone(page);\n          if(!z) continue;\n\n          let guard = 0;\n\n          while(overflowing(z) && guard < 50){\n            guard++;\n\n            const cs = cards(z);\n\n            /* One giant question cannot be moved forever. */\n            if(cs.length <= 1) break;\n\n            const last = cs[cs.length-1];\n            const nextPage = ensureNext(page);\n            const nextZone = zone(nextPage);\n\n            if(!last || !nextZone) break;\n\n            const firstNext =\n              nextZone.querySelector(\":scope > .modal-q-card[data-question-id]\");\n\n            if(firstNext){\n              nextZone.insertBefore(last, firstNext);\n            }else{\n              nextZone.appendChild(last);\n            }\n\n            changed = true;\n\n            void z.offsetHeight;\n            void nextZone.offsetHeight;\n          }\n        }\n\n        if(!changed) break;\n      }\n\n      if(typeof a4RefreshPageBadges === \"function\"){\n        a4RefreshPageBadges();\n      }\n\n      if(typeof a4RenumberQuestions === \"function\"){\n        a4RenumberQuestions();\n      }\n\n      if(typeof a4RenderPageSeparators === \"function\"){\n        a4RenderPageSeparators();\n      }\n\n      if(saveAfter && typeof a4SaveManualLayout === \"function\"){\n        await a4SaveManualLayout(false);\n      }\n\n    }finally{\n      running = false;\n    }\n  }\n\n  window.finalA4PushOverflowForward = pushOverflow;\n\n  const oldSetup = window.setupPdfA4DragManager;\n\n  window.setupPdfA4DragManager = function(examId){\n    if(typeof oldSetup === \"function\"){\n      oldSetup(examId);\n    }\n\n    setTimeout(()=>pushOverflow(false), 180);\n    setTimeout(()=>pushOverflow(false), 800);\n  };\n\n  const oldSave = window.a4SaveManualLayout;\n\n  window.a4SaveManualLayout = async function(showMessage=false){\n    await pushOverflow(false);\n\n    if(typeof oldSave === \"function\"){\n      return oldSave(showMessage);\n    }\n  };\n})();\n"}, {"text": "\n(function(){\n\n  const DEFAULT_PDF_COMPACT = {\n    fontScale:1,\n    spaceScale:1\n  };\n\n  let PDF_COMPACT_EXAM_ID = \"\";\n  let PDF_COMPACT_STATE = {\n    ...DEFAULT_PDF_COMPACT\n  };\n\n  function pdfClamp(value,min,max){\n    return Math.min(\n      max,\n      Math.max(min,Number(value))\n    );\n  }\n\n  function pdfRound(value,decimals=2){\n    const p = Math.pow(10,decimals);\n    return Math.round(value*p)/p;\n  }\n\n  function pdfCompactStorageKey(){\n    return \"prudle_pdf_compact_\" +\n      String(PDF_COMPACT_EXAM_ID || \"default\");\n  }\n\n  function pdfLoadCompactState(){\n    try{\n      const raw =\n        localStorage.getItem(\n          pdfCompactStorageKey()\n        );\n\n      if(!raw){\n        PDF_COMPACT_STATE = {\n          ...DEFAULT_PDF_COMPACT\n        };\n        return;\n      }\n\n      const saved = JSON.parse(raw);\n\n      PDF_COMPACT_STATE = {\n        fontScale:pdfClamp(\n          saved.fontScale ?? 1,\n          .72,\n          1.3\n        ),\n        spaceScale:pdfClamp(\n          saved.spaceScale ?? 1,\n          .05,\n          1.5\n        )\n      };\n\n    }catch(_){\n      PDF_COMPACT_STATE = {\n        ...DEFAULT_PDF_COMPACT\n      };\n    }\n  }\n\n  function pdfSaveCompactState(){\n    try{\n      localStorage.setItem(\n        pdfCompactStorageKey(),\n        JSON.stringify(\n          PDF_COMPACT_STATE\n        )\n      );\n    }catch(_){}\n  }\n\n  function pdfSetCssMm(root,name,base,scale,min=0){\n    root.style.setProperty(\n      name,\n      Math.max(\n        min,\n        base*scale\n      ).toFixed(2) + \"mm\"\n    );\n  }\n\n  function pdfSetCssPt(root,name,base,scale,min=5){\n    root.style.setProperty(\n      name,\n      Math.max(\n        min,\n        base*scale\n      ).toFixed(2) + \"pt\"\n    );\n  }\n\n  function pdfApplyCompactState(){\n    const modal =\n      document.getElementById(\n        \"questionsModal\"\n      );\n\n    if(!modal){\n      return;\n    }\n\n    const f =\n      PDF_COMPACT_STATE.fontScale;\n\n    const s =\n      PDF_COMPACT_STATE.spaceScale;\n\n    /* Text */\n    pdfSetCssPt(\n      modal,\n      \"--pdf-q-title-size\",\n      11.5,\n      f,\n      7\n    );\n\n    pdfSetCssPt(\n      modal,\n      \"--pdf-option-size\",\n      10.3,\n      f,\n      6.5\n    );\n\n    pdfSetCssPt(\n      modal,\n      \"--pdf-passage-size\",\n      10.5,\n      f,\n      6.5\n    );\n\n    pdfSetCssPt(\n      modal,\n      \"--pdf-meta-size\",\n      9,\n      f,\n      6\n    );\n\n    pdfSetCssPt(\n      modal,\n      \"--pdf-fill-size\",\n      11,\n      f,\n      7\n    );\n\n    pdfSetCssPt(\n      modal,\n      \"--pdf-fill-blank-size\",\n      10,\n      f,\n      6.5\n    );\n\n    /* Vertical spaces */\n    pdfSetCssMm(\n      modal,\n      \"--pdf-card-gap\",\n      3.5,\n      s,\n      0\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-card-pad-top\",\n      2.8,\n      s,\n      .2\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-card-pad-bottom\",\n      3.5,\n      s,\n      .2\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-title-gap\",\n      2,\n      s,\n      0\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-passage-gap\",\n      2.5,\n      s,\n      0\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-option-gap\",\n      .4,\n      s,\n      0\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-fill-gap\",\n      2,\n      s,\n      0\n    );\n\n    pdfSetCssMm(\n      modal,\n      \"--pdf-line-gap\",\n      2,\n      s,\n      0\n    );\n\n    pdfUpdateCompactLabels();\n\n    /*\n      Recalculate A4 overflow after changing font/spacing.\n      Questions that no longer fit are moved forward; reducing\n      spacing does NOT automatically pull questions backward,\n      so the user's manual arrangement remains under their control.\n    */\n    setTimeout(()=>{\n      if(\n        typeof finalA4PushOverflowForward ===\n        \"function\"\n      ){\n        finalA4PushOverflowForward(false);\n      }\n    },60);\n  }\n\n  function pdfUpdateCompactLabels(){\n    const fontEl =\n      document.getElementById(\n        \"pdfFontScaleValue\"\n      );\n\n    const spaceEl =\n      document.getElementById(\n        \"pdfSpaceScaleValue\"\n      );\n\n    if(fontEl){\n      fontEl.textContent =\n        Math.round(\n          PDF_COMPACT_STATE.fontScale*100\n        ) + \"%\";\n    }\n\n    if(spaceEl){\n      spaceEl.textContent =\n        Math.round(\n          PDF_COMPACT_STATE.spaceScale*100\n        ) + \"%\";\n    }\n  }\n\n  window.pdfAdjustFont = function(delta){\n    PDF_COMPACT_STATE.fontScale =\n      pdfRound(\n        pdfClamp(\n          PDF_COMPACT_STATE.fontScale +\n          Number(delta || 0),\n          .72,\n          1.3\n        ),\n        2\n      );\n\n    pdfSaveCompactState();\n    pdfApplyCompactState();\n  };\n\n  window.pdfAdjustSpacing = function(delta){\n    PDF_COMPACT_STATE.spaceScale =\n      pdfRound(\n        pdfClamp(\n          PDF_COMPACT_STATE.spaceScale +\n          Number(delta || 0),\n          .05,\n          1.5\n        ),\n        2\n      );\n\n    pdfSaveCompactState();\n    pdfApplyCompactState();\n  };\n\n  window.pdfSetNoGaps = function(){\n    /*\n      Keep tiny padding so borders/text do not visually collide,\n      but remove almost all before/after spacing.\n    */\n    PDF_COMPACT_STATE.spaceScale = .08;\n\n    pdfSaveCompactState();\n    pdfApplyCompactState();\n  };\n\n  window.pdfResetCompact = function(){\n    PDF_COMPACT_STATE = {\n      ...DEFAULT_PDF_COMPACT\n    };\n\n    pdfSaveCompactState();\n    pdfApplyCompactState();\n  };\n\n  function pdfBuildCompactToolbar(){\n    const main =\n      document.getElementById(\n        \"a4DragToolbar\"\n      );\n\n    if(!main){\n      return;\n    }\n\n    let bar =\n      document.getElementById(\n        \"pdfCompactToolbar\"\n      );\n\n    if(!bar){\n      bar =\n        document.createElement(\"div\");\n\n      bar.id =\n        \"pdfCompactToolbar\";\n\n      bar.className =\n        \"pdf-compact-toolbar\";\n\n      main.insertAdjacentElement(\n        \"afterend\",\n        bar\n      );\n    }\n\n    bar.innerHTML = `\n      <div class=\"pdf-compact-group\">\n        <strong>Text size</strong>\n\n        <button\n          type=\"button\"\n          onclick=\"pdfAdjustFont(-0.05)\"\n          title=\"Smaller text\"\n          style=\"background:#64748b\"\n        >\n          A−\n        </button>\n\n        <span\n          id=\"pdfFontScaleValue\"\n          class=\"pdf-compact-value\"\n        >\n          100%\n        </span>\n\n        <button\n          type=\"button\"\n          onclick=\"pdfAdjustFont(0.05)\"\n          title=\"Larger text\"\n          style=\"background:#164478\"\n        >\n          A+\n        </button>\n      </div>\n\n      <div class=\"pdf-compact-group\">\n        <strong>Before / After space</strong>\n\n        <button\n          type=\"button\"\n          onclick=\"pdfAdjustSpacing(-0.10)\"\n          title=\"Reduce spacing\"\n          style=\"background:#64748b\"\n        >\n          −\n        </button>\n\n        <span\n          id=\"pdfSpaceScaleValue\"\n          class=\"pdf-compact-value\"\n        >\n          100%\n        </span>\n\n        <button\n          type=\"button\"\n          onclick=\"pdfAdjustSpacing(0.10)\"\n          title=\"Increase spacing\"\n          style=\"background:#164478\"\n        >\n          +\n        </button>\n\n        <button\n          type=\"button\"\n          onclick=\"pdfSetNoGaps()\"\n          title=\"Remove almost all vertical spacing\"\n          style=\"background:#f59e0b\"\n        >\n          No Gaps\n        </button>\n      </div>\n\n      <button\n        type=\"button\"\n        onclick=\"pdfResetCompact()\"\n        style=\"background:#8b5cf6\"\n      >\n        Reset\n      </button>\n\n      <div class=\"pdf-compact-note\">\n        These controls change both the A4 preview and the printed PDF.\n        Reduce Text size and Before / After space to fit more questions\n        on the same A4 sheet.\n      </div>\n    `;\n\n    pdfUpdateCompactLabels();\n  }\n\n  function pdfInitCompactControls(examId){\n    PDF_COMPACT_EXAM_ID =\n      String(examId || \"\").trim();\n\n    pdfLoadCompactState();\n    pdfBuildCompactToolbar();\n    pdfApplyCompactState();\n  }\n\n  /*\n    Hook into the existing A4 preview initialization.\n  */\n  const previousSetup =\n    window.setupPdfA4DragManager;\n\n  window.setupPdfA4DragManager =\n    function(examId){\n\n      if(\n        typeof previousSetup ===\n        \"function\"\n      ){\n        previousSetup(examId);\n      }\n\n      setTimeout(()=>{\n        pdfInitCompactControls(\n          examId\n        );\n      },0);\n    };\n\n  /*\n    Before printing, reapply the exact same sizes to ensure that\n    preview and PDF are synchronized.\n  */\n  window.addEventListener(\n    \"beforeprint\",\n    ()=>{\n      pdfApplyCompactState();\n    }\n  );\n\n})();\n"}, {"text": "\n(function(){\n  const S={\n    running:false,\n    direction:0,\n    speed:0,\n    raf:0,\n    lastY:0,\n    box:null,\n    top:null,\n    bottom:null\n  };\n\n  function createZones(){\n    if(!document.getElementById(\"a4AutoScrollTop\")){\n      const el=document.createElement(\"div\");\n      el.id=\"a4AutoScrollTop\";\n      el.textContent=\"Keep dragging here to move to previous A4 pages\";\n      document.body.appendChild(el);\n    }\n    if(!document.getElementById(\"a4AutoScrollBottom\")){\n      const el=document.createElement(\"div\");\n      el.id=\"a4AutoScrollBottom\";\n      el.textContent=\"Keep dragging here to move to next A4 pages\";\n      document.body.appendChild(el);\n    }\n    S.top=document.getElementById(\"a4AutoScrollTop\");\n    S.bottom=document.getElementById(\"a4AutoScrollBottom\");\n  }\n\n  function getBox(){\n    const modal=document.getElementById(\"questionsModal\");\n    const box=modal?.querySelector(\".modal-box\");\n    if(box && box.scrollHeight>box.clientHeight) return box;\n    return document.scrollingElement || document.documentElement;\n  }\n\n  function isDragging(){\n    return !!document.querySelector(\"#a4PagesCanvas .modal-q-card.a4-dragging\");\n  }\n\n  function start(){\n    createZones();\n    S.box=getBox();\n    S.running=true;\n    document.body.classList.add(\"a4-auto-scroll-dragging\");\n    if(!S.raf) S.raf=requestAnimationFrame(frame);\n  }\n\n  function stop(){\n    S.running=false;\n    S.direction=0;\n    S.speed=0;\n    S.lastY=0;\n    document.body.classList.remove(\"a4-auto-scroll-dragging\");\n    S.top?.classList.remove(\"active\");\n    S.bottom?.classList.remove(\"active\");\n    if(S.raf){\n      cancelAnimationFrame(S.raf);\n      S.raf=0;\n    }\n  }\n\n  function bounds(){\n    const box=S.box || getBox();\n    if(\n      box &&\n      box!==document.documentElement &&\n      box!==document.body &&\n      box!==document.scrollingElement\n    ){\n      const r=box.getBoundingClientRect();\n      return {\n        top:Math.max(0,r.top),\n        bottom:Math.min(window.innerHeight,r.bottom)\n      };\n    }\n    return {top:0,bottom:window.innerHeight};\n  }\n\n  function update(y){\n    if(!S.running) start();\n    S.lastY=Number(y||0);\n\n    const b=bounds();\n    const edge=Math.min(150,Math.max(90,(b.bottom-b.top)*.18));\n    const topLimit=b.top+edge;\n    const bottomLimit=b.bottom-edge;\n\n    let dir=0;\n    let strength=0;\n\n    if(y<topLimit){\n      dir=-1;\n      strength=(topLimit-y)/edge;\n    }else if(y>bottomLimit){\n      dir=1;\n      strength=(y-bottomLimit)/edge;\n    }\n\n    strength=Math.max(0,Math.min(1,strength));\n\n    const minSpeed=6;\n    const maxSpeed=34;\n\n    S.direction=dir;\n    S.speed=dir===0 ? 0 : minSpeed+(maxSpeed-minSpeed)*Math.pow(strength,.72);\n\n    S.top?.classList.toggle(\"active\",dir===-1);\n    S.bottom?.classList.toggle(\"active\",dir===1);\n  }\n\n  function doScroll(delta){\n    const box=S.box || getBox();\n    if(!box) return;\n\n    if(\n      box===document.scrollingElement ||\n      box===document.documentElement ||\n      box===document.body\n    ){\n      window.scrollBy(0,delta);\n    }else{\n      box.scrollTop += delta;\n    }\n  }\n\n  function frame(){\n    S.raf=0;\n\n    if(!S.running) return;\n    if(!isDragging()){\n      stop();\n      return;\n    }\n\n    if(S.direction!==0 && S.speed>0){\n      doScroll(S.direction*S.speed);\n    }\n\n    S.raf=requestAnimationFrame(frame);\n  }\n\n  document.addEventListener(\"dragstart\",event=>{\n    const card=event.target?.closest?.(\n      \"#a4PagesCanvas .modal-q-card[data-question-id]\"\n    );\n    if(card) start();\n  },true);\n\n  document.addEventListener(\"dragover\",event=>{\n    if(!isDragging()) return;\n    update(event.clientY);\n  },true);\n\n  document.addEventListener(\"drop\",()=>{\n    setTimeout(stop,30);\n  },true);\n\n  document.addEventListener(\"dragend\",stop,true);\n\n  document.addEventListener(\"click\",event=>{\n    if(event.target?.closest?.(\"#questionsModal .modal-header button\")){\n      stop();\n    }\n  },true);\n})();\n"}];
function installScript(item){return new Promise((resolve,reject)=>{
  const tag=document.createElement('script');
  if(item.src){if(/firebase-(?:app|firestore)-compat\.js/.test(item.src)){resolve();return;}tag.src=item.src;tag.onload=resolve;tag.onerror=()=>reject(Error('تعذر تحميل '+item.src));}
  else {
    let source=item.text;
    source=source.replace(
      'previewBox.innerHTML = "❌ Error loading exams";',
      'previewBox.textContent = "❌ Error loading exams: " + (err?.message || String(err));'
    );
    tag.textContent=source;
  }
  document.body.appendChild(tag);
  if(!item.src)resolve();
});}
function App(){
 const holder=useRef(null),[status,setStatus]=useState('جاري التحقق من صلاحية Admin...'),[error,setError]=useState('');
 useEffect(()=>{let cancelled=false;
 (async()=>{
   await verifyAdmin();
   if(cancelled)return;
   setStatus('');
   holder.current.innerHTML=LEGACY_MARKUP;
   // Original code expects `firebase` as a classic-script global.
   window.firebase=firebase;
   const user=checkedUser();
   if(user){
     // Identity/roles remain authoritative in USERS and are verified in /db.
     // Do not overwrite the existing login roles in localStorage.
     if(!localStorage.getItem('username') && user.username){
       localStorage.setItem('username',String(user.username));
     }
   }
   for(const item of LEGACY_SCRIPTS){if(cancelled)break;await installScript(item);}
   await installScript({text:"(function(){\n  'use strict';\n  const required={\n    exams:'loadExams',questions:'loadQuestions',examCreate:'createExam',\n    questionSave:'saveQuestion',fullPreview:'openFullQuestions',\n    printPDF:'printQuestionsPDF',importWord:'importWord',importPDF:'importPDF',\n    copyQuestions:'openQuestionCopyBank',saveTimer:'editExamTime'\n  };\n  const missing=Object.entries(required).filter(([,name])=>typeof window[name]!=='function');\n  if(missing.length){\n    console.warn('[Prudle quiz feature audit] Missing functions:',missing);\n    const el=document.getElementById('prudleDataStatus');\n    if(el){el.hidden=false;el.textContent='بعض وظائف الاختبارات لم تُحمّل: '+missing.map(x=>x[1]).join(', ');}\n  }\n  function getActiveExam(){\n    try { return typeof CURRENT_PREVIEW_EXAM!=='undefined' ? String(CURRENT_PREVIEW_EXAM||'').trim():''; }\n    catch(_){return '';}\n  }\n  window.prudleOpenPdfPreview=async function(mode){\n    const examId=getActiveExam();\n    if(!examId){alert('اختر اختبارًا من البطاقات أولًا لعرض الأسئلة أو PDF.');return;}\n    const modal=document.getElementById('questionsModal');\n    if(typeof window.openFullQuestions!=='function'){\n      alert('تعذر تحميل نافذة عرض الأسئلة الأصلية.');return;\n    }\n    try{\n      await window.openFullQuestions(examId);\n      const wrap=document.getElementById('modalQuestionsWrap');\n      if(!modal || !wrap || !wrap.querySelector('.modal-q-card')){\n        console.warn('[Prudle PDF] No printable questions found in selected exam',examId);\n        return;\n      }\n      // Print is intentionally initiated by an explicit click on the original\n      // modal's PDF buttons to avoid browser popup/print blocking.\n      if(mode==='answers' || mode==='questions' || mode==='review'){\n        const btn=modal.querySelector(mode==='answers' ? '.print-answers-btn' :\n          mode==='review' ? '.print-review-btn' : '.print-questions-btn:not(.print-answers-btn):not(.print-review-btn)');\n        if(btn){ btn.focus({preventScroll:true}); }\n      }\n    }catch(err){\n      console.error('[Prudle PDF] Original exam preview failed:',err);\n      alert('تعذر عرض أسئلة الاختبار: '+(err?.message||err));\n    }\n  };\n  const box=document.getElementById('examPreviewBox');\n  const section=box?.closest('.box');\n  if(section && !document.getElementById('prudleQuickPdfTools')){\n    const bar=document.createElement('div');\n    bar.id='prudleQuickPdfTools';\n    bar.setAttribute('dir','rtl');\n    bar.innerHTML=`\n      <span class=\"prudle-pdf-label\">عرض الاختبار والطباعة (اختر بطاقة اختبار أولًا)</span>\n      <button type=\"button\" data-pdf=\"review\">👁️ معاينة الأسئلة</button>\n      <button type=\"button\" data-pdf=\"questions\">📄 PDF الأسئلة</button>\n      <button type=\"button\" data-pdf=\"answers\">✅ PDF الأسئلة والإجابات</button>`;\n    const tabs=document.getElementById('courseTabs');\n    if(tabs) tabs.before(bar);else box.after(bar);\n    bar.addEventListener('click',e=>{\n      const btn=e.target.closest('button[data-pdf]');\n      if(btn)window.prudleOpenPdfPreview(btn.dataset.pdf);\n    });\n  }\n  // Preserve native controls and leave original print code responsible for A4.\n})();"});
   if(!cancelled)document.dispatchEvent(new Event('DOMContentLoaded',{bubbles:true}));
 })().catch(e=>{console.error('Prudle quizzes startup:',e);setError(e.message||String(e));});
 return ()=>{cancelled=true};
 },[]);
 return React.createElement('div',{id:'prudle-admin-mount'},
   status?React.createElement('div',{className:'prudle-auth-message'},status):null,
   error?React.createElement('div',{className:'prudle-auth-message prudle-error'},error):null,
   React.createElement('div',{ref:holder,style:{display:status||error?'none':'block'}})
 );
}
if(!document.getElementById('root'))throw Error('Add <div id="root"></div> to Webflow Embed');
createRoot(document.getElementById('root')).render(React.createElement(App));
